  function normalizeFarmPathname(pathname) {
    let path = String(pathname || "/").split("?")[0].split("#")[0];
    try {
      path = decodeURIComponent(path);
    } catch (_) {}
    path = path.replace(/\/+$/, "") || "/";
    if (!path.startsWith("/")) path = "/" + path;
    if (FARM_ROUTE_ALIASES[path]) return FARM_ROUTE_ALIASES[path];
    return path;
  }

  function farmRoutePathFor(tab, family) {
    if (tab === AFTERPLAY_FAST_TAB) {
      return AFTERPLAY_PATH_BY_FAMILY[family || afterplayFamily] || "/coin";
    }
    return FARM_PATH_BY_TAB[tab] || "/";
  }

  function farmDocumentTitle(tab, family) {
    if (tab === AFTERPLAY_FAST_TAB) {
      const key = "afterplay_" + (family || afterplayFamily || "xp");
      const meta = FARM_TAB_META[key] || FARM_TAB_META.afterplay_fast;
      return (meta?.title || "ฟาร์ม") + " · CKR WWDC";
    }
    // Home tab keeps the site title (Google indexes the landing page with it).
    if (tab === "devplay") return "CKR WWDC · ฟาร์มหัวใจ Cookie Run ราคาถูก";
    const meta = FARM_TAB_META[tab];
    return (meta?.title || "CKR WWDC") + " · CKR WWDC";
  }

  function farmSearchWithoutTab() {
    const params = new URLSearchParams(location.search);
    params.delete("tab");
    const s = params.toString();
    return s ? "?" + s : "";
  }

  function syncFarmRoute(opts = {}) {
    // Farm tabs keep switching in the background; never let them rewrite /admincenter.
    if (adminCenterActive) return;
    const tab = opts.tab || farmTab;
    const family = tab === AFTERPLAY_FAST_TAB ? (opts.family || afterplayFamily) : "";
    const path = farmRoutePathFor(tab, family);
    const search = farmSearchWithoutTab();
    const hash = location.hash || "";
    const next = path + search + hash;
    const rawPath = String(location.pathname || "/").replace(/\/+$/, "") || "/";
    const currentPath = normalizeFarmPathname(location.pathname);
    document.title = farmDocumentTitle(tab, family);
    if (
      !opts.force &&
      currentPath === path &&
      rawPath === path &&
      location.search === search
    ) {
      return;
    }
    const state = { farmRoute: true, tab, family: family || "" };
    try {
      if (opts.replace) history.replaceState(state, "", next);
      else history.pushState(state, "", next);
    } catch (_) {}
  }

  function readFarmRoute() {
    try {
      const params = new URLSearchParams(location.search);
      const tabParam = String(params.get("tab") || "").trim();
      if (tabParam) {
        if (FARM_TAB_QUERY_ALIASES[tabParam]) return Object.assign({}, FARM_TAB_QUERY_ALIASES[tabParam]);
        if (FARM_PATH_BY_TAB[tabParam]) return { tab: tabParam };
        if (tabParam === AFTERPLAY_FAST_TAB) {
          return { tab: AFTERPLAY_FAST_TAB, family: afterplayFamily || "coin" };
        }
      }
      const path = normalizeFarmPathname(location.pathname);
      return FARM_ROUTE_BY_PATH[path] ? Object.assign({}, FARM_ROUTE_BY_PATH[path]) : { tab: "devplay" };
    } catch (_) {
      return { tab: "devplay" };
    }
  }

  function applyFarmRoute(opts = {}) {
    const route = opts.route || readFarmRoute();
    const tab = route.tab || "devplay";
    const family = route.family || "";
    const replace = opts.replace !== false;
    const prevWrite = farmRouteWrite;
    farmRouteWrite = replace ? "replace" : "push";
    try {
      if (family && AFTERPLAY_PATH_BY_FAMILY[family]) {
        afterplayFamily = family;
        setAfterplayFarmMode(afterplayFunctionId(), { silent: true, syncRoute: false });
      }
      if (tab === "devplay") {
        switchFarmTab("devplay", { silent: true, replaceRoute: replace });
        return;
      }
      if (tab === "guide" || tab === "pricing") {
        openInfoPage(tab, { silent: true, replaceRoute: replace });
        return;
      }
      if (tab === "live") {
        switchFarmTab("live", { silent: true, replaceRoute: replace, force: true });
        return;
      }
      if (tab === "crgcode") {
        switchFarmTab("crgcode", { silent: true, replaceRoute: replace, force: true });
        return;
      }
      if (tab === "mid_heart" || tab === "report_multi" || tab === "pc_program" || tab === "bot_ad") {
        switchFarmTab(tab, { silent: true, replaceRoute: replace });
        return;
      }
      if (tab === INVITE_TAB) {
        if (!requireNavMenuOpen(INVITE_TAB)) {
          switchFarmTab("devplay", { silent: true, replaceRoute: replace });
          return;
        }
        openInviteFriendTab({ replaceRoute: replace });
        return;
      }
      if (tab === IDSHOP_TAB || tab === IDSHOP_ORDERS_TAB) {
        if (!requireNavMenuOpen(tab)) {
          switchFarmTab("devplay", { silent: true, replaceRoute: replace });
          return;
        }
        openIdshopTab(tab, { replaceRoute: replace });
        return;
      }
      onFarmTabClick(tab);
      if (farmTab !== tab) {
        const wantPath = farmRoutePathFor(tab, family);
        const rawPath = String(location.pathname || "/").replace(/\/+$/, "") || "/";
        const params = new URLSearchParams(location.search);
        if (rawPath !== wantPath || params.has("tab")) {
          const url = wantPath + farmSearchWithoutTab() + (location.hash || "");
          document.title = farmDocumentTitle(tab, family);
          try {
            history.replaceState({ farmRoute: true, tab, family: family || "", pending: true }, "", url);
          } catch (_) {}
        } else {
          document.title = farmDocumentTitle(tab, family);
        }
      }
    } finally {
      farmRouteWrite = prevWrite;
    }
  }

  function maybeApplyPendingFarmRoute() {
    const route = readFarmRoute();
    if ((route.tab || "devplay") === farmTab) {
      if (farmTab !== AFTERPLAY_FAST_TAB || !route.family || route.family === afterplayFamily) {
        syncFarmRoute({ replace: true });
        return;
      }
    }
    applyFarmRoute({ replace: true, route });
  }

