  async function ensureApiReady() {
    if (apiReady) return true;
    return pingApiHealth(2);
  }

  async function handleSessionReplaced() {
    if (authBusy || kickingWebsiteSession || loggingOut) return;
    if (Date.now() - lastWebsiteLoginAt < SESSION_REPLACE_GRACE_MS) return;
    try {
      await sb.auth.signOut();
    } catch (_) {}
    accessToken = null;
    profile = null;
    earlyAccessFeatures = new Set();
    clearSessionToken();
    showLogin({ force: true });
    prefillRememberedLogin().catch(() => {});
    showErrorModal(ERR_TH.session_replaced, "มีการเข้าสู่ระบบจากที่อื่น");
  }

  function jwtExpMs(token) {
    try {
      const part = String(token || "").split(".")[1];
      if (!part) return 0;
      const padded = part.replace(/-/g, "+").replace(/_/g, "/");
      const json = JSON.parse(atob(padded));
      return Number(json.exp || 0) * 1000;
    } catch (_) {
      return 0;
    }
  }

  async function syncAccessTokenFromSupabase() {
    try {
      const { data } = await sb.auth.getSession();
      if (data?.session?.access_token) accessToken = data.session.access_token;
    } catch (_) {}
  }

  async function tryRefreshWebsiteSession() {
    if (sessionRefreshInflight) return sessionRefreshInflight;
    const pending = (async () => {
      try {
        const { data, error } = await sb.auth.refreshSession();
        const token = data?.session?.access_token;
        if (error || !token) return false;
        accessToken = token;
        return true;
      } catch (_) {
        return false;
      }
    })();
    sessionRefreshInflight = pending;
    try {
      return await pending;
    } finally {
      if (sessionRefreshInflight === pending) sessionRefreshInflight = null;
    }
  }

  async function ensureFreshWebsiteSession() {
    try {
      await Promise.race([
        (async () => {
          await syncAccessTokenFromSupabase();
          const exp = jwtExpMs(accessToken);
          if (!accessToken || (exp > 0 && exp < Date.now() + 120000)) {
            await tryRefreshWebsiteSession();
            await syncAccessTokenFromSupabase();
          }
        })(),
        new Promise((resolve) => setTimeout(resolve, 8000)),
      ]);
    } catch (_) {
      // Keep the current token and let the real request proceed.
    }
  }

  function setWebsiteAuthFormEnabled(on) {
    const enabled = !!on;
    ["login-form", "signup-form", "login-view"].forEach((id) => {
      const el = $(id);
      if (!el) return;
      if (enabled) el.removeAttribute("inert");
      else el.setAttribute("inert", "");
    });
    const form = $("login-form");
    if (!form) return;
    form.querySelectorAll("input, button").forEach((el) => {
      if (enabled) el.removeAttribute("disabled");
      else el.disabled = true;
    });
  }

  async function kickExpiredWebsiteSession() {
    if (kickingWebsiteSession || authBusy) return;
    kickingWebsiteSession = true;
    try {
      const alreadyOnLogin = !!(loginView && !loginView.classList.contains("hidden"));
      try {
        await sb.auth.signOut();
      } catch (_) {}
      accessToken = null;
      clearSessionToken();
      showLogin({ force: true });
      prefillRememberedLogin().catch(() => {});
      if (!alreadyOnLogin) {
        showErrorModal(
          ERR_TH.invalid_token || "เซสชันเว็บหมดอายุ — เข้าสู่ระบบใหม่",
          "เซสชันหมดอายุ"
        );
      }
    } finally {
      kickingWebsiteSession = false;
    }
  }

  async function handleWebsiteApiUnauthorized(path, detail, options) {
    const text = String(detail || "");
    if (
      /login_failed|devplay_wrong_password|devplay_not_found|devplay_rate_limited|devplay_account_locked|invalid_credentials|devplay_session_expired|powder_session_missing/i.test(
        text
      )
    ) {
      return "throw";
    }
    if (/\/api\/auth\/(login|register|signup)/i.test(path)) return "throw";
    if (/session_replaced/i.test(text)) {
      await handleSessionReplaced();
      return "throw";
    }
    if (!/invalid_token|missing_bearer_token/i.test(text)) return "throw";
    if (authBusy || kickingWebsiteSession || options._authRetry) return "throw";
    for (let i = 0; i < 2; i += 1) {
      const refreshed = await tryRefreshWebsiteSession();
      if (refreshed) {
        await syncAccessTokenFromSupabase();
        return "retry";
      }
      if (i === 0) await new Promise((resolve) => setTimeout(resolve, 400));
    }
    await kickExpiredWebsiteSession();
    return "throw";
  }

  function isRentalPermanent(p) {
    if (!p) return false;
    return !!(p.rental_is_permanent ?? p.is_permanent);
  }

  function isAdminUser(p) {
    const row = p || profile;
    if (!row) return false;
    if (row.is_admin === true) return true;
    if (row.is_admin === false) return false;
    const email = String(row.email || row.username || "").trim().toLowerCase();
    return email === "true.wifi8888@gmail.com" || email === "true.wifi8888";
  }

