  // Topbar Token pill: count up/down to the new balance + a floating "+N" chip.
  let topbarTokenShown = null;
  let topbarTokenRaf = 0;
  // 2 decimals (rounded down so the pill never shows more than the real balance);
  // the ".xx" part is dimmed so the whole-token amount stands out.
  function topbarTokenHtml(v) {
    const n = Math.floor((Number(v) || 0) * 100 + 1e-6) / 100;
    const neg = n < 0;
    const abs = Math.abs(n);
    const whole = Math.floor(abs);
    const dec = String(Math.round((abs - whole) * 100)).padStart(2, "0");
    return (neg ? "−" : "") + whole.toLocaleString("en-US") + '<span class="tok-dec">.' + dec + "</span>";
  }
  function animateTopbarToken(target) {
    const el = $("topbar-token-value");
    const pill = $("topbar-token-pill");
    if (!el) return;
    const to = Number(target) || 0;
    const from = topbarTokenShown;
    topbarTokenShown = to;
    cancelAnimationFrame(topbarTokenRaf);
    const reduce = window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (from == null || from === to || reduce) {
      el.innerHTML = topbarTokenHtml(to);
      return;
    }
    const diff = to - from;
    if (pill) {
      pill.classList.remove("is-up", "is-down");
      void pill.offsetWidth;
      pill.classList.add(diff > 0 ? "is-up" : "is-down");
      const chip = document.createElement("span");
      chip.className = "topbar-token-delta " + (diff > 0 ? "is-up" : "is-down");
      chip.textContent = (diff > 0 ? "+" : "−") + formatTokenAmount(Math.abs(diff));
      pill.appendChild(chip);
      setTimeout(() => chip.remove(), 1600);
    }
    const t0 = performance.now();
    const dur = 900;
    const step = (now) => {
      const k = Math.min(1, (now - t0) / dur);
      const e = 1 - Math.pow(1 - k, 3);
      const v = from + diff * e;
      el.innerHTML = topbarTokenHtml(k < 1 ? v : to);
      if (k < 1) topbarTokenRaf = requestAnimationFrame(step);
    };
    topbarTokenRaf = requestAnimationFrame(step);
  }

  let botTokenShown = null;
  let botTokenFetchedAt = 0;
  let botTokenFlight = false;

  function paintBotTokenPill(value) {
    const pill = $("topbar-bot-token-pill");
    const numEl = $("topbar-bot-token-value");
    if (!pill) return;
    const n = Number(value);
    const show = !!accessToken && Number.isFinite(n);
    pill.classList.toggle("hidden", !show);
    pill.hidden = !show;
    if (show) {
      botTokenShown = n;
      if (numEl) numEl.textContent = formatTokenAmount(n);
    }
  }

  function refreshBotTokenPill(force) {
    if (!accessToken) {
      paintBotTokenPill(null);
      return;
    }
    if (!force && Date.now() - botTokenFetchedAt < 20000) {
      if (botTokenShown != null) paintBotTokenPill(botTokenShown);
      return;
    }
    if (botTokenFlight) return;
    botTokenFlight = true;
    botTokenFetchedAt = Date.now();
    api("/api/android/v1/shop", { _skipAuthSync: true }).then((data) => {
      if (data && data.ok && data.bot_token_balance != null) paintBotTokenPill(data.bot_token_balance);
    }).catch(() => {}).finally(() => {
      botTokenFlight = false;
    });
  }

  function paintTokenBalance() {
    const n = formatTokenAmount(tokenBalance());
    if ($("menu-token-value")) $("menu-token-value").textContent = n;
    animateTopbarToken(tokenBalance());
    if ($("topbar-token-pill")) {
      const show = !!accessToken;
      $("topbar-token-pill").classList.toggle("hidden", !show);
    }
    refreshBotTokenPill(false);
    if ($("profile-modal-token-value")) $("profile-modal-token-value").innerHTML = topbarTokenHtml(tokenBalance());
    if (accessToken) {
      if ($("idshop-credit-label")) $("idshop-credit-label").textContent = n;
      if ($("idshop-credit-balance-label")) $("idshop-credit-balance-label").textContent = n;
      idshopCreditBalance = tokenBalance();
    }
  }

  function applyStartWallet(data) {
    if (!data || typeof data !== "object") return;
    if (data.token_balance != null) {
      if (profile) profile.token_balance = data.token_balance;
      if (!accessToken) inviteGuestCreditBalance = Number(data.token_balance) || 0;
    } else if (data.billing_outcome && Number(data.billing_outcome.reserved) > 0 && profile) {
      profile.token_balance = Math.max(0, tokenBalance() - Number(data.billing_outcome.reserved || 0));
    }
    if (profile && data.invite_credit_balance != null) {
      profile.invite_credit_balance = data.invite_credit_balance;
    }
    if (data.idshop_credit_balance != null) {
      idshopCreditBalance = Number(data.idshop_credit_balance) || 0;
    }
    paintTokenBalance();
  }

  /* ---------- Modal system ---------- */
  function clearModalActions() {
    modalActions.innerHTML = "";
    modalActions.className = "modal-actions";
  }

  function mapUiClass(className) {
    return String(className || "")
      .replace(/\bbtn-candy-compact\b/g, "btn-primary")
      .replace(/\bbtn-candy\b/g, "btn-primary");
  }

  function makeBtn(label, className, onClick, opts = {}) {
    const el = opts.href
      ? document.createElement("a")
      : document.createElement("button");
    el.className = "btn " + mapUiClass(className);
    if (opts.href) {
      el.href = opts.href;
      el.target = "_blank";
      el.rel = "noopener noreferrer";
    } else {
      el.type = "button";
      el.addEventListener("click", onClick);
    }
    if (opts.icon) {
      const img = document.createElement("img");
      img.src = opts.icon;
      img.alt = "";
      img.width = 24;
      img.height = 24;
      el.appendChild(img);
    }
    el.appendChild(document.createTextNode(label));
    return el;
  }

  function openModal({ mode, title, body, icon, locked, bodyHtml, cardClass }) {
    modalMode = mode;
    modalTitle.textContent = title;
    if (bodyHtml) {
      modalBody.innerHTML = bodyHtml;
    } else {
      modalBody.textContent = body || "";
    }
    modalIcon.src = icon || "assets/coin.png";
    modalRoot.classList.toggle("locked", !!locked);
    const closeBtn = $("modal-close");
    if (closeBtn) {
      closeBtn.classList.toggle("is-hidden", !!locked);
      closeBtn.disabled = !!locked;
    }
    if (modalCard) {
      modalCard.classList.remove("is-shake", "modal-card--picker", "modal-card--feature-pick");
      void modalCard.offsetWidth;
      if (mode === "error") modalCard.classList.add("is-shake");
      if (cardClass) modalCard.classList.add(cardClass);
    }
    lockBodyScroll("modal-open");
    animateOpen(modalRoot);
    const sheet = modalRoot.querySelector(".modal-card") || modalRoot;
    trapFocus(sheet);
  }

  function closeModal() {
    if (modalMode === "afterplay-random") abortAfterplayRandomModal();
    if (modalMode === "queue") return;
    if (modalMode === "proxy" && modalRoot.classList.contains("locked")) return;
    if (modalMode === "feature-pick" && modalRoot.classList.contains("locked")) return;
    if (modalMode === "empty") emptyModalDismissed = true;
    modalMode = null;
    clearModalActions();
    clearPixelConfetti();
    releaseFocusTrap();
    unlockBodyScroll("modal-open");
    animateClose(modalRoot, () => {
      modalRoot.classList.remove("locked");
      if (modalCard) modalCard.classList.remove("is-shake", "modal-card--picker", "modal-card--feature-pick");
      stopBalancePoll();
    });
    // A completion modal was the result surface — don't reveal the finished
    // live-status popup underneath after the user dismisses it.
    if (jobStatusView === "expanded" && (dockPhase === "done" || dockPhase === "error")) {
      closeRunStatusPopup();
    }
  }

  function forceCloseModal() {
    if (modalMode === "afterplay-random") abortAfterplayRandomModal();
    modalMode = null;
    clearModalActions();
    clearPixelConfetti();
    $("modal-body")?.classList.remove("result-stagger");
    releaseFocusTrap();
    unlockBodyScroll("modal-open");
    animateClose(
      modalRoot,
      () => {
        modalRoot.classList.remove("locked");
        if (modalCard) modalCard.classList.remove("is-shake", "modal-card--picker", "modal-card--feature-pick");
        stopBalancePoll();
      },
      { instant: true }
    );
  }

  function walletNeedsRenewal() {
    return !hasFarmAccess() && tokenBalance() <= 0;
  }

  function showEmptyCoinsModal(opts = {}) {
    if (!hasResolvedWebsiteProfile()) {
      openAuthModal("login");
      return;
    }
    const noTokens = tokenBalance() <= 0;
    const noRental = !hasFarmAccess();
    const tokenShortfall = opts.reason === "tokens" && (noTokens || opts.needed != null);
    if (!tokenShortfall && !walletNeedsRenewal()) return;
    emptyModalDismissed = false;
    clearModalActions();
    const expiredBoth = noRental && noTokens;
    openModal({
      mode: "empty",
      title: expiredBoth ? "หมดอายุเช่าแล้ว" : "Token ไม่พอ",
      body: expiredBoth || noTokens
        ? "เติม Token เพื่อใช้ฟาร์มหัวใจ / Gift Draw / ฟาร์มผง / เพื่อน / AfterPlay Fast / Ice Tower / ปลดล็อก L หรือเช่าวันเพื่อใช้ทุกฟังก์ชัน (รวมอัปเกรด / Party Run)"
        : rentalRenewHint(),
      icon: "assets/token.png",
      locked: false,
    });
    modalActions.appendChild(
      makeBtn("ไปต่ออายุ / เติมเงิน", "btn-empty-vault", () => {
        closeModal();
        openVaultModal({ kind: "token" });
      })
    );
    modalActions.appendChild(
      makeBtn("ไอดีราคาถูก", "btn-empty-idshop", () => {
        closeModal();
        openIdshopTab(IDSHOP_TAB);
      })
    );
    modalActions.appendChild(
      makeBtn("ตรวจสอบสิทธิ์อีกครั้ง", "btn-empty-recheck btn-wide", async () => {
        try {
          await refreshMe();
          if (!walletNeedsRenewal()) {
            forceCloseModal();
            setFarmStatus("พร้อมใช้งานแล้ว", "ok");
          } else {
            setFarmStatus("ยังไม่มี Token หรือวันเช่า — กดเติมเงิน", "err");
          }
        } catch (_) {
          setFarmStatus("ตรวจยอดไม่สำเร็จ ลองใหม่", "err");
        }
      })
    );
    startBalancePoll();
    if (!topupPackages.length) {
      loadTopupPackages()
        .then(() => {
          if (modalMode === "empty" && modalBody) {
            modalBody.textContent = expiredBoth || noTokens
              ? "เติม Token หรือเช่าวันได้ที่หน้าเติมเงิน / เช่าวัน"
              : rentalRenewHint();
          }
        })
        .catch(() => {});
    }
  }

  function showRentalOnlyModal(feature) {
    if (!hasResolvedWebsiteProfile()) {
      openAuthModal("login");
      return;
    }
    const key = normalizeFeatureKey(feature);
    const label = FEATURE_LABEL_TH[key] || "ฟังก์ชันนี้";
    clearModalActions();
    openModal({
      mode: "empty",
      title: "สำหรับผู้เช่ารายวันเท่านั้น",
      body: label + " ใช้ได้เมื่อเช่ารายวัน — Token อย่างเดียวใช้ฟังก์ชันนี้ไม่ได้",
      icon: "assets/reward_icon_partyrun_ticket.png",
      locked: false,
    });
    modalActions.appendChild(
      makeBtn("ไปเช่าวัน", "btn-empty-vault", () => {
        closeModal();
        openVaultModal({ kind: "rental" });
      })
    );
  }

  function inviteMaintenanceActive(value = inviteMaintenance) {
    return !!(value && value.maintenance);
  }

  function formatInviteMaintenanceEta(seconds) {
    const total = Math.max(0, Math.ceil(Number(seconds) || 0));
    if (!total) return "กำลังประเมินเวลาที่เหลือ…";
    const minutes = Math.floor(total / 60);
    const remain = total % 60;
    return minutes > 0
      ? "เหลือประมาณ " + formatNumTh(minutes) + " นาที " + formatNumTh(remain) + " วินาที"
      : "เหลือประมาณ " + formatNumTh(remain) + " วินาที";
  }

  function paintInviteMaintenance(value) {
    if (!value || !value.maintenance) {
      inviteMaintenance = null;
      const modal = $("invite-maintenance-modal");
      if (modal && !modal.classList.contains("hidden")) closeInviteMaintenanceModal();
      return false;
    }
    inviteMaintenance = value;
    const current = Math.max(0, Number(value.created_guests) || 0);
    const total = Math.max(0, Number(value.target_guests) || 0);
    const pct = total > 0 ? Math.min(100, Math.round((current / total) * 100)) : 0;
    if ($("invite-maintenance-current")) $("invite-maintenance-current").textContent = formatNumTh(current);
    if ($("invite-maintenance-total")) $("invite-maintenance-total").textContent = formatNumTh(total);
    if ($("invite-maintenance-fill")) {
      $("invite-maintenance-fill").style.transform = "scaleX(" + pct / 100 + ")";
    }
    if ($("invite-maintenance-eta")) {
      const waiting = value.phase === "waiting_worker";
      $("invite-maintenance-eta").textContent = waiting
        ? "กำลังรอ Light worker ว่าง · " + formatInviteMaintenanceEta(value.eta_seconds)
        : formatInviteMaintenanceEta(value.eta_seconds);
    }
    if ($("invite-maintenance-detail")) {
      $("invite-maintenance-detail").textContent = String(
        value.message || "หน้าเชิญเพื่อนจะพร้อมใช้งานทันทีเมื่อสร้าง Guest ครบ"
      );
    }
    return true;
  }

  async function refreshInviteMaintenance() {
    try {
      const data = await api("/api/invite/maintenance", { timeoutMs: 12000 });
      paintInviteMaintenance(data?.maintenance);
      return data?.maintenance || null;
    } catch (_) {
      return inviteMaintenance;
    }
  }

  function openInviteMaintenanceModal(value = inviteMaintenance) {
    if (!inviteMaintenanceActive(value)) return;
    const modal = $("invite-maintenance-modal");
    if (!modal) return;
    paintInviteMaintenance(value);
    if (modal.classList.contains("hidden")) {
      animateOpen(modal);
      lockBodyScroll("invite-maintenance-open");
      trapFocus(modal.querySelector(".invite-maintenance-sheet") || modal);
    }
    if (!inviteMaintenancePollTimer) {
      inviteMaintenancePollTimer = setInterval(() => {
        refreshInviteMaintenance().then((state) => {
          if (!inviteMaintenanceActive(state)) return;
          paintInviteMaintenance(state);
        });
      }, 5000);
    }
  }

  function closeInviteMaintenanceModal() {
    const modal = $("invite-maintenance-modal");
    if (inviteMaintenancePollTimer) {
      clearInterval(inviteMaintenancePollTimer);
      inviteMaintenancePollTimer = null;
    }
    if (!modal || modal.classList.contains("hidden")) return;
    unlockBodyScroll("invite-maintenance-open");
    releaseFocusTrap();
    animateClose(modal);
  }

  let inviteTabOpening = false;
  async function openInviteFriendTab(opts = {}) {
    if (!requireNavMenuOpen(INVITE_TAB)) return;
    if (inviteTabOpening) return;
    inviteTabOpening = true;
    closeNavDrawer();
    if (window.matchMedia("(max-width: 860px)").matches) {
      setFarmSidebarOpen(false);
    }
    setFarmBusy(true, "กำลังเปิดหน้าเชิญเพื่อน…");
    paintInviteStatsSkeleton();
    try {
      const maintenance = await refreshInviteMaintenance().catch(() => null);
      if (inviteMaintenanceActive(maintenance)) {
        setFarmBusy(false);
        openInviteMaintenanceModal(maintenance);
        return;
      }
      switchFarmTab(INVITE_TAB, { silent: true, replaceRoute: !!opts.replaceRoute });
      await refreshInviteStatus().catch(() => {});
      resumeInviteJobIfAny().catch(() => {});
    } catch (_) {
      switchFarmTab(INVITE_TAB, { silent: true, replaceRoute: !!opts.replaceRoute });
    } finally {
      setFarmBusy(false);
      inviteTabOpening = false;
    }
  }

  function loadInviteGuestSession() {
    try {
      const raw = localStorage.getItem(INVITE_GUEST_TOKEN_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (!parsed?.token) return null;
      const expiry = Number(parsed.expiresAt || 0);
      if (expiry && expiry <= Date.now()) {
        localStorage.removeItem(INVITE_GUEST_TOKEN_KEY);
        return null;
      }
      inviteGuestToken = String(parsed.token);
      inviteGuestExpiresAt = expiry || null;
      return inviteGuestToken;
    } catch (_) {
      return null;
    }
  }

  function persistInviteGuestSession(data) {
    const token = String(data?.guest_token || "").trim();
    if (!token) return false;
    inviteGuestToken = token;
    inviteGuestExpiresAt = data?.expires_at ? Date.parse(data.expires_at) : null;
    try {
      localStorage.setItem(
        INVITE_GUEST_TOKEN_KEY,
        JSON.stringify({ token, expiresAt: inviteGuestExpiresAt || 0 })
      );
    } catch (_) {}
    return true;
  }

  function clearInviteGuestSession() {
    inviteGuestToken = null;
    inviteGuestExpiresAt = null;
    inviteGuestCreditBalance = 0;
    try {
      localStorage.removeItem(INVITE_GUEST_TOKEN_KEY);
    } catch (_) {}
  }

  async function ensureInviteGuestSession() {
    if (accessToken) return null;
    if (inviteGuestToken && (!inviteGuestExpiresAt || inviteGuestExpiresAt > Date.now())) {
      return inviteGuestToken;
    }
    clearInviteGuestSession();
    const data = await api("/api/invite/guest/bootstrap", {
      method: "POST",
      body: {},
      _skipAuthSync: true,
    });
    if (!persistInviteGuestSession(data)) throw new Error("invite_guest_session_failed");
    return inviteGuestToken;
  }

  function inviteGuestJobPath(jobId, suffix = "") {
    if (!accessToken && inviteGuestToken) {
      return "/api/invite/guest/job/" + encodeURIComponent(jobId) + suffix;
    }
    return "/api/farm/job/" + encodeURIComponent(jobId) + suffix;
  }

  function inviteCreditBalance() {
    if (!accessToken) return Number(inviteGuestCreditBalance || 0) || 0;
    return tokenBalance();
  }

  function inviteCreditLinks() {
    const cost = inviteLinkCost() || 14;
    return Math.max(0, Math.floor(inviteCreditBalance() / cost));
  }

  function inviteUsesRental(data) {
    if (data && data.rental_ok != null) return !!data.rental_ok;
    if (data && data.billing === "rental") return true;
    if (inviteRentalOk) return true;
    return !!(accessToken && hasFeatureAccess("invite"));
  }

  function persistInviteJob(jobId, creditsCharged) {
    inviteActiveJobId = jobId || null;
    if (creditsCharged != null) {
      inviteLastCharge = Number(creditsCharged) || 14;
    }
    try {
      if (jobId) {
        sessionStorage.setItem(INVITE_JOB_KEY, String(jobId));
        sessionStorage.setItem(INVITE_CHARGE_KEY, String(inviteLastCharge));
      } else {
        sessionStorage.removeItem(INVITE_JOB_KEY);
        sessionStorage.removeItem(INVITE_CHARGE_KEY);
      }
    } catch (_) {}
  }

  function loadPersistedInviteJob() {
    try {
      const id = sessionStorage.getItem(INVITE_JOB_KEY);
      const charge = sessionStorage.getItem(INVITE_CHARGE_KEY);
      if (charge != null) inviteLastCharge = Number(charge) || 14;
      return id || null;
    } catch (_) {
      return null;
    }
  }

  function setInviteRunning(on) {
    inviteRunning = !!on;
    const panel = document.querySelector(".invite-panel");
    panel?.classList.toggle("is-invite-running", inviteRunning);
    document.body.classList.toggle("invite-job-running", inviteRunning);
    $("menu-nav-invite")?.classList.toggle("is-live-running", inviteRunning);
    const startBtn = $("invite-start-btn");
    const link = $("invite-link-input");
    const topupBtn = $("invite-credit-open-btn");
    const refreshBtn = $("invite-refresh-btn");
    const title = $("invite-start-btn-title");
    const cancelBtn = $("invite-cancel-btn");
    if (title) {
      title.textContent = inviteRunning
        ? "กำลังเชิญเพื่อน…"
        : inviteQueueRows.length > 1
          ? "เริ่มคิวเชิญเพื่อน"
          : "เริ่มคิวเชิญเพื่อน";
    }
    // Paste/add stays open; rows already submitted stay locked via paintInviteQueue.
    if (link) link.disabled = !!inviteQueueStarting;
    if (refreshBtn) refreshBtn.disabled = inviteRunning || inviteQueueStarting;
    if (cancelBtn) {
      cancelBtn.hidden = !inviteRunning;
      cancelBtn.classList.toggle("hidden", !inviteRunning);
      if (!inviteRunning) {
        cancelBtn.disabled = false;
        cancelBtn.textContent = "ยกเลิก";
      }
    }
    if (inviteRunning) {
      const room = queueHasRoom();
      if (startBtn) {
        startBtn.disabled = !room;
        startBtn.classList.toggle("is-disabled-look", !room);
      }
      if ($("invite-start-btn-sub")) {
        $("invite-start-btn-sub").textContent = inviteQueueStarting
          ? "กำลังส่งคิว…"
          : room
            ? "กำลังรัน — เพิ่มเป้าหมายในรายการได้"
            : "คิวเต็ม — รอให้งานเสร็จก่อน";
      }
      if (topupBtn) {
        topupBtn.disabled = true;
        topupBtn.classList.add("is-disabled-look");
        topupBtn.title = "รอให้งานเชิญเพื่อนเสร็จก่อน";
      }
    } else {
      // Re-apply idle enable rules from latest stats
      paintInviteStats({
        invite_credit_balance: inviteCreditBalance(),
        credit_links: inviteCreditLinksAvailable,
        pool_links: invitePoolLinksAvailable,
        runnable_links: inviteLinksAvailable,
        rental_ok: inviteRentalOk,
      });
    }
  }

  function showInviteProgressCard(_show) {
    /* Invite progress moved to the job hub. */
  }

  function inviteTargetGuests(job) {
    const result =
      job?.result && typeof job.result === "object" ? job.result : {};
    return (
      Number(result.target) ||
      Number(job?.params?.target_guests) ||
      Number(job?.progress?.total) ||
      29
    );
  }

  function inviteEffectiveCount(result) {
    if (!result || typeof result !== "object") return 0;
    if (result.success != null) return Number(result.success) || 0;
    if (result.effective != null) return Number(result.effective) || 0;
    return Number(result.invited || result.count || 0) || 0;
  }

  function paintInviteResultSummary(job) {
    const el = $("invite-result-summary");
    if (!el) return;
    const status = String(job?.status || "");
    if (!["succeeded", "failed", "cancelled"].includes(status)) {
      el.hidden = true;
      el.classList.add("hidden");
      el.textContent = "";
      return;
    }
    const result =
      job?.result && typeof job.result === "object" ? job.result : {};
    const target = inviteTargetGuests(job);
    const effective = inviteEffectiveCount(result);
    const failed = Number(result.failed) || 0;
    let text = "";
    const complete = effective >= target && target > 0;
    if (status === "cancelled") {
      text = "ยกเลิกแล้ว · ใช้ไป 1 Link (ไม่คืน)";
    } else if (complete) {
      text =
        "สำเร็จ " +
        formatNumTh(effective) +
        "/" +
        formatNumTh(target) +
        " · ใช้ 1 Link";
    } else if (effective === 0) {
      text = "ไม่สำเร็จ — คืน Link เต็ม";
    } else {
      text =
        "ไม่ครบ " +
        formatNumTh(target) +
        " — ได้ " +
        formatNumTh(effective) +
        "/" +
        formatNumTh(target) +
        " · ใช้ 1 Link" +
        (failed ? " · ล้มเหลว " + formatNumTh(failed) : "");
    }
    el.textContent = text;
    el.hidden = false;
    el.classList.remove("hidden");
    el.classList.toggle("is-ok", complete);
    el.classList.toggle("is-err", status === "failed" || status === "cancelled");
  }

  function paintInviteProgress(job, extras = {}) {
    const prog = job?.progress || {};
    const target = inviteTargetGuests(job);
    const current = Number(prog.current) || inviteEffectiveCount(job?.result) || 0;
    const total = Number(prog.total) || target;
    const lines = Array.isArray(job?.logs) ? job.logs : [];
    if (lines.length) inviteLogLines = lines.slice(-200);
    const logBody = $("invite-log-body");
    if (logBody && !$("invite-log-modal")?.classList.contains("hidden")) {
      logBody.textContent = inviteLogLines.length
        ? inviteLogLines.join("\n")
        : "ยังไม่มี log";
    }
    paintInviteResultSummary(job);
    if (job?.id) {
      attachCreditJobToHub("invite", job, {
        target: total,
        startedNow: !!extras.startedNow,
      });
    }
  }

  function selectedInviteCoins() {
    const list = quickInvitePackages();
    const pkg =
      list.find((p) => p.id === inviteSelectedPackageId) || list[0] || null;
    return Number(pkg?.price_baht || 14) || 14;
  }

  function paintInviteSelectedCoin() {
    const amount = selectedInviteCoins() || 0;
    const el = $("invite-selected-coin");
    if (el) el.textContent = formatNumTh(amount);
    if ($("invite-selected-coin-wallet")) {
      $("invite-selected-coin-wallet").textContent = formatNumTh(amount);
    }
    const pkg = quickInvitePackages().find((p) => p.id === inviteSelectedPackageId) || quickInvitePackages()[0];
    const links = Number(pkg?.links || 1) || 1;
    if ($("invite-selected-links")) $("invite-selected-links").textContent = formatNumTh(links);
    if ($("invite-credit-balance-label")) {
      $("invite-credit-balance-label").textContent = formatNumTh(inviteCreditLinks());
    }
  }

  async function copyInviteCoinAmount(amount) {
    const text = String(amount != null ? amount : selectedInviteCoins());
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(text);
      } else {
        const ta = document.createElement("textarea");
        ta.value = text;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        ta.remove();
      }
      setStatus($("invite-credit-status"), "คัดลอกยอด " + text + " บาทแล้ว", "ok");
      showToast("คัดลอกยอด " + text + " บาทแล้ว", "ok");
      return true;
    } catch (_) {
      setStatus($("invite-credit-status"), "คัดลอกไม่สำเร็จ — ใช้ยอด " + text + " บาท", "err");
      showToast("คัดลอกไม่สำเร็จ — ใช้ยอด " + text + " บาท", "err");
      return false;
    }
  }

  async function cancelInviteJob() {
    const jobId = inviteActiveJobId || loadPersistedInviteJob();
    if (!jobId || !inviteRunning) return;
    const btn = $("invite-cancel-btn");
    if (btn) {
      btn.disabled = true;
      btn.textContent = "กำลังยกเลิก…";
    }
    setStatus($("invite-status"), "กำลังยกเลิกงาน…", "muted");
    try {
      await cancelServerJob(jobId);
      // Soft-cancel may stay running briefly — keep polling until terminal.
      showToast("ส่งคำขอยกเลิกแล้ว", "ok");
      if (!invitePollTimer) pollInviteJob(jobId);
    } catch (e) {
      setStatus(
        $("invite-status"),
        String(e?.userMessage || e?.message || "ยกเลิกไม่สำเร็จ"),
        "err"
      );
      if (btn) {
        btn.disabled = false;
        btn.textContent = "ยกเลิก";
      }
    }
  }

  function openInviteLogModal() {
    openCreditLogModal(inviteLogLines, "Log งานเชิญเพื่อน");
  }

  function openCreditLogModal(lines, title) {
    const modal = $("invite-log-modal");
    if (!modal) return;
    const heading = $("invite-log-title");
    if (heading) heading.textContent = title || "Log งาน";
    const body = $("invite-log-body");
    if (body) {
      const rows = Array.isArray(lines) ? lines : [];
      body.textContent = rows.length ? rows.join("\n") : "ยังไม่มี log";
    }
    animateOpen(modal);
    lockBodyScroll("invite-log-open");
    const sheet = modal.querySelector(".invite-log-sheet") || modal;
    trapFocus(sheet);
  }

  function closeInviteLogModal() {
    const modal = $("invite-log-modal");
    if (!modal) return;
    unlockBodyScroll("invite-log-open");
    releaseFocusTrap();
    animateClose(modal);
  }

  function showInviteResultModal(job) {
    const result =
      job?.result && typeof job.result === "object" ? job.result : {};
    const ok = !!result.ok;
    const target = inviteTargetGuests(job);
    const effective = inviteEffectiveCount(result);
    const success = Number(result.success) || 0;
    const failed = Number(result.failed) || 0;
    const already = Number(result.already) || 0;
    const mid =
      result.target_mid ||
      job?.params?.target_mid ||
      "—";
    const complete = effective >= target && target > 0;
    let statusLabel = "ไม่สำเร็จ";
    if (complete) {
      statusLabel = "สำเร็จ";
    } else if (effective > 0) {
      statusLabel = "ไม่ครบ " + formatNumTh(effective) + "/" + formatNumTh(target);
    } else if (effective === 0) {
      statusLabel = "ไม่สำเร็จ";
    }
    const rows = [
      ["สถานะ", statusLabel],
      ["Target MID", escapeHtml(String(mid))],
      ["เป้าหมาย", formatNumTh(target) + " คน"],
      ["ได้จริง", formatNumTh(effective) + " / " + formatNumTh(target)],
      ["สำเร็จ (ใหม่)", formatNumTh(success)],
      ["มี referrer แล้ว", formatNumTh(already)],
      ["ล้มเหลว", formatNumTh(failed)],
    ];
    if (!ok && (job?.error || result.error)) {
      rows.push(["รายละเอียด", escapeHtml(String(job.error || result.error))]);
    }
    const html =
      '<table class="result-table"><tbody>' +
      rows
        .map(([k, v]) => `<tr><th>${k}</th><td>${v}</td></tr>`)
        .join("") +
      "</tbody></table>";
    clearModalActions();
    openModal({
      mode: "result",
      title: complete ? "เชิญเพื่อนสำเร็จ" : "เชิญเพื่อนจบแล้ว",
      bodyHtml: html,
      icon: "assets/gi/invite29.png",
      locked: false,
    });
    modalActions.appendChild(
      makeBtn("ตกลง", "btn-candy", () => forceCloseModal())
    );
    modalActions.appendChild(
      makeBtn("ดู Log", "btn-ghost", () => {
        forceCloseModal();
        openInviteLogModal();
      })
    );
  }

  function paintInviteStatsSkeleton() {
    const pool = $("invite-stat-pool-links");
    const guests = $("invite-stat-pool-guests");
    const credit = $("invite-stat-credit-links");
    const runnable = $("invite-stat-runnable-links");
    if (pool) pool.innerHTML = '<span class="invite-stat-skeleton skeleton-shimmer"></span>';
    if (guests) guests.innerHTML = '<span class="invite-stat-skeleton-sm skeleton-shimmer"></span>';
    if (credit) credit.innerHTML = '<span class="invite-stat-skeleton skeleton-shimmer"></span>';
    if (runnable) runnable.innerHTML = '<span class="invite-stat-skeleton-inline skeleton-shimmer"></span>';
  }

  function paintInviteStats(data) {
    const hasMaintenance = !!(
      data && Object.prototype.hasOwnProperty.call(data, "maintenance")
    );
    const maintenanceOn = hasMaintenance
      ? paintInviteMaintenance(data.maintenance)
      : inviteMaintenanceActive();
    const rawLinks = data?.runnable_links ?? data?.links_available;
    const cost = inviteLinkCost() || 14;
    const rentalOk = inviteUsesRental(data);
    inviteRentalOk = rentalOk;
    const creditBalance = data?.invite_credit_balance ?? data?.token_balance ?? inviteCreditBalance();
    const creditLinks = data?.credit_links != null
      ? Math.max(0, Number(data.credit_links) || 0)
      : Math.max(0, Math.floor((Number(creditBalance) || 0) / cost));
    const poolLinks = data?.pool_links != null
      ? Math.max(0, Number(data.pool_links) || 0)
      : invitePoolLinksAvailable;
    const links = rawLinks != null
      ? Math.max(0, Number(rawLinks) || 0)
      : (rentalOk ? poolLinks : Math.min(poolLinks, creditLinks));
    inviteLinksAvailable = links;
    invitePoolLinksAvailable = poolLinks;
    inviteCreditLinksAvailable = creditLinks;
    if (profile && data?.token_balance != null) {
      profile.token_balance = Number(data.token_balance) || 0;
    }
    if (profile && data?.invite_credit_balance != null) {
      profile.invite_credit_balance = Number(data.invite_credit_balance) || 0;
    }
    if (!accessToken && (data?.token_balance != null || data?.invite_credit_balance != null)) {
      inviteGuestCreditBalance = Number(data.token_balance ?? data.invite_credit_balance) || 0;
    }
    paintTokenBalance();
    if ($("invite-stat-pool-links")) {
      $("invite-stat-pool-links").textContent = formatNumTh(poolLinks);
    }
    if ($("invite-stat-pool-guests")) {
      const guests = data?.pool_ready_guests != null
        ? Math.max(0, Number(data.pool_ready_guests) || 0)
        : poolLinks * 29;
      $("invite-stat-pool-guests").textContent = formatNumTh(guests) + " Guest พร้อมใช้";
    }
    if ($("invite-credit-links-caption")) {
      $("invite-credit-links-caption").textContent = rentalOk
        ? "สิทธิ์วันเช่า"
        : "Link จาก Token ของคุณ";
    }
    if ($("invite-stat-credit-links")) {
      $("invite-stat-credit-links").textContent = rentalOk ? "ไม่จำกัด" : formatNumTh(creditLinks);
      $("invite-stat-credit-links").classList.toggle("is-unlimited", rentalOk);
    }
    if ($("invite-stat-runnable-links")) {
      $("invite-stat-runnable-links").textContent = formatNumTh(links);
    }
    if ($("invite-billing-note-extra")) {
      $("invite-billing-note-extra").textContent = rentalOk
        ? "· มีวันเช่าแล้วใช้ได้ไม่จำกัด"
        : "· หัก Token ตอนเริ่มงาน · มีวันเช่าแล้วไม่หัก";
    }
    if ($("invite-start-btn-sub") && !inviteRunning && !inviteBusy) {
      $("invite-start-btn-sub").textContent = rentalOk && links > 0
        ? "มีวันเช่า · ใช้ได้ไม่จำกัด"
        : links > 0
          ? "ใช้ " + formatTokenAmount(cost) + " Token · 1 Link"
          : poolLinks < 1
            ? "กำลังรอ Link ในระบบ"
            : rentalOk
              ? "กำลังรอ Link ในระบบ"
              : "เติม Token ก่อนเริ่มงาน";
    }
    const startBtn = $("invite-start-btn");
    if (startBtn) {
      const starting = inviteBusy && !inviteRunning;
      const running = !!inviteRunning;
      const canRun = !inviteBusy && !maintenanceOn && links > 0;
      setBtnLoading(startBtn, starting);
      const inviteSub = $("invite-start-btn-sub");
      if (starting) {
        startBtn.disabled = true;
        startBtn.classList.toggle("is-disabled-look", true);
        if (inviteSub) inviteSub.textContent = "กำลังส่งเข้าคิวงาน…";
      } else if (running) {
        const ok = canRun && queueHasRoom();
        startBtn.disabled = !ok;
        startBtn.classList.toggle("is-disabled-look", !ok);
        if (inviteSub) inviteSub.textContent = ok ? "กำลังรัน — กดเพื่อเข้าคิวเพิ่ม" : "กำลังรัน…";
      } else {
        startBtn.classList.toggle("is-disabled-look", !canRun);
        startBtn.disabled = !canRun;
      }
    }
    const note = $("invite-pool-empty-note");
    if (note) {
      note.hidden = links > 0 && !maintenanceOn;
      note.classList.toggle("hidden", links > 0 && !maintenanceOn);
      note.textContent = maintenanceOn
        ? "กำลังสร้าง Guest ใหม่ — หน้าเชิญเพื่อนจะเปิดใช้งานเมื่อสร้างครบ"
        : poolLinks < 1
          ? "ระบบยังไม่มี Link พร้อมใช้ — กรุณารอให้ระบบเติม Guest"
          : rentalOk
            ? "ยังไม่มี Link ที่ใช้เริ่มงานได้ในขณะนี้"
            : creditLinks < 1
              ? "มี Link ในระบบแล้ว แต่ Token ไม่พอ — เติม Token ก่อนเริ่มงาน หรือใช้วันเช่า"
              : "ยังไม่มี Link ที่ใช้เริ่มงานได้ในขณะนี้";
    }
    paintInviteSelectedCoin();
  }

  async function refreshInviteStatus() {
    try {
      if (!accessToken) await ensureInviteGuestSession();
      const data = await api("/api/invite/status");
      if (data?.invite_credit_balance != null && profile) {
        profile.invite_credit_balance = data.invite_credit_balance;
      }
      if (data?.token_balance != null && profile) profile.token_balance = data.token_balance;
      if (!accessToken && (data?.token_balance != null || data?.invite_credit_balance != null)) {
        inviteGuestCreditBalance = Number(data.token_balance ?? data.invite_credit_balance) || 0;
      }
      paintInviteStats(data);
      paintTokenBalance();
      return data;
    } catch (_) {
      paintInviteStats({ invite_credit_balance: inviteCreditBalance() });
      return null;
    }
  }

  function openInviteCreditModal() {
    const modal = $("invite-credit-modal");
    if (!modal) return;
    if (inviteRunning) {
      setStatus($("invite-status"), "รอให้งานเชิญเพื่อนเสร็จก่อน", "err");
      showToast("รอให้งานเชิญเพื่อนเสร็จก่อน", "err");
      return;
    }
    paintInviteStats({ invite_credit_balance: inviteCreditBalance() });
    setStatus($("invite-credit-status"), "", "muted");
    if ($("invite-credit-voucher")) $("invite-credit-voucher").value = "";
    // Must use animateOpen + is-open — otherwise invisible overlay freezes the page.
    renderInviteCreditPackages();
    paintInviteSelectedCoin();
    resetCheckoutFlow("invite");
    if (inviteSlipCtl) {
      inviteSlipCtl.applyKbank();
      inviteSlipCtl.reset();
    }
    animateOpen(modal);
    lockBodyScroll("invite-credit-open");
    const sheet = modal.querySelector(".invite-credit-sheet") || modal;
    trapFocus(sheet);
    loadInvitePackages()
      .then(() => {
        renderInviteCreditPackages();
        paintInviteSelectedCoin();
        if (inviteSlipCtl) {
          inviteSlipCtl.applyKbank();
          inviteSlipCtl.refreshQr();
        }
      })
      .catch(() => {
        invitePackages = OFFICIAL_INVITE_PACKAGES.slice();
        renderInviteCreditPackages();
        paintInviteSelectedCoin();
      });
    if (!accessToken && !inviteGuestToken) {
      ensureInviteGuestSession()
        .then(() => {
          if (inviteSlipCtl) inviteSlipCtl.refreshQr();
        })
        .catch(() => {
          setStatus($("invite-credit-status"), "เริ่มเซสชัน Guest ไม่สำเร็จ — ลองใหม่อีกครั้ง", "err");
        });
    }
  }

  function closeInviteCreditModal() {
    const modal = $("invite-credit-modal");
    if (!modal) return;
    resetCheckoutFlow("invite");
    unlockBodyScroll("invite-credit-open");
    releaseFocusTrap();
    animateClose(modal);
    setStatus($("invite-credit-status"), "", "muted");
  }

  async function loadInvitePackages() {
    invitePackages = OFFICIAL_INVITE_PACKAGES.slice();
    try {
      const data = await api("/api/invite/packages", { timeoutMs: 8000 });
      if (Array.isArray(data?.packages) && data.packages.length) {
        invitePackages = data.packages;
      }
      if (data && (data.promptpay || data.kbank_account)) {
        inviteKbankAccount = data.promptpay || data.kbank_account;
      }
    } catch (_) {
      invitePackages = OFFICIAL_INVITE_PACKAGES.slice();
    }
    if (!invitePackages.some((p) => p.id === inviteSelectedPackageId)) {
      inviteSelectedPackageId = invitePackages[0]?.id || "invite_14";
    }
    return invitePackages;
  }

  function fallbackInvitePackages() {
    return OFFICIAL_INVITE_PACKAGES.slice();
  }

  function quickInvitePackages() {
    const wanted = OFFICIAL_INVITE_PACKAGES.map((p) => [p.id, p.price_baht, p.credits, p.links]);
    const source = Array.isArray(invitePackages) && invitePackages.length ? invitePackages : OFFICIAL_INVITE_PACKAGES;
    return wanted.map(([id, price, credits, links]) => {
      const found = source.find((p) => p.id === id);
      return (
        found || {
          id,
          credits,
          price_baht: price,
          links,
          label_th: price + " บาท · " + links + " Link",
        }
      );
    });
  }

  function renderInviteCreditPackages() {
    const root = $("invite-credit-packages");
    if (!root) return;
    root.innerHTML = "";
    const list = quickInvitePackages();
    if (!inviteSelectedPackageId) {
      inviteSelectedPackageId = list[0]?.id || "invite_14";
    }
    list.forEach((pkg) => {
      const price = Number(pkg.price_baht || 0) || 0;
      const links = Number(pkg.links || Math.floor(Number(pkg.credits || 0) / 14) || 1);
      const selected = pkg.id === inviteSelectedPackageId;
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "invite-pack-btn" + (selected ? " is-selected" : "");
      btn.dataset.pack = pkg.id;
      btn.setAttribute("role", "option");
      btn.setAttribute("aria-selected", selected ? "true" : "false");
      btn.title = formatNumTh(price) + " บาท · " + formatNumTh(links) + " Link · แตะเพื่อเลือก";
      btn.innerHTML =
        '<span class="invite-pack-price">' +
        escapeHtml(formatNumTh(price)) +
        ' <small>บาท</small></span>' +
        '<span class="invite-pack-detail">' +
        escapeHtml(formatNumTh(links)) +
        ' Link</span>';
      btn.addEventListener("click", () => {
        inviteSelectedPackageId = pkg.id;
        renderInviteCreditPackages();
        paintInviteSelectedCoin();
        if (checkoutSheet("invite")?.dataset.ckoStep === "pay-slip" && inviteSlipCtl) {
          inviteSlipCtl.refreshQr();
        }
      });
      root.appendChild(btn);
    });
    paintInviteSelectedCoin();
  }

  function inviteDetailFromError(e) {
    const detail =
      e?.data?.detail && typeof e.data.detail === "object" ? e.data.detail : null;
    const code = e?.code || detail?.code;
    if (code !== "invite_credit_voucher" && code !== "use_invite_topup_endpoint") {
      return null;
    }
    return detail || { code, message: e?.userMessage || e?.message };
  }

  function idshopDetailFromError(e) {
    const detail =
      e?.data?.detail && typeof e.data.detail === "object" ? e.data.detail : null;
    const code = e?.code || detail?.code;
    if (code !== "idshop_credit_voucher") return null;
    return detail || { code, message: e?.userMessage || e?.message };
  }

  function routeInviteCreditVoucher(voucher, detail) {
    const v = String(voucher || "").trim();
    const packageId = detail?.invite_package_id || detail?.package_id;
    if (packageId && quickInvitePackages().some((p) => p.id === packageId)) {
      inviteSelectedPackageId = packageId;
    }
    closeVaultModal();
    openInviteCreditModal();
    setCheckoutFlowStep("invite", "pay-slip", { instant: true });
    const selected = quickInvitePackages().find((p) => p.id === inviteSelectedPackageId) || quickInvitePackages()[0];
    const price = Number(selected?.price_baht || 14);
    setStatus(
      $("invite-credit-status"),
      "เลือกแพ็ก " + formatNumTh(price) + " บาท · สแกน QR แล้วแนบสลิป",
      "ok"
    );
    showToast("พาไปเติม Link แล้ว", "ok");
  }

  function routeIdshopCreditVoucher(voucher, detail) {
    const v = String(voucher || "").trim();
    const packageId = detail?.idshop_package_id || detail?.package_id;
    const list = idshopCreditPacks();
    if (packageId && list.some((p) => p.id === packageId)) {
      idshopSelectedPackageId = packageId;
      const found = list.find((p) => p.id === packageId);
      idshopSelectedAmount = Number(found?.price_baht || 40);
    }
    closeVaultModal();
    openIdshopCreditModal();
    setCheckoutFlowStep("idshop", "pay-slip", { instant: true });
    const selected =
      idshopCreditPacks().find((p) => p.id === idshopSelectedPackageId) ||
      idshopCreditPacks()[0];
    const price = Number(selected?.price_baht || 40);
    setStatus(
      $("idshop-credit-status"),
      "เลือกแพ็ก " + formatNumTh(price) + " บาท · สแกน QR แล้วแนบสลิป",
      "ok"
    );
    showToast("พาไปเติมเครดิตไอดีแล้ว", "ok");
  }

  async function redeemInviteCredit() {
    if (inviteBusy) return;
    if (!accessToken) {
      try {
        await ensureInviteGuestSession();
      } catch (_) {
        setStatus($("invite-credit-status"), "เริ่มเซสชัน Guest ไม่สำเร็จ — ลองใหม่อีกครั้ง", "err");
        return;
      }
    }
    const voucher = String($("invite-credit-voucher")?.value || "").trim();
    if (!voucher) {
      setStatus($("invite-credit-status"), "วางลิงก์ซอง TrueMoney ก่อน", "err");
      return;
    }
    if (!inviteSelectedPackageId || !quickInvitePackages().some((p) => p.id === inviteSelectedPackageId)) {
      inviteSelectedPackageId = "invite_14";
    }
    if (inviteMaintenanceActive()) {
      openInviteMaintenanceModal();
      return;
    }
    const selected = quickInvitePackages().find((p) => p.id === inviteSelectedPackageId);
    const price = Number(selected?.price_baht || 0);
    const links = Number(selected?.links || 1);
    const body = { voucher, package_id: inviteSelectedPackageId };
    inviteBusy = true;
    setStatus($("invite-credit-status"), "กำลังตรวจสอบซองและเติม Link…", "muted");
    try {
      const data = await api("/api/invite/topup/redeem", {
        method: "POST",
        body,
      });
      if (profile && data.invite_credit_balance != null) {
        profile.invite_credit_balance = data.invite_credit_balance;
      }
      if (profile && data.token_balance != null) {
        profile.token_balance = data.token_balance;
      } else if (profile && data.invite_credit_balance != null) {
        profile.token_balance = data.invite_credit_balance;
      }
      if (!accessToken && (data.token_balance != null || data.invite_credit_balance != null)) {
        inviteGuestCreditBalance = Number(data.token_balance ?? data.invite_credit_balance) || 0;
      }
      paintInviteStats({
        token_balance: data.token_balance,
        invite_credit_balance: data.invite_credit_balance,
      });
      setStatus(
        $("invite-credit-status"),
        "เติม +" + formatNumTh(data.links_credited || links) + " Link สำเร็จ · ยอดซอง " + formatNumTh(price) + " บาท",
        "ok"
      );
      showToast("เติม Link สำเร็จ", "ok");
      if ($("invite-credit-voucher")) $("invite-credit-voucher").value = "";
      await refreshInviteStatus().catch(() => {});
      paintAfterplayStartEnabled();
      paintUnlockLQuote();
      paintIceTower();
    } catch (e) {
      setStatus(
        $("invite-credit-status"),
        topupFailMessage(e, "เติมไม่สำเร็จ"),
        "err"
      );
    } finally {
      inviteBusy = false;
    }
  }

  function inviteQueueUid() {
    inviteQueueSeq += 1;
    return "iq-" + Date.now().toString(36) + "-" + inviteQueueSeq;
  }

  function normalizeInviteTargetInput(raw) {
    return String(raw || "").trim();
  }

  function inviteTargetLooksLikeMid(s) {
    return /^[A-Za-z0-9]{8,12}$/.test(String(s || "").trim());
  }

  function inviteRowLabel(target, extra) {
    const t = normalizeInviteTargetInput(target);
    if (extra && extra.label) return String(extra.label);
    if (inviteTargetLooksLikeMid(t)) return t.toUpperCase();
    try {
      const u = new URL(t);
      return (u.hostname || "link") + "…" + t.slice(-8);
    } catch (_) {
      return t.length > 28 ? t.slice(0, 20) + "…" : t;
    }
  }

  function paintInviteQueue() {
    const list = $("invite-queue-list");
    const empty = $("invite-queue-empty");
    const countEl = $("invite-queue-count");
    if (countEl) {
      countEl.textContent = inviteQueueRows.length + " รายการ";
    }
    if (!list) return;
    list.innerHTML = "";
    if (!inviteQueueRows.length) {
      if (empty) {
        empty.hidden = false;
        empty.classList.remove("hidden");
      }
      return;
    }
    if (empty) {
      empty.hidden = true;
      empty.classList.add("hidden");
    }
    const statusTh = {
      idle: "รอ",
      resolving: "กำลังดึง…",
      pending: "รอส่ง",
      queued: "เข้าคิวแล้ว",
      running: "กำลังรัน",
      ok: "สำเร็จ",
      err: "ผิดพลาด",
    };
    inviteQueueRows.forEach((row, idx) => {
      const li = document.createElement("li");
      li.className = "invite-queue-item is-" + (row.status || "idle");
      li.dataset.queueId = row.id;
      const locked =
        inviteQueueStarting ||
        ["queued", "running", "ok"].includes(String(row.status || ""));

      const ord = document.createElement("span");
      ord.className = "invite-queue-ord";
      ord.textContent = String(idx + 1);

      const body = document.createElement("div");
      body.className = "invite-queue-item-body";
      const label = document.createElement("strong");
      label.className = "invite-queue-label";
      label.textContent = row.label || row.target;
      const meta = document.createElement("span");
      meta.className = "invite-queue-meta muted";
      const bits = [];
      if (row.mid && row.mid !== row.label) bits.push("MID " + row.mid);
      bits.push(statusTh[row.status] || row.status || "รอ");
      if (row.error) bits.push(row.error);
      meta.textContent = bits.join(" · ");
      body.append(label, meta);

      const rm = document.createElement("button");
      rm.type = "button";
      rm.className = "invite-queue-remove";
      rm.setAttribute("aria-label", "ลบเป้าหมาย");
      rm.textContent = "×";
      rm.disabled = locked;
      rm.addEventListener("click", () => removeInviteQueueRow(row.id));

      li.append(ord, body, rm);
      list.appendChild(li);
    });
    paintInviteDevPlayHelpers();
  }

  function addInviteQueueRow(target, opts) {
    const t = normalizeInviteTargetInput(target);
    if (!t) return null;
    const mid = String(opts?.mid || "").trim().toUpperCase() || null;
    // Dedupe by mid or exact target
    const key = (mid || t).toUpperCase();
    const dup = inviteQueueRows.some(
      (r) =>
        String(r.mid || r.target || "").trim().toUpperCase() === key ||
        String(r.target || "").trim() === t
    );
    if (dup) {
      setStatus($("invite-status"), "เป้าหมายนี้อยู่ในคิวแล้ว", "err");
      return null;
    }
    const row = {
      id: inviteQueueUid(),
      target: mid || t,
      mid: mid || (inviteTargetLooksLikeMid(t) ? t.toUpperCase() : null),
      label: inviteRowLabel(mid || t, opts),
      source: opts?.source || "paste",
      status: "idle",
      error: "",
      jobId: null,
    };
    inviteQueueRows.push(row);
    paintInviteQueue();
    setStatus(
      $("invite-status"),
      "เพิ่มแล้ว · " + row.label + " (" + inviteQueueRows.length + " รายการ)",
      "ok"
    );
    return row;
  }

  function removeInviteQueueRow(id) {
    if (inviteQueueStarting) return;
    inviteQueueRows = inviteQueueRows.filter((r) => r.id !== id);
    paintInviteQueue();
  }

  function markInviteQueueJobStatus(jobId, status, errorText) {
    const id = String(jobId || "").trim();
    if (!id) return;
    let changed = false;
    inviteQueueRows.forEach((row) => {
      if (String(row.jobId || "") !== id) return;
      row.status = status;
      if (errorText) row.error = String(errorText);
      else if (status === "ok") row.error = "";
      changed = true;
    });
    if (changed) paintInviteQueue();
  }

  function clearInviteDpLoginErrors() {
    const st = $("invite-dp-status");
    if (st) {
      st.textContent = "";
      st.hidden = true;
      st.classList.add("hidden");
      st.classList.remove("err", "ok", "muted", "is-err", "is-ok");
    }
  }

  function setInviteDpStatus(msg, kind) {
    const st = $("invite-dp-status");
    if (!st) return;
    st.textContent = msg || "";
    st.hidden = !msg;
    st.classList.toggle("hidden", !msg);
    st.classList.remove("err", "ok", "muted", "is-err", "is-ok");
    if (kind === "err") {
      st.classList.add("err", "is-err");
    } else if (kind === "ok") {
      st.classList.add("ok", "is-ok");
    } else {
      st.classList.add("muted");
    }
  }

  function paintInviteDevPlayHelpers() {
    const curBtn = $("invite-dp-current-btn");
    if (curBtn) {
      const mid = String(devplaySession?.mid || "").trim();
      const connected = isDevPlayConnected();
      const show = connected && !inviteQueueStarting;
      curBtn.hidden = !show;
      curBtn.classList.toggle("hidden", !show);
      curBtn.disabled = inviteQueueStarting;
      if (show) {
        const name = getDevPlayAccountDisplayName();
        curBtn.textContent = mid
          ? "ใช้บัญชีที่ล็อกอิน · " + name + " (" + mid + ")"
          : "ใช้บัญชีที่ล็อกอิน · " + name + " (ดึง MID)";
      }
    }
    const wrap = $("invite-dp-recent");
    if (!wrap) return;
    wrap.innerHTML = "";
    const entries = Array.isArray(devplayVaultEntries)
      ? devplayVaultEntries.slice(0, 5)
      : [];
    if (!entries.length || inviteQueueStarting) {
      wrap.hidden = true;
      wrap.classList.add("hidden");
      return;
    }
    wrap.hidden = false;
    wrap.classList.remove("hidden");
    const title = document.createElement("p");
    title.className = "invite-add-kicker";
    title.textContent = "บัญชีล่าสุด (สูงสุด 5)";
    wrap.appendChild(title);
    entries.forEach((entry) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "btn btn-ghost btn-sm invite-dp-recent-btn";
      const nick = entry.nickname || "player";
      const mail = maskDevPlayEmail(entry.email);
      const midHint = entry.mid ? " · " + entry.mid : "";
      btn.textContent = nick + " · " + mail + midHint;
      btn.disabled = inviteQueueStarting;
      btn.addEventListener("click", () => {
        addInviteQueueFromVaultEntry(entry).catch(() => {});
      });
      wrap.appendChild(btn);
    });
  }

  async function resolveInviteTargetViaApi(payload) {
    await ensureApiReady();
    if (!accessToken) {
      try {
        await ensureInviteGuestSession();
      } catch (_) {
        throw new Error("เริ่มเซสชัน Guest ไม่สำเร็จ");
      }
    }
    return api("/api/invite/resolve-target", {
      method: "POST",
      body: payload,
    });
  }

  function addInviteQueueFromPaste() {
    const input = $("invite-link-input");
    const raw = normalizeInviteTargetInput(input?.value);
    if (!raw) {
      setStatus($("invite-status"), "วาง MID หรือลิงก์ก่อน", "err");
      return;
    }
    const row = addInviteQueueRow(raw, { source: "paste" });
    if (row && input) input.value = "";
  }

  async function addInviteQueueFromDevPlayLogin() {
    clearInviteDpLoginErrors();
    const email = String($("invite-dp-mail")?.value || "").trim();
    const password = String($("invite-dp-secret")?.value || "");
    if (!email || !password) {
      setInviteDpStatus("กรอกอีเมลและรหัสผ่าน", "err");
      return;
    }
    setInviteDpStatus("กำลังดึง MID…", "muted");
    const secretEl = $("invite-dp-secret");
    try {
      const data = await resolveInviteTargetViaApi({ email, password });
      const mid = String(data.mid || "").trim().toUpperCase();
      if (!mid) throw new Error("ไม่พบ MID");
      addInviteQueueRow(mid, {
        mid,
        label: (data.nickname ? data.nickname + " · " : "") + mid,
        source: "devplay",
      });
      // Never keep password in the invite DOM after resolve.
      if (secretEl) secretEl.value = "";
      clearInviteDpLoginErrors();
      setInviteDpStatus("เพิ่ม MID " + mid + " แล้ว", "ok");
      // Cache mid on matching vault entry if present (no password in DOM list).
      const hit = devplayVaultEntries.find(
        (e) => String(e.email || "").trim().toLowerCase() === email.toLowerCase()
      );
      if (hit) hit.mid = mid;
      paintInviteDevPlayHelpers();
    } catch (e) {
      if (secretEl) secretEl.value = "";
      setInviteDpStatus(
        String(e?.userMessage || e?.message || thError(e?.code || e?.message) || "ดึง MID ไม่สำเร็จ"),
        "err"
      );
    }
  }

  async function addInviteQueueFromCurrentDevPlay() {
    clearInviteDpLoginErrors();
    if (!isDevPlayConnected()) {
      setInviteDpStatus("ยังไม่ได้ล็อกอิน DevPlay", "err");
      return;
    }
    let mid = String(devplaySession?.mid || "").trim().toUpperCase();
    const nick = getDevPlayAccountDisplayName();
    if (!mid) {
      const creds = getDevPlayCreds();
      if (!creds.email || !creds.password) {
        setInviteDpStatus("บัญชีปัจจุบันยังไม่มี MID — กรอกอีเมล/รหัสด้านบน", "err");
        return;
      }
      setInviteDpStatus("กำลังดึง MID จากบัญชีปัจจุบัน…", "muted");
      try {
        const data = await resolveInviteTargetViaApi({
          email: creds.email,
          password: creds.password,
        });
        mid = String(data.mid || "").trim().toUpperCase();
        if (devplaySession) devplaySession.mid = mid;
      } catch (e) {
        setInviteDpStatus(
          String(e?.userMessage || e?.message || "ดึง MID ไม่สำเร็จ"),
          "err"
        );
        return;
      }
    }
    if (!mid) {
      setInviteDpStatus("ไม่พบ MID ของบัญชีปัจจุบัน", "err");
      return;
    }
    addInviteQueueRow(mid, {
      mid,
      label: nick && nick !== "—" ? nick + " · " + mid : mid,
      source: "session",
    });
    clearInviteDpLoginErrors();
    setInviteDpStatus("เพิ่มแล้ว · " + mid, "ok");
  }

  async function addInviteQueueFromVaultEntry(entry) {
    clearInviteDpLoginErrors();
    const email = String(entry?.email || "").trim();
    const password = String(entry?.password || "");
    let mid = String(entry?.mid || "").trim().toUpperCase();
    const nick = entry?.nickname || maskDevPlayEmail(email) || "บัญชี";
    if (!mid) {
      if (!email || !password) {
        setInviteDpStatus("บัญชีนี้ไม่มีรหัสสำหรับดึง MID", "err");
        return;
      }
      setInviteDpStatus("กำลังดึง MID จากบัญชีล่าสุด…", "muted");
      try {
        const data = await resolveInviteTargetViaApi({ email, password });
        mid = String(data.mid || "").trim().toUpperCase();
        entry.mid = mid;
      } catch (e) {
        setInviteDpStatus(
          String(e?.userMessage || e?.message || "ดึง MID ไม่สำเร็จ"),
          "err"
        );
        return;
      }
    }
    if (!mid) {
      setInviteDpStatus("ไม่พบ MID", "err");
      return;
    }
    addInviteQueueRow(mid, {
      mid,
      label: nick + " · " + mid,
      source: "vault",
    });
    clearInviteDpLoginErrors();
    setInviteDpStatus("เพิ่มแล้ว · " + mid, "ok");
    paintInviteDevPlayHelpers();
  }

  async function waitForInviteQueueRoom(timeoutMs) {
    const limit = Math.max(10000, Number(timeoutMs) || 120000);
    const start = Date.now();
    while (Date.now() - start < limit) {
      await refreshAdvanceQueue();
      if (queueHasRoom()) return true;
      await new Promise((r) => setTimeout(r, 1200));
    }
    return queueHasRoom();
  }

  async function postInviteStartOne(target) {
    return api("/api/invite/start", {
      method: "POST",
      body: { target, workers: 5 },
    });
  }

  async function startInviteJob() {
    // Approach A: enqueue one /api/invite/start per queue row (reuse billing/pool).
    if (inviteBusy || inviteQueueStarting) return;
    if (!accessToken) {
      try {
        await ensureInviteGuestSession();
      } catch (_) {
        setStatus($("invite-status"), "เริ่มเซสชัน Guest ไม่สำเร็จ — ลองรีเฟรชหน้า", "err");
        return;
      }
    }
    // Allow one-shot paste: if list empty but input filled, add it first.
    const draft = normalizeInviteTargetInput($("invite-link-input")?.value);
    if (!inviteQueueRows.length && draft) {
      addInviteQueueRow(draft, { source: "paste" });
      if ($("invite-link-input")) $("invite-link-input").value = "";
    }
    const rows = inviteQueueRows.filter((r) => r.status !== "ok");
    if (!rows.length) {
      setStatus($("invite-status"), "เพิ่มเป้าหมายอย่างน้อย 1 รายการก่อน", "err");
      return;
    }
    if (inviteLinksAvailable < rows.length && !inviteUsesRental()) {
      // Soft warn — server still enforces per job; rental may cover.
      if (inviteLinksAvailable < 1) {
        setStatus(
          $("invite-status"),
          invitePoolLinksAvailable < 1
            ? "ระบบยังไม่มี Link พร้อมใช้ — กรุณารอให้ระบบเติม Guest"
            : "ยังไม่มี Link พร้อมใช้ — เติม Token ก่อน หรือใช้วันเช่า",
          "err"
        );
        return;
      }
    }
    if (inviteUsesRental() && invitePoolLinksAvailable < 1 && inviteLinksAvailable < 1) {
      setStatus(
        $("invite-status"),
        "ระบบยังไม่มี Link พร้อมใช้ — กรุณารอให้ระบบเติม Guest",
        "err"
      );
      return;
    }
    const inviteOk = await showInviteConfirmModal(rows.length);
    if (!inviteOk) {
      setStatus($("invite-status"), "ยกเลิกแล้ว", "muted");
      return;
    }
    inviteBusy = true;
    inviteQueueStarting = true;
    paintInviteQueue();
    setStatus($("invite-status"), "กำลังส่งคิว " + rows.length + " เป้าหมาย…", "muted");
    let firstLive = false;
    let submitted = 0;
    let failed = 0;
    try {
      for (let i = 0; i < inviteQueueRows.length; i++) {
        const row = inviteQueueRows[i];
        if (!row || row.status === "ok") continue;
        row.status = "pending";
        row.error = "";
        paintInviteQueue();
        if (anyJobLive() && !queueHasRoom()) {
          setStatus($("invite-status"), "คิวเต็ม — รอช่องว่างแล้วส่งต่อ…", "muted");
          const okRoom = await waitForInviteQueueRoom(180000);
          if (!okRoom) {
            row.status = "err";
            row.error = "คิวเต็ม";
            failed += 1;
            paintInviteQueue();
            showErrorModal(queueFullMessage(), "คิวเต็ม");
            break;
          }
        }
        const queueOnly = anyJobLive() || firstLive;
        try {
          const data = await postInviteStartOne(row.target);
          paintInviteStats({});
          const charged = data.token_cost ?? data.credits_charged;
          applyStartWallet(data);
          row.jobId = data.job_id || null;
          if (data.target_mid) {
            row.mid = String(data.target_mid).toUpperCase();
            if (!row.label || row.label === row.target) row.label = row.mid;
          }
          submitted += 1;
          if (queueOnly && data?.job_id) {
            row.status = "queued";
            announceQueuedJob(data, "เชิญเพื่อน 29 คน · " + (row.mid || row.label));
          } else {
            row.status = "running";
            firstLive = true;
            persistInviteJob(
              data.job_id,
              charged != null ? Number(charged) : inviteLinkCost()
            );
            if (data.queue) applyQueuePayload(data.queue);
            startAdvanceQueuePoll();
            inviteResultShownFor = null;
            inviteLogLines = ["job " + (data.job_id || "") + " queued…"];
            const summaryEl = $("invite-result-summary");
            if (summaryEl) {
              summaryEl.hidden = true;
              summaryEl.classList.add("hidden");
              summaryEl.textContent = "";
            }
            paintInviteProgress(
              {
                id: data.job_id,
                status: "queued",
                progress: { current: 0, total: 29, phase: "queued" },
                logs: inviteLogLines,
              },
              { startedNow: true }
            );
            setInviteRunning(true);
            if (data.job_id) pollInviteJob(data.job_id);
          }
          paintInviteQueue();
          await refreshInviteStatus().catch(() => {});
        } catch (e) {
          failed += 1;
          const detail =
            e?.data?.detail && typeof e.data.detail === "object"
              ? e.data.detail
              : e?.data;
          const code = e?.code || detail?.code;
          row.status = "err";
          row.error = String(
            e?.userMessage ||
              detail?.message ||
              e?.message ||
              thError(e?.data?.detail || e?.message) ||
              code ||
              "เริ่มไม่สำเร็จ"
          );
          paintInviteQueue();
          if (code === "already_running" || code === "queue_full") {
            showErrorModal(
              code === "queue_full" ? queueFullMessage() : ERR_TH.already_running,
              "คิวเต็ม"
            );
            refreshAdvanceQueue();
            resumeInviteJobIfAny().catch(() => {});
            break;
          } else if (code === "invite_pool_empty" || code === "invite_pool_race") {
            inviteLinksAvailable = 0;
            paintInviteStats({
              invite_credit_balance: inviteCreditBalance(),
              token_balance: inviteCreditBalance(),
              links_available: 0,
            });
            setStatus(
              $("invite-status"),
              "Pool ว่าง — หยุดส่งคิว · ระบบจะสร้าง Guest ให้อัตโนมัติเมื่อเริ่มงานได้",
              "err"
            );
            break;
          } else if (handleFarmBillingDenied(e)) {
            setStatus($("invite-status"), thError(e.message) || "Token ไม่พอ", "err");
            break;
          }
          // Continue remaining rows only for invalid-target style errors.
          if (code === "invalid_invite_link" || code === "invalid_invite_target") {
            continue;
          }
          break;
        }
      }
      if (submitted > 0) {
        setStatus(
          $("invite-status"),
          "ส่งคิวแล้ว " +
            submitted +
            "/" +
            rows.length +
            (failed ? " · ไม่สำเร็จ " + failed : "") +
            " · รันบน→ล่าง",
          failed && !submitted ? "err" : "ok"
        );
      } else if (failed) {
        setStatus($("invite-status"), "เริ่มคิวไม่สำเร็จ", "err");
      }
    } finally {
      inviteQueueStarting = false;
      inviteBusy = false;
      paintInviteQueue();
      setInviteRunning(inviteRunning);
    }
  }


  function stopInvitePoll() {
    if (invitePollTimer) {
      clearInterval(invitePollTimer);
      invitePollTimer = null;
    }
  }

  function isLoginFreeFarmTab(tab) {
    return (
      tab === INVITE_TAB ||
      tab === IDSHOP_TAB ||
      tab === IDSHOP_ORDERS_TAB ||
      tab === "guide" ||
      tab === "pricing" ||
      tab === "live"
    );
  }

  function wantsLocalApi() {
    try {
      return new URLSearchParams(location.search).get("api") === "local";
    } catch (_) {
      return false;
    }
  }

  function paintIdshopHeadWallet() {
    const wallet = $("idshop-wallet");
    const run = $("run");
    const show = farmTab === IDSHOP_TAB || farmTab === IDSHOP_ORDERS_TAB;
    if (wallet) {
      wallet.hidden = !show;
      wallet.classList.toggle("hidden", !show);
    }
    run?.classList.toggle("has-idshop-wallet", show);
  }

  function paintIdshopWallet() {
    if (accessToken) {
      paintTokenBalance();
      return;
    }
    const n = formatTokenAmount(idshopCreditBalance);
    if ($("idshop-credit-label")) $("idshop-credit-label").textContent = n;
    if ($("idshop-credit-balance-label")) $("idshop-credit-balance-label").textContent = n;
  }

  function idshopQuery() {
    const params = new URLSearchParams();
    const q = String($("idshop-q")?.value || "").trim();
    if (q) params.set("q", q);
    ["min_level", "min_gem", "min_life"].forEach((key) => {
      const el = $(
        key === "min_level" ? "idshop-min-level" : key === "min_gem" ? "idshop-min-gem" : "idshop-min-life"
      );
      const n = Number(el?.value || "");
      if (Number.isFinite(n) && n > 0) params.set(key, String(n));
    });
    const pmin = Number($("idshop-price-min")?.value || "");
    const pmax = Number($("idshop-price-max")?.value || "");
    if (Number.isFinite(pmin) && pmin > 0) params.set("price_min", String(pmin));
    if (Number.isFinite(pmax) && pmax > 0) params.set("price_max", String(pmax));
    if (idshopSelected.cookies.size) params.set("cookies", [...idshopSelected.cookies].join(","));
    if (idshopSelected.pets.size) params.set("pets", [...idshopSelected.pets].join(","));
    if (idshopSelected.treasures.size) params.set("treasures", [...idshopSelected.treasures].join(","));
    params.set("page", String(Math.max(1, idshopPage || 1)));
    params.set("limit", String(IDSHOP_PAGE_SIZE));
    params.set("view", "full");
    const qs = params.toString();
    return qs ? "?" + qs : "";
  }

  const IDSHOP_FILTER_KIND_META = {
    cookies: { title: "เลือกคุกกี้", hint: "เลือกหลายตัว = ไอดีต้องมีครบทุกตัว", label: "คุกกี้" },
    pets: { title: "เลือกสัตว์เลี้ยง", hint: "เลือกหลายตัว = ไอดีต้องมีครบทุกตัว", label: "สัตว์เลี้ยง" },
    treasures: { title: "เลือกสมบัติ", hint: "เลือกหลายตัว = ไอดีต้องมีครบทุกตัว", label: "สมบัติ" },
  };

  function idshopCode(row) {
    if (row && row.code) return String(row.code);
    const n = Number(row && row.stock_no);
    if (!Number.isFinite(n) || n <= 0) return "ID —";
    const width = n < 1000 ? 3 : String(Math.floor(n)).length;
    return "ID " + String(Math.floor(n)).padStart(width, "0");
  }

  function idshopNormCoupon(code) {
    return String(code || "").replace(/\s+/g, "").toUpperCase();
  }

  function idshopCouponErr(e) {
    if (e?.status === 401 || e?.status === 403) return "ต้องเข้าสู่ระบบแอดมินก่อนจัดการคูปอง";
    if (e?.status === 404) return "เซิร์ฟเวอร์ยังไม่มี API คูปอง — อัปเดต API แล้วลองใหม่";
    if (e?.status === 422) return "ข้อมูลคูปองไม่ถูกต้อง ตรวจรหัส วันที่ และค่าลด";
    const detail = e?.data?.detail && typeof e.data.detail === "object" && !Array.isArray(e.data.detail) ? e.data.detail : null;
    return e?.userMessage || detail?.message || thError(e?.message) || "คูปองใช้ไม่ได้";
  }

  function idshopActiveCouponCode() {
    return (
      idshopNormCoupon(idshopCouponQuote?.coupon?.code || idshopCouponQuote?.code || "") ||
      idshopNormCoupon(idshopCouponCode) ||
      ""
    );
  }

  function idshopPayBaht(row) {
    const list = Math.max(1, Number(row?.price_baht) || 0);
    if (row?.status === "sold" || row?.sold) return list;
    const coupon = idshopCouponQuote && idshopCouponQuote.coupon;
    if (!coupon) return list;
    if (list < Number(coupon.min_spend_baht || 0)) return list;
    if (String(coupon.kind) === "percent") {
      const off = Math.floor((list * Math.max(0, Math.min(100, Number(coupon.value) || 0))) / 100);
      return Math.max(1, list - off);
    }
    return Math.max(1, list - Math.max(0, Number(coupon.value) || 0));
  }

  function idshopCouponRemain(row) {
    if (!row?.expires_at) return "ไม่หมดอายุ";
    const sec = Number(row.remain_sec);
    if (Number.isFinite(sec)) {
      if (sec <= 0) return "หมดอายุแล้ว";
      if (sec < 3600) return "เหลือ " + formatNumTh(Math.max(1, Math.ceil(sec / 60))) + " นาที";
      if (sec < 86400) return "เหลือ " + formatNumTh(Math.floor(sec / 3600)) + " ชม.";
      return "เหลือ " + formatNumTh(Math.floor(sec / 86400)) + " วัน";
    }
    return "มีกำหนดหมดอายุ";
  }

  function mergeIdshopPublicCoupon(row) {
    if (!row || !row.code || row.visible === false) {
      idshopPublicCoupons = idshopPublicCoupons.filter((c) => String(c.id) !== String(row?.id || ""));
      paintIdshopCouponBar();
      return;
    }
    const id = String(row.id || "");
    const code = String(row.code || "");
    idshopPublicCoupons = [row].concat(
      idshopPublicCoupons.filter((c) => String(c.id) !== id && String(c.code) !== code)
    );
    paintIdshopCouponBar();
  }

  function paintIdshopCouponBar() {
    const active = idshopNormCoupon(idshopCouponCode);
    const html = idshopPublicCoupons
      .map((row) => {
        const code = String(row.code || "");
        const min = Number(row.min_spend_baht || 0);
        const remain = idshopCouponRemain(row);
        const parts = [];
        if (min) parts.push("ขั้นต่ำ ฿" + formatNumTh(min));
        if (remain) parts.push(remain);
        const metaText = parts.join(" • ") || "ไม่มีขั้นต่ำ";

        const valDisplay =
          row.kind === "percent"
            ? formatNumTh(row.value || 0) + "%"
            : "฿" + formatNumTh(row.value || 0);

        const on = idshopNormCoupon(code) === active;
        const titleBits = [
          row.label || "",
          metaText,
          on ? "แตะอีกครั้งเพื่อยกเลิก" : "กดเพื่อใช้คูปอง",
        ].filter(Boolean);

        return (
          '<button type="button" class="idshop-ticket' +
          (on ? " is-on" : "") +
          '" data-idshop-coupon="' +
          escapeHtml(code) +
          '" title="' +
          escapeHtml(titleBits.join(" · ")) +
          '" aria-pressed="' +
          (on ? "true" : "false") +
          '"><div class="idshop-ticket-left">' +
          '<div class="idshop-ticket-val">' +
          escapeHtml(valDisplay) +
          '</div><div class="idshop-ticket-sub">ส่วนลด</div>' +
          '</div><div class="idshop-ticket-mid">' +
          '<div class="idshop-ticket-code-row">' +
          '<span class="idshop-ticket-code">' +
          escapeHtml(code) +
          '</span><span class="idshop-ticket-label">' +
          escapeHtml(row.label || "ส่วนลด") +
          '</span></div><div class="idshop-ticket-meta">' +
          escapeHtml(metaText) +
          '</div></div><div class="idshop-ticket-right">' +
          '<span class="idshop-ticket-btn">' +
          (on ? "ใช้แล้ว ✓" : "ใช้โค้ด") +
          "</span></div></button>"
        );
      })
      .join("");
    const rail = $("idshop-coupon-rail");
    ["idshop-coupon-bar", "idshop-detail-coupons"].forEach((id) => {
      const root = $(id);
      if (!root) return;
      if (!idshopPublicCoupons.length) {
        root.innerHTML = "";
        root.hidden = true;
        return;
      }
      root.hidden = false;
      root.innerHTML = html;
    });
    if (rail) {
      rail.hidden = !idshopPublicCoupons.length;
    }
  }

  function setIdshopCouponCode(code, { preview = true, toggle = false } = {}) {
    const next = String(code || "").replace(/\s+/g, "");
    const now = Date.now();
    if (toggle && next && idshopNormCoupon(idshopCouponCode) === idshopNormCoupon(next)) {
      // Twin coupon rails + rapid re-clicks were turning a select into an
      // immediate deselect, so the UI showed a discounted price then bought
      // at the full 120 Token list price.
      if (now - idshopCouponToggleAt < 500) return;
      idshopCouponCode = "";
      idshopCouponQuote = null;
    } else {
      idshopCouponCode = next;
    }
    idshopCouponToggleAt = now;
    paintIdshopCouponBar();
    if (!preview) return;
    clearTimeout(idshopCouponPreviewTimer);
    idshopCouponPreviewTimer = setTimeout(() => previewIdshopCoupon().catch(() => {}), 220);
  }

  async function previewIdshopCoupon(listingId) {
    const code = String(idshopCouponCode || "").trim();
    const listing =
      listingId ||
      idshopDetailId ||
      (idshopListings.find((row) => row.status === "listed" && !row.sold) || {}).id;
    paintIdshopCouponBar();
    if (!code) {
      idshopCouponQuote = null;
      setStatus($("idshop-coupon-status"), "", "muted");
      if (idshopDetailId) paintIdshopDetail();
      paintIdshopGrid();
      return;
    }
    if (!listing) {
      idshopCouponQuote = null;
      setStatus($("idshop-coupon-status"), "เลือกไอดีเพื่อดูราคาหลังลด", "muted");
      paintIdshopGrid();
      return;
    }
    await ensureIdshopPreviewSession();
    try {
      const data = await api("/api/idshop/coupons/preview", {
        method: "POST",
        body: { listing_id: listing, coupon_code: code },
      });
      idshopCouponQuote = data;
      if (data?.coupon?.code) idshopCouponCode = String(data.coupon.code);
      const msg =
        "🏷️ " +
        (data?.coupon?.label || code) +
        " · จ่าย " +
        formatNumTh(data?.pay_baht) +
        " Token (จาก " +
        formatNumTh(data?.list_price_baht) +
        ")";
      setStatus($("idshop-coupon-status"), msg, "ok");
      if (idshopDetailId) setStatus($("idshop-detail-status"), msg, "ok");
      if (idshopDetailId) paintIdshopDetail();
      paintIdshopGrid();
    } catch (e) {
      idshopCouponQuote = null;
      const msg =
        e?.status === 401 ? "เข้าสู่ระบบเพื่อดูราคาหลังลด" : idshopCouponErr(e);
      setStatus($("idshop-coupon-status"), msg, e?.status === 401 ? "muted" : "err");
      if (idshopDetailId) setStatus($("idshop-detail-status"), msg, e?.status === 401 ? "muted" : "err");
      if (idshopDetailId) paintIdshopDetail();
      paintIdshopGrid();
    }
  }

  function idshopDateLocal(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    if (!Number.isFinite(d.getTime())) return "";
    const pad = (n) => String(n).padStart(2, "0");
    return (
      d.getFullYear() +
      "-" +
      pad(d.getMonth() + 1) +
      "-" +
      pad(d.getDate()) +
      "T" +
      pad(d.getHours()) +
      ":" +
      pad(d.getMinutes())
    );
  }

  function idshopDateInputIso(id) {
    const raw = String($(id)?.value || "").trim();
    if (!raw) return "";
    const d = new Date(raw);
    if (!Number.isFinite(d.getTime())) return "__invalid__";
    return d.toISOString();
  }

  function setIdshopAdminCouponStatus(msg, kind) {
    const el = $("admin-idshop-coupon-status");
    if (!el) return;
    el.textContent = msg || "";
    el.className = "status idshop-inline-status " + (kind || "muted");
  }

  function idshopCouponClientError(body) {
    if (!/^[A-Z0-9][A-Z0-9_-]{1,31}$/.test(String(body.code || ""))) {
      return "รหัสคูปองใช้ได้เฉพาะ A-Z 0-9 _ - ความยาว 2–32";
    }
    const value = Number(body.value);
    if (!Number.isFinite(value) || value < 1) return "ค่าลดต้องเป็นตัวเลข 1 ขึ้นไป";
    if (body.kind === "percent" && value > 100) return "ส่วนลดเปอร์เซ็นต์ต้องไม่เกิน 100";
    if (body.starts_at === "__invalid__" || body.expires_at === "__invalid__") {
      return "วันที่เริ่มหรือหมดอายุไม่ถูกต้อง";
    }
    return "";
  }

  function idshopCouponFormBody() {
    const maxRaw = String($("admin-idshop-coupon-max")?.value || "").trim();
    const body = {
      code: idshopNormCoupon($("admin-idshop-coupon-code")?.value),
      kind: $("admin-idshop-coupon-kind")?.value || "baht",
      value: Number($("admin-idshop-coupon-value")?.value || 0),
      min_spend_baht: Number($("admin-idshop-coupon-min")?.value || 0),
      max_uses_per_user: Number($("admin-idshop-coupon-per-user")?.value || 1) || 1,
      visible: !!$("admin-idshop-coupon-visible")?.checked,
    };
    const starts = idshopDateInputIso("admin-idshop-coupon-starts");
    const expires = idshopDateInputIso("admin-idshop-coupon-expires");
    if (starts) body.starts_at = starts;
    if (expires) body.expires_at = expires;
    if (maxRaw) body.max_uses = Number(maxRaw);
    return body;
  }

  function resetIdshopCouponForm() {
    idshopCouponEditId = "";
    if ($("admin-idshop-coupon-code")) $("admin-idshop-coupon-code").value = "";
    if ($("admin-idshop-coupon-kind")) $("admin-idshop-coupon-kind").value = "baht";
    if ($("admin-idshop-coupon-value")) $("admin-idshop-coupon-value").value = "5";
    if ($("admin-idshop-coupon-min")) $("admin-idshop-coupon-min").value = "50";
    if ($("admin-idshop-coupon-starts")) $("admin-idshop-coupon-starts").value = "";
    if ($("admin-idshop-coupon-expires")) $("admin-idshop-coupon-expires").value = "";
    if ($("admin-idshop-coupon-max")) $("admin-idshop-coupon-max").value = "";
    if ($("admin-idshop-coupon-per-user")) $("admin-idshop-coupon-per-user").value = "1";
    if ($("admin-idshop-coupon-visible")) $("admin-idshop-coupon-visible").checked = true;
    if ($("admin-idshop-coupon-save")) $("admin-idshop-coupon-save").textContent = "สร้างคูปอง";
    setIdshopAdminCouponStatus("", "muted");
  }

  function fillIdshopCouponForm(row) {
    idshopCouponEditId = String(row.id || "");
    if ($("admin-idshop-coupon-code")) $("admin-idshop-coupon-code").value = row.code || "";
    if ($("admin-idshop-coupon-kind")) $("admin-idshop-coupon-kind").value = row.kind || "baht";
    if ($("admin-idshop-coupon-value")) $("admin-idshop-coupon-value").value = String(row.value || 1);
    if ($("admin-idshop-coupon-min")) $("admin-idshop-coupon-min").value = String(row.min_spend_baht || 0);
    if ($("admin-idshop-coupon-starts")) $("admin-idshop-coupon-starts").value = idshopDateLocal(row.starts_at);
    if ($("admin-idshop-coupon-expires")) $("admin-idshop-coupon-expires").value = idshopDateLocal(row.expires_at);
    if ($("admin-idshop-coupon-max")) $("admin-idshop-coupon-max").value = row.max_uses ? String(row.max_uses) : "";
    if ($("admin-idshop-coupon-per-user")) $("admin-idshop-coupon-per-user").value = String(row.max_uses_per_user || 1);
    if ($("admin-idshop-coupon-visible")) $("admin-idshop-coupon-visible").checked = !!row.visible;
    if ($("admin-idshop-coupon-save")) $("admin-idshop-coupon-save").textContent = "บันทึกคูปอง";
  }

  function paintIdshopAdminCoupons(rows) {
    const root = $("admin-idshop-coupons");
    if (!root) return;
    idshopAdminCoupons = Array.isArray(rows) ? rows.slice() : idshopAdminCoupons;
    if (!idshopAdminCoupons.length) {
      root.innerHTML = '<p class="muted">ยังไม่มีคูปอง</p>';
      return;
    }
    root.innerHTML = idshopAdminCoupons
      .map((row) => {
        const used = Number(row.used_count || 0);
        const max = row.max_uses == null ? "ไม่จำกัด" : String(row.max_uses);
        return (
          '<div class="idshop-admin-row" data-coupon-id="' +
          escapeHtml(row.id) +
          '"><div><strong>' +
          escapeHtml(row.code || "") +
          '</strong><div class="muted">' +
          escapeHtml(row.label || "") +
          " · ขั้นต่ำ ฿" +
          escapeHtml(formatNumTh(row.min_spend_baht || 0)) +
          " · ใช้แล้ว " +
          escapeHtml(formatNumTh(used)) +
          "/" +
          escapeHtml(max) +
          (row.visible ? " · โชว์หน้าร้าน" : " · ซ่อน") +
          "</div></div><div>" +
          '<button type="button" class="btn btn-ghost btn-sm" data-idshop-coupon-edit="' +
          escapeHtml(row.id) +
          '">แก้</button> ' +
          '<button type="button" class="btn btn-ghost btn-sm" data-idshop-coupon-visible="' +
          escapeHtml(row.id) +
          '" data-visible="' +
          (row.visible ? "0" : "1") +
          '">' +
          (row.visible ? "ซ่อน" : "โชว์") +
          "</button> " +
          '<button type="button" class="btn btn-ghost btn-sm" data-idshop-coupon-del="' +
          escapeHtml(row.id) +
          '">ลบ</button></div></div>'
        );
      })
      .join("");
  }

  async function loadIdshopAdminCoupons() {
    try {
      const data = await api("/api/admin/idshop/coupons", { _skipAuthSync: true });
      paintIdshopAdminCoupons(data?.coupons || []);
    } catch (e) {
      const msg = idshopCouponErr(e) || "โหลดคูปองไม่สำเร็จ";
      setIdshopAdminCouponStatus(msg, "err");
      const root = $("admin-idshop-coupons");
      if (root) root.innerHTML = '<p class="muted">' + escapeHtml(msg) + "</p>";
      throw e;
    }
  }

  async function saveIdshopCoupon() {
    const body = idshopCouponFormBody();
    const localErr = idshopCouponClientError(body);
    if (localErr) {
      setIdshopAdminCouponStatus(localErr, "err");
      showToast(localErr, "err");
      return;
    }
    if ($("admin-idshop-coupon-code")) $("admin-idshop-coupon-code").value = body.code;
    try {
      let data;
      if (idshopCouponEditId) {
        data = await api("/api/admin/idshop/coupons/" + encodeURIComponent(idshopCouponEditId), {
          method: "PATCH",
          body,
        });
        showToast("บันทึกคูปองแล้ว", "ok");
        setIdshopAdminCouponStatus("บันทึกคูปองแล้ว", "ok");
      } else {
        data = await api("/api/admin/idshop/coupons", { method: "POST", body });
        showToast("สร้างคูปองแล้ว", "ok");
        setIdshopAdminCouponStatus("สร้างคูปองแล้ว", "ok");
      }
      const saved = data?.coupon;
      if (saved) mergeIdshopPublicCoupon(saved);
      resetIdshopCouponForm();
      await loadIdshopAdminCoupons();
      await loadIdshopCatalog();
      if (saved) mergeIdshopPublicCoupon(saved);
    } catch (e) {
      const msg = idshopCouponErr(e);
      setIdshopAdminCouponStatus(msg, "err");
      showToast(msg, "err");
      adminConsoleStatus(msg, "err");
    }
  }

