  function normalizeIdshopFavIds(raw) {
    const out = [];
    const seen = new Set();
    (Array.isArray(raw) ? raw : []).forEach((item) => {
      const s = String(item || "").trim();
      if (!s || seen.has(s)) return;
      seen.add(s);
      out.push(s);
    });
    return out.slice(0, IDSHOP_FAV_MAX);
  }

  function readLocalIdshopFavs() {
    try {
      return normalizeIdshopFavIds(JSON.parse(localStorage.getItem(IDSHOP_FAV_KEY) || "[]"));
    } catch (_) {
      return [];
    }
  }

  function writeLocalIdshopFavs(ids) {
    try {
      localStorage.setItem(IDSHOP_FAV_KEY, JSON.stringify(normalizeIdshopFavIds(ids)));
    } catch (_) {}
  }

  function setIdshopFavIds(ids, { persistLocal = true } = {}) {
    idshopFavIds = new Set(normalizeIdshopFavIds(ids));
    if (persistLocal) writeLocalIdshopFavs([...idshopFavIds]);
    if (profile) {
      profile.farm_prefs = { ...(profile.farm_prefs || {}), idshop_favorites: [...idshopFavIds] };
    }
    paintIdshopFavToggle();
  }

  function paintIdshopFavToggle() {
    const btn = $("idshop-fav-toggle");
    const badge = $("idshop-fav-badge");
    if (btn) {
      btn.classList.toggle("is-on", !!idshopFavOnly);
      btn.setAttribute("aria-pressed", idshopFavOnly ? "true" : "false");
    }
    if (badge) {
      const n = idshopFavIds.size;
      badge.hidden = n <= 0;
      badge.textContent = String(n);
    }
  }

  function hydrateIdshopFavorites() {
    const ident = accessToken && profile ? String(profile.id || profile.username || "me") : "guest";
    if (ident === idshopFavProfileKey) return;
    idshopFavProfileKey = ident;
    idshopFavMergedOnce = false;
    const local = readLocalIdshopFavs();
    if (!accessToken || !profile) {
      setIdshopFavIds(local, { persistLocal: false });
      return;
    }
    const server = normalizeIdshopFavIds(profile.farm_prefs?.idshop_favorites);
    const merged = normalizeIdshopFavIds([...server, ...local]);
    setIdshopFavIds(merged, { persistLocal: true });
    const extra = local.filter((id) => !server.includes(id));
    if (extra.length && !idshopFavMergedOnce) {
      idshopFavMergedOnce = true;
      api("/api/idshop/favorites", { method: "PUT", body: { ids: merged } })
        .then((data) => {
          if (Array.isArray(data?.ids)) setIdshopFavIds(data.ids);
        })
        .catch(() => {});
    }
  }

  function idshopFavHeartSvg(on) {
    return (
      '<svg class="idshop-btn-svg" viewBox="0 0 24 24" width="16" height="16" fill="' +
      (on ? "currentColor" : "none") +
      '" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<path d="M19.5 12.57 12 20l-7.5-7.43A5 5 0 1 1 12 6a5 5 0 1 1 7.5 6.57Z"></path>' +
      "</svg>"
    );
  }

  function idshopListingMatchesQuery(row, q) {
    if (!q) return true;
    const snap = row.snapshot || {};
    const blob = [
      idshopCode(row),
      row.nickname,
      snap.nickname,
      ...(snap.cookies || []).map((c) => c.name || c),
      ...(snap.treasures || []).map((t) => t.name || t),
    ]
      .join(" ")
      .toLowerCase();
    return blob.includes(q);
  }

  async function toggleIdshopFavorite(listingId, on) {
    const lid = String(listingId || "").trim();
    if (!lid) return;
    const nextOn = on == null ? !idshopFavIds.has(lid) : !!on;
    const next = [...idshopFavIds].filter((id) => id !== lid);
    if (nextOn) next.unshift(lid);
    setIdshopFavIds(next);
    if (accessToken) {
      try {
        const data = await api("/api/idshop/favorites", {
          method: "POST",
          body: { listing_id: lid, on: nextOn },
        });
        if (Array.isArray(data?.ids)) setIdshopFavIds(data.ids);
      } catch (e) {
        showToast(thError(e.message) || "บันทึกรายการโปรดไม่สำเร็จ", "err");
      }
    }
    if (idshopFavOnly) {
      paintIdshopGrid();
      paintIdshopFavToggle();
    } else {
      paintIdshopGrid();
    }
  }

  function paintIdshopFilterButtons() {
    ["cookies", "pets", "treasures"].forEach((kind) => {
      const btn = $("idshop-filter-" + kind);
      if (!btn) return;
      const n = idshopSelected[kind] ? idshopSelected[kind].size : 0;
      const count = btn.querySelector(".idshop-filter-count");
      btn.classList.toggle("is-on", n > 0);
      if (count) {
        count.hidden = n <= 0;
        count.textContent = n ? String(n) : "0";
      }
    });
    const toggle = $("idshop-filter-toggle");
    const badge = $("idshop-filter-badge");
    const n = idshopFilterActiveCount();
    const open = $("idshop-filters")?.classList.contains("is-open");
    if (toggle) {
      toggle.classList.toggle("is-on", n > 0);
      toggle.classList.toggle("is-open", open);
      toggle.setAttribute("aria-expanded", open ? "true" : "false");
    }
    if (badge) {
      badge.hidden = n <= 0;
      badge.textContent = String(n);
    }
    paintIdshopFavToggle();
  }

  function idshopFilterActiveCount() {
    let n = 0;
    if (String($("idshop-q")?.value || "").trim()) n += 1;
    ["idshop-min-level", "idshop-min-gem", "idshop-min-life", "idshop-price-min", "idshop-price-max"].forEach((id) => {
      const v = Number($(id)?.value || "");
      if (Number.isFinite(v) && v > 0) n += 1;
    });
    n += (idshopSelected.cookies?.size || 0) + (idshopSelected.pets?.size || 0) + (idshopSelected.treasures?.size || 0);
    return n;
  }

  function setIdshopFiltersOpen(open) {
    const panel = $("idshop-filters");
    if (!panel) return;
    const show = !!open;
    panel.classList.toggle("is-open", show);
    panel.setAttribute("aria-hidden", show ? "false" : "true");
    if ("inert" in panel) panel.inert = !show;
    paintIdshopFilterButtons();
  }

  function applyIdshopFilters() {
    idshopPage = 1;
    setIdshopFiltersOpen(false);
    if (idshopFavOnly) {
      paintIdshopGrid();
      paintIdshopPager();
      return;
    }
    loadIdshopCatalog({ forceSkeleton: true }).catch((e) => setStatus($("idshop-status"), thError(e.message) || "โหลดร้านไม่สำเร็จ", "err"));
  }

  function renderIdshopPickerChips() {
    const root = $("idshop-filter-picker-chips");
    if (!root) return;
    const q = String($("idshop-filter-picker-q")?.value || "")
      .trim()
      .toLowerCase();
    const rows = (idshopFilterOptions[idshopFilterKind] || []).filter((row) => {
      if (!q) return true;
      return String(row.name || "").toLowerCase().includes(q) || String(row.seq || "").includes(q);
    });
    root.innerHTML = "";
    if (!rows.length) {
      root.innerHTML = '<p class="muted">ไม่พบรายการ</p>';
      return;
    }
    rows.forEach((row) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "idshop-chip" + (idshopFilterDraft.has(row.seq) ? " is-on" : "");
      btn.innerHTML =
        idshopImgHtml(row.image_url || "", row.name || row.seq || "", "", idshopFilterKind === "pets" ? "pet" : idshopFilterKind === "treasures" ? "treasure" : "cookie") +
        "<span>" +
        escapeHtml(row.name || row.seq) +
        "</span>";
      btn.addEventListener("click", () => {
        if (idshopFilterDraft.has(row.seq)) idshopFilterDraft.delete(row.seq);
        else idshopFilterDraft.add(row.seq);
        renderIdshopPickerChips();
      });
      root.appendChild(btn);
    });
  }

  function openIdshopFilterPicker(kind) {
    idshopFilterKind = IDSHOP_FILTER_KIND_META[kind] ? kind : "cookies";
    idshopFilterDraft = new Set(idshopSelected[idshopFilterKind] || []);
    const meta = IDSHOP_FILTER_KIND_META[idshopFilterKind];
    if ($("idshop-filter-title")) $("idshop-filter-title").textContent = meta.title;
    if ($("idshop-filter-hint")) $("idshop-filter-hint").textContent = meta.hint;
    if ($("idshop-filter-picker-q")) $("idshop-filter-picker-q").value = "";
    renderIdshopPickerChips();
    const modal = $("idshop-filter-modal");
    if (!modal) return;
    animateOpen(modal);
    lockBodyScroll("idshop-filter-open");
  }

  function closeIdshopFilterPicker() {
    const modal = $("idshop-filter-modal");
    if (!modal || modal.classList.contains("hidden")) return;
    unlockBodyScroll("idshop-filter-open");
    animateClose(modal);
  }

  function confirmIdshopFilterPicker() {
    idshopSelected[idshopFilterKind] = new Set(idshopFilterDraft);
    paintIdshopFilterButtons();
    closeIdshopFilterPicker();
    loadIdshopCatalog().catch(() => {});
  }

  function idshopImgHtml(src, name, cls, kind) {
    const n = escapeHtml(name || "");
    const rawName = String(name || "").replace(/\s*\(เกรด.*$/, "").trim();
    const preferred =
      (typeof ckrPortraitSrc === "function" && ckrPortraitSrc(rawName, src, kind)) || src;
    if (!preferred) return "";
    const fallback =
      (typeof ckrLocalFallback === "function" && ckrLocalFallback(preferred, kind)) ||
      "assets/Brave-cookie.png";
    const clsList = ((cls ? cls + " " : "") + "ckr-wiki-img").trim();
    const tagMatch = String(preferred).match(/\/(?:cookies|pets|treasures)\/([^/?#]+)\.png/i);
    return (
      '<img alt="' +
      n +
      '" title="' +
      n +
      " · ดูรายละเอียด" +
      '"' +
      ' class="' +
      clsList +
      '"' +
      ' data-ckr-name="' +
      escapeHtml(rawName) +
      '"' +
      (kind ? ' data-ckr-kind="' + escapeHtml(kind) + '"' : "") +
      (tagMatch ? ' data-ckr-tag="' + escapeHtml(decodeURIComponent(tagMatch[1])) + '"' : "") +
      ' data-ckr-fallback="' +
      escapeHtml(fallback) +
      '" referrerpolicy="no-referrer" src="' +
      escapeHtml(preferred) +
      '" onerror="window.ckrImgError&&ckrImgError(this);" />'
    );
  }

