  function afterplayCalcMessage(source) {
    const src = String(source || afterplayLastEdit || "");
    if (src === "ebox" || src === "box") return "กำลังคำนวณกล่อง…";
    if (src === "coin") return "กำลังคำนวณเหรียญ…";
    if (src === "level") return "กำลังคำนวณเลเวล…";
    return "กำลังคำนวณรอบ…";
  }

  function afterplayCalcControlIds() {
    return [
      "afterplay-mode-coin",
      "afterplay-mode-xp",
      "afterplay-mode-box",
      "afterplay-mode-combined",
      "afterplay-pace-fast",
      "afterplay-pace-safe",
      "afterplay-target-level",
      "afterplay-target-coin",
      "afterplay-target-runs",
      "afterplay-coin-per",
      "afterplay-exp-per",
      "afterplay-ebox-ep",
      "afterplay-ebox-pick-btn",
      "afterplay-ebox-runs",
      "afterplay-ebox-auto-relic",
      "afterplay-start-btn",
      "menu-nav-afterplay-coin",
      "menu-nav-afterplay-xp",
      "menu-nav-afterplay-box",
      "menu-nav-afterplay-combined",
    ];
  }

  function setAfterplayCalcLocked(on, opts) {
    const keepActive = !!(opts && opts.keepActiveInput);
    const active = document.activeElement;
    afterplayCalcControlIds().forEach((id) => {
      const el = $(id);
      if (!el) return;
      if (on && id === "afterplay-start-btn" && afterplayHasRunnablePlan()) return;
      if (on) {
        if (keepActive && active && (el === active || el.contains(active))) return;
        if (el.dataset.calcPrevDisabled == null) {
          el.dataset.calcPrevDisabled = el.disabled ? "1" : "0";
        }
        el.disabled = true;
      } else if (el.dataset.calcPrevDisabled != null) {
        if (el.dataset.calcPrevDisabled === "0") el.disabled = false;
        delete el.dataset.calcPrevDisabled;
      }
    });
    document.querySelectorAll("[data-afterplay-family], [data-shortcut-tab='afterplay_fast']").forEach((el) => {
      el.classList.toggle("is-calc-locked", !!on);
      el.setAttribute("aria-disabled", on ? "true" : "false");
    });
    $("farm-panel-afterplay_fast")
      ?.querySelectorAll("[data-afterplay-goal]")
      .forEach((card) => card.classList.toggle("is-calc-locked", !!on));
  }

  function setAfterplayCalculating(on, message) {
    if (afterplayCalcHideTimer) {
      clearTimeout(afterplayCalcHideTimer);
      afterplayCalcHideTimer = null;
    }
    const panel = $("farm-panel-afterplay_fast");
    const banner = $("afterplay-calc-overlay");
    const text = $("afterplay-calc-text");
    const estimate = $("afterplay-estimate");
    if (on) {
      afterplayCalculating = true;
      afterplayCalcGen += 1;
      if (!afterplayCalcShownAt) afterplayCalcShownAt = Date.now();
      if (text) text.textContent = message || afterplayCalcMessage();
      panel?.classList.add("is-calculating");
      estimate?.classList.add("is-calculating");
      estimate?.setAttribute("aria-busy", "true");
      if (banner) {
        banner.hidden = false;
        banner.classList.remove("hidden");
        banner.setAttribute("aria-hidden", "false");
      }
      const keepInput = !!activeAfterplayCalcInput();
      setAfterplayCalcLocked(true, { keepActiveInput: keepInput });
      paintAfterplayStartEnabled();
      return;
    }
    const gen = afterplayCalcGen;
    const hide = () => {
      if (gen !== afterplayCalcGen) return;
      afterplayCalculating = false;
      afterplayCalcShownAt = 0;
      panel?.classList.remove("is-calculating");
      estimate?.classList.remove("is-calculating");
      estimate?.removeAttribute("aria-busy");
      if (banner) {
        banner.hidden = true;
        banner.classList.add("hidden");
        banner.setAttribute("aria-hidden", "true");
      }
      setAfterplayCalcLocked(false);
      paintAfterplayStartEnabled();
    };
    const elapsed = Date.now() - (afterplayCalcShownAt || Date.now());
    const wait = Math.max(0, AFTERPLAY_CALC_MIN_MS - elapsed);
    if (wait > 0) afterplayCalcHideTimer = setTimeout(hide, wait);
    else hide();
  }

  function activeAfterplayCalcInput() {
    const el = document.activeElement;
    if (!el) return null;
    if (!el.closest || !el.closest("#farm-panel-afterplay_fast")) return null;
    if (el.matches("input, select, textarea")) return el;
    return null;
  }

  function afterplayHasRunnablePlan(plan = afterplayPlan) {
    const ebox = isAfterplayEbox();
    const epPick = afterplayNeedsEpPick();
    const runs = Number(ebox ? plan?.planned || plan?.runs || 0 : plan?.runs || 0);
    if (runs < 1) return false;
    if (epPick && !afterplayEboxSelected.size) return false;
    if (ebox) return Number(plan?.life || 0) >= 1;
    if (plan?.enough_life != null) return !!plan.enough_life;
    const life = Number(
      plan?.life ?? plan?.before?.life ?? afterplaySnapCache.data?.snapshot?.life ?? NaN
    );
    return !Number.isFinite(life) || life >= runs;
  }

  function paintAfterplayStartEnabled() {
    const plan = afterplayPlan;
    const ebox = isAfterplayEbox();
    const epPick = afterplayNeedsEpPick();
    const runs = Number(ebox ? plan?.planned || plan?.runs || 0 : plan?.runs || 0);
    const enoughLife = ebox
      ? Number(plan?.life || 0) >= 1 && runs > 0
      : plan?.enough_life != null
        ? !!plan.enough_life
        : afterplayHasRunnablePlan(plan);
    const needEps = !epPick || afterplayEboxSelected.size > 0;
    const blockingCalc = afterplayCalculating && !afterplayHasRunnablePlan(plan);
    // A running job no longer blocks the button: the extra job joins the queue.
    const can =
      (!afterplayRunning || queueHasRoom()) &&
      !afterplayBusy &&
      !blockingCalc &&
      runs > 0 &&
      enoughLife &&
      needEps &&
      !!devplaySession?.id &&
      canPayForFeature("afterplay_fast");
    const btn = $("afterplay-start-btn");
    if (btn) {
      btn.disabled = !can;
      btn.classList.toggle("is-disabled-look", !can);
      btn.classList.toggle("is-starting", !!afterplayBusy);
      btn.classList.toggle("is-queue-add", can && anyJobLive());
      if (can) btn.title = anyJobLive() ? "เพิ่มเข้าคิวล่วงหน้า" : "";
    }
    const spinner = $("afterplay-start-spinner");
    if (spinner) {
      spinner.hidden = !afterplayBusy;
      spinner.classList.toggle("hidden", !afterplayBusy);
    }
    const startIcon = $("afterplay-start-btn-icon");
    if (startIcon) {
      startIcon.hidden = !!afterplayBusy;
      startIcon.classList.toggle("hidden", !!afterplayBusy);
    }
    const warn = $("afterplay-life-warn");
    if (warn) {
      const show = ebox
        ? runs > 0 && Number(plan?.life || 0) < 1
        : runs > 0 && plan && !enoughLife;
      warn.hidden = !show;
      warn.classList.toggle("hidden", !show);
      if (ebox) warn.textContent = "หัวใจเป็น 0 — ห้ามเริ่ม";
      else warn.textContent = "หัวใจไม่พอ — ห้ามเริ่ม";
    }
    const hint = $("afterplay-ebox-hint");
    if (hint) {
      const life = Number(plan?.life || 0);
      const show = ebox && runs > 0 && life >= 1 && life < runs;
      hint.hidden = !show;
      hint.classList.toggle("hidden", !show);
    }
    const keyWarn = $("afterplay-ebox-key-warn");
    if (keyWarn) {
      keyWarn.hidden = true;
      keyWarn.classList.add("hidden");
    }
    const sub = $("afterplay-start-btn-sub");
    if (sub && !afterplayRunning) {
      if (afterplayBusy) sub.textContent = "กำลังส่งเข้าคิวงาน…";
      else if (blockingCalc) sub.textContent = $("afterplay-calc-text")?.textContent || "กำลังคำนวณรอบ…";
      else if (!devplaySession?.id) sub.textContent = "ล็อกอิน DevPlay ก่อน";
      else if (epPick && afterplayEboxSelected.size < 1) sub.textContent = "เลือก Episode";
      else if (!enoughLife && runs > 0) sub.textContent = "หัวใจไม่พอ — ห้ามเริ่ม";
      else if (runs > 0) sub.textContent = "รวมในวันใช้งาน · " + formatNumTh(runs) + " รอบ";
      else if (epPick) sub.textContent = "เลือกด่านแล้วใส่จำนวนรอบ";
      else if (isAfterplayMoneyOnly()) sub.textContent = "ใส่จำนวนเหรียญที่อยากได้";
      else if (isAfterplayXpOnly()) sub.textContent = "ใส่เป้าเลเวล";
      else sub.textContent = "ใส่เป้าเลเวลหรือเหรียญอย่างใดอย่างหนึ่ง";
    }
  }

  function paintAfterplayBound(prefix, lo, hi, opts) {
    const a = Number(lo || 0);
    const b = Number(hi == null || hi === "" ? a : hi);
    const minV = Math.min(a, b);
    const maxV = Math.max(a, b);
    const wrap = $(prefix + "-wrap");
    wrap?.classList.toggle("is-single", minV === maxV);
    const fmt = (n) => {
      const t = formatNumTh(n);
      return opts && opts.plus && n > 0 ? "+" + t : t;
    };
    if ($(prefix + "-min")) $(prefix + "-min").textContent = fmt(minV);
    if ($(prefix + "-max")) $(prefix + "-max").textContent = fmt(maxV);
  }

  const AFTERPLAY_EXP_MIN = 10000;
  const AFTERPLAY_EXP_MAX = 14000;
  const AFTERPLAY_COIN_MIN = 350000;
  const AFTERPLAY_COIN_MAX = 420000;

  function afterplayXpLib() {
    return window.CKR_LEVEL_XP || null;
  }

  function afterplayFastMaxRuns() {
    return afterplayRunsCap();
  }

  function afterplayBoxQtyMax() {
    const n = Number(afterplayPricesMeta.boxQtyMax || AFTERPLAY_BOX_QTY_MAX);
    return Math.max(1, Math.min(AFTERPLAY_BOX_QTY_MAX, Number.isFinite(n) ? n : AFTERPLAY_BOX_QTY_MAX));
  }

  function afterplayBoxQtyDefault() {
    const n = Number(afterplayPricesMeta.boxQtyDefault || AFTERPLAY_BOX_QTY_DEFAULT);
    return Math.max(1, Math.min(afterplayBoxQtyMax(), Number.isFinite(n) ? n : AFTERPLAY_BOX_QTY_DEFAULT));
  }

  function afterplayRunsCap() {
    if (isAfterplayEbox()) {
      const n = Number(afterplayPricesMeta.eboxMaxRuns || 0);
      if (n > 0) return n;
      const specMax = Number(afterplaySpec().max_runs || 0);
      if (afterplayPlan?.max_runs != null && Number.isFinite(Number(afterplayPlan.max_runs))) {
        return Math.max(0, Number(afterplayPlan.max_runs));
      }
      return specMax > 0 ? specMax : 300;
    }
    const spec = afterplaySpec();
    const specMax = Number(spec.max_runs || 0);
    if (Array.isArray(afterplayFnCatalog) && afterplayFnCatalog.length && specMax > 0) {
      return specMax;
    }
    if (afterplayPlan?.max_runs != null && Number.isFinite(Number(afterplayPlan.max_runs))) {
      return Math.max(0, Number(afterplayPlan.max_runs));
    }
    if (afterplayPricesMeta.fastMaxRunsKnown) {
      return Math.max(0, Number(afterplayPricesMeta.fastMaxRuns) || 0);
    }
    return specMax > 0 ? specMax : 300;
  }

  function afterplayRequestedRuns() {
    const raw = Math.floor(Number($("afterplay-target-runs")?.value || 0));
    return Number.isFinite(raw) && raw >= 1 ? raw : 0;
  }

  function afterplayClampRuns(raw) {
    const n = Math.floor(Number(raw || 0));
    if (!Number.isFinite(n) || n < 1) return 0;
    const cap = afterplayRunsCap();
    return cap > 0 ? Math.max(1, Math.min(cap, n)) : n;
  }

  function syncAfterplayRunInputsMax() {
    const cap = afterplayRunsCap();
    const maxAttr = String(cap > 0 ? cap : 100000);
    const runsInp = $("afterplay-target-runs");
    if (runsInp) runsInp.max = maxAttr;
    if (isAfterplayEbox()) clampAfterplayEboxRunsInput();
  }

  function afterplayPlanView(plan) {
    if (!plan) return null;
    const cap = Number(plan.max_runs || 0);
    const needed =
      plan.goal === "coin"
        ? Number(plan.runs_needed != null ? plan.runs_needed : plan.runs_for_coin || 0)
        : Number(plan.runs_needed != null ? plan.runs_needed : plan.runs_for_level || 0);
    const runs = Number(plan.runs || 0);
    const sessions =
      plan.sessions_needed != null
        ? Number(plan.sessions_needed)
        : needed <= 0
          ? 0
          : cap > 0
            ? Math.ceil(needed / cap)
            : 1;
    return Object.assign({}, plan, {
      hearts_to_goal: Number(plan.hearts_to_goal != null ? plan.hearts_to_goal : needed),
      runs_needed: needed,
      runs_remaining: Math.max(
        0,
        Number(plan.runs_remaining != null ? plan.runs_remaining : needed - runs)
      ),
      sessions_needed: sessions,
      goal_level: Number(plan.goal_level || plan.target_level || 0),
    });
  }

  function hideAfterplayRoadmap() {
    const el = $("afterplay-roadmap");
    if (!el) return;
    el.hidden = true;
    el.classList.add("hidden");
    ["afterplay-roadmap-cap", "afterplay-roadmap-next"].forEach((id) => {
      const node = $(id);
      if (!node) return;
      node.hidden = true;
      node.classList.add("hidden");
      node.textContent = "";
    });
  }

  function paintAfterplayRoadmap(plan) {
    const wrap = $("afterplay-roadmap");
    const goalEl = $("afterplay-roadmap-goal");
    const capEl = $("afterplay-roadmap-cap");
    const nextEl = $("afterplay-roadmap-next");
    if (!wrap || !goalEl) return;
    if (isAfterplayEbox() || !plan || (plan.goal !== "level" && plan.goal !== "coin")) {
      hideAfterplayRoadmap();
      return;
    }
    const view = afterplayPlanView(plan);
    const fromLv = Number(view.before?.level || view.level || 0);
    const goalLv = Number(view.goal_level || 0);
    const toGoal = Number(view.hearts_to_goal || 0);
    const thisRuns = Number(view.runs || 0);
    if (view.goal === "level") {
      if (!goalLv) {
        hideAfterplayRoadmap();
        return;
      }
      if (fromLv >= goalLv) {
        goalEl.innerHTML =
          "เลเวลตอนนี้ <strong>" +
          formatNumTh(fromLv) +
          "</strong> ถึงหรือเกินเป้า <strong>" +
          formatNumTh(goalLv) +
          "</strong> แล้ว";
        capEl.hidden = true;
        capEl.classList.add("hidden");
        nextEl.hidden = true;
        nextEl.classList.add("hidden");
        wrap.hidden = false;
        wrap.classList.remove("hidden");
        return;
      }
      const per = Number(view.exp_per_run_min || AFTERPLAY_EXP_MIN);
      goalEl.innerHTML =
        "จากเลเวล <strong>" +
        formatNumTh(fromLv) +
        "</strong> ไป <strong>" +
        formatNumTh(goalLv) +
        "</strong> ใช้ประมาณ <strong>" +
        formatNumTh(toGoal) +
        "</strong> หัวใจ" +
        " <span>(ชัวร์ด้าน XP " +
        formatNumTh(per) +
        "/รอบ)</span>";
    } else {
      if (toGoal < 1 && thisRuns < 1) {
        hideAfterplayRoadmap();
        return;
      }
      goalEl.innerHTML =
        "ถึงเป้าเหรียญใช้ประมาณ <strong>" + formatNumTh(toGoal) + "</strong> หัวใจ";
    }
    wrap.hidden = false;
    wrap.classList.remove("hidden");
    const afterMin = Number(view.after_safe?.level || 0);
    const afterMax = Number(view.after_best?.level || afterMin);
    if (view.capped && Number(view.max_runs || 0) > 0) {
      capEl.hidden = false;
      capEl.classList.remove("hidden");
      let capHtml =
        "รอบนี้สูงสุด <strong>" +
        formatNumTh(view.max_runs) +
        "</strong> รอบ → ได้ประมาณเลเวล <strong>" +
        formatNumTh(afterMin) +
        "</strong>";
      if (afterMax !== afterMin) capHtml += "–<strong>" + formatNumTh(afterMax) + "</strong>";
      capEl.innerHTML = capHtml;
    } else {
      capEl.hidden = true;
      capEl.classList.add("hidden");
      capEl.textContent = "";
    }
    if (view.capped && Number(view.runs_remaining || 0) > 0) {
      const more = Math.max(0, Number(view.sessions_needed || 1) - 1);
      nextEl.hidden = false;
      nextEl.classList.remove("hidden");
      let extra =
        "เหลืออีกประมาณ <strong>" + formatNumTh(view.runs_remaining) + "</strong> หัวใจ";
      if (more > 0) {
        extra +=
          " · อีก <strong>" +
          formatNumTh(more) +
          "</strong> ครั้ง (ครั้งละไม่เกิน " +
          formatNumTh(view.max_runs) +
          " รอบ)";
      }
      const left = Number(view.hearts_left != null ? view.hearts_left : view.after_safe?.life);
      if (Number.isFinite(left) && left < Number(view.runs_remaining)) {
        extra +=
          " · หลังรอบนี้เหลือ <strong>" +
          formatNumTh(left) +
          "</strong> หัวใจ ต้องเติมก่อนรอบถัดไป";
      }
      nextEl.innerHTML = extra;
    } else {
      nextEl.hidden = true;
      nextEl.classList.add("hidden");
      nextEl.textContent = "";
    }
  }

  function estimateAfterplayPlanLocal() {
    const payload = afterplayGoalPayload();
    const cap = afterplayRunsCap();
    if (isAfterplayEbox()) {
      const asked = afterplayRequestedRuns();
      const runs = afterplayClampRuns(asked);
      if (runs < 1) return null;
      syncAfterplayEboxSelected();
      const snap = afterplaySnapCache.data?.snapshot || afterplayPlan?.before || null;
      const life = Number(snap?.life ?? afterplayPlan?.life ?? 0);
      const epN = afterplayEboxSelected.size;
      const planned = epN >= 1 ? runs * epN : 0;
      return {
        goal: "runs",
        runs,
        planned,
        hearts_required: planned,
        hearts_left: Math.max(0, life - planned),
        enough_life: life >= 1 && planned > 0,
        capped: cap > 0 && asked > cap,
        max_runs: cap,
        unlimited: cap <= 0,
        life,
        key: Number(snap?.key ?? afterplayPlan?.key ?? 0),
        eps: [...afterplayEboxSelected],
        auto_relic: afterplayEboxAutoRelicOn(),
      };
    }
    const snap = afterplaySnapCache.data?.snapshot || afterplayPlan?.before || null;
    if (!snap) {
      if (payload.goal === "runs" && Number(payload.runs || 0) >= 1) {
        const asked = afterplayRequestedRuns();
        const runs = afterplayClampRuns(asked);
        return {
          goal: "runs",
          runs,
          hearts_required: runs,
          enough_life: true,
          capped: cap > 0 && asked > cap,
          max_runs: cap,
          unlimited: cap <= 0,
        };
      }
      return null;
    }
    const xp = afterplayXpLib();
    const life = Number(snap.life || 0);
    const coinNow = Number(snap.coin || 0);
    const lv = Number(snap.level || 1);
    const bounds = afterplayYieldBounds();
    const expMin = bounds.expMin;
    const expMax = bounds.expMax;
    const coinMin = bounds.coinMin;
    const coinMax = bounds.coinMax;
    const xpOn = !isAfterplayMoneyOnly();
    const coinOn = !isAfterplayXpOnly();
    if (payload.goal === "level") {
      const tgt = Number(payload.target_level || 0);
      if (!tgt || !xp) return null;
      const neededXp = xp.xpToTarget(lv, tgt, snap.exp);
      const runsNeeded = neededXp <= 0 ? 0 : Math.ceil(neededXp / Math.max(1, expMin));
      const capped = cap > 0 && runsNeeded > cap;
      const runs = cap > 0 ? Math.max(0, Math.min(cap, runsNeeded)) : runsNeeded;
      const afterMin = xp.levelAfterXp(lv, snap.exp, xpOn ? runs * expMin : 0);
      const afterMax = xp.levelAfterXp(lv, snap.exp, xpOn ? runs * expMax : 0);
      const sessions = runsNeeded <= 0 ? 0 : cap > 0 ? Math.ceil(runsNeeded / cap) : 1;
      return {
        goal: "level",
        level: lv,
        before: { level: lv, exp: snap.exp, life, coin: coinNow },
        after_safe: {
          level: afterMin.level,
          exp: afterMin.exp_progress,
          life: Math.max(0, life - runs),
          coin: coinNow + (coinOn ? runs * coinMin : 0),
        },
        after_best: {
          level: afterMax.level,
          exp: afterMax.exp_progress,
          life: Math.max(0, life - runs),
          coin: coinNow + (coinOn ? runs * coinMax : 0),
        },
        runs,
        runs_needed: runsNeeded,
        runs_for_level: runsNeeded,
        runs_remaining: Math.max(0, runsNeeded - runs),
        sessions_needed: sessions,
        hearts_to_goal: runsNeeded,
        hearts_required: runs,
        hearts_left: Math.max(0, life - runs),
        enough_life: life >= runs && runs > 0,
        capped,
        max_runs: cap,
        unlimited: cap <= 0,
        goal_level: tgt,
        target_level: tgt,
        xp_gain_min: xpOn ? runs * expMin : 0,
        xp_gain_max: xpOn ? runs * expMax : 0,
        coin_min: coinOn ? runs * coinMin : 0,
        coin_max: coinOn ? runs * coinMax : 0,
        exp_per_run_min: xpOn ? expMin : 0,
        exp_per_run_max: xpOn ? expMax : 0,
      };
    }
    if (payload.goal === "coin") {
      const want = Number(payload.target_coin || 0);
      if (want < 1) return null;
      const runsNeeded = Math.ceil(want / Math.max(1, coinMin));
      const capped = cap > 0 && runsNeeded > cap;
      const runs = cap > 0 ? Math.max(0, Math.min(cap, runsNeeded)) : runsNeeded;
      const sessions = runsNeeded <= 0 ? 0 : cap > 0 ? Math.ceil(runsNeeded / cap) : 1;
      const afterMin = xp
        ? xp.levelAfterXp(lv, snap.exp, xpOn ? runs * expMin : 0)
        : { level: lv, exp_progress: snap.exp };
      const afterMax = xp
        ? xp.levelAfterXp(lv, snap.exp, xpOn ? runs * expMax : 0)
        : afterMin;
      return {
        goal: "coin",
        level: lv,
        before: { level: lv, exp: snap.exp, life, coin: coinNow },
        after_safe: {
          level: afterMin.level,
          exp: afterMin.exp_progress,
          life: Math.max(0, life - runs),
          coin: coinNow + runs * coinMin,
        },
        after_best: {
          level: afterMax.level,
          exp: afterMax.exp_progress,
          life: Math.max(0, life - runs),
          coin: coinNow + runs * coinMax,
        },
        runs,
        runs_needed: runsNeeded,
        runs_for_coin: runsNeeded,
        runs_remaining: Math.max(0, runsNeeded - runs),
        sessions_needed: sessions,
        hearts_to_goal: runsNeeded,
        hearts_required: runs,
        hearts_left: Math.max(0, life - runs),
        enough_life: life >= runs && runs > 0,
        capped,
        max_runs: cap,
        unlimited: cap <= 0,
        target_coin: want,
        xp_gain_min: xpOn ? runs * expMin : 0,
        xp_gain_max: xpOn ? runs * expMax : 0,
        coin_min: runs * coinMin,
        coin_max: runs * coinMax,
        exp_per_run_min: xpOn ? expMin : 0,
        exp_per_run_max: xpOn ? expMax : 0,
      };
    }
    if (payload.goal === "runs") {
      const asked = afterplayRequestedRuns();
      const runs = afterplayClampRuns(asked);
      if (runs < 1) return null;
      const afterMin = xp
        ? xp.levelAfterXp(lv, snap.exp, xpOn ? runs * expMin : 0)
        : { level: lv, exp_progress: snap.exp };
      const afterMax = xp
        ? xp.levelAfterXp(lv, snap.exp, xpOn ? runs * expMax : 0)
        : afterMin;
      return {
        goal: "runs",
        level: lv,
        before: { level: lv, exp: snap.exp, life, coin: coinNow },
        after_safe: {
          level: afterMin.level,
          exp: afterMin.exp_progress,
          life: Math.max(0, life - runs),
          coin: coinNow + (coinOn ? runs * coinMin : 0),
        },
        after_best: {
          level: afterMax.level,
          exp: afterMax.exp_progress,
          life: Math.max(0, life - runs),
          coin: coinNow + (coinOn ? runs * coinMax : 0),
        },
        runs,
        runs_needed: runs,
        hearts_required: runs,
        hearts_left: Math.max(0, life - runs),
        enough_life: life >= runs && runs > 0,
        capped: cap > 0 && asked > cap,
        max_runs: cap,
        unlimited: cap <= 0,
        xp_gain_min: xpOn ? runs * expMin : 0,
        xp_gain_max: xpOn ? runs * expMax : 0,
        coin_min: coinOn ? runs * coinMin : 0,
        coin_max: coinOn ? runs * coinMax : 0,
        exp_per_run_min: xpOn ? expMin : 0,
        exp_per_run_max: xpOn ? expMax : 0,
      };
    }
    return null;
  }

  function paintAfterplayEtaText(plan) {
    const runs = Number(plan?.planned || plan?.runs || 0);
    const capBit = plan?.max_runs ? " · สูงสุด " + formatNumTh(plan.max_runs) + " รอบ" : "";
    let eta = "—";
    if (plan?.eta_label) eta = plan.eta_label;
    else if (plan?.eta_sec != null && Number.isFinite(Number(plan.eta_sec))) {
      eta = "ประมาณ " + plan.eta_sec + " วินาที";
    } else if (runs > 0) {
      const round = Math.max(1, Number(afterplaySpec().round_sec || 8));
      eta = formatEtaSec(Math.ceil(runs / 2) * round);
    }
    if ($("afterplay-eta")) $("afterplay-eta").textContent = eta === "—" ? eta : eta + capBit;
    if ($("afterplay-est-eta")) $("afterplay-est-eta").textContent = eta;
  }

  function applyAfterplayLocalPlan() {
    if (afterplayRunning) return;
    const local = estimateAfterplayPlanLocal();
    if (!local) {
      const payload = afterplayGoalPayload();
      if (!payload.target_level && !payload.target_coin) hideAfterplayRoadmap();
      paintAfterplayStartEnabled();
      return;
    }
    const prev = afterplayPlan || {};
    afterplayPlan = Object.assign({}, prev, local, {
      credit: prev.credit,
      credit_per_run: prev.credit_per_run,
    });
    if ($("afterplay-est-runs")) $("afterplay-est-runs").textContent = formatNumTh(local.planned || local.runs || 0);
    if ($("afterplay-est-hearts")) {
      $("afterplay-est-hearts").textContent = formatNumTh(local.hearts_required || local.planned || local.runs || 0);
    }
    paintAfterplayEtaText(local);
    paintAfterplayBound("afterplay-est-xp", local.xp_gain_min, local.xp_gain_max, { plus: true });
    paintAfterplayBound("afterplay-est-coin", local.coin_min, local.coin_max, { plus: true });
    const before = local.before || {};
    const safe = local.after_safe || {};
    const best = local.after_best || {};
    const cmp = $("afterplay-compare");
    if (cmp) {
      const show = Number(local.runs || 0) > 0;
      cmp.hidden = !show;
      cmp.classList.toggle("hidden", !show);
      if (show) {
        if ($("afterplay-cmp-before-level")) $("afterplay-cmp-before-level").textContent = formatNumTh(before.level || 0);
        if ($("afterplay-cmp-before-coin")) $("afterplay-cmp-before-coin").textContent = formatNumTh(before.coin || 0);
        if ($("afterplay-cmp-before-life")) $("afterplay-cmp-before-life").textContent = formatNumTh(before.life || 0);
        paintAfterplayBound("afterplay-cmp-after-level", safe.level, best.level);
        paintAfterplayBound("afterplay-cmp-after-coin", safe.coin, best.coin);
        if ($("afterplay-cmp-after-life")) $("afterplay-cmp-after-life").textContent = formatNumTh(safe.life || 0);
      }
    }
    paintAfterplayRoadmap(afterplayPlan);
    paintAfterplayStartEnabled();
    if (afterplayNeedsEpPick() && !afterplayEboxSelected.size) {
      setStatus(afterplayStatusNode(), "เลือก Episode", "muted");
      if (!isAfterplayEbox()) return;
    }
    if (isAfterplayEbox()) {
      if (!afterplayEboxSelected.size) {
        setStatus(afterplayStatusNode(), "เลือก Episode", "muted");
      } else if (local.capped) {
        setStatus(
          afterplayStatusNode(),
          "รอบเกินเพดาน " + formatNumTh(local.max_runs || 0) + " — ใช้จำนวนสูงสุด",
          "err"
        );
      } else if (local.planned || local.runs) {
        setStatus(
          afterplayStatusNode(),
          formatNumTh(local.planned || local.runs) + " รอบ · หัวใจ" + (Number(local.life || 0) >= 1 ? "พร้อมเริ่ม" : "เป็น 0"),
          Number(local.life || 0) >= 1 ? "ok" : "err"
        );
      }
      return;
    }
    if (local.capped) {
      const view = afterplayPlanView(local);
      const need = formatNumTh(view?.hearts_to_goal || 0);
      const capN = formatNumTh(local.max_runs || 0);
      const goalBit =
        local.goal === "level"
          ? "ถึงเลเวล " + formatNumTh(view?.goal_level || 0) + " ต้อง " + need + " หัวใจ"
          : "ถึงเป้าต้อง " + need + " หัวใจ";
      setStatus(afterplayStatusNode(), goalBit + " · รอบนี้สูงสุด " + capN + " รอบ", "err");
    } else if (local.runs) {
      const why =
        local.goal === "coin"
          ? " (จากเหรียญ · ค่าประมาณ)"
          : local.goal === "level"
            ? " (จากเลเวล · ค่าประมาณ)"
            : "";
      setStatus(
        afterplayStatusNode(),
        "ชัวร์ " + formatNumTh(local.runs) + " รอบ" + why + " · หัวใจ" + (local.enough_life ? "พร้อม" : "ไม่พอ"),
        local.enough_life ? "ok" : "err"
      );
    }
  }

  function paintAfterplayPlan(data) {
    const snap = data?.snapshot || {};
    const plan = data?.plan || afterplayPlan;
    afterplayPlan = plan;
    if (data?.token_balance != null && profile) {
      profile.token_balance = data.token_balance;
      paintTokenBalance();
    }
    if (plan?.credit_per_run != null) paintAfterplayCreditHint(plan.credit_per_run);
    else if (data?.afterplay_fast_credit_per_run != null) {
      paintAfterplayCreditHint(data.afterplay_fast_credit_per_run);
    }
    const snapLevel = snap.level != null ? formatNumTh(snap.level) : "—";
    const snapExp = snap.exp != null ? formatNumTh(snap.exp) : "—";
    const snapLife = snap.life != null ? formatNumTh(snap.life) : "—";
    const snapCoin = snap.coin != null ? formatNumTh(snap.coin) : "—";
    ["afterplay-snap-level", "afterplay-snap-exp", "afterplay-snap-life", "afterplay-snap-coin", "afterplay-snap-key"].forEach((id) => {
      $(id)?.classList.remove("is-skel");
    });
    if ($("afterplay-snap-level")) $("afterplay-snap-level").textContent = snapLevel;
    if ($("afterplay-snap-exp")) $("afterplay-snap-exp").textContent = snapExp;
    if ($("afterplay-snap-life")) $("afterplay-snap-life").textContent = snapLife;
    if ($("afterplay-snap-coin")) $("afterplay-snap-coin").textContent = snapCoin;
    if ($("afterplay-snap-key")) $("afterplay-snap-key").textContent = snap.key != null ? formatNumTh(snap.key) : "—";
    if (Array.isArray(data?.episodes)) {
      afterplayEboxCatalog = data.episodes;
      paintAfterplayEboxSelect();
    }
    if (plan) {
      if (plan.max_runs != null && Number.isFinite(Number(plan.max_runs))) {
        afterplayPricesMeta.fastMaxRuns = Number(plan.max_runs);
        afterplayPricesMeta.fastMaxRunsKnown = true;
      }
      const planned = Number(plan.planned || plan.runs || 0);
      if ($("afterplay-est-runs")) $("afterplay-est-runs").textContent = formatNumTh(planned);
      if ($("afterplay-est-credit")) $("afterplay-est-credit").textContent = formatCredit(plan.credit || plan.cost || 0);
      if ($("afterplay-est-hearts")) {
        const need = isAfterplayEbox()
          ? planned
          : Number(plan.hearts_required || plan.runs || 0);
        $("afterplay-est-hearts").textContent = formatNumTh(need);
      }
      paintAfterplayBound("afterplay-est-xp", plan.xp_gain ?? plan.xp_gain_min, plan.xp_gain ?? plan.xp_gain_max, { plus: true });
      paintAfterplayBound("afterplay-est-coin", plan.coin_gain ?? plan.coin_min, plan.coin_gain ?? plan.coin_max, { plus: true });
      paintAfterplayEtaText(plan);
      const before = plan.before || snap;
      const safe = plan.after_safe || {};
      const best = plan.after_best || {};
      const cmp = $("afterplay-compare");
      if (cmp) {
        const show = Number(plan.runs || 0) > 0;
        cmp.hidden = !show;
        cmp.classList.toggle("hidden", !show);
        if (show) {
          if ($("afterplay-cmp-before-level")) $("afterplay-cmp-before-level").textContent = formatNumTh(before.level || 0);
          if ($("afterplay-cmp-before-coin")) $("afterplay-cmp-before-coin").textContent = formatNumTh(before.coin || 0);
          if ($("afterplay-cmp-before-life")) $("afterplay-cmp-before-life").textContent = formatNumTh(before.life || 0);
          paintAfterplayBound("afterplay-cmp-after-level", safe.level, best.level);
          paintAfterplayBound("afterplay-cmp-after-coin", safe.coin, best.coin);
          if ($("afterplay-cmp-after-life")) $("afterplay-cmp-after-life").textContent = formatNumTh(safe.life || 0);
        }
      }
      paintAfterplayRoadmap(plan);
    } else if (!isAfterplayEbox()) {
      applyAfterplayLocalPlan();
    }
    paintAfterplayGoalCards();
    paintAfterplayStartEnabled();
  }

  function paintAfterplayGoalCards() {
    const goal = afterplaySelectedGoal();
    $("afterplay-goal-level")?.classList.toggle("is-active", goal === "level");
    $("afterplay-goal-coin")?.classList.toggle("is-active", goal === "coin");
    $("afterplay-goal-runs")?.classList.toggle("is-active", goal === "runs");
  }

  function setAfterplayGoal(kind, opts) {
    let next = kind === "coin" ? "coin" : kind === "runs" ? "runs" : "level";
    if (next !== "runs") {
      if (isAfterplayMoneyOnly()) next = "coin";
      else if (isAfterplayXpOnly()) next = "level";
    }
    const changed = afterplayLastEdit !== next;
    afterplayLastEdit = next;
    paintAfterplayGoalCards();
    if (changed && !(opts && opts.silent)) scheduleAfterplayPreview(next);
  }

  function afterplaySelectedGoal() {
    if (afterplayFamily === "combined" || isAfterplayEbox()) return "runs";
    if (afterplayLastEdit === "runs") return "runs";
    if (isAfterplayMoneyOnly()) return "coin";
    if (isAfterplayXpOnly()) return "level";
    return afterplayLastEdit === "coin" ? "coin" : "level";
  }

  const AFTERPLAY_RANDOM_KEY = "ckr_afterplay_random_v1";
  let afterplayRandomByMode = {};
  let afterplayRandomModalIntent = "";

  function loadAfterplayRandomStore() {
    try {
      const raw = JSON.parse(localStorage.getItem(AFTERPLAY_RANDOM_KEY) || "{}");
      if (raw && typeof raw === "object") afterplayRandomByMode = raw;
    } catch (_) {}
  }

  function saveAfterplayRandomStore() {
    try {
      localStorage.setItem(AFTERPLAY_RANDOM_KEY, JSON.stringify(afterplayRandomByMode));
    } catch (_) {}
  }

  function afterplayClampSpan(lo, hi, cap) {
    const ceiling = Math.max(0, Math.floor(Number(cap) || 0));
    let end = Math.floor(Number(hi));
    let start = Math.floor(Number(lo));
    if (!Number.isFinite(end)) end = ceiling;
    if (!Number.isFinite(start)) start = 0;
    end = Math.max(0, Math.min(ceiling, end));
    start = Math.max(0, Math.min(end, start));
    return { min: start, max: end };
  }

  function afterplayRandomCurrent() {
    const id = afterplayFunctionId();
    const spec = afterplaySpec();
    const coinCap = Math.max(0, Number(spec.coin_max) || 0);
    const expCap = Math.max(0, Number(spec.exp_max) || 0);
    const prev = afterplayRandomByMode[id] && typeof afterplayRandomByMode[id] === "object"
      ? afterplayRandomByMode[id]
      : {};
    const coin = afterplayClampSpan(prev.coinMin, prev.coinMax == null ? coinCap : prev.coinMax, coinCap);
    const exp = afterplayClampSpan(prev.expMin, prev.expMax == null ? expCap : prev.expMax, expCap);
    const row = {
      on: !!prev.on && (coinCap > 0 || expCap > 0),
      coinMin: coin.min,
      coinMax: coin.max,
      expMin: exp.min,
      expMax: exp.max,
    };
    afterplayRandomByMode[id] = row;
    return row;
  }

  function afterplayYieldBounds() {
    const spec = afterplaySpec();
    const rand = afterplayRandomCurrent();
    const coinCap = Math.max(0, Number(spec.coin_max) || 0);
    const expCap = Math.max(0, Number(spec.exp_max) || 0);
    if (rand.on) {
      return {
        coinMin: coinCap ? rand.coinMin : 0,
        coinMax: coinCap ? rand.coinMax : 0,
        expMin: expCap ? rand.expMin : 0,
        expMax: expCap ? rand.expMax : 0,
      };
    }
    const coinTyped = Math.floor(Number($("afterplay-coin-per")?.value));
    const expTyped = Math.floor(Number($("afterplay-exp-per")?.value));
    const coin = coinCap
      ? (Number.isFinite(coinTyped) ? Math.max(0, Math.min(coinCap, coinTyped)) : Number(spec.coin_default) || 0)
      : 0;
    const exp = expCap
      ? (Number.isFinite(expTyped) ? Math.max(0, Math.min(expCap, expTyped)) : Number(spec.exp_default) || 0)
      : 0;
    return { coinMin: coin, coinMax: coin, expMin: exp, expMax: exp };
  }

  function paintAfterplayRandomUi() {
    const spec = afterplaySpec();
    const coinCap = Math.max(0, Number(spec.coin_max) || 0);
    const expCap = Math.max(0, Number(spec.exp_max) || 0);
    const show = coinCap > 0 || expCap > 0;
    const row = afterplayRandomCurrent();
    const wrap = $("afterplay-random-wrap");
    if (wrap) {
      wrap.hidden = !show;
      wrap.classList.toggle("hidden", !show);
    }
    const box = $("afterplay-random-toggle");
    if (box) box.checked = !!(show && row.on);
    const label = $("afterplay-random-label");
    if (label) {
      label.textContent = coinCap && expCap
        ? "สุ่มเหรียญและ XP ต่อรอบ"
        : coinCap
          ? "สุ่มเหรียญต่อรอบ"
          : "สุ่ม XP ต่อรอบ";
    }
    const summary = $("afterplay-random-summary");
    const open = show && row.on;
    if (summary) {
      summary.hidden = !open;
      summary.classList.toggle("hidden", !open);
    }
    const text = $("afterplay-random-summary-text");
    if (text && open) {
      const bits = [];
      if (coinCap) bits.push("เหรียญ " + formatNumTh(row.coinMin) + "–" + formatNumTh(row.coinMax));
      if (expCap) bits.push("XP " + formatNumTh(row.expMin) + "–" + formatNumTh(row.expMax));
      text.textContent = bits.join(" · ");
    }
    const coinInp = $("afterplay-coin-per");
    const expInp = $("afterplay-exp-per");
    if (coinInp) coinInp.disabled = !!(show && row.on && coinCap > 0);
    if (expInp) expInp.disabled = !!(show && row.on && expCap > 0);
  }

  function afterplayRandomInputHtml(id, label, value, max) {
    return (
      '<label class="afterplay-random-field"><span>' + label + "</span>" +
      '<input id="' + id + '" type="number" inputmode="numeric" min="0" max="' + max + '" step="1" value="' + value + '" /></label>'
    );
  }

  function openAfterplayRandomModal(intent) {
    const spec = afterplaySpec();
    const row = afterplayRandomCurrent();
    const coinCap = Math.max(0, Number(spec.coin_max) || 0);
    const expCap = Math.max(0, Number(spec.exp_max) || 0);
    if (!coinCap && !expCap) return;
    afterplayRandomModalIntent = intent || "enable";
    let fields = "";
    if (coinCap) {
      fields += afterplayRandomInputHtml("afterplay-rand-coin-min", "เหรียญน้อยสุด", row.coinMin, coinCap);
      fields += afterplayRandomInputHtml("afterplay-rand-coin-max", "เหรียญมากสุด", row.coinMax, coinCap);
    }
    if (expCap) {
      fields += afterplayRandomInputHtml("afterplay-rand-exp-min", "XP น้อยสุด", row.expMin, expCap);
      fields += afterplayRandomInputHtml("afterplay-rand-exp-max", "XP มากสุด", row.expMax, expCap);
    }
    const hint = (coinCap ? "เหรียญไม่เกิน " + formatNumTh(coinCap) : "") +
      (coinCap && expCap ? " · " : "") +
      (expCap ? "XP ไม่เกิน " + formatNumTh(expCap) : "");
    const icon = afterplayFamilyMeta()?.icon || (coinCap ? "coin_silver.png" : "xp.png?v=20260919x");
    clearModalActions();
    openModal({
      mode: "afterplay-random",
      title: "ตั้งช่วงสุ่มต่อรอบ",
      icon: featureIconSrc(icon),
      bodyHtml:
        "<p>แต่ละรอบจะสุ่มค่าใหม่ในช่วงนี้ ไม่เกินเพดานของโหมดนี้</p>" +
        '<p class="muted">' + hint + "</p>" +
        '<div class="afterplay-random-fields">' + fields + "</div>" +
        '<p class="muted" id="afterplay-rand-error"></p>' +
        '<p class="muted">ถ้าตั้งเป้าเลเวลหรือเป้าเหรียญ ระบบนับจำนวนรอบจากค่าน้อยสุด เพื่อให้ยังถึงเป้าได้</p>',
      locked: false,
    });
    modalActions.appendChild(makeBtn("บันทึก", "btn-candy", () => saveAfterplayRandomModal()));
    modalActions.appendChild(makeBtn("ยกเลิก", "btn-ghost", () => {
      abortAfterplayRandomModal();
      forceCloseModal();
    }));
  }

  function abortAfterplayRandomModal() {
    if (afterplayRandomModalIntent !== "enable") {
      afterplayRandomModalIntent = "";
      return;
    }
    afterplayRandomModalIntent = "";
    const row = afterplayRandomCurrent();
    row.on = false;
    saveAfterplayRandomStore();
    paintAfterplayRandomUi();
  }

  function saveAfterplayRandomModal() {
    const spec = afterplaySpec();
    const coinCap = Math.max(0, Number(spec.coin_max) || 0);
    const expCap = Math.max(0, Number(spec.exp_max) || 0);
    const err = $("afterplay-rand-error");
    const read = (id) => Math.floor(Number($(id)?.value));
    const row = afterplayRandomCurrent();
    if (coinCap) {
      const lo = read("afterplay-rand-coin-min");
      const hi = read("afterplay-rand-coin-max");
      if (!Number.isFinite(lo) || !Number.isFinite(hi) || lo < 0 || hi < 0 || lo > coinCap || hi > coinCap) {
        if (err) err.textContent = "เหรียญต้องอยู่ระหว่าง 0 ถึง " + formatNumTh(coinCap);
        return;
      }
      row.coinMin = Math.min(lo, hi);
      row.coinMax = Math.max(lo, hi);
    }
    if (expCap) {
      const lo = read("afterplay-rand-exp-min");
      const hi = read("afterplay-rand-exp-max");
      if (!Number.isFinite(lo) || !Number.isFinite(hi) || lo < 0 || hi < 0 || lo > expCap || hi > expCap) {
        if (err) err.textContent = "XP ต้องอยู่ระหว่าง 0 ถึง " + formatNumTh(expCap);
        return;
      }
      row.expMin = Math.min(lo, hi);
      row.expMax = Math.max(lo, hi);
    }
    row.on = true;
    afterplayRandomModalIntent = "";
    saveAfterplayRandomStore();
    forceCloseModal();
    paintAfterplayRandomUi();
    scheduleAfterplayPreview(afterplayLastEdit);
  }

  function afterplayAmountPayload() {
    const spec = afterplaySpec();
    const out = {};
    const coin = Math.floor(Number($("afterplay-coin-per")?.value));
    const exp = Math.floor(Number($("afterplay-exp-per")?.value));
    const box = Math.floor(Number($("afterplay-box-max")?.value));
    if (Number.isFinite(coin)) out.coin = Math.max(0, Math.min(spec.coin_max || 0, coin));
    if (Number.isFinite(exp)) out.exp = Math.max(0, Math.min(spec.exp_max || 0, exp));
    if (isAfterplayEbox()) {
      out.qty = 1;
      out.box_max = 1;
    } else if (Number.isFinite(box)) {
      out.box_max = Math.max(0, Math.min(afterplayBoxCap(), box));
    }
    const rand = afterplayRandomCurrent();
    if (rand.on && ((spec.coin_max || 0) > 0 || (spec.exp_max || 0) > 0)) {
      out.randomize = true;
      if ((spec.coin_max || 0) > 0) {
        out.coin_min = rand.coinMin;
        out.coin_max = rand.coinMax;
        out.coin = rand.coinMax;
      }
      if ((spec.exp_max || 0) > 0) {
        out.exp_min = rand.expMin;
        out.exp_max = rand.expMax;
        out.exp = rand.expMax;
      }
    }
    return out;
  }

  function afterplayGoalPayload() {
    const payload = { goal: afterplaySelectedGoal(), farm_mode: afterplayFunctionId(), pace: afterplayPace };
    Object.assign(payload, afterplayAmountPayload());
    if (isAfterplayEbox()) {
      syncAfterplayEboxSelected();
      payload.goal = "runs";
      const runs = afterplayClampRuns(afterplayRequestedRuns());
      if (runs >= 1) payload.runs = runs;
      payload.qty = 1;
      payload.box_max = 1;
      payload.target_eps = [...afterplayEboxSelected];
      payload.auto_relic = afterplayEboxAutoRelicOn();
      return payload;
    }
    if (payload.goal === "coin") {
      const coin = Math.floor(Number($("afterplay-target-coin")?.value || 0));
      if (coin >= 1) payload.target_coin = coin;
    } else if (payload.goal === "level") {
      const tgt = Math.floor(Number($("afterplay-target-level")?.value || 0));
      if (tgt >= 1) payload.target_level = Math.max(1, Math.min(110, tgt));
    } else {
      const runs = afterplayClampRuns(afterplayRequestedRuns());
      if (runs >= 1) payload.runs = runs;
    }
    if (afterplayNeedsEpPick()) {
      syncAfterplayEboxSelected();
      payload.target_eps = [...afterplayEboxSelected];
    }
    return payload;
  }

  async function refreshAfterplayPrices() {
    try {
      const data = await api("/api/farm/afterplay/prices", { timeoutMs: 12000 });
      if (data?.afterplay_fast_credit_per_run != null) {
        afterplayCreditPerRun = Number(data.afterplay_fast_credit_per_run) || afterplayCreditPerRun;
      }
      if (data?.afterplay_episode_box_credit_per_run != null) {
        afterplayEboxCreditPerRun = Number(data.afterplay_episode_box_credit_per_run) || afterplayEboxCreditPerRun;
      }
      afterplayPricesMeta.eboxEnabled = true;
      afterplayPricesMeta.moneyModesEnabled = true;
      if (Array.isArray(data?.functions)) afterplayFnCatalog = data.functions;
      iceTowerPrices.enabled = data?.ice_tower_enabled !== false;
      afterplayPricesMeta.eboxMaxRuns = Number(data?.afterplay_episode_box_max_runs || 50) || 50;
      afterplayPricesMeta.boxQtyMax = Math.max(
        1,
        Math.min(AFTERPLAY_BOX_QTY_MAX, Number(data?.box_qty_max || AFTERPLAY_BOX_QTY_MAX) || AFTERPLAY_BOX_QTY_MAX)
      );
      afterplayPricesMeta.boxQtyDefault = Math.max(
        1,
        Math.min(
          afterplayPricesMeta.boxQtyMax,
          Number(data?.box_qty_default || data?.episode_box?.default_runs_per_ep || AFTERPLAY_BOX_QTY_DEFAULT) ||
            AFTERPLAY_BOX_QTY_DEFAULT
        )
      );
      if (data?.afterplay_fast_max_runs != null) {
        afterplayPricesMeta.fastMaxRuns = Number(data.afterplay_fast_max_runs) || 0;
        afterplayPricesMeta.fastMaxRunsKnown = true;
      }
      if (data?.money_xp && typeof data.money_xp === "object") afterplayPricesMeta.money_xp = data.money_xp;
      if (data?.episode_box && typeof data.episode_box === "object") afterplayPricesMeta.episode_box = data.episode_box;
      if (data?.unlock_l_credit_each != null) {
        unlockLPrices.each = Number(data.unlock_l_credit_each) || unlockLPrices.each;
      }
      if (data?.unlock_l_credit_bundle != null) {
        unlockLPrices.bundle = Number(data.unlock_l_credit_bundle) || unlockLPrices.bundle;
      }
      if (data?.unlock_l_treasure_credit != null) {
        unlockLPrices.treasure = Number(data.unlock_l_treasure_credit) || unlockLPrices.treasure;
      }
      if (data?.ice_tower_credit_each != null) {
        iceTowerPrices.each = Number(data.ice_tower_credit_each) || iceTowerPrices.each;
      }
      if (data?.ice_tower_credit_bundle != null) {
        iceTowerPrices.bundle = Number(data.ice_tower_credit_bundle) || iceTowerPrices.bundle;
      }
      iceTowerPrices.unlockIfNeeded = false;
      iceTowerPrices.enabled = data?.ice_tower_enabled !== false;
      paintFeatureLocks();
      if ($("ice-tower-target-floor") && data?.ice_tower_default_target_floor) {
        $("ice-tower-target-floor").value = String(data.ice_tower_default_target_floor);
      }
      if ($("ice-tower-default-stars") && data?.ice_tower_default_stars) {
        $("ice-tower-default-stars").value = String(data.ice_tower_default_stars);
      }
      const eboxRuns = $("afterplay-ebox-runs");
      if (eboxRuns && !eboxRuns.dataset.touched) {
        eboxRuns.value = String(afterplayBoxQtyDefault());
      }
      paintAfterplayBoxQtyStepper();
      syncAfterplayRunInputsMax();
      syncAfterplayBoxMaxInput();
      applyAfterplayModeParts(afterplayFunctionId());
      paintAfterplayModeUi();
      paintAfterplayCreditHint();
      return data;
    } catch (_) {
      return null;
    }
  }

  async function refreshAfterplayPreview(opts) {
    const sid = requireDevplaySessionId();
    if (!sid) {
      setAfterplayCalculating(false);
      return null;
    }
    const options = opts || {};
    const force = !!options.force;
    const fromTab = !!options.fromTab;
    if (afterplayPreviewInflight) {
      afterplayPreviewQueued = true;
      return null;
    }
    if (
      fromTab &&
      !force &&
      afterplaySnapCache.data &&
      afterplaySnapCache.sid === sid &&
      Date.now() - afterplaySnapCache.at < AFTERPLAY_SNAP_TTL_MS
    ) {
      paintAfterplayPlan(afterplaySnapCache.data);
      applyAfterplayLocalPlan();
      return afterplaySnapCache.data;
    }
    afterplayPreviewInflight = true;
    afterplayPreviewQueued = false;
    const reqSeq = afterplayPreviewSeq;
    const apiMode = afterplayFunctionId();
    const goalPayload = afterplayGoalPayload();
    const body = { devplay_session_id: sid, farm_mode: apiMode, pace: afterplayPace };
    Object.assign(body, goalPayload);
    const haveSnap = !!(afterplaySnapCache.data && afterplaySnapCache.sid === sid);
    setAfterplayCalculating(true, haveSnap ? afterplayCalcMessage(options.source) : "กำลังอ่านไอดี…");
    if (!haveSnap) {
      setStatus(afterplayStatusNode(), "กำลังอ่านไอดี…", "muted");
      [
        ["afterplay-snap-level", "2.2rem"],
        ["afterplay-snap-exp", "3rem"],
        ["afterplay-snap-life", "2rem"],
        ["afterplay-snap-coin", "3rem"],
        ["afterplay-snap-key", "2rem"],
      ].forEach(([id, w]) => setStatSkeleton($(id), true, w));
    }
    let resumeCalc = false;
    try {
      const data = await api("/api/farm/afterplay/preview", { method: "POST", body, timeoutMs: 45000 });
      if (afterplayPreviewQueued || reqSeq !== afterplayPreviewSeq) return data;
      afterplaySnapCache = { at: Date.now(), sid, data };
      paintAfterplayPlan(data);
      const plan = data?.plan;
      if (afterplayNeedsEpPick() && !afterplayEboxSelected.size) {
        setStatus(afterplayStatusNode(), "เลือก Episode", "muted");
      } else if (isAfterplayEbox()) {
        if (!afterplayEboxSelected.size) {
          setStatus(afterplayStatusNode(), "เลือก Episode", "muted");
        } else if (plan?.capped) {
          setStatus(
            afterplayStatusNode(),
            "รอบ/ด่านเกินเพดาน " + formatNumTh(plan.max_runs || 0) + " — ใช้จำนวนสูงสุด",
            "err"
          );
        } else if (Number(plan?.planned || plan?.runs || 0) >= 1) {
          const runs = Number(plan.planned || plan.runs || 0);
          setStatus(
            afterplayStatusNode(),
            formatNumTh(runs) + " รอบ · หัวใจ" + (Number(plan.life || 0) >= 1 ? "พร้อมเริ่ม" : "เป็น 0"),
            Number(plan.life || 0) >= 1 ? "ok" : "err"
          );
        } else {
          setStatus(afterplayStatusNode(), "ใส่จำนวนรอบ/ด่าน", "muted");
        }
      } else if (plan?.capped) {
        const view = afterplayPlanView(plan);
        const need = formatNumTh(view?.hearts_to_goal || 0);
        const capN = formatNumTh(plan.max_runs || 0);
        const goalBit =
          plan.goal === "level"
            ? "ถึงเลเวล " + formatNumTh(view?.goal_level || 0) + " ต้อง " + need + " หัวใจ"
            : "ถึงเป้าต้อง " + need + " หัวใจ";
        setStatus(
          afterplayStatusNode(),
          goalBit + " · รอบนี้สูงสุด " + capN + " รอบ",
          "err"
        );
      } else if (plan?.runs) {
        const why =
          plan.goal === "coin"
            ? " (จากเหรียญ · ค่าประมาณ)"
            : plan.goal === "level"
              ? " (จากเลเวล · ค่าประมาณ)"
              : "";
        setStatus(
          afterplayStatusNode(),
          "ชัวร์ " + formatNumTh(plan.runs) + " รอบ" + why + " · หัวใจ" + (plan.enough_life ? "พร้อม" : "ไม่พอ"),
          plan.enough_life ? "ok" : "err"
        );
      } else if (
        goalPayload &&
        goalPayload.goal === "level" &&
        Number(goalPayload.target_level || 0) >= 1 &&
        Number(data?.snapshot?.level || 0) >= Number(goalPayload.target_level)
      ) {
        setStatus(afterplayStatusNode(), "เลเวลถึงหรือเกินเป้าแล้ว", "ok");
      } else if (goalPayload && goalPayload.goal === "coin" && !goalPayload.target_coin) {
        setStatus(afterplayStatusNode(), "ใส่จำนวนเหรียญที่อยากได้", "muted");
      } else if (goalPayload && goalPayload.goal === "level" && !goalPayload.target_level) {
        setStatus(afterplayStatusNode(), "ใส่เป้าเลเวล", "muted");
      } else if (isAfterplayMoneyOnly()) {
        setStatus(afterplayStatusNode(), "ใส่จำนวนเหรียญที่อยากได้", "muted");
      } else if (isAfterplayXpOnly()) {
        setStatus(afterplayStatusNode(), "ใส่เป้าเลเวล", "muted");
      } else {
        setStatus(afterplayStatusNode(), "ใส่เป้าเลเวลหรือเหรียญอย่างใดอย่างหนึ่ง", "muted");
      }
      return data;
    } catch (err) {
      if (afterplayPreviewQueued || reqSeq !== afterplayPreviewSeq) return null;
      if (!options._afterplayRecovered && (await recoverAfterplaySessionGap(err, afterplayStatusNode()))) {
        afterplayPreviewInflight = false;
        resumeCalc = true;
        return refreshAfterplayPreview({
          force: true,
          source: afterplayLastEdit,
          _afterplayRecovered: true,
        });
      }
      const raw = String(err?.userMessage || err?.message || "");
      setStatus(
        afterplayStatusNode(),
        thError(raw) || raw || "คำนวณไม่สำเร็จ",
        "err"
      );
      return null;
    } finally {
      afterplayPreviewInflight = false;
      if (afterplayPreviewQueued) {
        afterplayPreviewQueued = false;
        refreshAfterplayPreview({ force: true, source: afterplayLastEdit }).catch(() => {});
      } else if (!resumeCalc) {
        setAfterplayCalculating(false);
      }
    }
  }

  function scheduleAfterplayPreview(source) {
    afterplayLastEdit = source || afterplayLastEdit;
    paintAfterplayGoalCards();
    afterplayPreviewSeq += 1;
    applyAfterplayLocalPlan();
    if (devplaySession?.id) {
      setAfterplayCalculating(true, afterplayCalcMessage(afterplayLastEdit));
    }
    if (afterplayPreviewTimer) clearTimeout(afterplayPreviewTimer);
    afterplayPreviewTimer = setTimeout(() => {
      afterplayPreviewTimer = null;
      refreshAfterplayPreview({ source: afterplayLastEdit, force: true }).catch(() => {});
    }, 220);
  }

  function stopAfterplayPoll() {
    if (afterplayPollTimer) {
      clearInterval(afterplayPollTimer);
      afterplayPollTimer = null;
    }
  }

  function setAfterplayStarting(on) {
    const panel = $("farm-panel-afterplay_fast");
    const overlay = $("afterplay-start-overlay");
    const text = $("afterplay-start-overlay-text");
    if (on) {
      if (text) text.textContent = "กำลังส่งเข้าคิวงาน…";
      panel?.classList.add("is-starting");
      if (overlay) {
        overlay.hidden = false;
        overlay.classList.remove("hidden");
        overlay.setAttribute("aria-hidden", "false");
      }
      setAfterplayCalcLocked(true);
      paintAfterplayStartEnabled();
      return;
    }
    panel?.classList.remove("is-starting");
    if (overlay) {
      overlay.hidden = true;
      overlay.classList.add("hidden");
      overlay.setAttribute("aria-hidden", "true");
    }
    if (!afterplayCalculating) setAfterplayCalcLocked(false);
    paintAfterplayStartEnabled();
  }

  async function startAfterplayJob(opts) {
    // Same-kind: allow queue-add when advance queue has room (mirror cross-kind anyJobLive path).
    if (afterplayBusy) return;
    if (afterplayCalculating && !afterplayHasRunnablePlan()) return;
    if (!requireFeatureAccess("afterplay_fast")) return;
    if (isAfterplayRentalOnlyMode() && !requireAfterplayModeAccess()) return;
    const sid = requireDevplaySessionId();
    if (!sid) return;
    const payload = afterplayGoalPayload();
    if (afterplayNeedsEpPick() && !afterplayEboxSelected.size) {
      setStatus(afterplayStatusNode(), "เลือก Episode ที่ปลดแล้ว", "err");
      return;
    }
    if (payload.goal === "runs" && !payload.runs) {
      setStatus(afterplayStatusNode(), "ใส่จำนวนรอบก่อน", "err");
      return;
    }
    if (payload.goal === "coin" && !payload.target_coin && !payload.runs) {
      setStatus(afterplayStatusNode(), "ใส่จำนวนเหรียญหรือจำนวนรอบก่อน", "err");
      return;
    }
    if (payload.goal === "level" && !payload.target_level && !payload.runs) {
      setStatus(afterplayStatusNode(), "ใส่เป้าเลเวลหรือจำนวนรอบก่อน", "err");
      return;
    }
    if (isAfterplayEbox()) {
      if (Number(afterplayPlan?.life || 0) < 1) {
        setStatus(afterplayStatusNode(), "หัวใจเป็น 0 — ห้ามเริ่ม", "err");
        return;
      }
    } else if (afterplayPlan && afterplayPlan.enough_life === false) {
      setStatus(afterplayStatusNode(), "หัวใจไม่พอ — ห้ามเริ่ม", "err");
      return;
    }
    if (!opts?.skipConfirm) {
      const afterplayOk = await showAfterplayConfirmModal();
      if (!afterplayOk) {
        setStatus(afterplayStatusNode(), "ยกเลิกแล้ว", "muted");
        return;
      }
    }
    if (anyJobLive() && !queueHasRoom()) {
      showErrorModal(queueFullMessage(), "คิวเต็ม");
      return;
    }
    const queueOnly = anyJobLive();
    afterplayBusy = true;
    setAfterplayStarting(true);
    setStatus(afterplayStatusNode(), "กำลังส่งเข้าคิวงาน…", "muted");
    try {
      afterplayJobMode = afterplayFunctionId();
      const body = { devplay_session_id: sid, farm_mode: afterplayJobMode, pace: afterplayPace };
      Object.assign(body, afterplayGoalPayload());
      const data = await api("/api/farm/afterplay/start", { method: "POST", body, timeoutMs: 45000 });
      afterplaySnapCache = { at: 0, sid: "", data: null };
      applyStartWallet(data);
      if (data?.job_id && queueOnly) {
        rememberJobAccount(data.job_id);
        announceQueuedJob(data, afterplayModeLabel(afterplayJobMode));
        setStatus(
          afterplayStatusNode(),
          "เข้าคิวล่วงหน้าแล้ว" + queueSeqTag(data) + " — เริ่มอัตโนมัติเมื่อถึงคิว",
          "ok"
        );
      } else if (data?.job_id) {
        afterplayActiveJobId = data.job_id;
        persistKeyedJob(AFTERPLAY_JOB_KEY, data.job_id);
        afterplayResultShownFor = null;
        setAfterplayRunning(true);
        attachCreditJobToHub(
          "afterplay_fast",
          {
            id: data.job_id,
            status: "queued",
            ticket_count: Number(afterplayPlan?.planned || afterplayPlan?.runs || afterplayGoalPayload()?.runs) || 0,
            progress: { current: 0, total: Number(afterplayPlan?.planned || afterplayPlan?.runs) || 0, phase: "queued" },
          },
          { startedNow: true, family: afterplayFamily }
        );
        if (data.queue) applyQueuePayload(data.queue);
        startAdvanceQueuePoll();
        pollAfterplayJob(data.job_id);
        setStatus(afterplayStatusNode(), "เข้าคิวแล้ว — ใช้สิทธิ์วันใช้งาน", "ok");
      }
    } catch (err) {
      if (!afterplayStartRecovered && (await recoverAfterplaySessionGap(err, afterplayStatusNode()))) {
        afterplayStartRecovered = true;
        afterplayBusy = false;
        setAfterplayStarting(false);
        try {
          await startAfterplayJob({ skipConfirm: true });
          return;
        } finally {
          afterplayStartRecovered = false;
        }
      }
      const raw = String(err?.userMessage || err?.message || "");
      if (!handleFarmBillingDenied(err)) {
        setStatus(
          afterplayStatusNode(),
          thError(raw) || raw || "เริ่มไม่สำเร็จ",
          "err"
        );
      }
    } finally {
      afterplayBusy = false;
      setAfterplayStarting(false);
      paintAfterplayStartEnabled();
    }
  }

  function pollAfterplayJob(jobId) {
    stopAfterplayPoll();
    afterplayActiveJobId = jobId;
    let ticks = 0;
    let misses = 0;
    const tick = async () => {
      ticks += 1;
      if (ticks > 1800) {
        stopAfterplayPoll();
        persistKeyedJob(AFTERPLAY_JOB_KEY, null);
        afterplayActiveJobId = null;
        setAfterplayRunning(false);
        setStatus(afterplayStatusNode(), "รอผลนานเกินไป — กดรีเฟรช", "err");
        return;
      }
      try {
        const job = await api("/api/farm/job/" + encodeURIComponent(jobId));
        misses = 0;
        afterplayLogLines = paintCreditJobProgress("afterplay", job) || afterplayLogLines;
        if (["queued", "running"].includes(job.status)) setAfterplayRunning(true);
        if (["succeeded", "failed", "cancelled"].includes(job.status)) {
          stopAfterplayPoll();
          persistKeyedJob(AFTERPLAY_JOB_KEY, null);
          setAfterplayRunning(false);
          await refreshInviteStatus().catch(() => {});
          const jobKey = String(job.id || jobId);
          if (afterplayResultShownFor !== jobKey) {
            afterplayResultShownFor = jobKey;
            showAfterplayResultModal(job);
          }
          const incomplete = farmResultIncomplete(job);
          setStatus(
            afterplayStatusNode(),
            incomplete
              ? farmIncompleteLabel(job)
              : job.status === "succeeded"
                ? afterplaySuccessStatus(job?.result?.farm_mode || afterplayJobMode)
                : "จบ: " + (thError(job.error || job.status) || job.error || job.status),
            incomplete ? "warn" : job.status === "succeeded" ? "ok" : "err"
          );
          refreshAfterplayPreview({ force: true, source: afterplayLastEdit }).catch(() => {});
          attachNextQueuedJob();
        }
      } catch (_) {
        misses += 1;
        if (misses >= 8) {
          stopAfterplayPoll();
          persistKeyedJob(AFTERPLAY_JOB_KEY, null);
          afterplayActiveJobId = null;
          setAfterplayRunning(false);
          setStatus(afterplayStatusNode(), "เช็คสถานะงานไม่สำเร็จ — กดรีเฟรช", "err");
        }
      }
    };
    tick();
    afterplayPollTimer = setInterval(tick, 2000);
  }

  function signedDelta(n) {
    const v = Number(n) || 0;
    if (v > 0) return "+" + formatNumTh(v);
    if (v < 0) return formatNumTh(v);
    return "0";
  }

  async function cancelAfterplayJob() {
    const jobId = afterplayActiveJobId || loadKeyedJob(AFTERPLAY_JOB_KEY);
    if (!jobId) return;
    try {
      await cancelServerJob(jobId);
      showToast("ส่งคำขอยกเลิกแล้ว", "ok");
      if (!afterplayPollTimer) pollAfterplayJob(jobId);
    } catch (e) {
      setStatus(afterplayStatusNode(), String(e?.userMessage || e?.message || "ยกเลิกไม่สำเร็จ"), "err");
    }
  }

  const UNLOCK_L_TREASURE_EPS = new Set([502, 503]);

  function unlockLIsTreasure(ep) {
    return UNLOCK_L_TREASURE_EPS.has(Number(ep));
  }

  function unlockLIsUnavailable(row) {
    if (!row || row.owned) return false;
    if (row.unavailable === true) return true;
    const ep = Number(row.ep);
    if (UNLOCK_L_TREASURE_EPS.has(ep)) return isIceTowerOffline();
    if (ep === 5 && row.unlocked !== true) return isIceTowerOffline();
    return false;
  }

  function unlockLEpisodeReady(row) {
    if (!row || row.owned) return false;
    if (unlockLIsUnavailable(row)) return false;
    const ep = Number(row.ep);
    if (row.unlocked === true) return true;
    if (row.unlocked === false) return false;
    return ep === 1;
  }

  function unlockLIsClassL(ep) {
    const n = Number(ep);
    return n >= 1 && n <= 7;
  }

  function unlockLCardLabel(row) {
    const ep = Number(row?.ep);
    if (row?.special_label) return String(row.special_label);
    if (Number(row?.special) === 2 || ep === 502) return "Special 2";
    if (Number(row?.special) === 3 || ep === 503) return "Special 3";
    return "EP " + ep;
  }

  function unlockLNeedsLife(billable, _catalog) {
    return (billable || []).some((ep) => unlockLIsClassL(ep));
  }

  function unlockLNeedsKey(billable, catalog) {
    return unlockLKeyPlan(billable, catalog).needKey;
  }

  const UNLOCK_L_EP5_KEYS = 5;
  const UNLOCK_L_TREASURE_FRAME = "assets/icons/grade_frames/L.png";
  const UNLOCK_L_PARENT = {
    2: [1, 40],
    3: [1, 60],
    6: [1, 80],
    4: [3, 50],
    7: [6, 40],
    502: [1, 30],
    503: [1, 10],
  };
  const UNLOCK_ROUND_SEC = 40;
  const HUNT_ROUND_SEC = 11;
  const ICE_ROUND_SEC = 40;
  const QUESTS_PER_UNLOCK_ROUND = 5;
  const UNLOCK_L_OVERLAP = 2;

  function wallPlaySec(nPlays, secEach, overlap) {
    const ov = Math.max(1, Number(overlap) || 1);
    const n = Math.max(0, Number(nPlays) || 0);
    const each = Math.max(0, Number(secEach) || 0);
    if (!n || !each) return 0;
    return Math.ceil(n / ov) * each;
  }

  function unlockLAncestorsNeeded(targetEps) {
    const needed = {};
    const visit = (ep) => {
      const parent = UNLOCK_L_PARENT[ep];
      if (!parent) return;
      const p = parent[0];
      const need = parent[1];
      needed[p] = Math.max(needed[p] || 0, need);
      visit(p);
    };
    (targetEps || []).forEach((raw) => {
      const ep = Number(raw);
      visit(ep);
      if (ep === 5) needed[1] = Math.max(needed[1] || 0, 30);
    });
    return needed;
  }

  function estimateUnlockLEta(billable, catalog, snap, overlap) {
    const byEp = new Map((catalog || []).map((r) => [Number(r.ep), r]));
    const hunt = (billable || []).filter((ep) => {
      const row = byEp.get(Number(ep)) || { ep };
      if (row.owned) return false;
      return unlockLEpisodeReady(row);
    });
    if (!hunt.length) {
      return { eta_sec: 0, eta_label: "", note: "", unlock_sec: 0, hunt_sec: 0, ice_sec: 0 };
    }
    const ov = Math.max(1, Math.min(2, Number(overlap) || UNLOCK_L_OVERLAP));
    const life = Number(snap?.life || 0);
    const key = Number(snap?.key || 0);
    let huntSec = 0;
    if (hunt.some((ep) => unlockLIsClassL(ep))) huntSec += wallPlaySec(life, HUNT_ROUND_SEC, ov);
    if (hunt.some((ep) => Number(ep) === 502)) huntSec += wallPlaySec(key, ICE_ROUND_SEC, ov);
    else if (hunt.some((ep) => Number(ep) === 503)) huntSec += wallPlaySec(key, HUNT_ROUND_SEC, ov);
    const note = huntSec ? "ล่าจนกว่าจะได้หรือหัวใจ/กุญแจหมด" : "";
    return {
      eta_sec: huntSec,
      eta_label: huntSec ? formatEtaSec(huntSec) + (note ? " · " + note : "") : "",
      note,
      unlock_sec: 0,
      hunt_sec: huntSec,
      ice_sec: 0,
    };
  }

  function estimateIceTowerEta(needStars, ice, overlap) {
    let sec = 0;
    const keys = Number(ice?.keys || 0);
    const stars = Math.max(0, Number(needStars) || 0);
    const play = keys > 0 ? Math.min(stars, keys) : stars;
    sec += wallPlaySec(play, ICE_ROUND_SEC, overlap || UNLOCK_L_OVERLAP);
    return {
      eta_sec: sec,
      eta_label: sec ? formatEtaSec(sec) + " · ไต่หอ" : "",
    };
  }

  function remainingEtaSec() {
    const sec = Number(dockEta?.sec) || 0;
    if (sec <= 0) return 0;
    const at = Number(dockEta.at) || 0;
    if (!at) return sec;
    return Math.max(0, Math.round(sec - (Date.now() / 1000 - at)));
  }

  function remainingEtaLabel() {
    const left = remainingEtaSec();
    if (left > 0) {
      return String(formatEtaSec(left) || "").replace(/^ประมาณ/, "เหลือประมาณ");
    }
    if ((Number(dockEta?.sec) || 0) > 0 && dockPhase === "running") {
      return "ใกล้เสร็จแล้ว — อย่ายกเลิก";
    }
    return "";
  }

  function setDockEtaFromProgress(prog) {
    if (!prog || typeof prog !== "object") return;
    if (prog.eta_sec == null && !prog.eta_label) return;
    dockEta = {
      sec: Math.max(0, Number(prog.eta_sec) || 0),
      label: String(prog.eta_label || ""),
      at: Number(prog.updated_at) || Date.now() / 1000,
    };
  }

  function clearDockEta() {
    dockEta = { sec: 0, label: "", at: 0 };
  }

  function unlockLKeyPlan(billable, _catalog) {
    const have = Number(unlockLSnap.key || 0);
    const treasures = (billable || []).filter((ep) => unlockLIsTreasure(ep));
    const hunt = treasures.length > 0;
    let minNeed = 0;
    let maxNeed = 0;
    if (hunt) {
      minNeed = 1;
      maxNeed = have;
    }
    return {
      have,
      minNeed,
      maxNeed,
      enough: have >= minNeed,
      needKey: minNeed > 0,
      ep5Unlock: false,
      hunt,
      treasures,
    };
  }

  function unlockLQuote(selected, catalog) {
    const byEp = new Map((catalog || []).map((r) => [Number(r.ep), r]));
    const owned = new Set((catalog || []).filter((r) => r.owned).map((r) => Number(r.ep)));
    const billable = [...selected].filter((ep) => {
      if (owned.has(ep)) return false;
      const row = byEp.get(ep) || { ep };
      return unlockLEpisodeReady(row);
    });
    const lEps = billable.filter((ep) => unlockLIsClassL(ep));
    const treasures = billable.filter((ep) => unlockLIsTreasure(ep));
    const each = Number(unlockLPrices.each || 15);
    const bundle = Number(unlockLPrices.bundle || 100);
    const treasureEach = Number(unlockLPrices.treasure || 15);
    const lCredit = lEps.length <= 0 ? 0 : lEps.length >= 7 ? bundle : Math.round(each * lEps.length * 100) / 100;
    const tCredit = Math.round(treasureEach * treasures.length * 100) / 100;
    return {
      n: billable.length,
      lCount: lEps.length,
      treasureCount: treasures.length,
      credit: Math.round((lCredit + tCredit) * 100) / 100,
      billable,
    };
  }

  const UNLOCK_L_EP_IMAGES = {
    1: "assets/King_Choco_Drop.png",
    2: "assets/Tiger_Lily_Cookie.png",
    3: "assets/Fire_Spirit_Cookie.png",
    4: "assets/Moonlight_Cookie.png",
    5: "assets/Wind_Archer_Cookie.png",
    6: "assets/Blooming_Dancheong_Cookie.png",
    7: "assets/unlock_l_ep7.png",
    502: "assets/treasures/sea_fairy_yearning.png",
    503: "assets/treasures/marshmallow_star.png",
  };

  function unlockLEpImage(ep, name) {
    const mapped = UNLOCK_L_EP_IMAGES[Number(ep)];
    if (mapped) return mapped;
    const n = String(name || "").trim();
    if (!n) return "assets/Tiger_Lily_Cookie.png";
    return "assets/" + n.replace(/\s+/g, "_").replace(/[()]/g, "") + ".png";
  }

  function unlockLEpShortName(ep) {
    const n = Number(ep) || 0;
    if (!n) return "";
    const row = (unlockLCatalog || []).find((r) => Number(r.ep) === n);
    if (row?.name) return String(row.name);
    return unlockLCardLabel(row || { ep: n });
  }

  function unlockLListEps(raw) {
    if (!Array.isArray(raw)) return [];
    const out = [];
    raw.forEach((item) => {
      const n = Number(item);
      if (n > 0 && !out.includes(n)) out.push(n);
    });
    return out;
  }

  function unlockLEpsFromJob(jobOrRow) {
    const prog = jobOrRow?.progress && typeof jobOrRow.progress === "object" ? jobOrRow.progress : {};
    const res = parseFarmJobResult(jobOrRow?.result);
    const params = jobOrRow?.params && typeof jobOrRow.params === "object" ? jobOrRow.params : {};
    const current = Number(prog.ep) || 0;
    const unlocked = unlockLListEps(res.unlocked);
    const targets = unlockLListEps(res.target_eps)
      .concat(unlockLListEps(params.target_eps))
      .concat(unlockLListEps(params.billable_eps));
    const uniqueTargets = [];
    targets.forEach((n) => {
      if (!uniqueTargets.includes(n)) uniqueTargets.push(n);
    });
    return { current, unlocked, targets: uniqueTargets };
  }

  function unlockLDisplayEp(jobOrRow) {
    const info = unlockLEpsFromJob(jobOrRow || {});
    if (info.current) return info.current;
    if (info.unlocked.length) return info.unlocked[info.unlocked.length - 1];
    if (info.targets.length) return info.targets[0];
    return 0;
  }

  function unlockLExtrasFromJob(jobOrRow) {
    const info = unlockLEpsFromJob(jobOrRow || {});
    const unlockEps = info.targets.length
      ? info.targets
      : info.unlocked.length
        ? info.unlocked
        : info.current
          ? [info.current]
          : [];
    return {
      unlockEp: info.current || unlockLDisplayEp(jobOrRow) || 0,
      unlockEps,
    };
  }

  function unlockLThumbsFromJob(jobOrRow) {
    return unlockLExtrasFromJob(jobOrRow).unlockEps.map((ep) => ({
      ep,
      name: unlockLEpShortName(ep),
      url: unlockLEpImage(ep),
    }));
  }

  function afterplayEboxRows() {
    const rows = afterplayEboxCatalog && afterplayEboxCatalog.length ? afterplayEboxCatalog : [
      { ep: 1, name: "ด่าน 1" },
      { ep: 2, name: "ด่าน 2" },
      { ep: 3, name: "ด่าน 3" },
      { ep: 4, name: "ด่าน 4" },
      { ep: 5, name: "ด่าน 5 · Ice Tower" },
      { ep: 6, name: "ด่าน 6" },
      { ep: 7, name: "ด่าน 7" },
    ];
    return rows.filter((r) => Number(r.ep) >= 1 && Number(r.ep) <= 7);
  }

  function afterplayEboxEpUnlocked(ep) {
    const n = Number(ep);
    if (n < 1 || n > 7) return false;
    const rows = afterplayEboxCatalog || [];
    if (!rows.length) return true;
    const row = rows.find((r) => Number(r.ep) === n);
    if (!row) return n === 1;
    return row.unlocked !== false;
  }

  function afterplayEboxEpAllowed(ep) {
    return afterplayEboxEpUnlocked(ep);
  }

  function afterplayEboxUnlockedList() {
    return [1, 2, 3, 4, 5, 6, 7].filter(afterplayEboxEpAllowed);
  }

  function afterplayEboxAutoRelicOn() {
    const el = $("afterplay-ebox-auto-relic");
    if (!el) return true;
    return !!el.checked;
  }

  function loadAfterplayEboxAutoRelic() {
    const el = $("afterplay-ebox-auto-relic");
    if (!el) return;
    try {
      const saved = localStorage.getItem(AFTERPLAY_EBOX_RELIC_KEY);
      if (saved === "0") el.checked = false;
      else el.checked = true;
    } catch (_) {
      el.checked = true;
    }
  }

  function afterplayEboxMeta(ep) {
    const n = Number(ep);
    const catalog = questCatalog();
    const row = (catalog.episodes || []).find((item) => Number(item.id) === n);
    const pad = n < 10 ? "0" + n : String(n);
    const coverFile = row?.cover || ("epN" + pad + ".jpg");
    const iconFile = row?.icon || ("epN" + pad + ".png");
    return {
      ep: n,
      name: n === 5 ? "ด่าน 5 · Ice Tower" : String(row?.name_th || row?.kicker || ("ด่าน " + n)),
      cover: questIconSrc(coverFile, "cover"),
      icon: questIconSrc(iconFile, "episode"),
    };
  }

  function afterplayEboxPickValue() {
    const unlocked = afterplayEboxUnlockedList();
    if (!afterplayEboxSelected.size) return "";
    if (unlocked.length && unlocked.every((ep) => afterplayEboxSelected.has(ep)) && afterplayEboxSelected.size === unlocked.length) {
      return "all";
    }
    if (afterplayEboxSelected.size === 1) return String([...afterplayEboxSelected][0]);
    return "all";
  }

  function setAfterplayEboxPick(value, opts) {
    const sel = afterplayEpSelect();
    const raw = String(value || "");
    if (raw === "all") {
      const unlocked = afterplayEboxUnlockedList();
      if (!unlocked.length) return;
      afterplayEboxSelected = new Set(unlocked);
      if (sel) sel.value = "all";
    } else {
      const n = Math.floor(Number(raw));
      if (!afterplayEboxEpAllowed(n)) {
        if (!opts?.silent) showToast("เลือกได้เฉพาะด่านที่ปลดแล้ว", "err");
        return;
      }
      afterplayEboxSelected = new Set([n]);
      if (sel) sel.value = String(n);
    }
    paintAfterplayEboxGrid();
    if (!opts?.skipPreview) scheduleAfterplayPreview("ebox");
  }

  function afterplayEboxPickCopy(value) {
    const pick = String(value || "").trim();
    if (pick === "all") return "ทุกด่านที่ปลดแล้ว";
    const n = Math.floor(Number(pick));
    if (n >= 1 && n <= 7) return afterplayEboxMeta(n).name;
    return "ยังไม่ได้เลือก";
  }

  function paintAfterplayEboxTrigger() {
    const label = $("afterplay-ebox-pick-label");
    const icon = $("afterplay-ebox-pick-icon");
    const btn = $("afterplay-ebox-pick-btn");
    const pick = afterplayEboxPickValue();
    if (label) label.textContent = afterplayEboxPickCopy(pick);
    if (icon) {
      icon.src =
        pick && pick !== "all"
          ? afterplayEboxMeta(Number(pick)).icon
          : "assets/mystery_box.png?v=20260901c";
    }
    btn?.classList.toggle("is-empty", !pick);
  }

  function paintAfterplayEboxPickerGrid() {
    const grid = $("afterplay-ebox-picker-grid");
    if (!grid) return;
    const unlocked = afterplayEboxUnlockedList();
    const pick = String(afterplayEboxDraft || "");
    const allOn = pick === "all";
    const tiles = [
      '<button type="button" class="afterplay-ebox-picker-all' +
        (allOn ? " is-on" : "") +
        '" data-ebox-pick="all"' +
        (unlocked.length ? "" : " disabled") +
        ">" +
        "<strong>ทุกด่านที่ปลดแล้ว</strong>" +
        "<span>" +
        (afterplayFamily === "combined"
          ? "ยิง Coin/Xp/Box ทุกด่านที่บัญชีนี้ปลดแล้ว"
          : "ฟาร์มกล่องทุกด่านที่บัญชีนี้ปลดแล้ว") +
        "</span>" +
        "</button>",
    ];
    [1, 2, 3, 4, 5, 6, 7].forEach((ep) => {
      const meta = afterplayEboxMeta(ep);
      const allowed = afterplayEboxEpAllowed(ep);
      const selected = !allOn && pick === String(ep);
      tiles.push(
        '<button type="button" class="afterplay-ebox-picker-tile afterplay-ebox-picker-tile--' +
          ep +
          (allowed ? "" : " is-locked") +
          (selected ? " is-on" : "") +
          '" data-ebox-pick="' +
          ep +
          '" title="' +
          escapeHtml(allowed ? meta.name : meta.name + " · ยังไม่ได้ปลดด่าน") +
          '">' +
          '<span class="afterplay-ebox-picker-cover" style="background-image:url(\'' +
          escapeHtml(meta.cover) +
          "')\"></span>" +
          '<span class="afterplay-ebox-picker-shade" aria-hidden="true"></span>' +
          '<img class="afterplay-ebox-picker-icon" src="' +
          escapeHtml(meta.icon) +
          '" alt="" width="22" height="22" loading="lazy" />' +
          '<strong class="afterplay-ebox-picker-name">' +
          escapeHtml(meta.name) +
          "</strong>" +
          (allowed ? "" : '<span class="afterplay-ebox-picker-lock">ยังไม่ได้ปลดด่าน</span>') +
          "</button>"
      );
    });
    grid.innerHTML = tiles.join("");
  }

  function paintAfterplayEboxGrid() {
    paintAfterplayEboxTrigger();
    paintAfterplayEboxPickerGrid();
  }

  function syncAfterplayEboxPickerOk() {
    const ok = $("afterplay-ebox-picker-ok");
    if (ok) ok.disabled = !String(afterplayEboxDraft || "").trim();
  }

  function showAfterplayEboxPicker() {
    afterplayEboxDraft = afterplayEboxPickValue();
    clearModalActions();
    openModal({
      mode: "pick",
      title: "เลือกด่านฟาร์มกล่อง",
      icon: "assets/mystery_box.png?v=20260901c",
      locked: false,
      cardClass: "modal-card--picker",
      bodyHtml:
        '<p class="afterplay-ebox-picker-hint">เลือกด่านที่ปลดแล้ว แล้วกดตกลง</p>' +
        '<div class="afterplay-ebox-picker-grid" id="afterplay-ebox-picker-grid" role="listbox" aria-label="เลือกด่าน"></div>',
    });
    paintAfterplayEboxPickerGrid();
    $("afterplay-ebox-picker-grid")?.addEventListener("click", (ev) => {
      const btn = ev.target.closest("[data-ebox-pick]");
      if (!btn) return;
      if (btn.disabled || btn.classList.contains("is-locked")) {
        showToast("เลือกได้เฉพาะด่านที่ปลดแล้ว", "err");
        return;
      }
      afterplayEboxDraft = String(btn.getAttribute("data-ebox-pick") || "");
      paintAfterplayEboxPickerGrid();
      syncAfterplayEboxPickerOk();
    });
    modalActions.classList.add("row");
    const ok = makeBtn("ตกลง", "btn-candy", () => {
      if (!String(afterplayEboxDraft || "").trim()) return;
      setAfterplayEboxPick(afterplayEboxDraft);
      forceCloseModal();
    });
    ok.id = "afterplay-ebox-picker-ok";
    ok.disabled = !String(afterplayEboxDraft || "").trim();
    modalActions.appendChild(ok);
    modalActions.appendChild(makeBtn("ยกเลิก", "btn-ghost", () => forceCloseModal()));
  }

  function clampAfterplayEboxRunsInput() {
    const el = $("afterplay-ebox-runs");
    if (!el) return 0;
    const lo = 1;
    const cap = afterplayBoxQtyMax();
    el.min = String(lo);
    el.max = String(cap);
    const raw = String(el.value || "").trim();
    const n = Math.floor(Number(raw));
    if (!Number.isFinite(n) || n < lo) {
      el.value = String(afterplayBoxQtyDefault());
      paintAfterplayBoxQtyStepper();
      return afterplayBoxQtyDefault();
    }
    const v = Math.max(lo, Math.min(cap, n));
    if (String(el.value) !== String(v)) el.value = String(v);
    paintAfterplayBoxQtyStepper();
    return v;
  }

  function paintAfterplayBoxQtyStepper() {
    const el = $("afterplay-ebox-runs");
    const minus = $("afterplay-box-qty-minus");
    const plus = $("afterplay-box-qty-plus");
    if (!el) return;
    const n = Math.floor(Number(el.value));
    const v = Number.isFinite(n) ? n : afterplayBoxQtyDefault();
    const lo = 1;
    const hi = afterplayBoxQtyMax();
    if (minus) minus.disabled = v <= lo;
    if (plus) plus.disabled = v >= hi;
    const hint = $("afterplay-box-qty-hint");
    if (hint) hint.textContent = "ค่าเริ่ม 1 · สูงสุด " + hi + " ใบต่อรอบ";
  }

  function setAfterplayBoxQty(next) {
    const el = $("afterplay-ebox-runs");
    if (!el) return;
    const hi = afterplayBoxQtyMax();
    const v = Math.max(1, Math.min(hi, Math.floor(Number(next) || afterplayBoxQtyDefault())));
    el.value = String(v);
    el.dataset.touched = "1";
    paintAfterplayBoxQtyStepper();
    scheduleAfterplayPreview("ebox");
  }

  function afterplayEpSelect() {
    return $("afterplay-ebox-ep");
  }

  function syncAfterplayEboxSelected() {
    const v = String(afterplayEpSelect()?.value || "");
    if (v === "all") {
      afterplayEboxSelected = new Set(afterplayEboxUnlockedList());
      return;
    }
    const n = Math.floor(Number(v));
    afterplayEboxSelected = n >= 1 && n <= 7 && afterplayEboxEpAllowed(n) ? new Set([n]) : new Set();
  }

  function paintAfterplayEboxSelect() {
    ["afterplay-ebox-ep"].forEach((id) => {
      const sel = $(id);
      if (!sel) return;
      [...sel.options].forEach((opt) => {
        if (opt.value === "all") {
          opt.textContent = "ทุกด่านที่ปลดแล้ว";
          opt.disabled = afterplayEboxUnlockedList().length < 1;
          return;
        }
        const ep = Math.floor(Number(opt.value));
        if (ep < 1 || ep > 7) return;
        const allowed = afterplayEboxEpAllowed(ep);
        let label = "Episode " + ep;
        if (ep === 5) label += " · Ice Tower";
        if (!allowed) label += " · ยังไม่ปลด";
        opt.textContent = label;
        opt.disabled = !allowed;
      });
      const cur = String(sel.value || "");
      const curEp = Math.floor(Number(cur));
      if (cur && cur !== "all" && !afterplayEboxEpAllowed(curEp)) sel.value = "";
    });
    syncAfterplayEboxSelected();
    paintAfterplayEboxGrid();
  }

  function paintUnlockLGrid() {
    const grid = $("unlockl-grid");
    if (!grid) return;
    grid.innerHTML = "";
    unlockLCatalog.forEach((row) => {
      const ep = Number(row.ep);
      const owned = !!row.owned;
      const unavailable = !owned && unlockLIsUnavailable(row);
      const epLocked = !owned && !unavailable && !unlockLEpisodeReady(row);
      const selected = !owned && !unavailable && !epLocked && unlockLSelected.has(ep);
      const treasure = unlockLIsTreasure(ep) || row.kind === "treasure";
      const label = unlockLCardLabel(row);
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className =
        "unlockl-card" +
        (owned ? " is-owned" : "") +
        (unavailable ? " is-maintenance" : "") +
        (epLocked ? " is-ep-locked" : "") +
        (selected ? " is-selected" : "") +
        (treasure ? " is-treasure" : "");
      btn.dataset.ep = String(ep);
      btn.disabled = owned || unavailable || epLocked;
      btn.title = unavailable
        ? (row.name || label) + " · ปิดปรับปรุง (ใช้กุญแจ / Ice Tower)"
        : epLocked
          ? (row.name || label) + " · ต้องปลดด่านนี้มาก่อน"
          : (row.name || label) + (owned ? " · มีแล้ว" : "");
      btn.setAttribute(
        "aria-label",
        label + " " + (row.name || "") + (owned ? " มีแล้ว" : unavailable ? " ปิดปรับปรุง" : epLocked ? " ต้องปลดด่านก่อน" : " ยังไม่มี")
      );
      const check = document.createElement("span");
      check.className = "unlockl-card-check";
      check.textContent = selected ? "✓" : "";
      const img = document.createElement("img");
      img.className = "unlockl-card-img";
      img.src = unlockLEpImage(ep, row.name);
      img.alt = "";
      img.width = treasure ? 67 : 88;
      img.height = treasure ? 67 : 88;
      img.loading = "lazy";
      img.onerror = () => {
        img.onerror = null;
        img.src = "assets/Tiger_Lily_Cookie.png";
      };
      const art = document.createElement("span");
      if (treasure) {
        art.className = "unlockl-treasure-wrap";
        const frame = document.createElement("img");
        frame.className = "unlockl-treasure-frame";
        frame.src = gradeFrameSrc("L", treasureIsEvo(row));
        frame.alt = "";
        art.append(frame, img);
      } else {
        art.className = "unlockl-art";
        art.append(img);
      }
      const epEl = document.createElement("span");
      epEl.className = "unlockl-ep";
      epEl.textContent = label;
      const stateEl = document.createElement("span");
      stateEl.className = "unlockl-state";
      stateEl.textContent = owned
        ? "มีแล้ว"
        : unavailable
          ? "ปิดปรับปรุง"
          : epLocked
            ? "ยังไม่ปลดด่าน"
            : selected
              ? "เลือกแล้ว"
              : "ยังไม่มี";
      btn.append(check, art, epEl, stateEl);
      if (!owned && !unavailable && !epLocked) {
        btn.addEventListener("click", (ev) => {
          ev.preventDefault();
          ev.stopPropagation();
          if (unlockLSelected.has(ep)) unlockLSelected.delete(ep);
          else unlockLSelected.add(ep);
          paintUnlockLGrid();
          paintUnlockLQuote();
        });
      }
      grid.appendChild(btn);
    });
    paintUnlockLQuote();
  }

  function paintUnlockLQuote() {
    const q = unlockLQuote(unlockLSelected, unlockLCatalog);
    if ($("unlockl-quote")) $("unlockl-quote").textContent = formatCredit(q.credit) + " Credit";
    if ($("unlockl-price-each")) $("unlockl-price-each").textContent = formatCredit(unlockLPrices.each);
    if ($("unlockl-price-bundle")) $("unlockl-price-bundle").textContent = formatCredit(unlockLPrices.bundle);
    if ($("unlockl-price-treasure")) $("unlockl-price-treasure").textContent = formatCredit(unlockLPrices.treasure);
    if ($("unlockl-toolbar-meta")) {
      $("unlockl-toolbar-meta").textContent = q.n
        ? "เลือก " + formatNumTh(q.n) + " รายการ · รวมในวันใช้งาน"
        : "เลือกตัวที่ปลดด่านแล้ว · รวมในวันใช้งาน";
    }
    const eta = q.n ? estimateUnlockLEta(q.billable, unlockLCatalog, unlockLSnap, UNLOCK_L_OVERLAP) : null;
    const etaEl = $("unlockl-eta");
    if (etaEl) {
      if (eta && eta.eta_sec > 0) {
        etaEl.hidden = false;
        etaEl.classList.remove("hidden", "is-empty");
        etaEl.textContent =
          eta.eta_label +
          " — อย่ายกเลิกกลางคัน งานยังไม่จบจนกว่าจะขึ้นว่าสำเร็จ";
      } else {
        etaEl.hidden = true;
        etaEl.classList.add("hidden");
        etaEl.textContent = "";
      }
    }
    if ($("unlockl-snap-life")) $("unlockl-snap-life").textContent = formatNumTh(unlockLSnap.life || 0);
    if ($("unlockl-snap-key")) $("unlockl-snap-key").textContent = formatNumTh(unlockLSnap.key || 0);
    const btn = $("unlockl-start-btn");
    const needLife = unlockLNeedsLife(q.billable, unlockLCatalog);
    const keys = unlockLKeyPlan(q.billable, unlockLCatalog);
    const noLife = needLife && Number(unlockLSnap.life || 0) < 1;
    const noKey = keys.needKey && !keys.enough;
    const can =
      !unlockLBusy &&
      q.n > 0 &&
      !!devplaySession?.id &&
      !noLife &&
      !noKey &&
      canPayForFeature("unlock_l");
    if (btn) {
      const starting = unlockLBusy && !unlockLRunning;
      const running = !!unlockLRunning;
      setBtnLoading(btn, starting);
      if (starting) {
        btn.disabled = true;
        btn.classList.toggle("is-disabled-look", true);
        const sub = $("unlockl-start-btn-sub");
        if (sub) sub.textContent = "กำลังส่งเข้าคิวงาน…";
      } else if (running) {
        const ok = can && queueHasRoom();
        btn.disabled = !ok;
        btn.classList.toggle("is-disabled-look", !ok);
        const sub = $("unlockl-start-btn-sub");
        if (sub) {
          sub.textContent = ok ? "กำลังรัน — กดเพื่อเข้าคิวเพิ่ม" : "กำลังรัน…";
        }
      } else {
        btn.disabled = !can;
        btn.classList.toggle("is-disabled-look", !can);
      }
    }
    const lifeWarn = $("unlockl-life-warn");
    if (lifeWarn) {
      lifeWarn.hidden = !noLife;
      lifeWarn.classList.toggle("hidden", !noLife);
    }
    const keyWarn = $("unlockl-key-warn");
    if (keyWarn) {
      keyWarn.hidden = !noKey;
      keyWarn.classList.toggle("hidden", !noKey);
      if (noKey) {
        keyWarn.textContent =
          keys.have < 1
            ? "กุญแจในไอดีเป็น 0 — สมบัติ Special ใช้กุญแจ"
            : "กุญแจในไอดี " +
              formatNumTh(keys.have) +
              " ดอก — ต้องอย่างน้อย " +
              formatNumTh(keys.minNeed) +
              " ดอก";
      }
    }
    const keyHint = $("unlockl-key-hint");
    if (keyHint) {
      const showHint = !noKey && keys.needKey && q.n > 0;
      keyHint.hidden = !showHint;
      keyHint.classList.toggle("hidden", !showHint);
      if (showHint) {
        const who = keys.hunt
          ? keys.treasures.length > 1
            ? "สมบัติ Special 2/3 ใช้ทีละดอกจนกว่าจะได้"
            : Number(keys.treasures[0]) === 502
              ? "Special 2 ใช้ทีละดอกจนกว่าจะได้"
              : "Special 3 ใช้ทีละดอกจนกว่าจะได้"
          : "สมบัติ Special ใช้กุญแจ";
        keyHint.textContent =
          "กุญแจในไอดี " +
          formatNumTh(keys.have) +
          " ดอก · " +
          who +
          " · ใช้ประมาณสูงสุด " +
          formatNumTh(keys.maxNeed) +
          " ดอก";
      }
    }
    if ($("unlockl-start-btn-sub") && !unlockLRunning && !unlockLBusy) {
      if (!q.n) $("unlockl-start-btn-sub").textContent = "เลือกอย่างน้อย 1 ตัวที่ปลดด่านแล้ว";
      else if (noLife) $("unlockl-start-btn-sub").textContent = "หัวใจเป็น 0 — ห้ามเริ่ม";
      else if (noKey) {
        $("unlockl-start-btn-sub").textContent =
          keys.have < 1 ? "กุญแจในไอดีเป็น 0 — ห้ามเริ่ม" : "กุญแจไม่พอ (มี " + formatNumTh(keys.have) + " ต้อง " + formatNumTh(keys.minNeed) + ")";
      }
      else {
        let sub = "เริ่มปลดล็อค · " + formatNumTh(q.n) + " ตัว";
        if (eta && eta.eta_sec > 0) sub += " · " + formatEtaSec(eta.eta_sec);
        else sub += " · รวมในวันใช้งาน";
        if (keys.needKey) sub += " · กุญแจสูงสุด ~" + formatNumTh(keys.maxNeed);
        $("unlockl-start-btn-sub").textContent = sub;
      }
    }
    paintFeatureTokenRates();
  }

  async function refreshUnlockLCatalog(opts) {
    const sid = requireDevplaySessionId();
    if (!sid) return null;
    const options = opts || {};
    const force = !!options.force;
    const fromTab = !!options.fromTab;
    if (
      fromTab &&
      !force &&
      unlockLCatalogCache.data &&
      unlockLCatalogCache.sid === sid &&
      Date.now() - unlockLCatalogCache.at < AFTERPLAY_SNAP_TTL_MS
    ) {
      paintUnlockLGrid();
      return unlockLCatalogCache.data;
    }
    setStatus($("unlockl-status"), "กำลังโหลดคลัง…", "muted");
    if (!unlockLCatalog.length) paintUnlockLSkeleton(10);
    try {
      const data = await api("/api/farm/unlock-l/catalog", {
        method: "POST",
        body: { devplay_session_id: sid },
        timeoutMs: 45000,
      });
      if (data?.token_balance != null && profile) {
        profile.token_balance = data.token_balance;
        paintTokenBalance();
      }
      unlockLPrices = {
        each: Number(data.credit_each || 15),
        bundle: Number(data.credit_bundle || 100),
        treasure: Number(data.credit_treasure || unlockLPrices.treasure || 15),
      };
      unlockLCatalog = Array.isArray(data.episodes) ? data.episodes : [];
      unlockLSnap = {
        life: Number(data.snapshot?.life || 0),
        key: Number(data.snapshot?.key || 0),
      };
      const owned = new Set(unlockLCatalog.filter((r) => r.owned).map((r) => Number(r.ep)));
      unlockLSelected = new Set(
        [...unlockLSelected].filter((ep) => {
          if (owned.has(ep)) return false;
          const row = unlockLCatalog.find((r) => Number(r.ep) === ep);
          return unlockLEpisodeReady(row || { ep });
        })
      );
      unlockLCatalogCache = { at: Date.now(), sid, data };
      paintUnlockLGrid();
      setStatus($("unlockl-status"), "เลือกตัวที่ปลดด่านแล้ว หรือกดเลือกทั้งหมด", "ok");
      return data;
    } catch (err) {
      if (!unlockLCatalog.length) paintUnlockLGrid();
      setStatus($("unlockl-status"), String(err?.userMessage || err?.message || "โหลดคลังไม่สำเร็จ"), "err");
      return null;
    }
  }

  function selectAllUnlockL() {
    unlockLSelected = new Set(
      unlockLCatalog.filter((r) => unlockLEpisodeReady(r)).map((r) => Number(r.ep))
    );
    paintUnlockLGrid();
  }

  function setUnlockLRunning(on) {
    unlockLRunning = !!on;
    $("farm-tab-unlock_l")?.classList.toggle("is-live-running", unlockLRunning);
    $("menu-nav-unlock_l")?.classList.toggle("is-live-running", unlockLRunning);
    const cancelBtn = $("unlockl-cancel-btn");
    if (cancelBtn) {
      cancelBtn.hidden = !unlockLRunning;
      cancelBtn.classList.toggle("hidden", !unlockLRunning);
      cancelBtn.disabled = false;
      cancelBtn.textContent = "ยกเลิก";
    }
    paintUnlockLQuote();
  }

  async function startUnlockLJob() {
    // Same-kind: allow queue-add when advance queue has room (mirror cross-kind anyJobLive path).
    if (unlockLBusy) return;
    if (!requireFeatureAccess("unlock_l")) return;
    const sid = requireDevplaySessionId();
    if (!sid) return;
    const q = unlockLQuote(unlockLSelected, unlockLCatalog);
    if (!q.n) {
      setStatus($("unlockl-status"), "เลือกอย่างน้อย 1 ตัวที่ปลดด่านแล้ว", "err");
      return;
    }
    if (unlockLNeedsLife(q.billable, unlockLCatalog) && Number(unlockLSnap.life || 0) < 1) {
      setStatus($("unlockl-status"), "หัวใจเป็น 0 — ต้องมีหัวใจเพื่อล่าตัว L", "err");
      return;
    }
    const keys = unlockLKeyPlan(q.billable, unlockLCatalog);
    if (keys.needKey && !keys.enough) {
      setStatus(
        $("unlockl-status"),
        keys.have < 1
          ? "กุญแจในไอดีเป็น 0 — ห้ามเริ่ม"
          : "กุญแจในไอดี " + formatNumTh(keys.have) + " ดอก — ต้องอย่างน้อย " + formatNumTh(keys.minNeed) + " ดอก",
        "err"
      );
      return;
    }
    const unlockOk = await showUnlockLConfirmModal(q.billable.length || q.n);
    if (!unlockOk) {
      setStatus($("unlockl-status"), "ยกเลิกแล้ว", "muted");
      return;
    }
    if (anyJobLive() && !queueHasRoom()) {
      showErrorModal(queueFullMessage(), "คิวเต็ม");
      return;
    }
    const queueOnly = anyJobLive();
    unlockLBusy = true;
    setStatus($("unlockl-status"), "กำลังเริ่มงาน…", "muted");
    try {
      const data = await api("/api/farm/unlock-l/start", {
        method: "POST",
        body: { devplay_session_id: sid, target_eps: [...unlockLSelected] },
        timeoutMs: 45000,
      });
      applyStartWallet(data);
      if (data?.job_id && queueOnly) {
        rememberJobAccount(data.job_id);
        announceQueuedJob(data, "ปลดล็อค L");
        setStatus(
          $("unlockl-status"),
          "เข้าคิวล่วงหน้าแล้ว" + queueSeqTag(data) + " — เริ่มอัตโนมัติเมื่อถึงคิว",
          "ok"
        );
      } else if (data?.job_id) {
        if (data.queue) applyQueuePayload(data.queue);
        startAdvanceQueuePoll();
        unlockLActiveJobId = data.job_id;
        persistKeyedJob(UNLOCKL_JOB_KEY, data.job_id);
        unlockLResultShownFor = null;
        setUnlockLRunning(true);
        const etaStart = estimateUnlockLEta(q.billable, unlockLCatalog, unlockLSnap, UNLOCK_L_OVERLAP);
        setDockEtaFromProgress({
          eta_sec: etaStart.eta_sec,
          eta_label: etaStart.eta_label,
          updated_at: Date.now() / 1000,
        });
        attachCreditJobToHub(
          "unlock_l",
          {
            id: data.job_id,
            status: "queued",
            ticket_count: unlockLSelected.size,
            progress: {
              current: 0,
              total: unlockLSelected.size,
              phase: "queued",
              eta_sec: etaStart.eta_sec || 0,
              eta_label: etaStart.eta_label || "",
            },
            params: { target_eps: [...unlockLSelected] },
          },
          {
            startedNow: true,
            unlockEps: [...unlockLSelected],
            unlockEp: [...unlockLSelected][0] || 0,
          }
        );
        pollUnlockLJob(data.job_id);
        setStatus($("unlockl-status"), "เข้าคิวแล้ว — คิด Token ตามตัวที่ปลดสำเร็จ", "ok");
      }
    } catch (err) {
      if (!handleFarmBillingDenied(err)) {
        setStatus($("unlockl-status"), String(err?.userMessage || err?.message || "เริ่มไม่สำเร็จ"), "err");
      }
    } finally {
      unlockLBusy = false;
      paintUnlockLQuote();
    }
  }

  function stopUnlockLPoll() {
    if (unlockLPollTimer) {
      clearInterval(unlockLPollTimer);
      unlockLPollTimer = null;
    }
  }

  function pollUnlockLJob(jobId) {
    stopUnlockLPoll();
    unlockLActiveJobId = jobId;
    let ticks = 0;
    const tick = async () => {
      ticks += 1;
      if (ticks > 34560) {
        stopUnlockLPoll();
        setStatus($("unlockl-status"), "ยังรอผลอยู่ — กดรีเฟรชเพื่อดูสถานะล่าสุด", "muted");
        return;
      }
      try {
        const job = await api("/api/farm/job/" + encodeURIComponent(jobId));
        unlockLLogLines = paintCreditJobProgress("unlockl", job) || unlockLLogLines;
        if (["queued", "running"].includes(job.status)) setUnlockLRunning(true);
        if (["succeeded", "failed", "cancelled"].includes(job.status)) {
          stopUnlockLPoll();
          persistKeyedJob(UNLOCKL_JOB_KEY, null);
          setUnlockLRunning(false);
          await refreshInviteStatus().catch(() => {});
          const jobKey = String(job.id || jobId);
          if (unlockLResultShownFor !== jobKey) {
            unlockLResultShownFor = jobKey;
            showUnlockLResultModal(job);
          }
          setStatus(
            $("unlockl-status"),
            job.status === "succeeded" ? "ปลดล็อค L สำเร็จ" : "จบ: " + (huntReasonTh(job.error) || job.error || job.status),
            job.status === "succeeded" ? "ok" : "err"
          );
          refreshUnlockLCatalog({ force: true }).catch(() => {});
          attachNextQueuedJob();
        }
      } catch (_) {}
    };
    tick();
    unlockLPollTimer = setInterval(tick, 2500);
  }

  async function cancelUnlockLJob() {
    const jobId = unlockLActiveJobId || loadKeyedJob(UNLOCKL_JOB_KEY);
    if (!jobId) return;
    try {
      await cancelServerJob(jobId);
      showToast("ส่งคำขอยกเลิกแล้ว", "ok");
      if (!unlockLPollTimer) pollUnlockLJob(jobId);
    } catch (e) {
      setStatus($("unlockl-status"), String(e?.userMessage || e?.message || "ยกเลิกไม่สำเร็จ"), "err");
    }
  }

  function iceTowerFloorNum(value) {
    const n = Number(value);
    return Number.isFinite(n) && n >= 1 ? n : 0;
  }

  const ICE_TOWER_SELECT_MAX = 10;

  const ICE_TOWER_UNSUPPORTED_STARS = {
    14: [1, 3],
    15: [2],
    26: [2],
    32: [2],
    38: [2],
    41: [2],
    53: [1],
    59: [3],
    72: [1],
  };

  function iceTowerUnsupportedList(floor, row) {
    const n = iceTowerFloorNum(floor);
    const fromRow = Array.isArray(row?.unsupported_stars)
      ? row.unsupported_stars.map(Number).filter((star) => star >= 1 && star <= 3)
      : null;
    if (fromRow && fromRow.length) return fromRow;
    return ICE_TOWER_UNSUPPORTED_STARS[n] || [];
  }

  function iceTowerNextStarBlocked(floor, row) {
    if (row?.web_blocked) return true;
    const have = Number(row?.stars || 0);
    if (have >= 3) return false;
    return iceTowerUnsupportedList(floor, row).includes(have + 1);
  }

  function iceTowerUnsupportedMessage(floor, row) {
    const n = iceTowerFloorNum(floor);
    const have = Number(row?.stars || 0);
    const blocked = iceTowerUnsupportedList(n, row).filter((star) => star > have);
    const star = blocked[0] || have + 1;
    return "ชั้น " + n + " ดาว " + star + " เว็บยังไม่รองรับ — ต้องปลดดาวนี้เองในเกมก่อน";
  }

  function iceTowerAvailableSet() {
    const raw = iceTowerPlan?.plan?.available_floors;
    return new Set((Array.isArray(raw) ? raw : []).map(iceTowerFloorNum).filter(Boolean));
  }

  function iceTowerHasScan() {
    return !!(iceTowerPlan && iceTowerPlan.ice);
  }

  function iceTowerRowFor(n, byFloor) {
    return (byFloor && byFloor.get(n)) || { floor: n, stars: 0, full: false };
  }

  function iceTowerFloorOpenForPlay(n, row) {
    if (!iceTowerHasScan()) return false;
    if (iceTowerPlan.ice?.ice_unlocked !== true) return false;
    if (n < 1) return false;
    if (row && (row.full || Number(row.stars || 0) >= 3)) return false;
    return !iceTowerNextStarBlocked(n, row);
  }

  function iceTowerIsSelectable(floor, row, available) {
    if (iceTowerRunning) return false;
    const n = iceTowerFloorNum(floor);
    if (!iceTowerFloorOpenForPlay(n, row)) return false;
    if (available && available.size) return available.has(n);
    return false;
  }

  // A locked floor can join the job when the floor below is also picked:
  // it opens once that floor earns its first star during the run.
  function iceTowerChainable(n, row, kept) {
    if (!iceTowerFloorOpenForPlay(n, row)) return false;
    if (Number(row?.stars || 0) > 0) return false;
    return n > 1 && kept.has(n - 1);
  }

  function iceTowerNormalizeSelection(byFloor, available) {
    const kept = new Set();
    [...iceTowerSelected]
      .map(iceTowerFloorNum)
      .filter(Boolean)
      .sort((a, b) => a - b)
      .forEach((n) => {
        if (kept.size >= ICE_TOWER_SELECT_MAX) return;
        const row = iceTowerRowFor(n, byFloor);
        if (iceTowerIsSelectable(n, row, available) || iceTowerChainable(n, row, kept)) kept.add(n);
      });
    return kept;
  }

  // Floors to add so `n` becomes pickable: n plus any locked floors below it
  // down to an already-picked or already-open floor. [] when unreachable.
  function iceTowerChainPath(n, byFloor, available) {
    if (iceTowerRunning) return [];
    const row = iceTowerRowFor(n, byFloor);
    if (iceTowerIsSelectable(n, row, available)) return [n];
    if (!iceTowerFloorOpenForPlay(n, row) || Number(row.stars || 0) > 0) return [];
    const path = [n];
    for (let k = n - 1; k >= 1; k -= 1) {
      if (iceTowerSelected.has(k)) return path.reverse();
      const below = iceTowerRowFor(k, byFloor);
      if (iceTowerIsSelectable(k, below, available)) {
        path.push(k);
        return path.reverse();
      }
      if (!iceTowerFloorOpenForPlay(k, below) || Number(below.stars || 0) > 0) return [];
      path.push(k);
      if (path.length + iceTowerSelected.size > ICE_TOWER_SELECT_MAX) return [];
    }
    return [];
  }

  function toggleIceTowerFloor(floor) {
    const n = iceTowerFloorNum(floor);
    if (!n || iceTowerRunning) return;
    const ice = iceTowerPlan?.ice || {};
    const byFloor = new Map((ice.floors || []).map((item) => [Number(item.floor), item]));
    const row = iceTowerRowFor(n, byFloor);
    if (iceTowerNextStarBlocked(n, row)) {
      const msg = iceTowerUnsupportedMessage(n, row);
      showToast(msg, "err");
      setStatus($("ice-tower-status"), msg, "err");
      return;
    }
    if (iceTowerSelected.has(n)) {
      iceTowerSelected.delete(n);
      paintIceTower();
      return;
    }
    const path = iceTowerChainPath(n, byFloor, iceTowerAvailableSet()).filter((k) => !iceTowerSelected.has(k));
    if (!path.length) return;
    if (iceTowerSelected.size + path.length > ICE_TOWER_SELECT_MAX) {
      const msg = "เลือกได้สูงสุด " + formatNumTh(ICE_TOWER_SELECT_MAX) + " ชั้นต่อครั้ง";
      showToast(msg, "err");
      setStatus($("ice-tower-status"), msg, "err");
      return;
    }
    path.forEach((k) => iceTowerSelected.add(k));
    if (path.length > 1) {
      showToast("เลือกชั้น " + path[0] + "–" + path[path.length - 1] + " ให้ต่อเนื่องกันแล้ว", "muted");
    }
    paintIceTower();
  }

  function iceTowerQuote() {
    if (!iceTowerHasScan() || iceTowerPlan.ice?.ice_unlocked !== true) {
      return { n: 0, remaining: 0, selected: [], credit: 0 };
    }
    const available = iceTowerAvailableSet();
    const selected = [...iceTowerSelected].map(iceTowerFloorNum).filter(Boolean);
    const n = selected.length;
    const remaining = available.size;
    const raw = n * Number(iceTowerPrices.each || 2);
    const credit = raw;
    return { n, remaining, selected, credit: Math.round(credit * 100) / 100 };
  }

  function iceTowerStartMessage(quote, noKey, needsLife, enoughCredit, needsUnlock, unlockBlocked, keyInfo) {
    if (!iceTowerHasScan()) return "กดรีเฟรชเพื่อสแกนด่านก่อน";
    if (needsUnlock || unlockBlocked) return "กรุณาปลด Tower of Frozen Waves มาก่อน";
    if (!quote.n) return "เลือกชั้นที่ยังไม่ครบ 3 ดาว ได้สูงสุด 10 ชั้น";
    if (noKey) return "กุญแจในไอดีเป็น 0 — ห้ามเริ่ม";
    if (needsLife) return "หัวใจเป็น 0 — ห้ามเริ่ม";
    const have = Number(keyInfo?.have || 0);
    const need = Number(keyInfo?.need || 0);
    const keyBit = need > 0 ? " · กุญแจสูงสุด ~" + formatNumTh(need) + " / ในไอดี " + formatNumTh(have) : "";
    const etaBit = quote?.eta_label ? " · " + quote.eta_label : "";
    return "เริ่ม " + formatNumTh(quote.n) + " ชั้น · รวมในวันใช้งาน" + keyBit + etaBit;
  }

  function paintIceTower() {
    const ice = iceTowerPlan?.ice || {};
    const plan = iceTowerPlan?.plan || {};
    const byFloor = new Map((ice.floors || []).map((row) => [Number(row.floor), row]));
    const available = iceTowerAvailableSet();
    iceTowerSelected = iceTowerNormalizeSelection(byFloor, available);
    const scanned = iceTowerHasScan();
    const target = Number(plan.target_floor || $("ice-tower-target-floor")?.value || 100);
    const defaultStars = Math.max(1, Math.min(3, Number($("ice-tower-default-stars")?.value || plan.default_stars || 3)));
    const grid = $("ice-tower-grid");
    if (grid) {
      grid.innerHTML = "";
      if (scanned) {
        for (let floor = 1; floor <= target; floor += 1) {
          const row = byFloor.get(floor) || { floor, stars: 0, full: false };
          const selected = iceTowerSelected.has(floor);
          const webBlocked = iceTowerNextStarBlocked(floor, row);
          const selectable = selected || iceTowerChainPath(floor, byFloor, available).length > 0;
          const full = !!row.full || Number(row.stars || 0) >= 3;
          const lockedAhead = !full && !selectable && !webBlocked;
          const unsupportedStars = iceTowerUnsupportedList(floor, row);
          const btn = document.createElement("button");
          btn.type = "button";
          btn.dataset.floor = String(floor);
          btn.className =
            "ice-tower-floor" +
            (selected ? " is-selected" : "") +
            (full ? " is-full" : "") +
            (webBlocked ? " is-unsupported" : "") +
            (lockedAhead ? " is-locked" : "") +
            (selectable ? " is-selectable" : "");
          btn.disabled = (!selectable && !webBlocked) || iceTowerRunning;
          const haveStars = Number(row.stars || 0);
          const wantStars = full ? 3 : defaultStars;
          const starBits = [1, 2, 3]
            .map((n) => {
              const filled = n <= haveStars;
              const blockedStar = unsupportedStars.includes(n);
              return (
                '<span class="ice-star' +
                (filled ? " is-filled" : "") +
                (blockedStar ? " is-unsupported" : "") +
                '" aria-hidden="true">★</span>'
              );
            })
            .join("");
          btn.setAttribute("aria-pressed", selected ? "true" : "false");
          let why = "";
          if (full) why = " · ครบ 3 ดาวแล้ว ไม่เปิดให้วิ่งซ้ำ";
          else if (ice.ice_unlocked !== true) why = " · ต้องปลด Tower of Frozen Waves ก่อน";
          else if (webBlocked) why = " · " + iceTowerUnsupportedMessage(floor, row);
          else if (lockedAhead) why = " · ต้องเล่นชั้น " + (floor - 1) + " ก่อน";
          else if (selected) why = " · เลือกแล้ว";
          btn.setAttribute("aria-label", "ชั้น " + floor + " · " + haveStars + "/3 ดาว · เป้า " + wantStars + why);
          btn.title = "ชั้น " + floor + why;
          btn.innerHTML =
            (selected ? '<span class="ice-tower-check" aria-hidden="true">✓</span>' : "") +
            "<strong>" +
            floor +
            "</strong><span class=\"ice-tower-stars\">" +
            starBits +
            "</span>";
          grid.appendChild(btn);
        }
        applyIceTowerFilter();
      } else if (iceTowerBusy) {
        paintIceTowerSkeleton(24);
      } else {
        grid.innerHTML =
          '<div class="ice-tower-empty-placeholder">' +
            '<div class="ice-empty-icon">❄️</div>' +
            '<p class="ice-empty-title">ยังไม่ได้สแกนข้อมูล Ice Tower</p>' +
            '<p class="ice-empty-sub">เชื่อมต่อ DevPlay แล้วกดปุ่ม "สแกน / รีเฟรช" เพื่ออ่านด่านและดาวปัจจุบัน</p>' +
          '</div>';
      }
    }
    const q = iceTowerQuote();
    if (iceTowerBusy && !scanned) {
      setStatSkeleton($("ice-tower-snap-life"), true, "2rem");
      setStatSkeleton($("ice-tower-snap-key"), true, "2rem");
    } else {
      $("ice-tower-snap-life")?.classList.remove("is-skel");
      $("ice-tower-snap-key")?.classList.remove("is-skel");
      if ($("ice-tower-snap-life")) $("ice-tower-snap-life").textContent = scanned ? formatNumTh(ice.life || 0) : "—";
      if ($("ice-tower-snap-key")) $("ice-tower-snap-key").textContent = scanned ? formatNumTh(ice.keys || 0) : "—";
    }
    const needsUnlock = scanned && ice.ice_unlocked !== true;
    const unlockBlocked = needsUnlock;
    if ($("ice-tower-summary")) {
      if (!scanned) {
        $("ice-tower-summary").textContent = "เชื่อม DevPlay แล้วกดรีเฟรชเพื่อสแกนด่านก่อน";
      } else if (needsUnlock) {
        $("ice-tower-summary").textContent =
          "กรุณาปลด Tower of Frozen Waves มาก่อน ถึงจะใช้งานได้";
      } else {
        $("ice-tower-summary").textContent =
          "ชั้นปัจจุบัน " + formatNumTh(ice.current_floor || 1) +
          " · ดาวชั้นนี้ " + formatNumTh(ice.current_stars || 0) + "/3" +
          " · ดาวรวม " + formatNumTh(ice.total_stars || 0) + "/300" +
          " · เหลือให้เลือก " + formatNumTh(q.remaining) + " ชั้น";
      }
    }
    $("ice-tower-summary")?.classList.toggle("is-locked", !!needsUnlock || !scanned);
    if ($("ice-tower-toolbar-meta")) {
      $("ice-tower-toolbar-meta").textContent = !scanned
        ? "กดรีเฟรชเพื่อสแกนด่านก่อน แล้วเลือกได้สูงสุด 10 ชั้น"
        : needsUnlock
          ? "กรุณาปลด Tower of Frozen Waves มาก่อน"
          : q.n
            ? "เลือก " + formatNumTh(q.n) + "/10 ชั้น · รวมในวันใช้งาน"
            : "เลือกได้สูงสุด 10 ชั้นต่อครั้ง · ชั้นครบ 3 ดาววิ่งซ้ำไม่ได้";
    }
    const haveKeys = Number(ice.keys || 0);
    let needKeys = 0;
    iceTowerSelected.forEach((floor) => {
      const row = byFloor.get(Number(floor)) || {};
      const haveStars = Number(row.stars || 0);
      let want = defaultStars;
      const blocked = iceTowerUnsupportedList(floor, row).find((star) => star > haveStars && star <= want);
      if (blocked) want = blocked - 1;
      if (want > haveStars) needKeys += want - haveStars;
    });
    if (!needKeys) needKeys = Number(plan.planned_stars || 0);
    const iceEta = q.n
      ? estimateIceTowerEta(needKeys, ice, UNLOCK_L_OVERLAP)
      : null;
    const iceEtaEl = $("ice-tower-eta");
    if (iceEtaEl) {
      if (iceEta && iceEta.eta_sec > 0 && !unlockBlocked) {
        iceEtaEl.hidden = false;
        iceEtaEl.classList.remove("hidden", "is-empty");
        iceEtaEl.textContent =
          iceEta.eta_label + " — อย่ายกเลิกกลางคัน จนกว่าหอจะขึ้นว่าสำเร็จ";
      } else {
        iceEtaEl.hidden = true;
        iceEtaEl.classList.add("hidden");
        iceEtaEl.textContent = "";
      }
    }
    const noKey = haveKeys < 1;
    const needsLife = false;
    const iceLocked = iceTowerPrices.enabled === false;
    const canStart =
      scanned &&
      !iceLocked &&
      !iceTowerBusy &&
      q.n > 0 &&
      !noKey &&
      !unlockBlocked &&
      canPayForFeature("ice_tower");
    const iceStart = $("ice-tower-start-btn");
    if (iceStart) {
      const starting = iceTowerBusy && !iceTowerRunning;
      const running = !!iceTowerRunning;
      setBtnLoading(iceStart, starting);
      const iceSub = $("ice-tower-start-btn-sub");
      if (starting) {
        iceStart.disabled = true;
        if (iceSub) iceSub.textContent = "กำลังส่งเข้าคิวงาน…";
      } else if (running) {
        const ok = canStart && queueHasRoom();
        iceStart.disabled = !ok;
        if (iceSub) iceSub.textContent = ok ? "กำลังรัน — กดเพื่อเข้าคิวเพิ่ม" : "กำลังรัน…";
      } else {
        iceStart.disabled = !canStart;
      }
    }
    const iceKeyWarn = $("ice-tower-key-warn");
    if (iceKeyWarn) {
      const show = q.n > 0 && noKey;
      iceKeyWarn.hidden = !show;
      iceKeyWarn.classList.toggle("hidden", !show);
      iceKeyWarn.textContent = "กุญแจในไอดีเป็น 0 — ห้ามเริ่ม";
    }
    const iceKeyHint = $("ice-tower-key-hint");
    if (iceKeyHint) {
      const show = q.n > 0 && !noKey;
      iceKeyHint.hidden = !show;
      iceKeyHint.classList.toggle("hidden", !show);
      if (show) {
        let msg =
          "กุญแจในไอดี " +
          formatNumTh(haveKeys) +
          " ดอก · แผนนี้ใช้สูงสุด " +
          formatNumTh(needKeys) +
          " ดอก (ตามดาวเป้าหมาย)";
        if (needKeys > haveKeys) {
          msg += " — จะไต่ได้ประมาณ " + formatNumTh(haveKeys) + " ดาวแล้วหยุด";
        }
        iceKeyHint.textContent = msg;
      }
    }
    if ($("ice-tower-start-btn-sub") && !iceTowerRunning && !iceTowerBusy) {
      $("ice-tower-start-btn-sub").textContent = iceLocked
        ? "ปิดปรับปรุง"
        : iceTowerStartMessage(
            { ...q, eta_label: iceEta && iceEta.eta_sec ? formatEtaSec(iceEta.eta_sec) : "" },
            noKey,
            needsLife,
            true,
            needsUnlock,
            unlockBlocked,
            {
              have: haveKeys,
              need: needKeys,
            }
          );
    }
    paintFeatureTokenRates();
  }

  function applyIceTowerFilter(filter) {
    if (filter) iceTowerFilter = filter;
    document.querySelectorAll("[data-ice-filter]").forEach((btn) => {
      const on = btn.dataset.iceFilter === iceTowerFilter;
      btn.classList.toggle("is-active", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
    });
    const grid = $("ice-tower-grid");
    if (!grid) return;
    grid.querySelectorAll(".ice-tower-floor").forEach((btn) => {
      const f = Number(btn.dataset.floor || 0);
      let show = true;
      if (iceTowerFilter === "todo") {
        show = !btn.classList.contains("is-full");
      } else if (iceTowerFilter === "1-20") {
        show = f >= 1 && f <= 20;
      } else if (iceTowerFilter === "21-40") {
        show = f >= 21 && f <= 40;
      } else if (iceTowerFilter === "41-60") {
        show = f >= 41 && f <= 60;
      } else if (iceTowerFilter === "61-80") {
        show = f >= 61 && f <= 80;
      } else if (iceTowerFilter === "81-100") {
        show = f >= 81 && f <= 100;
      }
      btn.hidden = !show;
    });
  }

  async function refreshIceTower(opts) {
    const sid = requireDevplaySessionId();
    if (!sid) return null;
    if (iceTowerPrices.enabled === false) {
      setStatus($("ice-tower-status"), "ปิดปรับปรุง", "err");
      paintIceTower();
      return null;
    }
    iceTowerBusy = true;
    setStatus($("ice-tower-status"), "กำลังสแกน Ice Tower…", "muted");
    if (!iceTowerHasScan()) {
      paintIceTower();
      setStatSkeleton($("ice-tower-snap-life"), true, "2rem");
      setStatSkeleton($("ice-tower-snap-key"), true, "2rem");
    }
    try {
      const targetFloor = Math.max(1, Math.min(100, Number($("ice-tower-target-floor")?.value) || 100));
      const defaultStars = Math.max(1, Math.min(3, Number($("ice-tower-default-stars")?.value) || 3));
      const data = await api("/api/farm/ice-tower/preview", {
        method: "POST",
        body: {
          devplay_session_id: sid,
          target_floor: targetFloor,
          default_stars: defaultStars,
          selected_floors: [...iceTowerSelected],
        },
        timeoutMs: 60000,
      });
      iceTowerPlan = data;
      if (data?.token_balance != null && profile) {
        profile.token_balance = data.token_balance;
        paintTokenBalance();
      }
      iceTowerPrices.each = Number(data?.plan?.quote?.each || iceTowerPrices.each);
      iceTowerPrices.bundle = Number(data?.plan?.quote?.bundle || iceTowerPrices.bundle);
      if (data?.plan?.unlock_if_needed != null) {
        iceTowerPrices.unlockIfNeeded = false;
      }
      paintIceTower();
      const locked = data?.ice?.ice_unlocked !== true;
      setStatus(
        $("ice-tower-status"),
        locked
          ? "กรุณาปลด Tower of Frozen Waves มาก่อน ถึงจะใช้งานได้"
          : "เลือกชั้นที่ยังไม่ครบ 3 ดาว ได้สูงสุด 10 ชั้น — ชั้นถัดไปต้องเล่นชั้นก่อนหน้าก่อน",
        locked ? "err" : "ok"
      );
      if (locked && opts?.fromTab && farmTab === ICE_TOWER_TAB) {
        showIceTowerLockedModal();
      }
      return data;
    } catch (err) {
      setStatus($("ice-tower-status"), String(err?.userMessage || err?.message || "สแกนไม่สำเร็จ"), "err");
      return null;
    } finally {
      iceTowerBusy = false;
      paintIceTower();
    }
  }

  function selectAllIceTower() {
    showToast("Ice Tower เลือกได้สูงสุด 10 ชั้นต่อครั้ง", "muted");
  }

  function iceTowerUnsupportedPairs() {
    const pairs = [];
    Object.keys(ICE_TOWER_UNSUPPORTED_STARS).forEach((floor) => {
      (ICE_TOWER_UNSUPPORTED_STARS[floor] || []).forEach((star) => {
        pairs.push({ floor: Number(floor), star: Number(star) });
      });
    });
    pairs.sort((a, b) => a.floor - b.floor || a.star - b.star);
    return pairs;
  }

  function paintIceTowerUnsupportedCard() {
    const list = $("ice-tower-unsupported-list");
    if (!list || list.dataset.ready === "1") return;
    list.textContent = "";
    iceTowerUnsupportedPairs().forEach((item) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "ice-unsupported-item";
      btn.dataset.floor = String(item.floor);
      btn.textContent = "ชั้น " + formatNumTh(item.floor) + " · ดาว " + formatNumTh(item.star);
      list.appendChild(btn);
    });
    list.dataset.ready = "1";
  }

  function setIceTowerUnsupportedOpen(open) {
    const card = $("ice-tower-unsupported-card");
    const toggle = $("ice-tower-unsupported-open");
    if (!card) return;
    card.hidden = !open;
    card.classList.toggle("hidden", !open);
    if (toggle) toggle.setAttribute("aria-expanded", open ? "true" : "false");
    if (open) paintIceTowerUnsupportedCard();
  }

  function focusIceTowerFloor(floor) {
    const cell = document.querySelector(
      '#ice-tower-grid .ice-tower-floor[data-floor="' + String(floor) + '"]'
    );
    if (!cell) {
      showToast("สแกนด่านก่อน แล้วค่อยไปที่ชั้นนี้", "muted");
      return;
    }
    cell.scrollIntoView({ block: "nearest", behavior: "smooth" });
    cell.classList.add("is-flash");
    window.setTimeout(() => cell.classList.remove("is-flash"), 1400);
  }

  function setIceTowerRunning(on) {
    iceTowerRunning = !!on;
    $("menu-nav-ice_tower")?.classList.toggle("is-live-running", iceTowerRunning);
    const cancel = $("ice-tower-cancel-btn");
    if (cancel) {
      cancel.hidden = !iceTowerRunning;
      cancel.classList.toggle("hidden", !iceTowerRunning);
    }
    paintIceTower();
  }

  async function startIceTowerJob() {
    // Same-kind: allow queue-add when advance queue has room (mirror cross-kind anyJobLive path).
    if (iceTowerBusy) return;
    if (!requireFeatureAccess("ice_tower")) return;
    if (iceTowerPrices.enabled === false) {
      showErrorModal(ERR_TH.feature_locked, "ปิดปรับปรุง");
      return;
    }
    const sid = requireDevplaySessionId();
    if (!sid) return;
    if (!iceTowerHasScan()) {
      setStatus($("ice-tower-status"), "กดรีเฟรชเพื่อสแกนด่านก่อน", "err");
      return;
    }
    if (iceTowerPlan?.ice?.ice_unlocked !== true) {
      setStatus(
        $("ice-tower-status"),
        "กรุณาปลด Tower of Frozen Waves มาก่อน ถึงจะใช้งานได้",
        "err"
      );
      return;
    }
    const q = iceTowerQuote();
    if (!q.n || q.n > ICE_TOWER_SELECT_MAX) {
      return setStatus($("ice-tower-status"), "เลือกได้สูงสุด 10 ชั้นต่อครั้ง", "err");
    }
    const haveKeys = Number(iceTowerPlan?.ice?.keys || 0);
    if (haveKeys < 1) {
      setStatus($("ice-tower-status"), "กุญแจในไอดีเป็น 0 — ห้ามเริ่ม", "err");
      return;
    }
    const iceOk = await showIceTowerConfirmModal();
    if (!iceOk) {
      setStatus($("ice-tower-status"), "ยกเลิกแล้ว", "muted");
      return;
    }
    if (anyJobLive() && !queueHasRoom()) {
      showErrorModal(queueFullMessage(), "คิวเต็ม");
      return;
    }
    const queueOnly = anyJobLive();
    iceTowerBusy = true;
    try {
      const data = await api("/api/farm/ice-tower/start", {
        method: "POST",
        body: {
          devplay_session_id: sid,
          target_floor: Number($("ice-tower-target-floor")?.value) || 100,
          default_stars: Number($("ice-tower-default-stars")?.value) || 3,
          selected_floors: q.selected,
        },
        timeoutMs: 60000,
      });
      applyStartWallet(data);
      if (!data?.job_id) {
        setStatus($("ice-tower-status"), "เริ่มไม่สำเร็จ — ไม่มีงานในคิว", "err");
        return;
      }
      if (queueOnly) {
        rememberJobAccount(data.job_id);
        announceQueuedJob(data, "หอน้ำแข็ง");
        setStatus(
          $("ice-tower-status"),
          "เข้าคิวล่วงหน้าแล้ว" + queueSeqTag(data) + " — เริ่มอัตโนมัติเมื่อถึงคิว",
          "ok"
        );
        return;
      }
      if (data.queue) applyQueuePayload(data.queue);
      startAdvanceQueuePoll();
      iceTowerActiveJobId = data.job_id;
      persistKeyedJob(ICE_TOWER_JOB_KEY, data.job_id);
      iceTowerResultShownFor = null;
      setIceTowerRunning(true);
      const ice = iceTowerPlan?.ice || {};
      const plan = iceTowerPlan?.plan || {};
      const defaultStars = Math.max(1, Math.min(3, Number($("ice-tower-default-stars")?.value || plan.default_stars || 3)));
      const byFloor = new Map((ice.floors || []).map((row) => [Number(row.floor), row]));
      let needStars = 0;
      (q.selected || []).forEach((floor) => {
        const row = byFloor.get(Number(floor)) || {};
        const haveStars = Number(row.stars || 0);
        if (defaultStars > haveStars) needStars += defaultStars - haveStars;
      });
      if (!needStars) needStars = Number(plan.planned_stars || 0);
      const etaStart = estimateIceTowerEta(needStars, ice, UNLOCK_L_OVERLAP);
      setDockEtaFromProgress({
        eta_sec: etaStart.eta_sec,
        eta_label: etaStart.eta_label,
        updated_at: Date.now() / 1000,
      });
      attachCreditJobToHub(
        "ice_tower",
        {
          id: data.job_id,
          status: "queued",
          ticket_count: Number(q?.n) || 0,
          progress: {
            current: 0,
            total: Number(q?.n) || 0,
            phase: "queued",
            eta_sec: etaStart.eta_sec || 0,
            eta_label: etaStart.eta_label || "",
          },
        },
        { startedNow: true }
      );
      pollIceTowerJob(data.job_id);
      setStatus(
        $("ice-tower-status"),
        "เข้าคิวแล้ว — คิด Token ตามชั้นที่สำเร็จ",
        "ok"
      );
    } catch (err) {
      if (!handleFarmBillingDenied(err)) {
        setStatus($("ice-tower-status"), String(err?.userMessage || err?.message || "เริ่มไม่สำเร็จ"), "err");
      }
    } finally {
      iceTowerBusy = false;
      paintIceTower();
    }
  }

  function stopIceTowerPoll() {
    if (iceTowerPollTimer) clearInterval(iceTowerPollTimer);
    iceTowerPollTimer = null;
  }

  function pollIceTowerJob(jobId) {
    stopIceTowerPoll();
    if (!jobId) {
      persistKeyedJob(ICE_TOWER_JOB_KEY, null);
      iceTowerActiveJobId = null;
      setIceTowerRunning(false);
      return;
    }
    iceTowerActiveJobId = jobId;
    let misses = 0;
    const tick = async () => {
      try {
        const job = await api("/api/farm/job/" + encodeURIComponent(jobId));
        misses = 0;
        iceTowerLogLines = paintCreditJobProgress("ice-tower", job) || iceTowerLogLines;
        if (["queued", "running"].includes(job.status)) setIceTowerRunning(true);
        if (["succeeded", "failed", "cancelled"].includes(job.status)) {
          stopIceTowerPoll();
          persistKeyedJob(ICE_TOWER_JOB_KEY, null);
          setIceTowerRunning(false);
          await refreshInviteStatus().catch(() => {});
          const key = String(job.id || jobId);
          if (iceTowerResultShownFor !== key) {
            iceTowerResultShownFor = key;
            showIceTowerResultModal(job);
          }
          const incomplete = farmResultIncomplete(job);
          setStatus(
            $("ice-tower-status"),
            incomplete
              ? farmIncompleteLabel(job)
              : job.status === "succeeded"
                ? "Ice Tower สำเร็จ"
                : "จบ: " + (thError(job.error || job.status) || job.error || job.status),
            incomplete ? "warn" : job.status === "succeeded" ? "ok" : "err"
          );
          refreshIceTower({ force: true }).catch(() => {});
          attachNextQueuedJob();
        }
      } catch (_) {
        misses += 1;
        if (misses >= 8) {
          stopIceTowerPoll();
          persistKeyedJob(ICE_TOWER_JOB_KEY, null);
          iceTowerActiveJobId = null;
          setIceTowerRunning(false);
          setStatus($("ice-tower-status"), "เช็คสถานะงานไม่สำเร็จ — กดรีเฟรช", "err");
        }
      }
    };
    tick();
    iceTowerPollTimer = setInterval(tick, 2500);
  }

  async function cancelIceTowerJob() {
    const jobId = iceTowerActiveJobId || loadKeyedJob(ICE_TOWER_JOB_KEY);
    if (!jobId) return;
    try {
      await cancelServerJob(jobId);
      showToast("ส่งคำขอยกเลิกแล้ว", "ok");
      if (!iceTowerPollTimer) pollIceTowerJob(jobId);
    } catch (err) {
      setStatus($("ice-tower-status"), String(err?.userMessage || err?.message || "ยกเลิกไม่สำเร็จ"), "err");
    }
  }

  function showIceTowerResultModal(job) {
    const res = job?.result && typeof job.result === "object" ? job.result : {};
    const floors = Array.isArray(res.completed_floors) ? res.completed_floors : [];
    const selected = Array.isArray(res.selected_floors) ? res.selected_floors : [];
    const incomplete = farmResultIncomplete(job);
    const fullyOk = !incomplete && (job?.status === "succeeded" || !!res.ok);
    const statusText = fullyOk
      ? "สำเร็จ"
      : incomplete
        ? farmIncompleteLabel(job)
        : job?.status || "ไม่สำเร็จ";
    const rows = [
      ["สถานะ", statusText],
      ["ชั้นที่สำเร็จ", floors.length ? floors.map((n) => "ชั้น " + n).join(", ") : "—"],
      ["ชั้นที่เลือก", selected.length ? formatNumTh(selected.length) : "—"],
      ["ดาวที่ยิง", formatNumTh(res.played || 0)],
    ];
    if (res.refunded) rows.push(["คืน Credit", formatCredit(res.refunded)]);
    const html = '<table class="result-table"><tbody>' +
      rows.map(([k, v]) => "<tr><th>" + k + "</th><td>" + escapeHtml(String(v)) + "</td></tr>").join("") +
      "</tbody></table>";
    clearModalActions();
    openModal({
      mode: "result",
      title: incomplete ? "Ice Tower จบกลางคัน" : "สรุปผล Ice Tower",
      bodyHtml: html,
      icon: "assets/ice_tower.png",
      locked: false,
    });
    modalActions.appendChild(makeBtn("ตกลง", "btn-candy", () => forceCloseModal()));
  }

  function resumeCreditJobsIfAny() {
    const ap = loadKeyedJob(AFTERPLAY_JOB_KEY);
    if (ap) pollAfterplayJob(ap);
    const ul = loadKeyedJob(UNLOCKL_JOB_KEY);
    if (ul) pollUnlockLJob(ul);
    const ice = loadKeyedJob(ICE_TOWER_JOB_KEY);
    if (ice) pollIceTowerJob(ice);
    const fr = loadKeyedJob(FRIEND_JOB_KEY);
    if (fr) pollFriendJob(fr);
    refreshAdvanceQueue().then(() => {
      if (advanceQueue.open > 0) {
        startAdvanceQueuePoll();
        // Nothing local is polling yet if the page was reloaded mid-queue.
        attachNextQueuedJob(400);
      }
    });
  }

  function friendCountValue() {
    return Math.max(0, Math.min(300, Math.floor(Number($("friend-count")?.value) || 0)));
  }

  function friendListRows() {
    const rows = Array.isArray(friendSnap?.list) ? friendSnap.list : [];
    return rows.filter((row) => row && row.player_id);
  }

  function pruneFriendSelection() {
    const have = new Set(friendListRows().map((row) => String(row.player_id)));
    for (const id of Array.from(friendSelected)) {
      if (!have.has(id)) friendSelected.delete(id);
    }
  }

  function parseFriendMids(text) {
    const parts = String(text || "").split(/[\s,;]+/);
    const out = [];
    const seen = new Set();
    for (const part of parts) {
      const id = String(part || "").trim();
      if (!id || !/^[A-Za-z0-9][A-Za-z0-9_\-.]{1,31}$/.test(id)) continue;
      const key = id.toUpperCase();
      if (seen.has(key)) continue;
      seen.add(key);
      out.push(id);
      if (out.length >= 1000) break;
    }
    return out;
  }

  const FRIEND_MID_TEMPLATE_ADD_MAX = 200;

  function friendSelectedTemplateMids() {
    const out = [];
    for (const row of friendMidTemplates) {
      const mid = String(row?.mid_display || row?.mid || "").trim();
      const key = String(row?.mid || mid).toUpperCase();
      if (!key || !friendMidTemplateSelected.has(key)) continue;
      out.push(mid || key);
    }
    return out;
  }

  function mergeFriendMids() {
    const typed = $("friend-mid-input")?.value || "";
    const selected = friendSelectedTemplateMids();
    if (!selected.length) return parseFriendMids(typed);
    return parseFriendMids(selected.join("\n") + "\n" + typed);
  }

  function friendQuoteCount() {
    if (friendMode === "add_mid") return mergeFriendMids().length;
    if (friendMode === "add") {
      const room = Math.max(0, Number(friendSnap?.room || 0));
      let n = friendCountValue();
      if (n <= 0) n = room;
      n = Math.min(n, room, friendPrices.maxAdd || 300);
      return n;
    }
    pruneFriendSelection();
    return friendSelected.size;
  }

  function friendRentalSub(add, n) {
    if (friendMode === "add_mid") {
      return n
        ? "ส่งคำขอ " + formatNumTh(n) + " ไอดี · ฟรี ไม่หัก Token"
        : "เลือกจากเทมเพลต หรือวาง MID";
    }
    if (!canPayForFeature("friend")) {
      const rem = featureRemainingLabel("friend");
      return rem ? "เหลือ " + rem : "เติม Token หรือเช่าวัน";
    }
    const rem = featureRemainingLabel("friend");
    const remBit = rem ? " · เหลือ " + rem : "";
    const addRate = " · " + formatTokenAmount(tokenRate("friend_add")) + " Token/คน";
    if (add) return n ? "เพิ่ม " + formatNumTh(n) + " คน" + addRate + remBit : "ช่องเพื่อนเต็มแล้ว";
    return n
      ? "ลบ " + formatNumTh(n) + " คนที่เลือก · ฟรีเมื่อมี Token หรือวันเช่า" + remBit
      : "เลือกเพื่อนที่จะลบจากรายชื่อ" + remBit;
  }

  function paintFriendHeartBanner() {
    const banner = $("friend-heart-banner");
    const text = $("friend-heart-banner-text");
    const back = $("friend-heart-banner-back");
    if (!banner || !text) return;
    if (!friendHeartReturn) {
      banner.classList.add("hidden");
      banner.hidden = true;
      banner.classList.remove("is-ready");
      if (back) {
        back.classList.add("hidden");
        back.hidden = true;
      }
      return;
    }
    const have = Math.max(0, Number(friendSnap?.friends || 0));
    const cap = Math.max(1, Number(friendSnap?.cap || 300));
    const threshold = Math.max(1, Number(friendSnap?.threshold || 250));
    const selected = friendMode === "remove" ? friendSelected.size : 0;
    const after = Math.max(0, have - selected);
    const ready = have < threshold;
    const label = "ฟาร์มหัวใจ";
    banner.hidden = false;
    banner.classList.remove("hidden");
    banner.classList.toggle("is-ready", ready);
    if (ready) {
      text.textContent =
        "เพื่อนเหลือ " +
        formatNumTh(have) +
        "/" +
        formatNumTh(cap) +
        " — พอเริ่ม " +
        label +
        " ได้แล้ว";
      if (back) {
        back.hidden = false;
        back.classList.remove("hidden");
        back.textContent = "กลับไป" + label;
      }
    } else {
      text.textContent =
        label +
        " ใช้ไม่ได้ตอนเพื่อน " +
        formatNumTh(threshold) +
        " คนขึ้นไป · ตอนนี้ " +
        formatNumTh(have) +
        "/" +
        formatNumTh(cap) +
        (selected
          ? " · ถ้าลบคนที่เลือกจะเหลือ " + formatNumTh(after) + " คน"
          : " · เลือกเพื่อนที่จะลบ (เพื่อนจริงไม่ถูกบังคับลบ)") +
        (after < threshold ? " — เหลือไม่เกิน " + formatNumTh(threshold - 1) + " จะเริ่มฟาร์มได้" : "");
      if (back) {
        back.hidden = true;
        back.classList.add("hidden");
      }
    }
  }

  function paintFriendSelectionChrome() {
    const rows = friendListRows();
    const n = friendSelected.size;
    const countEl = $("friend-selected-count");
    if (countEl) countEl.textContent = "เลือก " + formatNumTh(n) + " คน";
    const all = $("friend-select-all");
    if (all) {
      all.checked = rows.length > 0 && n === rows.length;
      all.indeterminate = n > 0 && n < rows.length;
    }
    paintFriendHeartBanner();
  }

  function paintFriendList() {
    const list = $("friend-list");
    const empty = $("friend-list-empty");
    const card = $("friend-list-card");
    const add = friendMode === "add";
    const addMid = friendMode === "add_mid";
    if (card) {
      card.classList.toggle("hidden", add || addMid);
      card.hidden = add || addMid;
    }
    if (add || addMid) {
      if (list) list.innerHTML = "";
      return;
    }
    pruneFriendSelection();
    const rows = friendListRows();
    if (!list) return;
    if (!rows.length) {
      list.innerHTML = "";
      if (empty) {
        empty.hidden = false;
        empty.textContent = friendSnap
          ? "ไอดีนี้ยังไม่มีเพื่อน"
          : friendBusy
            ? "กำลังโหลดรายชื่อเพื่อน…"
            : "เชื่อม DevPlay แล้วกดรีเฟรชเพื่อดูรายชื่อ";
      }
      paintFriendSelectionChrome();
      return;
    }
    if (empty) empty.hidden = true;
    list.innerHTML = rows
      .map((row) => {
        const id = String(row.player_id);
        const nick = String(row.nickname || "").trim() || id;
        const lv = Math.max(0, Number(row.level) || 0);
        const guest = !!row.guest;
        const checked = friendSelected.has(id);
        return (
          '<li class="friend-pick-row' +
          (checked ? " is-selected" : "") +
          (guest ? " is-guest" : "") +
          '">' +
          '<label>' +
          '<input type="checkbox" data-friend-id="' +
          escapeHtml(id) +
          '"' +
          (checked ? " checked" : "") +
          " />" +
          '<span class="friend-pick-copy">' +
          '<span class="friend-pick-name">' +
          escapeHtml(nick) +
          (guest ? '<span class="friend-guest-chip">Guest</span>' : "") +
          "</span>" +
          '<span class="friend-pick-meta">' +
          escapeHtml(id) +
          "</span>" +
          "</span>" +
          '<span class="friend-pick-lv">Lv.' +
          formatNumTh(lv) +
          "</span>" +
          "</label>" +
          "</li>"
        );
      })
      .join("");
    paintFriendSelectionChrome();
  }

  function setFriendSelected(id, on) {
    const pid = String(id || "");
    if (!pid) return;
    if (on) friendSelected.add(pid);
    else friendSelected.delete(pid);
    const row = Array.from(document.querySelectorAll("#friend-list input[data-friend-id]")).find(
      (el) => el.getAttribute("data-friend-id") === pid
    );
    const li = row?.closest(".friend-pick-row");
    if (row) row.checked = !!on;
    li?.classList.toggle("is-selected", !!on);
    paintFriend({ skipList: true });
  }

  function toggleFriendSelectAll(on) {
    const rows = friendListRows();
    const next = on == null ? !(rows.length > 0 && friendSelected.size === rows.length) : !!on;
    friendSelected = next ? new Set(rows.map((row) => String(row.player_id))) : new Set();
    paintFriend();
  }

  function selectFriendGuests() {
    const guests = friendListRows().filter((row) => row.guest).map((row) => String(row.player_id));
    if (!guests.length) {
      showToast("ไม่มี Guest ในลิสต์นี้", "muted");
      return;
    }
    friendSelected = new Set(guests);
    paintFriend();
  }

  function paintFriend(opts) {
    const have = friendSnap ? Number(friendSnap.friends || 0) : null;
    const room = friendSnap ? Number(friendSnap.room || 0) : null;
    const friendSkel = friendBusy && !friendSnap;
    if (friendSkel) {
      setStatSkeleton($("friend-snap-have"), true, "2rem");
      setStatSkeleton($("friend-snap-room"), true, "2rem");
    } else {
      $("friend-snap-have")?.classList.remove("is-skel");
      $("friend-snap-room")?.classList.remove("is-skel");
      if ($("friend-snap-have")) $("friend-snap-have").textContent = have == null ? "—" : formatNumTh(have);
      if ($("friend-snap-room")) $("friend-snap-room").textContent = room == null ? "—" : formatNumTh(room);
    }
    const fill = $("friend-progress-fill");
    const pText = $("friend-progress-text");
    const pPct = $("friend-progress-pct");
    fill?.classList.toggle("is-skel", !!friendSkel);
    if (have != null) {
      const pct = Math.min(100, Math.max(0, Math.round((have / 300) * 100)));
      if (fill) fill.style.width = pct + "%";
      if (pText) pText.textContent = formatNumTh(have) + " / 300 คน";
      if (pPct) pPct.textContent = pct + "%";
    } else if (!friendSkel) {
      if (fill) fill.style.width = "0%";
      if (pText) pText.textContent = "— / 300 คน";
      if (pPct) pPct.textContent = "0%";
    }
    const n = friendQuoteCount();
    if ($("friend-toolbar-meta")) {
      $("friend-toolbar-meta").textContent = friendMode === "add_mid"
        ? "ส่งคำขอจากเทมเพลตร่วมหรือ MID ที่เตรียมเอง · ไม่หัก Token · ไม่จำกัดช่องเพื่อนของไอดีนี้ · สูงสุด 1,000 ไอดีต่อครั้ง"
        : "ลบหรือเพิ่มเพื่อนในไอดีที่ล็อกอิน · เพดาน " + formatNumTh(friendPrices.maxAdd || 300);
    }
    const add = friendMode === "add";
    const addMid = friendMode === "add_mid";
    const countRow = $("friend-count-row");
    if (countRow) {
      countRow.classList.toggle("hidden", !add);
      countRow.hidden = !add;
    }
    const midRow = $("friend-mid-row");
    if (midRow) {
      midRow.classList.toggle("hidden", !addMid);
      midRow.hidden = !addMid;
    }
    const midCount = $("friend-mid-count");
    if (midCount) {
      midCount.textContent = formatNumTh(addMid ? n : 0) + " ไอดี";
    }
    if (addMid) paintFriendMidTemplates();
    $("friend-mode-remove")?.classList.toggle("is-active", friendMode === "remove");
    $("friend-mode-add")?.classList.toggle("is-active", add);
    $("friend-mode-add-mid")?.classList.toggle("is-active", addMid);
    if ($("friend-mode-remove")) $("friend-mode-remove").setAttribute("aria-selected", friendMode === "remove" ? "true" : "false");
    if ($("friend-mode-add")) $("friend-mode-add").setAttribute("aria-selected", add ? "true" : "false");
    if ($("friend-mode-add-mid")) $("friend-mode-add-mid").setAttribute("aria-selected", addMid ? "true" : "false");
    if ($("friend-count-hint")) {
      $("friend-count-hint").textContent = add
        ? "0 = เติมช่องว่างทั้งหมด (สูงสุด " + formatNumTh(room || friendPrices.maxAdd || 300) + ")"
        : "เลือกจากรายชื่อด้านบน";
    }
    if ($("friend-summary")) {
      $("friend-summary").textContent = friendSnap
        ? "เพื่อน " + formatNumTh(have) + "/300 · ว่าง " + formatNumTh(room)
        : friendSkel
          ? "กำลังอ่านจำนวนเพื่อน…"
          : "เชื่อม DevPlay แล้วกดรีเฟรช";
    }
    if (!opts?.skipList) paintFriendList();
    else paintFriendSelectionChrome();
    if ($("friend-start-btn-title")) {
      $("friend-start-btn-title").textContent = add
        ? "เริ่มเพิ่มเพื่อน"
        : addMid
          ? "เริ่มส่งคำขอเพื่อน"
          : "เริ่มลบเพื่อน";
    }
    if ($("friend-start-icon")) {
      $("friend-start-icon").src = add || addMid ? "assets/Cookie0023_head.png" : "assets/Angel_cookie_sm.png";
    }
    if ($("friend-start-btn-sub") && !friendRunning && !friendBusy) {
      $("friend-start-btn-sub").textContent = friendRentalSub(add, n);
    }
    const start = $("friend-start-btn");
    if (start) {
      const starting = friendBusy && !friendRunning;
      const running = !!friendRunning;
      const canPay = addMid || canPayForFeature("friend");
      const can = canPay && !friendBusy && (addMid ? n > 0 : !!friendSnap && n > 0);
      setBtnLoading(start, starting);
      const friendSub = $("friend-start-btn-sub");
      if (starting) {
        start.disabled = true;
        start.classList.toggle("is-disabled-look", true);
        if (friendSub) friendSub.textContent = "กำลังส่งเข้าคิวงาน…";
      } else if (running) {
        const ok = can && queueHasRoom();
        start.disabled = !ok;
        start.classList.toggle("is-disabled-look", !ok);
        if (friendSub) friendSub.textContent = ok ? "กำลังรัน — กดเพื่อเข้าคิวเพิ่ม" : "กำลังรัน…";
      } else {
        start.disabled = !can;
        start.classList.toggle("is-disabled-look", !can);
      }
    }
    paintFeatureTokenRates();
  }

  function paintFriendMidTemplates() {
    const list = $("friend-mid-template-list");
    const empty = $("friend-mid-template-empty");
    if (!list || !empty) return;
    const have = Array.isArray(friendMidTemplates) ? friendMidTemplates : [];
    const live = new Set(have.map((row) => String(row?.mid || "").toUpperCase()).filter(Boolean));
    for (const key of Array.from(friendMidTemplateSelected)) {
      if (!live.has(key)) friendMidTemplateSelected.delete(key);
    }
    empty.hidden = have.length > 0;
    empty.classList.toggle("hidden", have.length > 0);
    list.hidden = have.length < 1;
    const actions = $("friend-mid-template-actions");
    if (actions) {
      actions.hidden = have.length < 1;
      actions.classList.toggle("hidden", have.length < 1);
    }
    const box = $("friend-mid-template");
    if (box) box.classList.toggle("is-empty", have.length < 1);
    list.innerHTML = have
      .map((row) => {
        const key = String(row?.mid || "").toUpperCase();
        const label = escapeHtml(String(row?.mid_display || row?.mid || key));
        const on = friendMidTemplateSelected.has(key);
        return (
          '<button type="button" class="friend-mid-chip' +
          (on ? " is-selected" : "") +
          '" data-mid="' +
          escapeHtml(key) +
          '" aria-pressed="' +
          (on ? "true" : "false") +
          '">' +
          label +
          "</button>"
        );
      })
      .join("");
  }

  async function loadFriendMidTemplates(force) {
    if (!hasResolvedWebsiteProfile()) return;
    if (friendMidTemplatesLoaded && !force) {
      paintFriendMidTemplates();
      return;
    }
    try {
      const data = await api("/api/farm/friend/mid-templates", { timeoutMs: 20000 });
      friendMidTemplates = Array.isArray(data?.items) ? data.items : [];
      friendMidTemplatesLoaded = true;
      paintFriendMidTemplates();
      paintFriend({ skipList: true });
    } catch (err) {
      if ($("friend-mid-template-status")) {
        setStatus(
          $("friend-mid-template-status"),
          String(err?.userMessage || err?.message || "โหลดเทมเพลตไม่สำเร็จ"),
          "err"
        );
      }
    }
  }

  function toggleFriendMidTemplate(mid, on) {
    const key = String(mid || "").toUpperCase();
    if (!key) return;
    const next = on == null ? !friendMidTemplateSelected.has(key) : !!on;
    if (next) friendMidTemplateSelected.add(key);
    else friendMidTemplateSelected.delete(key);
    paintFriend({ skipList: true });
    paintFriendMidTemplates();
  }

  function selectAllFriendMidTemplates() {
    friendMidTemplateSelected = new Set(
      friendMidTemplates.map((row) => String(row?.mid || "").toUpperCase()).filter(Boolean)
    );
    paintFriend({ skipList: true });
    paintFriendMidTemplates();
  }

  function clearFriendMidTemplates() {
    friendMidTemplateSelected = new Set();
    paintFriend({ skipList: true });
    paintFriendMidTemplates();
  }

  async function addFriendMidTemplate() {
    if (friendMidTemplateBusy) return;
    const sid = requireDevplaySessionId();
    if (!sid) return;
    if (!hasResolvedWebsiteProfile()) {
      openAuthModal("login");
      return;
    }
    const all = parseFriendMids($("friend-mid-template-input")?.value || "");
    if (!all.length) {
      setStatus($("friend-mid-template-status"), "ใส่ MID ที่จะแชร์ก่อน", "err");
      return;
    }
    const mids = all.slice(0, FRIEND_MID_TEMPLATE_ADD_MAX);
    const leftover = all.slice(FRIEND_MID_TEMPLATE_ADD_MAX);
    friendMidTemplateBusy = true;
    const addBtn = $("friend-mid-template-add-btn");
    if (addBtn) addBtn.disabled = true;
    setStatus(
      $("friend-mid-template-status"),
      "กำลังตรวจ " + formatNumTh(mids.length) + " ไอดี…",
      "muted"
    );
    try {
      const data = await api("/api/farm/friend/mid-templates", {
        method: "POST",
        body: { devplay_session_id: sid, mids },
        timeoutMs: 180000,
      });
      friendMidTemplates = Array.isArray(data?.items) ? data.items : friendMidTemplates;
      friendMidTemplatesLoaded = true;
      const added = Array.isArray(data?.added) ? data.added : [];
      const rejected = Array.isArray(data?.rejected) ? data.rejected : [];
      const pruned = Array.isArray(data?.pruned) ? data.pruned : [];
      for (const row of added) {
        const key = String(row?.mid || "").toUpperCase();
        if (key) friendMidTemplateSelected.add(key);
      }
      const box = $("friend-mid-template-input");
      if (box) box.value = leftover.join("\n");
      paintFriendMidTemplates();
      paintFriend({ skipList: true });
      const bits = [];
      if (added.length) bits.push("เข้าเทมเพลต " + formatNumTh(added.length) + " ไอดี");
      if (pruned.length) bits.push("ลบที่ส่งไม่ได้ " + formatNumTh(pruned.length));
      if (rejected.length) {
        const first = String(rejected[0]?.reason || "ส่งคำขอไม่ได้");
        bits.push(rejected.length === 1 ? first : first + " · อีก " + formatNumTh(rejected.length - 1));
      }
      if (leftover.length) bits.push("เหลือ " + formatNumTh(leftover.length) + " ในช่อง · สูงสุด " + formatNumTh(FRIEND_MID_TEMPLATE_ADD_MAX) + " ต่อครั้ง");
      setStatus(
        $("friend-mid-template-status"),
        bits.join(" · ") || "ตรวจแล้ว",
        added.length ? "ok" : rejected.length ? "err" : "muted"
      );
    } catch (err) {
      setStatus(
        $("friend-mid-template-status"),
        String(err?.userMessage || err?.message || "เพิ่มเทมเพลตไม่สำเร็จ"),
        "err"
      );
    } finally {
      friendMidTemplateBusy = false;
      if (addBtn) addBtn.disabled = false;
    }
  }

  function setFriendMode(mode) {
    const next = String(mode || "").toLowerCase();
    friendMode = next === "add" ? "add" : next === "add_mid" ? "add_mid" : "remove";
    if ($("friend-count")) $("friend-count").value = "0";
    paintFriend();
    if (friendMode === "add_mid") loadFriendMidTemplates();
  }

  async function refreshFriendPreview(opts) {
    const sid = requireDevplaySessionId();
    if (!sid) return null;
    if (friendBusy && !opts?.force) return friendSnap;
    friendBusy = true;
    if (!friendSnap) paintFriend();
    try {
      const data = await api("/api/farm/friend/preview", {
        method: "POST",
        body: { devplay_session_id: sid },
        timeoutMs: 30000,
      });
      friendSnap = data;
      if (data?.ops) {
        friendPrices.maxAdd = Number(data.ops.friend_max_add) || friendPrices.maxAdd;
      }
      if (data?.prices) {
        friendPrices.maxAdd = Number(data.prices.friend_max_add) || friendPrices.maxAdd;
      }
      paintFriend();
      setStatus($("friend-status"), "พร้อมเริ่ม", "ok");
      return data;
    } catch (err) {
      setStatus($("friend-status"), String(err?.userMessage || err?.message || "สแกนเพื่อนไม่สำเร็จ"), "err");
      return null;
    } finally {
      friendBusy = false;
      paintFriend();
    }
  }

  function setFriendRunning(on) {
    friendRunning = !!on;
    $("farm-tab-friend")?.classList.toggle("is-live-running", friendRunning);
    const cancel = $("friend-cancel-btn");
    if (cancel) {
      cancel.hidden = !friendRunning;
      cancel.classList.toggle("hidden", !friendRunning);
    }
    paintFriend();
  }

  async function startFriendJob() {
    // Same-kind: allow queue-add when advance queue has room (mirror cross-kind anyJobLive path).
    if (friendBusy) return;
    const sid = requireDevplaySessionId();
    if (!sid) return;
    const n = friendQuoteCount();
    if (friendMode === "add" && n < 1) return setStatus($("friend-status"), "ช่องเพื่อนเต็มแล้ว", "err");
    if (friendMode === "remove" && n < 1) {
      return setStatus($("friend-status"), "เลือกเพื่อนที่จะลบจากรายชื่อก่อน", "err");
    }
    if (friendMode === "add_mid" && n < 1) {
      return setStatus($("friend-status"), "เลือกจากเทมเพลต หรือวาง MID ทีละบรรทัดก่อน", "err");
    }
    if (friendMode === "add_mid") {
      if (!hasResolvedWebsiteProfile()) {
        openAuthModal("login");
        return;
      }
    } else if (!requireFeatureAccess("friend")) return;
    const friendOk = await showFriendConfirmModal();
    if (!friendOk) {
      setStatus($("friend-status"), "ยกเลิกแล้ว", "muted");
      return;
    }
    if (anyJobLive() && !queueHasRoom()) {
      showErrorModal(queueFullMessage(), "คิวเต็ม");
      return;
    }
    const queueOnly = anyJobLive();
    friendBusy = true;
    try {
      const selectedIds =
        friendMode === "remove"
          ? Array.from(friendSelected)
          : friendMode === "add_mid"
            ? mergeFriendMids()
            : [];
      const data = await api("/api/farm/friend/start", {
        method: "POST",
        body: {
          devplay_session_id: sid,
          mode: friendMode,
          count: friendMode === "add" ? friendCountValue() : selectedIds.length,
          player_ids: selectedIds,
        },
        timeoutMs: 60000,
      });
      applyStartWallet(data);
      if (queueOnly && data?.job_id) {
        rememberJobAccount(data.job_id);
        announceQueuedJob(
          data,
          friendMode === "add" ? "เพิ่มเพื่อน" : friendMode === "add_mid" ? "ส่งคำขอเพื่อน MID" : "ลบเพื่อน"
        );
        setStatus(
          $("friend-status"),
          "เข้าคิวล่วงหน้าแล้ว" + queueSeqTag(data) + " — เริ่มอัตโนมัติเมื่อถึงคิว",
          "ok"
        );
        return;
      }
      if (data.queue) applyQueuePayload(data.queue);
      startAdvanceQueuePoll();
      friendActiveJobId = data.job_id;
      persistKeyedJob(FRIEND_JOB_KEY, data.job_id);
      friendResultShownFor = null;
      setFriendRunning(true);
      attachCreditJobToHub(
        "friend",
        {
          id: data.job_id,
          status: "queued",
          ticket_count: n,
          progress: { current: 0, total: n, phase: "queued" },
        },
        { startedNow: true }
      );
      pollFriendJob(data.job_id);
      setStatus(
        $("friend-status"),
        friendMode === "add_mid"
          ? "เข้าคิวแล้ว — ส่งคำขอเพื่อน ไม่หัก Token"
          : friendMode === "remove"
            ? "เข้าคิวแล้ว — ลบเพื่อนที่เลือก ไม่หัก Token"
            : "เข้าคิวแล้ว — คิด Token ตามคนที่สำเร็จ",
        "ok"
      );
    } catch (err) {
      if (!handleFarmBillingDenied(err)) {
        setStatus($("friend-status"), String(err?.userMessage || err?.message || "เริ่มไม่สำเร็จ"), "err");
      }
    } finally {
      friendBusy = false;
      paintFriend();
    }
  }

  function stopFriendPoll() {
    if (friendPollTimer) clearInterval(friendPollTimer);
    friendPollTimer = null;
  }

  function pollFriendJob(jobId) {
    stopFriendPoll();
    friendActiveJobId = jobId;
    const tick = async () => {
      try {
        const job = await api("/api/farm/job/" + encodeURIComponent(jobId));
        friendLogLines = paintCreditJobProgress("friend", job) || friendLogLines;
        if (["queued", "running"].includes(job.status)) setFriendRunning(true);
        if (["succeeded", "failed", "cancelled"].includes(job.status)) {
          stopFriendPoll();
          persistKeyedJob(FRIEND_JOB_KEY, null);
          setFriendRunning(false);
          const key = String(job.id || jobId);
          if (friendResultShownFor !== key) {
            friendResultShownFor = key;
            showFriendResultModal(job);
          }
          setStatus($("friend-status"), job.status === "succeeded" ? "งานเพื่อนสำเร็จ" : "จบ: " + (job.error || job.status), job.status === "succeeded" ? "ok" : "err");
          refreshFriendPreview({ force: true }).then(() => {
            if (friendMode === "add_mid") loadFriendMidTemplates(true);
            if (
              friendHeartReturn &&
              Number(friendSnap?.friends || 0) < Number(friendSnap?.threshold || 250)
            ) {
              showToast("เพื่อนเหลือไม่เกิน 249 แล้ว — กดกลับไปฟาร์มหัวใจได้", "ok");
            }
          }).catch(() => {});
          attachNextQueuedJob();
        }
      } catch (_) {}
    };
    tick();
    friendPollTimer = setInterval(tick, 2500);
  }

  async function cancelFriendJob() {
    const jobId = friendActiveJobId || loadKeyedJob(FRIEND_JOB_KEY);
    if (!jobId) return;
    try {
      await cancelServerJob(jobId);
      showToast("ส่งคำขอยกเลิกแล้ว", "ok");
      if (!friendPollTimer) pollFriendJob(jobId);
    } catch (err) {
      setStatus($("friend-status"), String(err?.userMessage || err?.message || "ยกเลิกไม่สำเร็จ"), "err");
    }
  }

  function showFriendResultModal(job) {
    const res = job?.result && typeof job.result === "object" ? job.result : {};
    const mode = String(res.mode || "remove");
    const rows = [
      ["สถานะ", job?.status === "succeeded" || res.ok ? "สำเร็จ" : job?.status || "ไม่สำเร็จ"],
      ["โหมด", mode === "add" ? "เพิ่มเพื่อน" : mode === "add_mid" ? "ส่งคำขอเพื่อน MID" : "ลบเพื่อน"],
    ];
    if (mode === "add") rows.push(["เพิ่มได้", formatNumTh(res.added || 0) + " / " + formatNumTh(res.need || 0)]);
    else if (mode === "add_mid") {
      rows.push(["ส่งคำขอแล้ว", formatNumTh(res.sent || 0)]);
      if (res.already) rows.push(["มีคำขอ/เป็นเพื่อนอยู่แล้ว", formatNumTh(res.already)]);
      if (res.failed_full) rows.push(["ผู้รับเต็ม 300 คน", formatNumTh(res.failed_full)]);
      if (res.failed_unknown) rows.push(["ไม่พบ MID", formatNumTh(res.failed_unknown)]);
      if (res.failed_auth) rows.push(["session หลุด", formatNumTh(res.failed_auth)]);
      const otherFail = Math.max(
        0,
        Number(res.failed || 0) -
          Number(res.failed_full || 0) -
          Number(res.failed_unknown || 0) -
          Number(res.failed_auth || 0)
      );
      if (otherFail) rows.push(["ไม่สำเร็จ", formatNumTh(otherFail)]);
      else if (res.failed && !res.failed_full && !res.failed_unknown && !res.failed_auth) {
        rows.push(["ไม่สำเร็จ", formatNumTh(res.failed)]);
      }
      if (res.skipped_have) rows.push(["ข้ามเพราะเป็นเพื่อนแล้ว", formatNumTh(res.skipped_have)]);
      if (res.skipped_self) rows.push(["ข้าม MID ตัวเอง", formatNumTh(res.skipped_self)]);
      if (res.pruned_templates) rows.push(["ลบออกจากเทมเพลต (ส่งไม่ได้)", formatNumTh(res.pruned_templates)]);
    } else rows.push(["ลบได้", formatNumTh(res.removed || 0)]);
    if (res.friends != null) rows.push(["เพื่อนตอนนี้", formatNumTh(res.friends)]);
    if (res.left != null) rows.push(["เหลือ", formatNumTh(res.left)]);
    const html = '<table class="result-table"><tbody>' +
      rows.map(([k, v]) => "<tr><th>" + k + "</th><td>" + escapeHtml(String(v)) + "</td></tr>").join("") +
      "</tbody></table>";
    clearModalActions();
    openModal({ mode: "result", title: "สรุปผลเพื่อน", bodyHtml: html, icon: "assets/Angel_cookie_sm.png", locked: false });
    modalActions.appendChild(makeBtn("ตกลง", "btn-candy", () => forceCloseModal()));
  }

