  // Currency deltas come back keyed (coin/life/key/gem); item rewards arrive as
  // "item:<id>:<tier>" or "item:<id>:<tier>@uuid". Labels live in
  // js/gift_item_labels.js (window.GIFTDRAW_ITEM_LABELS).
  const GIFTDRAW_LABEL = {
    coin: "💰 เหรียญ",
    life: "❤️ หัวใจ",
    key: "🔑 กุญแจ",
    gem: "💎 คริสตัล",
    jelly: "🍬 เจลลี่",
  };
  const GIFTDRAW_ITEM_LABELS =
    (typeof window !== "undefined" && window.GIFTDRAW_ITEM_LABELS) || {};

  /** First numeric segment after optional "item:" prefix (before : or @). */
  function giftDrawItemId(raw) {
    const s = String(raw || "");
    const rest = s.startsWith("item:") ? s.slice(5) : s;
    const m = rest.match(/^(\d+)/);
    return m ? m[1] : "";
  }

  function giftDrawItemLabel(raw) {
    const id = giftDrawItemId(raw);
    if (!id) {
      const rest = String(raw || "").startsWith("item:")
        ? String(raw).slice(5)
        : String(raw || "");
      return rest ? "🎁 " + rest : "🎁 ของรางวัล";
    }
    const name = GIFTDRAW_ITEM_LABELS[id];
    if (name) return "🎁 " + name;
    return "🎁 ของ #" + id;
  }

  /** Rewrite item:<id>… tokens inside live log / delta dump strings. */
  function formatGiftDrawItemTokens(text) {
    return String(text || "").replace(
      /item:(\d+)[^\s'"`,}\]]*/g,
      (full, id) => {
        const name = GIFTDRAW_ITEM_LABELS[id];
        return name ? "🎁 " + name : "🎁 ของ #" + id;
      }
    );
  }

  function giftDrawRewardKeyLabel(key) {
    const k = String(key || "");
    if (k.startsWith("item:")) return giftDrawItemLabel(k);
    return GIFTDRAW_LABEL[k] || k;
  }

  /** Join reward pairs as "💰 เหรียญ 1,000 · 🎁 Fast Start 1". */
  function formatGiftDrawRewardPairs(pairs) {
    const parts = [];
    for (const [key, qty] of pairs || []) {
      const n = Number(qty);
      if (!Number.isFinite(n) || !n) continue;
      parts.push(giftDrawRewardKeyLabel(key) + " " + formatNumTh(n));
    }
    return parts.join(" · ");
  }

  /**
   * Turn Python/JSON-ish reward dumps into readable Thai/EN text.
   * e.g. "{'coin': 1000}" → "💰 เหรียญ 1,000"
   *      "ok {'item:214:0': 1, 'coin': 2000}" → "🎁 Fast Start 1 · 💰 เหรียญ 2,000"
   */
  function formatGiftDrawRewardText(text) {
    let s = String(text || "").trim();
    if (!s) return "";
    s = s.replace(/^ok\s+/i, "");
    if (/^\(?\s*no\s*delta\s*\)?$/i.test(s)) return "ไม่มีของเพิ่ม";
    if (/\{[^{}]*\}/.test(s)) {
      return s.replace(/\{[^{}]*\}/g, (blob) => {
        const pairs = [];
        const re = /['"]([^'"]+)['"]\s*:\s*(-?\d+(?:\.\d+)?)/g;
        let m;
        while ((m = re.exec(blob))) pairs.push([m[1], Number(m[2])]);
        return formatGiftDrawRewardPairs(pairs) || blob;
      });
    }
    return formatGiftDrawItemTokens(s);
  }

  function giftDrawRewardRows(totals) {
    const merged = Object.create(null);
    for (const [key, qty] of Object.entries(totals || {})) {
      const n = Number(qty) || 0;
      if (!n) continue;
      if (String(key).startsWith("item:")) {
        const id = giftDrawItemId(key) || String(key);
        const mk = "item:" + id;
        merged[mk] = (merged[mk] || 0) + n;
      } else {
        merged[key] = (merged[key] || 0) + n;
      }
    }
    const entries = Object.entries(merged);
    if (!entries.length) return [];
    return entries
      .sort((a, b) => b[1] - a[1])
      .map(([key, qty]) => {
        const label = key.startsWith("item:")
          ? giftDrawItemLabel(key)
          : GIFTDRAW_LABEL[key] || key;
        return [
          escapeHtml(label),
          `<span class="result-delta">+${escapeHtml(formatNumTh(qty))}</span>`,
        ];
      });
  }

  function showGiftDrawResultModal(summary) {
    const rewardRows = giftDrawRewardRows(summary.totals);
    const rows = [
      ["บัญชีเกม", escapeHtml(summary.account || "—")],
      [
        "เปิดกล่อง",
        `<span class="result-delta">${escapeHtml(summary.drawsOk)}</span> / ${escapeHtml(summary.requested)} กล่อง`,
      ],
      ["กล่องคงเหลือ", escapeHtml(summary.boxesAfter)],
      ...rewardRows,
    ];
    if (!rewardRows.length) {
      rows.splice(3, 0, ["ของที่ได้", "ไม่มียอดเปลี่ยนแปลงที่ตรวจจับได้"]);
    }
    const html =
      '<table class="result-table"><tbody>' +
      rows.map(([k, v]) => `<tr><th>${k}</th><td>${v}</td></tr>`).join("") +
      "</tbody></table>" +
      '<p class="queue-note" style="margin-top:12px">ไม่ได้ใช้เพชรเลย · ถ้าในเกมยังไม่เห็นของ ให้ปิดเกมแล้วเข้าใหม่</p>';

    clearModalActions();
    openModal({
      mode: "result",
      title: "สรุปผลเปิดกล่องขวัญ",
      bodyHtml: html,
      icon: "assets/icon_giftpoint.png",
      locked: false,
    });
    $("modal-body")?.classList.add("result-stagger");
    spawnPixelConfetti();
    modalActions.appendChild(
      makeBtn("ตกลง", "btn-candy", () => forceCloseModal())
    );
  }

  function clearPixelConfetti() {
    const layer = $("modal-confetti");
    if (!layer) return;
    layer.classList.remove("is-active");
    layer.replaceChildren();
  }

  function spawnPixelConfetti() {
    const layer = $("modal-confetti");
    if (!layer) return;
    clearPixelConfetti();
    if (prefersReducedMotion()) return;
    const colors = ["#f0b429", "#f6e7c8", "#e23d2e", "#3ecf8e", "#ffd36a", "#ff8a5b"];
    const frag = document.createDocumentFragment();
    for (let i = 0; i < 20; i++) {
      const bit = document.createElement("span");
      bit.className = "pixel-bit";
      const size = 4 + Math.floor(Math.random() * 5);
      bit.style.width = size + "px";
      bit.style.height = size + "px";
      bit.style.left = Math.random() * 100 + "%";
      bit.style.background = colors[i % colors.length];
      bit.style.setProperty("--dx", Math.round(Math.random() * 80 - 40) + "px");
      bit.style.setProperty("--delay", (Math.random() * 0.45).toFixed(2) + "s");
      bit.style.setProperty("--dur", (1.5 + Math.random() * 1.1).toFixed(2) + "s");
      frag.appendChild(bit);
    }
    layer.appendChild(frag);
    layer.classList.add("is-active");
    setTimeout(() => clearPixelConfetti(), 2800);
  }

  function escapeHtml(s) {
    return String(s ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function stopQueuePoll() {
    if (queuePollTimer) {
      clearTimeout(queuePollTimer);
      queuePollTimer = null;
    }
  }

  function queuePollDelayMs() {
    const busy =
      !!activeWatchJobId ||
      pendingFarmJobs.length > 0 ||
      dockPhase === "running" ||
      dockPhase === "queued";
    const base = busy ? 5000 : 12000;
    // Back off when the gate is failing or slow so clients cannot keep a
    // saturated API in a self-sustaining poll storm.
    const failFactor = queuePollFailures > 0 ? Math.min(8, 2 ** queuePollFailures) : 1;
    const slowFactor = gateSlowStreak > 0 ? Math.min(8, 2 ** gateSlowStreak) : 1;
    return Math.min(60000, base * Math.max(failFactor, slowFactor));
  }

  function scheduleQueuePollTick() {
    queuePollTimer = setTimeout(() => {
      queuePollTimer = null;
      if (!document.hidden) {
        refreshGateAndQueueUi().catch(() => {});
      }
      scheduleQueuePollTick();
    }, queuePollDelayMs());
  }

  function startQueuePoll() {
    // One in-flight gate + a single timer. Extra start() calls must not
    // stack parallel /api/farm/gate requests.
    if (!queuePollTimer) scheduleQueuePollTick();
    refreshGateAndQueueUi().catch(() => {});
  }

  function jobKindToMode(kind) {
    // Return null for unknown/missing kinds so callers can decide instead of
    // silently defaulting to Party Run (the old bug: active-job without job_kind).
    if (kind == null || kind === "") return null;
    const map = {
      partyrun: "partyrun",
      heart: "heart",
      powder: "powder",
      giftdraw: "giftdraw",
      upgrade: "upgrade",
      jelly_upgrade: "jelly_upgrade",
      cookie_unlock: "cookie_unlock",
      cookie: "cookie_unlock",
      pet_unlock: "pet_unlock",
      heart_free: "heart_free",
      lv_free_power: "lv_free_power",
      lv_free_cookie: "lv_free_cookie",
      afterplay_fast: "afterplay_fast",
      unlock_l: "unlock_l",
      ice_tower: "ice_tower",
      friend: "friend",
      invite: "invite",
      invite_friend: "invite",
      quest_claim: "quest_claim",
      quest: "quest_claim",
      treasure_evo: "treasure_evo",
      evo: "treasure_evo",
      daily_reward: "daily_reward",
      boost_buy: "boost_buy",
      treasure_ticket: "treasure_ticket",
      ingredient_extract: "ingredient_extract",
      treasure_break: "treasure_break",
    };
    return map[kind] || kind;
  }

  function modeToJobKind(mode) {
    if (mode === "cookie_unlock" || mode === "cookie") return "cookie_unlock";
    return mode || "partyrun";
  }

  const JOB_KIND_TH = {
    partyrun: "Party Run",
    powder: "ฟาร์มผง",
    giftdraw: "เปิดกล่องขวัญ",
    heart: "ฟาร์มหัวใจ",
    heartloop_timed: "HeartLoop",
    afterplay_fast: "ฟาร์มเงิน / XP / กล่อง",
    afterplay_box: "กล่อง",
    unlock_l: "ปลดล็อค L",
    ice_tower: "Ice Tower",
    friend: "เพื่อน (ทดสอบ)",
    quest_claim: "รับ Quest Auto",
    treasure_evo: "EVO สมบัติ",
    daily_reward: "รับรางวัลรายวัน",
    boost_buy: "ซื้อ Boost",
    treasure_ticket: "เปิดตั๋วสมบัติ",
    ingredient_extract: "สกัดวัตถุดิบ",
    treasure_break: "ย่อยสมบัติ",
    daily_reward_multi: "รับรางวัลรายวัน (หลายบัญชี)",
    mid_heart: "ฟาร์มใจ MID",
    report_multi: "รายงานไอดี (หลายบัญชี)",
    pc_program: "โปรแกรม PC",
    bot_ad: "Bot-Ad",
    invite: "เชิญเพื่อน",
    invite_friend: "เชิญเพื่อน",
    upgrade: "ตีบวกสมบัติ",
    jelly_upgrade: "อัปเกรด Jelly",
    cookie_unlock: "ปลดล็อก Cookie",
    pet_unlock: "ปลดล็อก Pet",
    heart_free: "หัวใจฟรี 100",
    lv_free_power: "ชุดพลังฟรี",
    lv_free_cookie: "Cookie Lv ฟรี",
  };

  function jobKindLabel(kind, extras) {
    extras = extras || {};
    const k = String(kind || "");
    if (k === "afterplay_fast") {
      const fam =
        extras.family ||
        (extras.farm_mode ? afterplaySpec(extras.farm_mode).family : "");
      if (fam) return afterplayFamilyMeta(fam)?.title || JOB_KIND_TH.afterplay_fast;
      return JOB_KIND_TH.afterplay_fast;
    }
    if (k === "unlock_l") {
      const ep = Number(extras.unlock_ep || extras.ep) || 0;
      if (ep) return "ปลดล็อค L · " + unlockLEpShortName(ep);
      return JOB_KIND_TH.unlock_l;
    }
    return JOB_KIND_TH[k] || k || "รอเริ่ม";
  }

  function jobKindIcon(kind, extras) {
    extras = extras || {};
    const k = String(kind || "");
    if (k === "afterplay_fast") {
      const fam =
        extras.family ||
        (extras.farm_mode ? afterplaySpec(extras.farm_mode).family : "");
      if (fam) {
        const icon = AFTERPLAY_FAMILY_NAV.find((row) => row.family === fam)?.icon;
        if (icon) return featureIconSrc(icon);
      }
      return featureIconSrc(FARM_TAB_META.afterplay_fast.icon);
    }
    if (k === "unlock_l") {
      const ep = Number(extras.unlock_ep || extras.ep) || 0;
      return resolveMediaSrc(unlockLEpImage(ep));
    }
    const mode = jobKindToMode(k) || k;
    const meta = FARM_TAB_META[mode];
    if (meta?.icon) return featureIconSrc(meta.icon);
    return resolveMediaSrc(dockModeIcon(mode));
  }

  // Rough wait from gate.me.eta_sec (pool-aware) with legacy position×turn fallback.
  function formatEtaSec(sec) {
    const n = Math.max(0, Math.floor(Number(sec) || 0));
    if (n <= 0) return "";
    if (n < 90) return "ประมาณ " + n + " วินาที";
    if (n < 3600) return "ประมาณ " + Math.ceil(n / 60) + " นาที";
    const h = Math.floor(n / 3600);
    const m = Math.ceil((n % 3600) / 60);
    return m > 0 ? "ประมาณ " + h + " ชม. " + m + " นาที" : "ประมาณ " + h + " ชม.";
  }

  function poolLabelTh(poolOrKind) {
    const k = String(poolOrKind || "").toLowerCase();
    if (k === "heart") return "คิวหัวใจ";
    if (k === "powder") return "คิวผง";
    if (k === "light") return "คิวงานเบา";
    if (k === "afterplay") return "คิว AfterPlay";
    if (k === "unlock_l") return "คิวปลดล็อค L";
    if (k === "ice_tower") return "คิว Ice Tower";
    if (k === "browser") return "คิวเบราว์เซอร์";
    return JOB_KIND_TH[k] ? "คิว" + JOB_KIND_TH[k] : "คิวฟาร์ม";
  }

  function queuePoolStats(gate) {
    const g = gate || {};
    const me = g.me || {};
    const pool = me.pool || g.pool || "";
    const bucket = g.pools && pool ? g.pools[pool] : null;
    const running = bucket ? Number(bucket.running) || 0 : 0;
    const slots = bucket ? Math.max(0, Number(bucket.slots) || 0) : 0;
    const ahead =
      me.ahead != null
        ? Number(me.ahead)
        : Number(me.position) > 0
          ? Number(me.position) - 1
          : null;
    return { pool, running, slots, ahead };
  }

  function queueWorkerChipText(gate) {
    const stats = queuePoolStats(gate);
    const parts = [];
    if (stats.slots > 0) parts.push("กำลังทำ " + stats.running + "/" + stats.slots + " งาน");
    else if (stats.running > 0) parts.push("กำลังทำ " + stats.running + " งาน");
    if (stats.ahead != null && Number.isFinite(stats.ahead)) {
      parts.push(stats.ahead <= 0 ? "ถึงคิวแล้ว" : "รออีก " + stats.ahead + " คิว");
    }
    return parts.join(" · ") || "กำลังจัดคิว";
  }

  function queueRowIsAhead(row, myPos) {
    if (!row || row.is_me) return false;
    const pos = Number(row.position);
    const mine = Number(myPos);
    if (!Number.isFinite(pos) || !Number.isFinite(mine) || mine <= 0) return !row.is_me;
    return pos < mine;
  }

  function queueProgressText(row) {
    if (!row || row.status !== "running") return "ยังไม่เริ่ม";
    const prog = row.progress || {};
    const total = Number(prog.total) || 0;
    const current = Math.max(0, Number(prog.current) || 0);
    if (total > 0) return formatNumTh(Math.min(current, total)) + "/" + formatNumTh(total);
    return "กำลังเริ่ม";
  }

  function queueProgressPct(row) {
    if (!row || row.status !== "running") return 0;
    const prog = row.progress || {};
    const pct = Number(prog.pct);
    if (Number.isFinite(pct)) return Math.max(0, Math.min(100, Math.round(pct)));
    const total = Number(prog.total) || 0;
    const current = Math.max(0, Number(prog.current) || 0);
    if (total <= 0) return 0;
    return Math.max(0, Math.min(100, Math.round((current / total) * 100)));
  }

  function queueWaitText(gate) {
    const g = gate || {};
    const me = g.me || {};
    if (me.eta_sec != null && Number(me.eta_sec) >= 0 && me.status === "waiting") {
      return formatEtaSec(me.eta_sec);
    }
    const ahead =
      me.ahead != null
        ? Number(me.ahead)
        : Number(me.position) > 0
          ? Number(me.position) - 1
          : NaN;
    const turn = Number(g.turn_seconds) || 120;
    if (!Number.isFinite(ahead) || ahead < 0) return "";
    if (ahead === 0) return "ใกล้ถึงคิวแล้ว";
    return formatEtaSec(ahead * turn);
  }

  function queueRankChipText(gate, phase) {
    if (phase !== "queued") return "";
    const me = (gate || lastGate || {}).me || {};
    if (me.position != null && Number(me.position) > 0) {
      return "รอคิว · อันดับ " + Number(me.position);
    }
    return "รอคิว";
  }

  function queueDetailText(gate, jobTitle) {
    const g = gate || lastGate || {};
    const me = g.me || {};
    const pool = me.pool || g.pool || me.kind || "";
    const label = poolLabelTh(pool) || jobTitle || "คิวฟาร์ม";
    const ahead =
      me.ahead != null
        ? Number(me.ahead)
        : me.position != null
          ? Math.max(0, Number(me.position) - 1)
          : null;
    const wait = queueWaitText(g);
    const parts = [label];
    const stats = queuePoolStats(g);
    if (stats.slots > 0) {
      parts.push("Worker กำลังทำ " + stats.running + "/" + stats.slots + " งาน");
    }
    if (ahead != null && Number.isFinite(ahead)) {
      parts.push(
        ahead <= 0 ? "ถึงคิวของคุณแล้ว" : "มี " + ahead + " คนอยู่ข้างหน้า"
      );
    }
    if (wait) parts.push("อีก" + wait.replace(/^ประมาณ /, " "));
    return parts.join(" · ");
  }

  function turnCountdownText(iso) {
    if (!iso) return "";
    const end = Date.parse(iso);
    if (!Number.isFinite(end)) return "";
    const sec = Math.max(0, Math.ceil((end - Date.now()) / 1000));
    const m = Math.floor(sec / 60);
    const s = String(sec % 60).padStart(2, "0");
    return m + ":" + s;
  }

  function renderQueueModal(gate, opts = {}) {
    lastGate = gate || lastGate;
    const g = lastGate || {};
    const me = g.me || {};
    const waking = !!opts.waking;
    let bodyHtml = '<div class="queue-panel">';
    bodyHtml += '<div class="queue-spinner" aria-hidden="true"></div>';

    if (waking) {
      bodyHtml +=
        '<p class="queue-note">กำลังปลุกเซิร์ฟเวอร์… รอสักครู่แล้วระบบจะเข้าคิวให้อัตโนมัติ</p>';
    } else if (isHeavyWorkerRecycling()) {
      bodyHtml +=
        '<p class="queue-note">' + escapeHtml(ERR_TH.worker_unavailable) + "</p>";
    } else if (me.status === "active" || g.is_my_turn) {
      const left = turnCountdownText(me.turn_expires_at);
      bodyHtml +=
        '<div class="queue-stat"><span>สถานะ</span><strong>ถึงคิวของคุณแล้ว</strong></div>';
      bodyHtml +=
        '<div class="queue-stat"><span>เหลือเวลาเริ่มฟาร์ม</span><strong>' +
        escapeHtml(left || "2:00") +
        "</strong></div>";
      bodyHtml += queuedRun
        ? '<p class="queue-note">ถึงคิวแล้ว — กำลังเริ่มให้อัตโนมัติ…</p>'
        : '<p class="queue-note warn">ต้องกดเริ่มฟาร์มภายใน 2 นาที ไม่งั้นคิวจะข้ามไปคนถัดไป</p>';
    } else if (me.status === "waiting") {
      bodyHtml +=
        '<div class="queue-stat"><span>คิวของคุณ</span><strong>อันดับ ' +
        escapeHtml(me.position ?? "—") +
        "</strong></div>";
      bodyHtml +=
        '<div class="queue-stat"><span>ในคิวทั้งหมด</span><strong>' +
        escapeHtml(g.queue_length ?? 0) +
        "</strong></div>";
      const wait = queueWaitText(g);
      if (wait) {
        bodyHtml +=
          '<div class="queue-stat"><span>รออีกประมาณ</span><strong>' +
          escapeHtml(wait) +
          "</strong></div>";
      }
      if (g.job_kind) {
        bodyHtml +=
          '<div class="queue-stat"><span>ตอนนี้กำลังรัน</span><strong>' +
          escapeHtml(JOB_KIND_TH[g.job_kind] || g.job_kind) +
          "</strong></div>";
      }
      bodyHtml += queuedRun
        ? '<p class="queue-note">จองคิวไว้แล้ว — ถึงคิวเมื่อไหร่ระบบจะเริ่มให้อัตโนมัติ</p>'
        : '<p class="queue-note">รอคิวอยู่ — ปิดหน้าต่างไม่ได้ จนกว่าจะถึงคิวของคุณ</p>';
    } else if (g.farm_busy) {
      bodyHtml +=
        '<div class="queue-stat"><span>สถานะ</span><strong>มีคนกำลังฟาร์ม' +
        (g.job_kind ? " (" + escapeHtml(JOB_KIND_TH[g.job_kind] || g.job_kind) + ")" : "") +
        "</strong></div>";
      bodyHtml +=
        '<div class="queue-stat"><span>ในคิว</span><strong>' +
        escapeHtml(g.queue_length ?? 0) +
        "</strong></div>";
      bodyHtml +=
        '<p class="queue-note">กดเข้าคิวเพื่อจองลำดับ — คนกดก่อนได้คิวก่อน</p>';
    } else {
      bodyHtml +=
        '<p class="queue-note">ระบบกำลังจัดคิว…</p>';
    }
    bodyHtml += "</div>";

    clearModalActions();
    openModal({
      mode: "queue",
      title: waking ? "กำลังเชื่อมต่อเซิร์ฟเวอร์" : "คิวฟาร์ม",
      bodyHtml,
      icon: "assets/tr_event_116.png",
      locked: true,
    });

    if (!waking && !me.status && g.farm_busy) {
      modalActions.appendChild(
        makeBtn("เข้าคิว", "btn-candy", () => {
          joinQueue().catch(() => {});
        })
      );
    } else if (me.status === "active" || g.is_my_turn) {
      if (queuedRun) {
        // The run was already confirmed before we hit farm_busy, and the turn
        // only lasts two minutes — waiting for a second click loses the slot.
        resumeQueuedRun();
        return;
      }
      modalActions.appendChild(
        makeBtn("เริ่มฟาร์มเลย", "btn-run", () => {
          forceCloseModal();
          stopQueuePoll();
          $("farm-btn")?.focus();
          setFarmStatus( "ถึงคิวแล้ว — กดเริ่มฟาร์มได้เลย", "ok");
        })
      );
    }
    if (queuedRun && (me.status === "waiting" || (!me.status && g.farm_busy))) {
      modalActions.appendChild(
        makeBtn("ยกเลิกคิว", "btn-ghost", () => {
          leaveServerQueue()
            .catch(() => {})
            .finally(() => {
              forceCloseModal();
            });
        })
      );
    }
  }

  async function leaveServerQueue() {
    try {
      await api("/api/farm/queue/leave", { method: "POST", body: {} });
    } catch (_) {
      /* still clear local state */
    }
    clearQueuedRun();
    stopQueuePoll();
    if (dockPhase === "queued") resetFarmDockIdle();
    setFarmStatus("ยกเลิกคิวแล้ว", "muted");
    refreshGateAndQueueUi().catch(() => {});
    renderFarmDock();
  }

  async function cancelServerJob(jobId) {
    if (!jobId) return null;
    return api(inviteGuestJobPath(jobId, "/cancel"), {
      method: "POST",
      body: {},
    });
  }

  async function cancelAllMyFarmWork() {
    clearPendingFarmJobs();
    const liveId = liveJob?.id || activeWatchJobId;
    // Optimistic UI first.
    clearQueuedRun();
    stopQueuePoll();
    stopWatchJobPoll();
    stopDockElapsedTimer();
    if (liveJob && !liveJob.finished) {
      liveJob.finished = true;
      dockPhase = "error";
      dockOk = false;
    }
    setFarmStatus("กำลังยกเลิกทั้งหมด…", "muted");
    scheduleRenderFarmDock({ immediate: true });
    try {
      await api("/api/farm/jobs/cancel-all", { method: "POST", body: {} });
    } catch (e) {
      if (liveId) {
        try {
          await cancelServerJob(liveId);
        } catch (_) {}
      }
      try {
        await api("/api/farm/queue/leave", { method: "POST", body: {} });
      } catch (_) {}
    }
    setFarmStatus("ยกเลิกงานทั้งหมดแล้ว", "muted");
    scheduleRenderFarmDock();
    updateFarmAvailability();
    refreshGateAndQueueUi().catch(() => {});
  }

  async function joinQueue(jobKind) {
    try {
      const kind = jobKind || queuedJobKind || currentJobKind();
      const data = await api("/api/farm/queue/join", {
        method: "POST",
        body: { job_kind: kind },
      });
      showFarmDockQueue(data);
      startQueuePoll();
      return data;
    } catch (e) {
      clearQueuedRun();
      showErrorModal(thError(e.message) || "เข้าคิวไม่สำเร็จ", "คิว");
      throw e;
    }
  }

  function currentJobKind() {
    const map = {
      partyrun: "partyrun",
      powder: "powder",
      heart: "heart",
      giftdraw: "giftdraw",
      upgrade: "upgrade",
      cookie: "cookie_unlock",
      jelly_upgrade: "jelly_upgrade",
      cookie_unlock: "cookie_unlock",
      pet_unlock: "pet_unlock",
      heart_free: "heart",
      lv_free_power: "lv_free_power",
      lv_free_cookie: "lv_free_cookie",
      quest_claim: "quest_claim",
      treasure_evo: "treasure_evo",
      daily_reward: "daily_reward",
      boost_buy: "boost_buy",
      treasure_ticket: "treasure_ticket",
      ingredient_extract: "ingredient_extract",
      treasure_break: "treasure_break",
    };
    return map[farmTab] || null;
  }

  function isFarmExecutorBusy() {
    return !!(farmRunning || activeWatchJobId);
  }

  function activeFarmMode() {
    return statusContext?.mode || pipelineState?.mode || null;
  }

  function isModeActivelyRunning(mode) {
    return isFarmExecutorBusy() && activeFarmMode() === mode;
  }

  // ----- Advance queue -------------------------------------------------------
  // A job may be submitted while another one runs. The server keeps the order
  // and starts them one at a time, so the browser only has to report the queue.

  /** True when a job already owns the live status card or is waiting its turn. */
  function anyJobLive() {
    return !!(isFarmExecutorBusy() || hasCreditJobRunning() || advanceQueue.open > 0);
  }

  /** Same-function busy check: other functions now run side by side on the server. */
  function jobKindLive(kind) {
    const k = String(kind || "");
    const items = Array.isArray(advanceQueue.items) ? advanceQueue.items : [];
    if (items.some((it) => String(it.kind || it.job_kind || "") === k)) return true;
    const mode = String(activeFarmMode() || "");
    return isFarmExecutorBusy() && (mode === k || (k === "heart" && mode === "heart_free"));
  }

  function heartJobLive() {
    return jobKindLive("heart");
  }

  function queueHasRoom() {
    return advanceQueue.open < advanceQueue.limit;
  }

  function queueFullMessage() {
    return (
      "คิวเต็มแล้ว — เข้าคิวล่วงหน้าได้สูงสุด " +
      advanceQueue.limit +
      " งาน รอให้งานในคิวเสร็จหรือยกเลิกบางงานก่อน"
    );
  }

  function applyQueuePayload(data) {
    if (!data || typeof data !== "object") return;
    advanceQueue = {
      limit: Number(data.limit) || advanceQueue.limit,
      open: Number(data.open) || 0,
      running: Number(data.running) || 0,
      pending: Number(data.pending) || 0,
      canQueueMore: data.can_queue_more !== false,
      items: Array.isArray(data.items) ? data.items : [],
    };
    renderAdvanceQueue();
    updateFarmAvailability();
    paintAfterplayStartEnabled();
  }

  async function refreshAdvanceQueue() {
    if (!accessToken || advanceQueueInFlight) return advanceQueue;
    advanceQueueInFlight = true;
    try {
      const data = await api("/api/farm/queue", { timeoutMs: 8000 });
      applyQueuePayload(data);
    } catch (_) {
    } finally {
      advanceQueueInFlight = false;
    }
    return advanceQueue;
  }

  function startAdvanceQueuePoll() {
    if (advanceQueueTimer) return;
    advanceQueueTimer = setInterval(() => {
      if (!accessToken) return;
      if (advanceQueue.open <= 0 && !anyJobLive()) return;
      refreshAdvanceQueue();
    }, 6000);
  }

  function stopAdvanceQueuePoll() {
    if (!advanceQueueTimer) return;
    clearInterval(advanceQueueTimer);
    advanceQueueTimer = null;
  }

  function queueNumberText(item) {
    const seq = Number(item?.seq);
    return Number.isFinite(seq) && seq > 0 ? "#" + seq : "#—";
  }

  function queueItemTitle(item) {
    const kind = String(item?.kind || "");
    const base = JOB_KIND_TH[kind] || kind || "งานฟาร์ม";
    const mode = String(item?.farm_mode || "");
    if (kind === "afterplay_fast" && mode) {
      const modeTh = afterplayModeLabel(mode);
      if (modeTh) return base + " · " + modeTh;
    }
    if (kind === "friend") {
      if (mode === "add") return "เพิ่มเพื่อน";
      if (mode === "add_mid") return "ส่งคำขอเพื่อน MID";
      if (mode === "remove") return "ลบเพื่อน";
    }
    return base;
  }

  /** Tell the user a job took a queue slot instead of starting right away. */
  function queueSeqTag(data) {
    const seq = Number(data?.job_seq);
    return Number.isFinite(seq) && seq > 0 ? " #" + seq : "";
  }

  function announceQueuedJob(data, label) {
    showToast(
      "เข้าคิวล่วงหน้าแล้ว" + queueSeqTag(data) + (label ? " — " + label : ""),
      "ok"
    );
    if (data?.queue) applyQueuePayload(data.queue);
    else refreshAdvanceQueue();
    showFarmDock();
    startAdvanceQueuePoll();
    // Self-heal: if nothing is actually running, take over the live view.
    attachNextQueuedJob(600);
  }

  async function cancelQueuedJob(jobId) {
    if (!jobId) return;
    try {
      await cancelServerJob(jobId);
      showToast("ยกเลิกงานในคิวแล้ว — คืน Token ที่จองไว้", "muted");
    } catch (e) {
      showToast(thError(e?.message) || "ยกเลิกไม่สำเร็จ", "err");
    }
    await refreshAdvanceQueue();
    await refreshMe().catch(() => {});
  }

  /** After one job ends, hand the live view to whatever the server starts next. */
  function attachNextQueuedJob(delayMs) {
    setTimeout(async () => {
      if (!accessToken) return;
      const q = await refreshAdvanceQueue();
      const next = q?.items?.[0];
      if (!next?.job_id) {
        stopAdvanceQueuePoll();
        return;
      }
      const kind = String(next.kind || "");
      if (kind === "afterplay_fast") {
        if (!afterplayPollTimer) {
          persistKeyedJob(AFTERPLAY_JOB_KEY, next.job_id);
          pollAfterplayJob(next.job_id);
        }
        return;
      }
      if (kind === "unlock_l") {
        if (!unlockLPollTimer) {
          persistKeyedJob(UNLOCKL_JOB_KEY, next.job_id);
          pollUnlockLJob(next.job_id);
        }
        return;
      }
      if (kind === "ice_tower") {
        if (!iceTowerPollTimer) {
          persistKeyedJob(ICE_TOWER_JOB_KEY, next.job_id);
          pollIceTowerJob(next.job_id);
        }
        return;
      }
      if (kind === "friend") {
        if (!friendPollTimer) {
          persistKeyedJob(FRIEND_JOB_KEY, next.job_id);
          pollFriendJob(next.job_id);
        }
        return;
      }
      if (kind === "invite") {
        if (!invitePollTimer) {
          inviteActiveJobId = next.job_id;
          resumeInviteJobIfAny().catch(() => {});
        }
        return;
      }
      if (activeWatchJobId || farmRunning) return;
      resumeFarmSession().catch(() => {});
    }, delayMs != null ? delayMs : 1200);
  }

  function setQueueTokenFallback(on) {
    queueTokenFallback = !!on;
    try {
      localStorage.setItem(TOKEN_FALLBACK_KEY, queueTokenFallback ? "1" : "0");
    } catch (_) {}
    const box = $("queue-token-fallback");
    if (box) box.checked = queueTokenFallback;
  }

  function queueItemMeta(item) {
    const bits = [];
    if (item?.account_label) bits.push("ไอดี: " + String(item.account_label));
    const reserved = Number(item?.reserved);
    if (Number.isFinite(reserved) && reserved > 0) {
      bits.push("กัน " + formatTokenAmount(reserved) + " Token");
    } else if (String(item?.billing || "") === "rental") {
      bits.push(item?.token_fallback ? "วันเช่า · หมดแล้วหัก Token" : "ใช้วันเช่า");
    }
    return bits.join(" · ");
  }

  function renderAdvanceQueue() {
    const section = $("advance-queue-section");
    const list = $("advance-queue-list");
    const countEl = $("advance-queue-count");
    if (!section || !list) return;
    const items = Array.isArray(advanceQueue.items) ? advanceQueue.items : [];
    const show = items.length > 0;
    section.hidden = !show;
    section.classList.toggle("hidden", !show);
    if (countEl) countEl.textContent = advanceQueue.open + " / " + advanceQueue.limit;
    if (!show) {
      list.textContent = "";
      return;
    }
    list.textContent = "";
    items.forEach((item) => {
      const running = String(item?.status || "") === "running";
      const li = document.createElement("li");
      li.className = "advance-queue-item" + (running ? " is-running" : "");

      const seq = document.createElement("span");
      seq.className = "advance-queue-seq";
      seq.textContent = queueNumberText(item);
      li.appendChild(seq);

      const body = document.createElement("div");
      body.className = "advance-queue-body";
      const name = document.createElement("span");
      name.className = "advance-queue-name";
      name.textContent =
        queueItemTitle(item) + (running ? " · กำลังรัน" : " · รอคิวที่ " + (item.position || "—"));
      body.appendChild(name);
      const meta = queueItemMeta(item);
      if (meta) {
        const metaEl = document.createElement("span");
        metaEl.className = "advance-queue-meta";
        metaEl.textContent = meta;
        body.appendChild(metaEl);
      }
      li.appendChild(body);

      if (!running) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "advance-queue-cancel";
        const requested = !!item?.cancel_requested;
        btn.textContent = requested ? "กำลังยกเลิก…" : "ยกเลิก";
        btn.disabled = requested;
        btn.addEventListener("click", () => {
          btn.disabled = true;
          btn.textContent = "กำลังยกเลิก…";
          cancelQueuedJob(item.job_id);
        });
        li.appendChild(btn);
      }
      list.appendChild(li);
    });
  }

  function pendingJobsCount() {
    return pendingFarmJobs.length;
  }

  function clearPendingFarmJobs() {
    pendingFarmJobs = [];
    if (pendingStartTimer) {
      clearTimeout(pendingStartTimer);
      pendingStartTimer = null;
    }
  }

  /** Hard-reset live dock state so the next job never inherits the previous mode/steps/logs. */
  function resetDockLiveForJob(mode, target, extras = {}) {
    const m = mode || "partyrun";
    const preserveTab = !!extras.preserveTab;
    const ctxExtras = { ...extras };
    delete ctxExtras.preserveTab;
    clearStageTimer();
    stopDockElapsedTimer();
    // New job takes over the single live slot; its id is attached once known (watchFarmJob).
    liveJob = { id: null, mode: m, target: Number(target) || 0, finished: false };
    dockPhase = "running";
    dockOk = null;
    dockJobStartedAt = parseJobClockMs(extras.started_at || extras.created_at) || Date.now();
    dockJobFinishedAt = parseJobClockMs(extras.finished_at) || null;
    dockServerElapsedSec =
      extras.elapsed_sec != null && Number.isFinite(Number(extras.elapsed_sec))
        ? Number(extras.elapsed_sec)
        : null;
    dockLiveLogOpen = false;
    if (!preserveTab) {
      clearJobStatusHold();
      jobStatusTab = "live";
      liveSubView = "overview";
    }
    const prevThumbs =
      statusContext?.mode === m && Array.isArray(statusContext?.cookieThumbs)
        ? statusContext.cookieThumbs
        : null;
    statusContext = {
      mode: m,
      target: Number(target) || 0,
      ...(prevThumbs ? { cookieThumbs: prevThumbs } : {}),
      ...ctxExtras,
    };
    pipelineState = freshPipeline(m);
    startDockElapsedTimer();
  }

  /** Drop a finished live card so a newly queued job is not buried under stale Party Run/etc. */
  function clearFinishedLiveCard() {
    if (dockPhase !== "done" && dockPhase !== "error") return;
    dockPhase = null;
    dockOk = null;
    dockJobStartedAt = null;
    dockJobFinishedAt = null;
    dockServerElapsedSec = null;
    stopDockElapsedTimer();
    pipelineState = null;
    statusContext = null;
    if (liveJob?.finished) liveJob = null;
  }

  function enqueueFarmJob({ mode, label, target, runFn, extras }) {
    if (pendingFarmJobs.length >= PENDING_FARM_MAX) {
      showErrorModal(
        "คิวเต็มแล้ว (สูงสุด " +
          PENDING_FARM_MAX +
          " งาน) — รอให้งานปัจจุบันหรือในคิวเสร็จก่อน",
        "คิวเต็ม"
      );
      return false;
    }
    const id =
      "pq_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 7);
    pendingFarmJobs.push({
      id,
      mode: mode || "partyrun",
      label: label || mode || "งานฟาร์ม",
      target: Number(target) || 0,
      runFn,
      extras: extras || null,
    });
    // Finished card must not keep showing the previous mode over the new queued job.
    clearFinishedLiveCard();
    showFarmDock();
    renderFarmDock();
    updateFarmAvailability();
    setFarmStatus(
      "เข้าคิวแล้ว (#" + pendingFarmJobs.length + ") — " + (label || mode),
      "ok"
    );
    return true;
  }

  function cancelPendingFarmJob(id) {
    const before = pendingFarmJobs.length;
    pendingFarmJobs = pendingFarmJobs.filter((j) => j.id !== id);
    if (pendingFarmJobs.length === before) return;
    renderFarmDock();
    updateFarmAvailability();
    setFarmStatus("ยกเลิกงานในคิวแล้ว", "muted");
  }

  function cancelLiveFarmJob() {
    const jobId = liveJob?.id || activeWatchJobId;
    if (!jobId) return Promise.resolve();
    const wasQueued = dockPhase === "queued";
    if (liveJob) liveJob.cancelRequested = true;
    userCancelLatchIds.add(String(jobId));
    if (pipelineState) pipelineState.cancelling = true;
    setFarmStatus(ERR_TH.cancelling, "muted");
    showToast(wasQueued ? "กำลังออกจากคิว…" : ERR_TH.cancelling, "muted");
    scheduleRenderFarmDock();
    return cancelServerJob(jobId)
      .then(() => {
        if (wasQueued) {
          // Queued cancel is immediate on server.
          if (liveJob) liveJob.finished = true;
          dockPhase = "error";
          dockOk = false;
          persistWatchJobId(null);
          stopWatchJobPoll();
          stopDockElapsedTimer();
          setFarmStatus("ออกจากคิวแล้ว", "muted");
        } else {
          // Soft-cancel: keep watching until terminal.
          setFarmStatus("ส่งคำขอยกเลิกแล้ว — รอระบบหยุดงาน", "muted");
          if (!watchJobTimer && jobId && !isCreditHubMode(liveJob?.mode)) {
            watchFarmJob(
              jobId,
              liveJob?.mode || statusContext?.mode || "partyrun",
              liveJob?.target || statusContext?.target || 0,
              {}
            ).catch(() => {});
          }
        }
        scheduleRenderFarmDock();
      })
      .catch((e) => {
        if (liveJob) liveJob.cancelRequested = false;
        userCancelLatchIds.delete(String(jobId));
        if (pipelineState) pipelineState.cancelling = false;
        showErrorModal(thError(e.message) || "ยกเลิกไม่สำเร็จ", "ยกเลิกงาน");
        resumeFarmSession().catch(() => {});
      });
  }

  function isAdminJobsPaneOpen() {
    return !!(adminConsoleOpen && adminConsoleTab === "jobs" && isAdminUser());
  }

  function stopAdminJobsPoll() {
    if (adminJobsPollTimer) {
      clearTimeout(adminJobsPollTimer);
      adminJobsPollTimer = null;
    }
  }

  function adminJobsPollDelayMs() {
    return isAdminJobsPaneOpen() && adminJobsTab === "live" ? 8000 : 12000;
  }

  function scheduleAdminJobsPollTick() {
    adminJobsPollTimer = setTimeout(() => {
      adminJobsPollTimer = null;
      if (!document.hidden && isAdminJobsPaneOpen() && adminJobsTab === "live") {
        loadAdminJobs({ reset: true, silent: true }).catch(() => {});
      }
      if (isAdminUser() && adminConsoleOpen) scheduleAdminJobsPollTick();
    }, adminJobsPollDelayMs());
  }

  function startAdminJobsPoll() {
    if (window.CKRAdminJobs) return;
    if (!isAdminUser()) return;
    if (adminJobsPollTimer) return;
    scheduleAdminJobsPollTick();
  }

  function adminJobsFingerprint(items) {
    return (items || [])
      .map((r) =>
        [
          r.job_id || "",
          r.status || "",
          r.cancel_requested ? "1" : "0",
          (r.progress && r.progress.current) || "",
          (r.progress && r.progress.phase) || "",
          r.error || "",
          r.heartbeat_at || "",
          adminJobIsStuck(r) ? "stuck" : "",
        ].join(":")
      )
      .join("|");
  }

  function adminJobAgeSec(row) {
    const ts = adminJobIsWaiting(row)
      ? row.created_at
      : row.heartbeat_at || row.started_at || row.created_at;
    if (!ts) return null;
    const t = Date.parse(ts);
    if (!Number.isFinite(t)) return null;
    return Math.max(0, Math.floor((Date.now() - t) / 1000));
  }

  function adminJobIsWaiting(row) {
    const st = String(row?.status || "");
    return st === "queued" || st === "holding";
  }

  function adminJobIsStuck(row) {
    // Waiting jobs have not started — that is "รอคิว", never "ค้าง".
    if (adminJobIsWaiting(row)) return false;
    if ((row.status || "") !== "running") return false;
    const now = Date.now();
    const hb = row.heartbeat_at ? Date.parse(row.heartbeat_at) : NaN;
    const started = row.started_at ? Date.parse(row.started_at) : NaN;
    const STALE_MS = 90_000;
    if (Number.isFinite(hb)) return now - hb > STALE_MS;
    if (Number.isFinite(started)) return now - started > STALE_MS;
    return true;
  }

  function adminJobToCard(row) {
    const kind = row.kind || "partyrun";
    const mode = jobKindToMode(kind);
    const st = row.status || "";
    const waiting = adminJobIsWaiting(row);
    const stuck = adminJobIsStuck(row);
    const phase = stuck
      ? "stuck"
      : st === "succeeded"
        ? "done"
        : st === "failed" || st === "cancelled"
          ? "error"
          : st === "running"
            ? "running"
            : waiting
              ? "queued"
              : "idle";
    const incomplete = farmResultIncomplete(row);
    const afterplayPartial =
      (incomplete && jobKindToMode(kind) === "afterplay_fast") ||
      String(row.error || "") === "incomplete_afterplay";
    let badge =
      st === "succeeded"
        ? "สำเร็จ"
        : afterplayPartial
          ? farmIncompleteLabel(row)
          : st === "failed"
            ? "ล้มเหลว"
            : st === "cancelled"
              ? "ยกเลิก"
              : stuck
                ? "ค้าง"
                : st === "running"
                  ? "กำลังรัน"
                  : waiting
                    ? "รอคิว"
                    : st;
    const canCancel = waiting || st === "running";
    const prog = row.progress || {};
    const progText =
      prog.total > 0
        ? String(prog.current || 0) + "/" + String(prog.total) + (prog.phase ? " · " + prog.phase : "")
        : prog.phase || "";
    const ageSec = adminJobAgeSec(row);
    const ageLine = ageSec != null ? (waiting ? "รอมาแล้ว " : "อายุ ") + formatDockElapsed(ageSec) : "";
    const startedLine = formatDockStartedAt(
      waiting ? row.created_at : row.started_at || row.created_at || row.finished_at
    ) || "";
    const timeLine = [startedLine, ageLine, stuck ? "บังคับจบได้" : ""]
      .filter(Boolean)
      .join(" · ");
    return {
      mode,
      phase,
      title: (row.username || "user") + " · " + (JOB_KIND_TH[kind] || kind),
      badge,
      detail: stuck
        ? row.error || "งานเริ่มแล้วแต่สะดุด — heartbeat หาย"
        : waiting
          ? "รอถึงคิว — ยังไม่เริ่มงาน"
          : row.error || progText || kind,
      timeLine,
      live: false,
      cancelable: canCancel,
      adminCancelId: canCancel ? row.job_id : "",
      jobId: row.job_id || "",
      stuck,
      adminJobId: row.job_id || "",
    };
  }

  function isHeavyWorkerRecycling() {
    const workers = (lastHealth && lastHealth.workers) || {};
    const heart = workers.heart || {};
    const powder = workers.powder || {};
    const heavy = workers.heavy || {};
    return !!(
      heavy.recycling ||
      heavy.alive === false ||
      (heart.alive === false && powder.alive === false) ||
      heart.recycling ||
      powder.recycling ||
      (lastHealth && lastHealth.worker_recycling) ||
      window.__ckrWorkerRecycling
    );
  }

  function renderAdminWorkerChip() {
    const chip = $("farm-dock-admin-worker");
    const text = $("farm-dock-admin-worker-text");
    if (!chip || !text) return;
    const alive = Number(window.__ckrWorkersAlive);
    const memPct = Number(window.__ckrMemoryPct);
    const memNote = Number.isFinite(memPct) ? " · RAM " + memPct + "%" : "";
    const workers = (lastHealth && lastHealth.workers) || {};
    const heartOk = !!(workers.heart && workers.heart.alive);
    const powderOk = !!(workers.powder && workers.powder.alive);
    const lightOk = !!(workers.light && workers.light.alive);
    const heavyOk = !!(workers.heavy && workers.heavy.alive) || heartOk || powderOk;
    chip.classList.remove("is-alive", "is-down");
    if (!Number.isFinite(alive)) {
      text.textContent = "กำลังตรวจสอบ worker…";
    } else if (alive <= 0) {
      chip.classList.add("is-down");
      text.textContent = "ไม่มี worker พร้อมทำงาน — งานใหม่อาจรอคิว" + memNote;
    } else {
      const ok = (heartOk || heavyOk) && powderOk && lightOk;
      // If split pools missing from health payload, fall back to heavy/light.
      const hasSplit = !!(workers.heart || workers.powder);
      chip.classList.add(ok || (!hasSplit && heavyOk && lightOk) ? "is-alive" : "is-down");
      if (hasSplit) {
        text.textContent =
          "หัวใจ " +
          (heartOk ? "พร้อม" : "ออฟไลน์") +
          " · ผง " +
          (powderOk ? "พร้อม" : "ออฟไลน์") +
          " · เบา " +
          (lightOk ? "พร้อม" : "ออฟไลน์") +
          " (" +
          alive +
          " ตัว)" +
          memNote;
      } else {
        text.textContent =
          "Heavy " +
          (heavyOk ? "พร้อม" : "ออฟไลน์") +
          " · Light " +
          (lightOk ? "พร้อม" : "ออฟไลน์") +
          " (" +
          alive +
          " ตัว)" +
          memNote;
      }
    }
    const heartMaxRow = $("farm-dock-admin-heart-max");
    if (heartMaxRow) heartMaxRow.classList.toggle("hidden", !isAdminUser());
    const powderMaxRow = $("farm-dock-admin-powder-max");
    if (powderMaxRow) powderMaxRow.classList.toggle("hidden", !isAdminUser());
  }

  async function loadAdminHeartMaxSetting() {
    if (!isAdminUser()) return;
    const input = $("farm-dock-admin-heart-max-input");
    const msg = $("farm-dock-admin-heart-max-msg");
    const powderInput = $("farm-dock-admin-powder-max-input");
    const powderMsg = $("farm-dock-admin-powder-max-msg");
    if (!input && !powderInput) return;
    try {
      const data = await api("/api/admin/settings");
      const n = Number(data.heart_max_target);
      if (Number.isFinite(n) && input) input.value = String(n);
      const range = data.heart_max_target_range;
      if (Array.isArray(range) && range.length >= 2 && input) {
        input.min = String(range[0]);
        input.max = String(range[1]);
      }
      const pn = Number(data.powder_max_target);
      if (Number.isFinite(pn) && powderInput) {
        powderInput.value = String(pn);
        powderMax = Math.max(1, Math.floor(pn));
        clampPowderTargetInputs();
      }
      const pr = data.powder_max_target_range;
      if (Array.isArray(pr) && pr.length >= 2 && powderInput) {
        powderInput.min = String(pr[0]);
        powderInput.max = String(pr[1]);
      }
      if (msg) {
        const hhi = Array.isArray(range) && range.length >= 2 ? range[1] : null;
        msg.textContent = hhi
          ? "เพดานหัวใจสูงสุดต่อ job ที่ลูกค้าตั้งได้ · แอดมินปรับได้ 1–" + formatNumTh(hhi)
          : "เพดานหัวใจสูงสุดต่อ job ที่ลูกค้าตั้งได้ — แอดมินปรับเพิ่ม/ลดได้อิสระ";
      }
      if (powderMsg) {
        const hi = Array.isArray(pr) && pr.length >= 2 ? pr[1] : null;
        powderMsg.textContent = hi
          ? "ค่าปัจจุบันใช้เป็นเพดานผู้ใช้ · แอดมินปรับได้ 1–" + formatNumTh(hi)
          : "ค่าเริ่มต้น 5,000 — แอดมินปรับเพิ่ม/ลดได้";
      }
      const hlp = data.heartloop_pricing;
      if (hlp && typeof hlp === "object") {
        const ph = $("farm-dock-admin-hl-perhour");
        const p12 = $("farm-dock-admin-hl-pack12");
        const p24 = $("farm-dock-admin-hl-pack24");
        if (ph && Number.isFinite(Number(hlp.per_hour))) ph.value = String(hlp.per_hour);
        if (p12 && Number.isFinite(Number(hlp.pack_12h))) p12.value = String(hlp.pack_12h);
        if (p24 && Number.isFinite(Number(hlp.pack_24h))) p24.value = String(hlp.pack_24h);
      }
    } catch (e) {
      const err = thError(e.message) || "โหลดการตั้งค่าไม่สำเร็จ";
      if (msg) msg.textContent = err;
      if (powderMsg) powderMsg.textContent = err;
    }
  }

  async function saveAdminHeartMaxSetting() {
    const input = $("farm-dock-admin-heart-max-input");
    const msg = $("farm-dock-admin-heart-max-msg");
    const btn = $("farm-dock-admin-heart-max-save");
    if (!input || !isAdminUser()) return;
    const n = Math.floor(Number(input.value) || 0);
    if (!Number.isFinite(n) || n < 1) {
      if (msg) msg.textContent = "ใส่จำนวนหัวใจที่ถูกต้อง";
      return;
    }
    if (msg) msg.textContent = "กำลังบันทึก…";
    try {
      await withAdminSave(btn, async () => {
        const data = await api("/api/admin/settings", {
          method: "POST",
          body: { heart_max_target: n },
        });
        const saved = Number(data.heart_max_target);
        if (Number.isFinite(saved)) {
          applyHeartMax(saved);
          paintHeartStepper();
          if (input) input.value = String(heartMax);
        }
        if (msg) msg.textContent = "บันทึกแล้ว — สูงสุด " + formatNumTh(saved || n) + " หัวใจ/job";
      }, "บันทึกเพดานหัวใจแล้ว");
    } catch (e) {
      if (msg) msg.textContent = thError(e.message) || "บันทึกไม่สำเร็จ";
    }
  }

  async function saveAdminPowderMaxSetting() {
    const input = $("farm-dock-admin-powder-max-input");
    const msg = $("farm-dock-admin-powder-max-msg");
    const btn = $("farm-dock-admin-powder-max-save");
    if (!input || !isAdminUser()) return;
    const n = Math.floor(Number(String(input.value || "").replace(/[^\d]/g, "")) || 0);
    const minAllowed = Math.max(1, Number(input.min) || 1);
    const maxAllowed = Math.max(minAllowed, Number(input.max) || 2000000);
    if (!Number.isFinite(n) || n < minAllowed) {
      if (msg) msg.textContent = "ใส่จำนวนผงอย่างน้อย " + formatNumTh(minAllowed);
      return;
    }
    if (n > maxAllowed) {
      if (msg)
        msg.textContent =
          "สูงสุดที่ระบบรับได้คือ " + formatNumTh(maxAllowed) + " ผง/รอบ";
      return;
    }
    if (msg) msg.textContent = "กำลังบันทึก…";
    try {
      await withAdminSave(btn, async () => {
        const data = await api("/api/admin/settings", {
          method: "POST",
          body: { powder_max_target: n },
        });
        const saved = Number(data.powder_max_target);
        if (Number.isFinite(saved)) {
          powderMax = Math.max(1, Math.floor(saved));
          if (input) input.value = String(powderMax);
          clampPowderTargetInputs();
          paintPowderGoalControls();
          refreshPowderEstimate().catch(() => {});
        }
        const range = data.powder_max_target_range;
        if (Array.isArray(range) && range.length >= 2) {
          input.min = String(range[0]);
          input.max = String(range[1]);
        }
        if (msg)
          msg.textContent =
            "บันทึกแล้ว — ผู้ใช้ตั้งเป้าได้สูงสุด " +
            formatNumTh(saved || n) +
            " ผง/รอบ";
      }, "บันทึกเพดานผงแล้ว");
    } catch (e) {
      if (msg) msg.textContent = thError(e.message) || "บันทึกไม่สำเร็จ";
    }
  }

  async function saveAdminHeartLoopPricing() {
    const ph = $("farm-dock-admin-hl-perhour");
    const p12 = $("farm-dock-admin-hl-pack12");
    const p24 = $("farm-dock-admin-hl-pack24");
    const msg = $("farm-dock-admin-hl-msg");
    const btn = $("farm-dock-admin-hl-save");
    if (!ph || !isAdminUser()) return;
    const per = Math.floor(Number(ph.value) || 0);
    const pack12 = Math.floor(Number(p12?.value) || 0);
    const pack24 = Math.floor(Number(p24?.value) || 0);
    if (per < 1 || pack12 < 1 || pack24 < 1) {
      if (msg) msg.textContent = "ใส่ราคาที่ถูกต้องทั้ง 3 ช่อง";
      return;
    }
    if (msg) msg.textContent = "กำลังบันทึก…";
    try {
      await withAdminSave(btn, async () => {
        const data = await api("/api/admin/settings", {
          method: "POST",
          body: { heartloop_pricing: { per_hour: per, pack_12h: pack12, pack_24h: pack24 } },
        });
        const saved = data.heartloop_pricing || {};
        if (msg)
          msg.textContent =
            "บันทึกแล้ว — ต่อ ชม. " +
            (saved.per_hour ?? per) +
            "฿ · 12ชม. " +
            (saved.pack_12h ?? pack12) +
            "฿ · 24ชม. " +
            (saved.pack_24h ?? pack24) +
            "฿";
      }, "บันทึกราคา HeartLoop แล้ว");
    } catch (e) {
      if (msg) msg.textContent = thError(e.message) || "บันทึกไม่สำเร็จ";
    }
  }

  function renderAdminStats() {
    const statsBox = $("farm-dock-admin-stats");
    const filters = $("farm-dock-admin-filters");
    const showLive = adminJobsTab === "live";
    if (statsBox) statsBox.classList.toggle("hidden", !showLive);
    if (filters) filters.classList.toggle("hidden", !showLive);
    if (!showLive) return;
    let running = 0;
    let queued = 0;
    let stuck = 0;
    for (const r of adminJobsItems) {
      if (adminJobIsStuck(r)) stuck += 1;
      else if (r.status === "running") running += 1;
      else if (adminJobIsWaiting(r)) queued += 1;
    }
    const set = (id, n) => {
      const el = $(id);
      if (el) el.textContent = String(n);
    };
    set("farm-dock-admin-stat-running", running);
    set("farm-dock-admin-stat-queued", queued);
    set("farm-dock-admin-stat-stuck", stuck);
    document.querySelectorAll("[data-admin-filter]").forEach((btn) => {
      btn.classList.toggle(
        "is-active",
        btn.getAttribute("data-admin-filter") === adminJobsFilter
      );
    });
  }

  function adminJobsFiltered() {
    if (adminJobsTab !== "live" || adminJobsFilter === "all") return adminJobsItems;
    return adminJobsItems.filter((r) => {
      if (adminJobsFilter === "stuck") return adminJobIsStuck(r);
      if (adminJobsFilter === "running") return r.status === "running" && !adminJobIsStuck(r);
      if (adminJobsFilter === "queued") return adminJobIsWaiting(r);
      return true;
    });
  }

  function renderAdminJobsList() {
    if (window.CKRAdminJobs) return;
    const box = $("farm-dock-admin-list");
    const moreBtn = $("farm-dock-admin-more");
    const warn = $("farm-dock-admin-warn");
    const focusedElement = document.activeElement;
    const focusedCancelId = box?.contains(focusedElement)
      ? focusedElement.dataset.adminCancel || ""
      : "";
    renderAdminWorkerChip();
    renderAdminStats();
    if (warn) {
      const alive = Number(window.__ckrWorkersAlive);
      if (isHeavyWorkerRecycling() && adminJobsTab === "live") {
        warn.textContent = ERR_TH.worker_unavailable;
        warn.classList.remove("hidden");
      } else if (Number.isFinite(alive) && alive <= 0 && adminJobsTab === "live") {
        warn.textContent = "ไม่มี worker ที่พร้อมทำงาน — งานใหม่อาจรอคิวนานกว่าปกติ";
        warn.classList.remove("hidden");
      } else {
        warn.textContent = "";
        warn.classList.add("hidden");
      }
    }
    if (!box) return;
    box.replaceChildren();
    const rows = adminJobsFiltered();
    if (!rows.length) {
      if (adminJobsLoading && !adminJobsItems.length) {
        paintFarmDockHistorySkeleton(box, 4);
      } else {
        const empty = document.createElement("p");
        empty.className = "farm-dock-empty";
        empty.textContent =
          adminJobsTab === "live"
            ? adminJobsItems.length
              ? "ไม่มีงานในตัวกรองนี้"
              : "ไม่มีงานที่กำลังรันหรือรอคิว"
            : "ยังไม่มีประวัติงาน";
        box.appendChild(empty);
      }
    } else {
      for (const row of rows) {
        try {
          box.appendChild(renderTxCard(adminJobToCard(row)));
        } catch (_) {}
      }
    }
    if (focusedCancelId) {
      const focusedButton = Array.from(box.querySelectorAll("[data-admin-cancel]")).find(
        (button) => button.dataset.adminCancel === focusedCancelId
      );
      focusedButton?.focus({ preventScroll: true });
    }
    if (moreBtn) {
      moreBtn.classList.toggle("hidden", !(adminJobsTab === "history" && adminJobsHasMore));
    }
  }

  let adminJobsLoading = false;
  let adminJobsFp = "";
  let adminJobsReqId = 0;

  async function loadAdminJobs({ reset = true, silent = false } = {}) {
    if (window.CKRAdminJobs) return window.CKRAdminJobs.refresh();
    if (!isAdminUser()) return;
    if (silent && adminJobsLoading) return;
    const reqId = ++adminJobsReqId;
    const status = adminJobsTab === "history" ? "history" : "active";
    adminJobsLoading = true;
    try {
      if (reset) adminJobsOffset = 0;
      if (reset && !silent) renderAdminJobsList();
      const data = await api(
        "/api/admin/jobs?status=" +
          encodeURIComponent(status) +
          "&limit=" +
          ADMIN_JOBS_PAGE +
          "&offset=" +
          adminJobsOffset
      );
      if (reqId !== adminJobsReqId) return;
      const items = Array.isArray(data.items) ? data.items : [];
      const next = reset ? items : adminJobsItems.concat(items);
      const fp = adminJobsFingerprint(next);
      const changed = fp !== adminJobsFp || !reset;
      adminJobsItems = next;
      adminJobsOffset = adminJobsItems.length;
      adminJobsHasMore = items.length >= ADMIN_JOBS_PAGE;
      adminJobsFp = fp;
      if (!silent || changed) renderAdminJobsList();
      if (adminJobsTab === "live") startAdminJobsPoll();
      else stopAdminJobsPoll();
    } catch (e) {
      if (reqId !== adminJobsReqId) return;
      if (!silent) {
        adminConsoleStatus(thError(e.message) || "โหลดงานไม่สำเร็จ", "err");
        renderAdminJobsList();
      }
    } finally {
      if (reqId === adminJobsReqId) {
        adminJobsLoading = false;
        if (!silent) renderAdminJobsList();
      }
    }
  }

  async function adminCancelJob(jobId) {
    if (!jobId) return;
    // Optimistic remove so stuck rows disappear immediately in Admin UI.
    adminJobsItems = adminJobsItems.filter((r) => r.job_id !== jobId);
    adminJobsFp = adminJobsFingerprint(adminJobsItems);
    renderAdminJobsList();
    try {
      await api("/api/admin/jobs/" + encodeURIComponent(jobId) + "/cancel", {
        method: "POST",
        body: {},
      });
      setFarmStatus("ยกเลิกงานของ user แล้ว", "muted");
    } finally {
      await loadAdminJobs({ reset: true });
    }
  }

  async function adminClearQueueAll() {
    const ok = window.confirm(
      "ล้างคิวทั้งระบบและยกเลิกงาน queued/running ทั้งหมด?"
    );
    if (!ok) return;
    await withAdminSave($("farm-dock-admin-clear"), async () => {
      adminJobsItems = [];
      adminJobsFp = "";
      renderAdminJobsList();
      const data = await api("/api/admin/queue/clear", { method: "POST", body: {} });
      const count = data.cancelled_jobs || 0;
      setFarmStatus("ล้างคิวแล้ว — งาน " + count + " รายการ", "ok");
      await loadAdminJobs({ reset: true });
    }, "ล้างคิวงานทั้งหมดแล้ว");
  }

  function dequeueAndStartNext(delayMs) {
    if (startingFromPersonalQueue) return;
    if (isFarmExecutorBusy()) return;
    if (queuedRun) return;
    if (!pendingFarmJobs.length) return;
    if (pendingStartTimer) return;
    // Keep success/error visible briefly before switching to the next queued job.
    const wait =
      delayMs != null
        ? Math.max(0, Number(delayMs) || 0)
        : dockPhase === "done" || dockPhase === "error"
          ? 900
          : 320;
    pendingStartTimer = setTimeout(() => {
      pendingStartTimer = null;
      if (isFarmExecutorBusy() || queuedRun) return;
      const next = pendingFarmJobs.shift();
      if (!next || typeof next.runFn !== "function") {
        renderFarmDock();
        updateFarmAvailability();
        return;
      }
      resetDockLiveForJob(next.mode, next.target, next.extras || {});
      renderFarmDock({ mode: next.mode, target: next.target });
      updateFarmAvailability();
      setFarmStatus("ถึงคิวแล้ว — เริ่ม " + (next.label || next.mode), "ok");
      startingFromPersonalQueue = true;
      Promise.resolve()
        .then(() => next.runFn())
        .catch(() => {})
        .finally(() => {
          startingFromPersonalQueue = false;
          if (!isFarmExecutorBusy() && !queuedRun && pendingFarmJobs.length) {
            dequeueAndStartNext();
          }
        });
    }, wait);
  }

  /** The server owns the queue now, so a busy executor no longer blocks a submit.
   * The label is remembered for the "เข้าคิวล่วงหน้าแล้ว #N" toast. */
  function queueIfBusy(mode, target, label, runFn, extras) {
    if (label) pendingQueueLabel = String(label);
    return false;
  }

  function takePendingQueueLabel(mode) {
    const label = pendingQueueLabel || jobTitleForMode(mode) || mode || "งานฟาร์ม";
    pendingQueueLabel = null;
    return label;
  }

  /** Report a failed advance-queue submit without touching the live card. */
  function reportQueueSubmitError(e, label) {
    const detail = e?.data?.detail;
    const code = String(
      (typeof detail === "object" && detail?.code) || detail || e?.message || ""
    );
    if (/no_advance_queue/i.test(code)) {
      showErrorModal(
        (typeof detail === "object" && detail?.message) || ERR_TH.no_advance_queue,
        "ยังเริ่มไม่ได้"
      );
      return;
    }
    if (/queue_full/i.test(code)) {
      const msg =
        (typeof detail === "object" && detail?.message) || queueFullMessage();
      showErrorModal(msg, "คิวเต็ม");
      refreshAdvanceQueue();
      return;
    }
    if (handleFarmBillingDenied(e)) return;
    const raw = String(e?.userMessage || e?.message || "");
    showToast(
      (label ? label + " — " : "") + (thError(raw) || raw || "เข้าคิวไม่สำเร็จ"),
      "err"
    );
  }

  /** Hit farm_busy: hold the run, take a queue slot, and resume when it is ours. */
  async function enterQueueFor(gate, runFn, jobKind) {
    queuedJobKind = jobKind || currentJobKind();
    if (queueResumeAttempts >= 3) {
      queuedRun = null;
      queueResumeAttempts = 0;
      showFarmDockQueue(gate || { farm_busy: true, queue_length: 0, me: {} });
      startQueuePoll();
      return;
    }
    queuedRun = runFn || null;
    showFarmDockQueue(gate || { farm_busy: true, queue_length: 0, me: {} });
    startQueuePoll();
    if (!gate?.me?.status) {
      await joinQueue().catch(() => {});
    }
  }

  function resumeQueuedRun() {
    const run = queuedRun;
    if (!run || isFarmExecutorBusy()) return;
    queuedRun = null;
    queueResumeAttempts += 1;
    stopQueuePoll();
    dockPhase = "running";
    setFarmStatus( "ถึงคิวแล้ว — กำลังเริ่มให้อัตโนมัติ", "ok");
    run();
  }

  function clearQueuedRun() {
    queuedRun = null;
    queueResumeAttempts = 0;
  }

  async function refreshGateAndQueueUi() {
    if (!accessToken) return null;
    if (gateRefreshInflight) return gateRefreshInflight;
    const startedAt = Date.now();
    gateRefreshInflight = (async () => {
    try {
      const data = await api("/api/farm/gate", { timeoutMs: 8000 });
      queuePollFailures = 0;
      const elapsed = Date.now() - startedAt;
      gateSlowStreak = elapsed >= 2500 ? Math.min(6, gateSlowStreak + 1) : 0;
      lastGate = data;
      if (data.is_admin && profile) {
        profile.role = "admin";
        profile.is_admin = true;
      }
      if (Array.isArray(data.early_access_features)) {
        applyEarlyAccess(data.early_access_features);
      }
      applyFarmNavPayload(data);
      if (!data.feature_locks) paintFeatureLocks();
      const queueStatus = data.me?.status;
      const isQueued = queueStatus === "waiting" || queueStatus === "active";
      if (isQueued) {
        showFarmDockQueue(data);
        startQueuePoll();
      } else if (queuedRun && data.can_run && !data.farm_busy) {
        resumeQueuedRun();
      } else if (dockPhase === "queued" && !data.farm_busy && !data.me?.status) {
        resetFarmDockIdle();
        stopQueuePoll();
      } else if (dockPhase === "queued" || queuedRun) {
        showFarmDockQueue(data);
      }
      if (Array.isArray(data.queue_items)) {
        renderFarmDockQueue(data.queue_items);
      }
      return data;
    } catch (e) {
      if (isTransientNetworkError(e)) queuePollFailures += 1;
      if (isTransientNetworkError(e)) {
        gateSlowStreak = Math.min(6, gateSlowStreak + 1);
      }
      const isLocallyQueued = dockPhase === "queued" || !!queuedRun;
      if (isLocallyQueued && isTransientNetworkError(e)) {
        showFarmDockQueue(lastGate || { farm_busy: true, queue_length: 0 }, { waking: true });
        startQueuePoll();
      }
      return null;
    } finally {
      gateRefreshInflight = null;
    }
    })();
    return gateRefreshInflight;
  }

  function stopActivityPoll() {
    if (activityPollTimer) {
      clearTimeout(activityPollTimer);
      activityPollTimer = null;
    }
  }

  function activityPollDelayMs() {
    const busy =
      dockPhase === "running" ||
      dockPhase === "queued" ||
      !!activeWatchJobId ||
      pendingFarmJobs.length > 0;
    // Keep polls light — activity is cached server-side; hammering it under
    // heart load was starving login/run requests.
    return busy ? 8000 : 30000;
  }

  function scheduleActivityPollTick() {
    activityPollTimer = setTimeout(() => {
      activityPollTimer = null;
      if (!document.hidden) {
        refreshFarmActivity().catch(() => {});
      }
      scheduleActivityPollTick();
    }, activityPollDelayMs());
  }

  function startActivityPoll() {
    stopActivityPoll();
    refreshFarmActivity().catch(() => {});
    scheduleActivityPollTick();
  }

  function paintFarmActivity(data) {
    farmActivityData = data || null;
    // Activity is informational only. Rebuilding the status sheet here caused
    // tab/focus flicker every poll, especially on iOS.
  }

  async function refreshFarmActivity() {
    if (!accessToken) return null;
    try {
      const data = await api("/api/farm/activity");
      paintFarmActivity(data);
      return data;
    } catch (_) {
      return null;
    }
  }

  function paintFarmDockSystem(data) {
    farmActivityData = data || farmActivityData;
    // System board removed from FAB popup — history list covers this.
  }

  function systemBarCopy() {
    const d = farmActivityData || {};
    if (isHeavyWorkerRecycling()) {
      return {
        title: "สถานะระบบ",
        sub: ERR_TH.worker_unavailable,
      };
    }
    if (d.current?.job_kind) {
      const label = JOB_KIND_TH[d.current.job_kind] || d.current.job_kind;
      return { title: "สถานะระบบ", sub: "กำลังรัน: " + label };
    }
    if (d.farm_busy) {
      return { title: "สถานะระบบ", sub: "กำลังรันงานอื่น…" };
    }
    return { title: "สถานะระบบ", sub: "ว่าง — พร้อมรับงาน" };
  }

  function resetFarmDockIdle() {
    if (farmRunning || activeWatchJobId || dockPhase === "running" || dockPhase === "queued" || hasCreditJobRunning()) {
      return;
    }
    dockPhase = null;
    dockOk = null;
    dockJobStartedAt = null;
    dockJobFinishedAt = null;
    liveJob = null;
    statusContext = null;
    pipelineState = null;
    farmDockFlash = { text: "", kind: "muted" };
    stopDockElapsedTimer();
    if (jobHubShouldStayVisible()) {
      jobStatusView = jobStatusView === "expanded" ? "expanded" : "minimized";
      syncJobStatusShell();
      renderFarmDock();
    } else {
      hideJobStatusShell();
      renderFarmDock();
    }
  }

