  function tokenConfirmLines(preview) {
    if (!preview) return [];
    if (preview.free) {
      return [
        "งานนี้ไม่หัก Token",
        "คงเหลือ " + formatTokenAmount(preview.have) + " Token",
      ];
    }
    if (preview.covered) {
      return [
        "มีวันเช่าของฟังก์ชันนี้ — ไม่หัก Token",
        "คงเหลือ " + formatTokenAmount(preview.have) + " Token",
      ];
    }
    const lines = [
      "เรท " + formatTokenAmount(preview.rate) + " Token ต่อหน่วยที่สำเร็จ",
      "สำรองสูงสุด " + formatTokenAmount(preview.cost) + " Token · ส่วนที่ไม่สำเร็จคืนให้",
      "ตอนนี้มี " + formatTokenAmount(preview.have) + " Token",
    ];
    if (preview.neverRental) lines.push("วันเช่าไม่ครอบคลุมฟังก์ชันนี้");
    if (preview.enough) {
      lines.push("หลังกดเริ่มจะเหลือประมาณ " + formatTokenAmount(preview.remain) + " Token");
    } else {
      lines.push(
        "หลังกดเริ่มจะเหลือ " +
          formatTokenAmount(preview.remain) +
          " Token — ไม่พอ ขาด " +
          formatTokenAmount(Math.abs(preview.remain)) +
          " Token"
      );
    }
    return lines;
  }

