  function isFriendsCrowdedError(e) {
    const code = String(
      e?.code || e?.data?.detail?.code || e?.data?.detail?.message || e?.message || ""
    );
    return e?.status === 412 || /friends_crowded/i.test(code);
  }

  async function openFriendRemoveForHeart(snap, returnTab) {
    friendHeartReturn = returnTab === "heart_free" ? "heart_free" : "heart";
    setFriendMode("remove");
    switchFarmTab("friend");
    setStatus(
      $("friend-status"),
      "เลือกเพื่อนที่จะลบเอง — เพื่อนจริงไม่ถูกบังคับลบ",
      "muted"
    );
    paintFriendHeartBanner();
    try {
      await refreshFriendPreview({ force: true });
    } catch (_) {}
    if (snap && friendSnap) {
      friendSnap.threshold = snap.threshold || friendSnap.threshold || 250;
    }
    paintFriend();
  }

  async function confirmHeartFriendWipeIfNeeded(returnTab) {
    setFarmStatus("กำลังตรวจจำนวนเพื่อน…", "muted");
    const tab = returnTab === "heart_free" ? "heart_free" : "heart";
    try {
      await ensureApiReady();
      const snap = await api("/api/farm/heart/friends", {
        method: "POST",
        body: heartFriendScanBody(),
        timeoutMs: 60000,
      });
      if (!snap?.crowded) {
        return { proceed: true, snap };
      }
      const ok = await showHeartFriendsCrowdedModal(snap);
      if (ok) await openFriendRemoveForHeart(snap, tab);
      return { proceed: false, snap };
    } catch (e) {
      if (isFriendsCrowdedError(e)) {
        const snap = e?.data?.detail && typeof e.data.detail === "object" ? e.data.detail : {};
        const ok = await showHeartFriendsCrowdedModal(snap);
        if (ok) await openFriendRemoveForHeart(snap, tab);
        return { proceed: false, snap };
      }
      throw e;
    }
  }

