  function hasDevPlayCreds() {
    const { email, password } = getDevPlayCreds();
    return !!(email && password);
  }

  function getDevPlayCreds() {
    if (devplaySession?.email && devplaySession?.password) {
      return {
        email: String(devplaySession.email).trim(),
        password: String(devplaySession.password),
      };
    }
    const mail = ($("dp-acct-mail")?.value || "").trim();
    const secret = $("dp-acct-secret")?.value || "";
    return { email: mail, password: secret };
  }

  // ---- HeartLoop (timed permanent-friend harvest) -----------------------
  let heartloopPricing = { per_hour: 5, pack_12h: 50, pack_24h: 100 };
  let heartloopFreeSlots = null;
  let heartloopCustom = false;

  function heartloopPriceFor(hours) {
    const h = Math.max(1, Math.min(24, parseInt(hours, 10) || 12));
    if (h === 12) return heartloopPricing.pack_12h;
    if (h === 24) return heartloopPricing.pack_24h;
    return h * heartloopPricing.per_hour;
  }

  function heartloopSelectedHours() {
    if (heartloopCustom) {
      return Math.max(1, Math.min(24, parseInt($("heartloop-hours")?.value, 10) || 6));
    }
    const active = document.querySelector("#heartloop-packs .heartloop-pack.is-active");
    return parseInt(active?.getAttribute("data-hours"), 10) || 12;
  }

  function paintHeartLoop() {
    const perEl = $("heartloop-perhour");
    if (perEl) perEl.textContent = String(heartloopPricing.per_hour);
    ["12", "24"].forEach((h) => {
      const priceEl = document.querySelector('[data-pack-price="' + h + '"]');
      const listEl = document.querySelector('[data-pack-list="' + h + '"]');
      const yieldEl = document.querySelector('[data-pack-yield="' + h + '"]');
      const hours = parseInt(h, 10);
      const price = heartloopPriceFor(hours);
      const list = hours * heartloopPricing.per_hour;
      if (priceEl) priceEl.textContent = price + "฿";
      if (listEl) {
        if (list > price) {
          listEl.textContent = list + "฿";
          listEl.hidden = false;
        } else {
          listEl.hidden = true;
        }
      }
      if (yieldEl) {
        if (heartloopFreeSlots != null) {
          yieldEl.innerHTML =
            'คุณ: <span class="heartloop-yield-hl">~' +
            (heartloopFreeSlots * hours).toLocaleString() +
            "</span> หัวใจ";
        } else {
          yieldEl.textContent = "สูงสุด " + (300 * hours).toLocaleString() + " หัวใจ";
        }
      }
    });
    const customRow = $("heartloop-custom-row");
    if (customRow) customRow.hidden = !heartloopCustom;
    const customPrice = $("heartloop-custom-price");
    if (customPrice && heartloopCustom) {
      const h = heartloopSelectedHours();
      let txt = "= " + heartloopPriceFor(h) + "฿";
      if (heartloopFreeSlots != null) txt += " · ~" + (heartloopFreeSlots * h).toLocaleString() + " หัวใจ";
      customPrice.textContent = txt;
    }
    const sub = $("heartloop-btn-sub");
    if (sub) {
      const h = heartloopSelectedHours();
      const price = heartloopPriceFor(h);
      sub.textContent = (heartloopCustom ? h + " ชม." : "แพ็ค " + h + " ชม.") + " · " + price + "฿";
    }
  }

  async function heartloopCheckSlots() {
    const btn = $("heartloop-check");
    const slots = $("heartloop-slots");
    const sub = $("heartloop-slots-sub");
    if (!isDevPlayConnected() && !hasDevPlayCreds()) {
      showDevPlayRequiredModal();
      return;
    }
    if (btn) {
      btn.disabled = true;
      btn.textContent = "⏳ กำลังตรวจ…";
    }
    try {
      await ensureApiReady();
      const res = await api("/api/farm/heartloop/preview", {
        method: "POST",
        body: {
          email: getDevPlayCreds().email,
          password: getDevPlayCreds().password,
          devplay_session_id: devplaySession?.id,
        },
        timeoutMs: 60000,
      });
      heartloopFreeSlots = Number(res.free_slots || 0);
      if (res.pricing) heartloopPricing = res.pricing;
      if (slots) {
        slots.hidden = false;
        slots.innerHTML =
          "เพื่อนตอนนี้ " +
          Number(res.friends || 0) +
          "/" +
          Number(res.cap || 300) +
          " → ช่องว่าง <span class='heartloop-yield-hl'>" +
          heartloopFreeSlots +
          "</span> คน";
      }
      if (sub) {
        sub.hidden = false;
        sub.textContent = res.recommend_clear
          ? "💡 แนะนำติ๊ก “ลบเพื่อนก่อนเริ่ม” เพื่อเปิดช่องให้เต็ม 300 (ได้หัวใจสูงสุด)"
          : "✅ ไอดีนี้ช่องว่างเต็มแล้ว พร้อมเก็บหัวใจสูงสุด";
      }
      paintHeartLoop();
    } catch (e) {
      const msg =
        e?.data?.detail?.message || e?.data?.detail?.code || e?.message || "ตรวจไม่สำเร็จ";
      if (slots) {
        slots.hidden = false;
        slots.textContent = "ตรวจไม่สำเร็จ: " + msg;
      }
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.textContent = "🔍 ตรวจช่องว่างเพื่อนในไอดี + ดูยอดที่จะได้";
      }
    }
  }

  async function heartloopRun() {
    const status = $("heartloop-status");
    if (!isDevPlayConnected() && !hasDevPlayCreds()) {
      showDevPlayRequiredModal();
      return;
    }
    const hours = heartloopSelectedHours();
    const price = heartloopPriceFor(hours);
    const clear = !!$("heartloop-clear")?.checked;
    const estLine =
      heartloopFreeSlots != null
        ? "\nคาดว่าจะได้ ~" + (heartloopFreeSlots * hours).toLocaleString() + " หัวใจ (ช่องว่างตอนนี้ " + heartloopFreeSlots + ")"
        : "";
    const ok = await showJobConfirmModal({
      title: "เริ่ม HeartLoop?",
      body:
        "ระยะเวลา " +
        hours +
        " ชั่วโมง · ราคา " +
        price +
        " Token" +
        (clear ? "\n⚠️ จะลบเพื่อนทั้งหมดในไอดีก่อนเริ่ม (รวมเพื่อนจริง)" : "") +
        estLine +
        "\n\nระบบจะเก็บหัวใจให้ทุกชั่วโมงจนครบ แล้วลบเพื่อนคลังออกให้เอง",
      confirmLabel: "เริ่มเลย",
    });
    if (!ok) return;
    const btn = $("heartloop-btn");
    if (btn) btn.disabled = true;
    if (status) setStatus(status, "กำลังเริ่มงาน…", "muted");
    try {
      await ensureApiReady();
      const res = await api("/api/farm/heartloop/run", {
        method: "POST",
        body: {
          email: getDevPlayCreds().email,
          password: getDevPlayCreds().password,
          devplay_session_id: devplaySession?.id,
          hours: hours,
          clear_friends: clear,
        },
        timeoutMs: 60000,
      });
      if (status)
        setStatus(status, "✅ เริ่มงานแล้ว! ดูความคืบหน้าได้ที่แท็บ Live", "ok");
      if (res?.job_id || res?.ok) {
        setTimeout(() => switchFarmTab("live"), 900);
      }
    } catch (e) {
      const code = e?.data?.detail?.code || e?.data?.detail || e?.message || "";
      let msg = "เริ่มงานไม่สำเร็จ";
      if (/insufficient_tokens/i.test(String(code))) msg = "Token ไม่พอ — เติมเงินก่อนนะ";
      else if (/login_failed/i.test(String(code))) msg = "ล็อกอินไอดีไม่สำเร็จ ตรวจอีเมล/รหัส";
      else if (code) msg = "เริ่มงานไม่สำเร็จ: " + code;
      if (status) setStatus(status, msg, "err");
    } finally {
      if (btn) btn.disabled = false;
    }
  }

  function wireHeartLoop() {
    const packs = $("heartloop-packs");
    if (packs) {
      packs.querySelectorAll(".heartloop-pack").forEach((b) => {
        b.addEventListener("click", () => {
          packs.querySelectorAll(".heartloop-pack").forEach((x) => x.classList.remove("is-active"));
          b.classList.add("is-active");
          heartloopCustom = false;
          const toggle = $("heartloop-custom-toggle");
          if (toggle) toggle.checked = false;
          paintHeartLoop();
        });
      });
    }
    const toggle = $("heartloop-custom-toggle");
    if (toggle) {
      toggle.addEventListener("change", () => {
        heartloopCustom = toggle.checked;
        if (heartloopCustom) {
          packs?.querySelectorAll(".heartloop-pack").forEach((x) => x.classList.remove("is-active"));
        } else {
          const first = packs?.querySelector('.heartloop-pack[data-hours="12"]');
          first?.classList.add("is-active");
        }
        paintHeartLoop();
      });
    }
    const hoursInput = $("heartloop-hours");
    if (hoursInput) hoursInput.addEventListener("input", paintHeartLoop);
    $("heartloop-hours-minus")?.addEventListener("click", () => {
      if (!hoursInput) return;
      hoursInput.value = String(Math.max(1, (parseInt(hoursInput.value, 10) || 6) - 1));
      paintHeartLoop();
    });
    $("heartloop-hours-plus")?.addEventListener("click", () => {
      if (!hoursInput) return;
      hoursInput.value = String(Math.min(24, (parseInt(hoursInput.value, 10) || 6) + 1));
      paintHeartLoop();
    });
    $("heartloop-check")?.addEventListener("click", heartloopCheckSlots);
    $("heartloop-btn")?.addEventListener("click", heartloopRun);
    paintHeartLoop();
  }

  function getDevPlayAccountDisplayName() {
    if (!devplaySession) return "—";
    const nick = String(devplaySession.nickname || "").trim();
    if (nick && nick.toLowerCase() !== "player") return nick;
    const mail = String(devplaySession.email || "").trim();
    if (mail.includes("@")) return mail.split("@")[0] || mail;
    if (mail) return mail;
    if (nick) return nick;
    return "—";
  }

  function devplayVaultStorageKey() {
    const uid = profile?.id;
    if (!uid) return null;
    return "ckr_devplay_vault_v1_" + uid;
  }

  function vaultBytesToB64(bytes) {
    let bin = "";
    const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    for (let i = 0; i < arr.length; i++) bin += String.fromCharCode(arr[i]);
    return btoa(bin);
  }

  function vaultB64ToBytes(str) {
    const bin = atob(String(str || ""));
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  async function deriveDevPlayVaultKey(userId) {
    const enc = new TextEncoder();
    const keyMaterial = await crypto.subtle.importKey(
      "raw",
      enc.encode(String(userId) + "|" + DEVPLAY_VAULT_PEPPER),
      "PBKDF2",
      false,
      ["deriveKey"]
    );
    return crypto.subtle.deriveKey(
      {
        name: "PBKDF2",
        salt: enc.encode("ckr-devplay-vault-salt"),
        iterations: 100000,
        hash: "SHA-256",
      },
      keyMaterial,
      { name: "AES-GCM", length: 256 },
      false,
      ["encrypt", "decrypt"]
    );
  }

  async function encryptDevPlayVault(entries) {
    const uid = profile?.id;
    if (!uid) return null;
    const key = await deriveDevPlayVaultKey(uid);
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const plaintext = new TextEncoder().encode(JSON.stringify(entries));
    const cipher = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, plaintext);
    return JSON.stringify({ v: 1, iv: vaultBytesToB64(iv), data: vaultBytesToB64(cipher) });
  }

  async function decryptDevPlayVault(blob) {
    const uid = profile?.id;
    if (!uid) return [];
    const parsed = JSON.parse(blob);
    if (!parsed || parsed.v !== 1 || !parsed.iv || !parsed.data) return [];
    const key = await deriveDevPlayVaultKey(uid);
    const iv = vaultB64ToBytes(parsed.iv);
    const cipher = vaultB64ToBytes(parsed.data);
    const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, cipher);
    const entries = JSON.parse(new TextDecoder().decode(plain));
    return Array.isArray(entries) ? entries : [];
  }

  async function loadLocalDevPlayVaultEntries() {
    const storageKey = devplayVaultStorageKey();
    if (!storageKey) return [];
    const raw = localStorage.getItem(storageKey);
    if (!raw) return [];
    try {
      const entries = await decryptDevPlayVault(raw);
      return Array.isArray(entries) ? entries : [];
    } catch (_) {
      return [];
    }
  }

  function clearLocalDevPlayVault() {
    const storageKey = devplayVaultStorageKey();
    if (storageKey) localStorage.removeItem(storageKey);
  }

  async function migrateLocalDevPlayVaultToCloud(localEntries) {
    if (!Array.isArray(localEntries) || !localEntries.length) return;
    for (const entry of localEntries) {
      const email = String(entry?.email || "").trim();
      const password = String(entry?.password || "");
      if (!email || !password) continue;
      try {
        await api("/api/devplay/vault", {
          method: "PUT",
          body: {
            email,
            password,
            nickname: entry.nickname || "player",
            cookieName: entry.cookieName || null,
            profileImageKey: entry.profileImageKey || null,
          },
        });
      } catch (_) {
        /* keep local; retry next login */
        return;
      }
    }
    clearLocalDevPlayVault();
  }

  async function persistLocalDevPlayVault(entries) {
    const storageKey = devplayVaultStorageKey();
    if (!storageKey) return;
    try {
      const list = Array.isArray(entries) ? entries.slice(0, DEVPLAY_VAULT_MAX) : [];
      if (!list.length) {
        localStorage.removeItem(storageKey);
        return;
      }
      const blob = await encryptDevPlayVault(list);
      if (blob) localStorage.setItem(storageKey, blob);
    } catch (_) {}
  }

  async function loadDevPlayVault() {
    if (!profile?.id || !accessToken) {
      devplayVaultEntries = [];
      devplayVaultLoading = false;
      paintDevPlayAccountPicker();
      return;
    }
    const first = !devplayVaultEntries.length;
    if (first) {
      devplayVaultLoading = true;
      paintDevPlayAccountPicker();
    }
    try {
      await ensureApiReady();
      const data = await api("/api/devplay/vault");
      const remote = Array.isArray(data.entries) ? data.entries : [];
      if (remote.length) {
        devplayVaultEntries = remote.slice(0, DEVPLAY_VAULT_MAX);
        await persistLocalDevPlayVault(devplayVaultEntries);
      } else {
        const localEntries = await loadLocalDevPlayVaultEntries();
        if (localEntries.length) {
          await migrateLocalDevPlayVaultToCloud(localEntries);
          const again = await api("/api/devplay/vault");
          devplayVaultEntries = Array.isArray(again.entries)
            ? again.entries.slice(0, DEVPLAY_VAULT_MAX)
            : localEntries.slice(0, DEVPLAY_VAULT_MAX);
          await persistLocalDevPlayVault(devplayVaultEntries);
        }
      }
    } catch (_) {
      const localEntries = await loadLocalDevPlayVaultEntries();
      devplayVaultEntries = localEntries.slice(0, DEVPLAY_VAULT_MAX);
    } finally {
      devplayVaultLoading = false;
      paintDevPlayAccountPicker();
    }
  }

  async function upsertDevPlayVaultEntry(creds, meta = {}) {
    const emailRaw = String(creds?.email || "").trim();
    const password = String(creds?.password || "");
    if (!emailRaw || !password) return;
    const emailKey = emailRaw.toLowerCase();
    const next = {
      email: emailRaw,
      password,
      nickname: meta.nickname || "player",
      cookieName: meta.cookieName || null,
      profileImageKey: meta.profileImageKey || null,
      mid: meta.mid ? String(meta.mid).trim().toUpperCase() : null,
      lastUsedAt: Date.now(),
    };
    // Optimistic local update for snappy UI
    devplayVaultEntries = devplayVaultEntries.filter(
      (e) => String(e.email || "").trim().toLowerCase() !== emailKey
    );
    devplayVaultEntries.unshift(next);
    if (devplayVaultEntries.length > DEVPLAY_VAULT_MAX) {
      devplayVaultEntries = devplayVaultEntries.slice(0, DEVPLAY_VAULT_MAX);
    }
    paintDevPlayAccountPicker();
    try {
      await ensureApiReady();
      await api("/api/devplay/vault", {
        method: "PUT",
        body: {
          email: emailRaw,
          password,
          nickname: next.nickname,
          cookieName: next.cookieName,
          profileImageKey: next.profileImageKey,
        },
      });
      const data = await api("/api/devplay/vault");
      if (Array.isArray(data.entries)) {
        devplayVaultEntries = data.entries.slice(0, DEVPLAY_VAULT_MAX);
        paintDevPlayAccountPicker();
      }
    } catch (_) {
      /* keep optimistic list; next load will reconcile */
    }
    await persistLocalDevPlayVault(devplayVaultEntries);
  }

  async function removeDevPlayVaultEntry(email) {
    const norm = String(email || "").trim().toLowerCase();
    devplayVaultEntries = devplayVaultEntries.filter(
      (e) => String(e.email || "").trim().toLowerCase() !== norm
    );
    paintDevPlayAccountPicker();
    try {
      await ensureApiReady();
      await api("/api/devplay/vault?email=" + encodeURIComponent(email || ""), {
        method: "DELETE",
      });
    } catch (_) {
      /* list already updated locally */
    }
    await persistLocalDevPlayVault(devplayVaultEntries);
  }

  function maskDevPlayEmail(email) {
    const s = String(email || "").trim();
    const at = s.indexOf("@");
    if (at <= 1) return s;
    const name = s.slice(0, at);
    const domain = s.slice(at);
    const mask = name.length > 2 ? "***" : "*";
    return name.slice(0, 1) + mask + domain;
  }

  function resolveVaultAvatarUrl(entry) {
    return resolveDevPlayAvatarUrl({
      cookieName: entry?.cookieName,
      profileImageKey: entry?.profileImageKey,
    });
  }

  function paintDevPlayAccountPicker() {
    const picker = $("devplay-account-picker");
    const list = $("devplay-account-picker-list");
    const newWrap = $("devplay-new-account-wrap");
    if (!picker || !list) return;

    const loading = !!devplayVaultLoading && !devplayVaultEntries.length;
    const show = !isDevPlayConnected() && (loading || devplayVaultEntries.length > 0);
    picker.classList.toggle("hidden", !show);
    picker.hidden = !show;
    if (newWrap) {
      newWrap.classList.toggle("hidden", !show);
      newWrap.hidden = !show;
    }

    list.innerHTML = "";
    if (!show) return;
    if (loading) {
      paintDevPlayVaultSkeleton(3);
      return;
    }

    devplayVaultEntries.forEach((entry) => {
      const row = document.createElement("button");
      row.type = "button";
      row.className = "devplay-vault-card";
      row.dataset.vaultEmail = entry.email;
      row.disabled = !!(devplayConnecting || farmRunning);
      row.setAttribute("role", "listitem");

      const img = document.createElement("img");
      img.className = "devplay-vault-card-avatar";
      img.alt = "";
      img.width = 48;
      img.height = 48;
      img.loading = "lazy";
      img.decoding = "async";
      bindDevPlayAvatarImg(img, resolveVaultAvatarUrl(entry), {
        cookieFallback: devPlayCookiePortraitUrl(entry?.cookieName),
      });

      const body = document.createElement("div");
      body.className = "devplay-vault-card-body";
      const name = document.createElement("span");
      name.className = "devplay-vault-card-name";
      name.textContent = entry.nickname || "player";
      const mail = document.createElement("span");
      mail.className = "devplay-vault-card-email muted";
      mail.textContent = maskDevPlayEmail(entry.email);
      body.append(name, mail);

      const removeBtn = document.createElement("button");
      removeBtn.type = "button";
      removeBtn.className = "devplay-vault-card-remove";
      removeBtn.dataset.vaultRemove = entry.email;
      removeBtn.setAttribute("aria-label", "ลบบัญชี " + entry.email);
      removeBtn.textContent = "×";

      row.append(img, body, removeBtn);
      list.appendChild(row);
    });
    paintInviteDevPlayHelpers();
    paintProfileDevPlay();
  }

  function isDevPlayConnected() {
    return !!devplaySession?.id && devplayConnectionState !== "expired";
  }

  function paintDevPlayConnectStatus(text, kind) {
    const el = $("devplay-connect-status");
    if (!el) return;
    el.textContent = text || "";
    el.classList.remove("is-ok", "is-err", "muted", "hidden");
    if (text) {
      el.removeAttribute("hidden");
      el.hidden = false;
    } else {
      el.setAttribute("hidden", "");
      el.hidden = true;
      el.classList.add("hidden");
    }
    if (kind === "ok") el.classList.add("is-ok");
    else if (kind === "err") el.classList.add("is-err");
    else el.classList.add("muted");
  }

  function clampTicketCount(raw) {
    const max = Math.max(1, ticketMax || 1);
    const n = Math.floor(Number(String(raw).replace(/[^\d]/g, "")));
    if (!Number.isFinite(n) || n < 1) return 1;
    return Math.min(n, max);
  }

  function paintTicketStepper() {
    const input = $("ticket-count");
    const hint = $("ticket-max-hint");
    const minus = $("ticket-minus");
    const plus = $("ticket-plus");
    const max = Math.max(1, ticketMax || 1);
    ticketCount = clampTicketCount(ticketCount);
    const editing = input && document.activeElement === input;
    if (input && !editing) input.value = String(ticketCount);
    if (hint) {
      if (!isDevPlayConnected()) {
        hint.textContent = "เชื่อม DevPlay เพื่อเริ่มเลือกจำนวนตั๋ว";
      } else if (devplaySession?.ticketsLoading) {
        hint.textContent = "กำลังนับตั๋วในพื้นหลัง… เลือกรันไปก่อนได้";
      } else if (devplaySession?.tickets == null) {
        hint.textContent =
          "ยังไม่ทราบยอดตั๋ว — เลือกจำนวนได้ (สูงสุด " +
          formatNumTh(max) +
          ") · ต้องมีวันเช่าคงเหลือ";
      } else if (Number(devplaySession.tickets) <= 0) {
        hint.textContent = "ไม่มีตั๋ว Party Run ในไอดีนี้";
      } else {
        hint.textContent =
          "เหลือ " +
          formatNumTh(devplaySession.tickets) +
          " ใบ · พิมพ์ได้ 1–" +
          formatNumTh(max);
      }
    }
    const canStep = isDevPlayConnected() && !devplayConnecting;
    if (input) input.disabled = !canStep;
    if (minus) minus.disabled = !canStep || ticketCount <= 1;
    if (plus) plus.disabled = !canStep || ticketCount >= max;
  }

  function commitTicketCountFromInput() {
    const input = $("ticket-count");
    if (!input) return;
    ticketCount = clampTicketCount(input.value);
    paintTicketStepper();
    updateFarmAvailability();
  }

  function clearDevPlayCreds() {
    const mail = $("dp-acct-mail");
    const secret = $("dp-acct-secret");
    if (mail) {
      mail.value = "";
      mail.setAttribute("readonly", "readonly");
    }
    if (secret) {
      secret.value = "";
      secret.setAttribute("readonly", "readonly");
    }
  }

  function logoutDevPlay() {
    if (devplayConnecting || farmStarting) {
      showErrorModal("รอสักครู่แล้วค่อยสลับไอดี", "กำลังทำงานอยู่");
      return;
    }
    devplaySession = null;
    devplayConnectionState = "disconnected";
    ticketMax = 99;
    ticketCount = 1;
    upgradeTreasures = [];
    upgradeSelected.clear();
    upgradePickerDraft.clear();
    upgradePickerFilter = "";
    upgradeEstimate = null;
    upgradeCoin = 0;
    powderPlan = null;
    powderEstimate = null;
    clearDevPlayCreds();
    switchFarmTab("devplay", { silent: true, replaceRoute: true });
    paintDevPlayConnectStatus("ออกจาก DevPlay แล้ว — เข้าด้วยบัญชีอื่นได้", "muted");
    paintDevPlayHub();
    paintDevPlayAccountPicker();
    paintUpgradeSelectedSummary();
    paintTicketStepper();
    updateFarmAvailability();
    setFarmStatus("ออกจาก DevPlay แล้ว", "muted");
    showToast("ออกจาก DevPlay แล้ว", "logout");
  }

  function resetDevPlaySession() {
    devplayConnectionState = "expired";
    ticketMax = 99;
    ticketCount = 1;
    paintDevPlayConnectStatus("ยังไม่ได้เชื่อมบัญชีเกม", "muted");
    paintDevPlayHub();
    paintDevPlayAccountPicker();
    paintTicketStepper();
  }

  function paintFarmNavLock() {
    const connected = isDevPlayConnected();
    const heartFreeNav = $("farm-tab-heart_free");
    if (heartFreeNav) heartFreeNav.hidden = heartMerged();
    FARM_DOCK_TABS.forEach((t) => {
      const btn = $("farm-tab-" + t);
      if (!btn || btn.hidden) return;
      const featureLocked = isFeatureLocked(t);
      const noEnt =
        hasResolvedWebsiteProfile() &&
        !uiPreview &&
        !isAdminUser(profile) &&
        !isRentalPermanent(profile) &&
        !hasFeatureAccess(t) &&
        !isTokenEligibleFarmTab(t) &&
        !isFreeTierFarmTab(t);
      // DevPlay-not-connected lock vs admin feature lock are separate classes.
      btn.classList.toggle("is-locked", (!connected || noEnt) && !featureLocked);
      btn.classList.toggle("is-feature-locked", featureLocked);
      btn.setAttribute(
        "aria-disabled",
        connected && !featureLocked && !noEnt ? "false" : "true"
      );
      if (noEnt && !featureLocked) {
        btn.title = "ยังไม่ได้ปลดล็อกฟังก์ชันนี้";
      } else if (!connected && !featureLocked) {
        btn.title = "";
      }
    });
    // Invite is opened from the Menu section only (not a farm-feature tab).
    paintFeatureLocks();
  }

  function paintDevPlayHub() {
    window.CKRReport?.render?.();
    const connected = isDevPlayConnected();
    const onDevPlayTab = farmTab === "devplay";
    const loginCard = $("devplay-login-card");
    const hero = $("player-hero");
    const headChip = $("player-head-chip");
    const dock = $("feature-dock");
    const hub = document.querySelector("#farm-panel-devplay .devplay-hub");
    const run = $("run");
    loginCard?.classList.toggle("hidden", connected);
    hub?.classList.toggle("is-connected", connected);
    if (hero) {
      const showHero = connected && onDevPlayTab;
      hero.classList.toggle("hidden", !showHero);
      hero.hidden = !showHero;
      hero.classList.remove("player-hero--compact");
    }
    if (headChip) {
      const showChip = connected && !onDevPlayTab;
      headChip.classList.toggle("hidden", !showChip);
      headChip.hidden = !showChip;
    }
    if (dock) {
      const showDock = onDevPlayTab;
      dock.classList.toggle("hidden", !showDock);
      dock.hidden = !showDock;
    }
    if (run) {
      run.classList.toggle("has-player-hero", connected && onDevPlayTab);
      run.classList.toggle("has-player-chip", connected && !onDevPlayTab);
    }
    paintFarmNavLock();
    syncOvenDevPlayLayout();
    paintFeatureDock();
    paintDevPlayAccountPicker();

    if (!devplaySession) return;

    const nick = getDevPlayAccountDisplayName();
    const lvl = devplaySession.level == null ? "—" : "Lv " + devplaySession.level;
    const coin = devplaySession.coin == null ? "—" : formatNumTh(devplaySession.coin);
    const exp = devplaySession.exp == null ? "—" : formatNumTh(devplaySession.exp);
    const powder =
      devplaySession.powder == null ? "—" : formatNumTh(devplaySession.powder);
    const gem = devplaySession.gem == null ? "—" : formatNumTh(devplaySession.gem);
    const life = devplaySession.life == null ? "—" : formatNumTh(devplaySession.life);
    const boxes =
      devplaySession.giftBoxes == null ? "—" : formatNumTh(devplaySession.giftBoxes);
    let ticketsLabel = "—";
    if (devplaySession.ticketsLoading) ticketsLabel = "กำลังนับ…";
    else if (devplaySession.tickets != null)
      ticketsLabel = formatNumTh(devplaySession.tickets);

    if ($("player-hero-name")) $("player-hero-name").textContent = nick;
    if ($("player-head-chip-name")) $("player-head-chip-name").textContent = nick;
    if ($("player-hero-level")) $("player-hero-level").textContent = lvl;
    if ($("player-stat-coin")) $("player-stat-coin").textContent = coin;
    if ($("player-stat-xp")) $("player-stat-xp").textContent = exp;
    if ($("player-stat-powder")) $("player-stat-powder").textContent = powder;
    if ($("player-stat-gem")) $("player-stat-gem").textContent = gem;
    if ($("player-stat-life")) $("player-stat-life").textContent = life;
    if ($("player-stat-boxes")) $("player-stat-boxes").textContent = boxes;
    if ($("player-stat-tickets")) $("player-stat-tickets").textContent = ticketsLabel;
    if ($("player-stat-key"))
      $("player-stat-key").textContent =
        devplaySession.key == null ? "—" : formatNumTh(devplaySession.key);

    // MID with copy
    const midVal = $("player-hero-mid");
    const midBtn = $("player-hero-mid-btn");
    const mid = String(devplaySession.mid || "").trim();
    if (midVal) midVal.textContent = mid || "—";
    if (midBtn) {
      midBtn.hidden = !mid;
      midBtn.onclick = (e) => {
        e.preventDefault();
        if (mid) {
          copyTextToClipboard(mid, "คัดลอก MID: " + mid + " เรียบร้อย");
        }
      };
    }

    // Email DevPlay
    const emailVal = $("player-hero-email-val");
    const emailBadge = $("player-hero-email");
    const email = devplaySession.email || getDevPlayCreds()?.email || "";
    if (emailVal) emailVal.textContent = email || "—";
    if (emailBadge) emailBadge.hidden = !email;

    // EXP Bar
    updatePlayerExpBar(devplaySession.level, devplaySession.exp);

    // Inventory overview
    paintPlayerInventoryStats();

    paintPlayerHeroAvatar();

    if (farmTab === "devplay") {
      if (connected) {
        setWorkspaceTitle("ศูนย์ฟีเจอร์", "เลือกโหมดที่ต้องการใช้งาน");
      } else {
        const meta = FARM_TAB_META.devplay;
        if (meta) setWorkspaceTitle(meta.title, meta.hint);
      }
    }

    const refreshBtn = $("devplay-refresh-btn");
    const proxyBtn = $("devplay-proxy-btn");
    if (refreshBtn) {
      refreshBtn.hidden = !connected;
      refreshBtn.classList.toggle("hidden", !connected);
      refreshBtn.disabled = !!(devplayRefreshing || devplayConnecting || farmRunning);
    }
    if (proxyBtn) {
      proxyBtn.hidden = true;
      proxyBtn.classList.add("hidden");
    }
    paintDevPlayConnectStatus("", "ok");
  }

  function updatePlayerExpBar(level, exp) {
    const expCard = $("player-hero-exp-card");
    if (!expCard) return;
    const lv = Number(level) || 1;
    const totalExp = Number(exp) || 0;
    const xpLib = window.CKR_LEVEL_XP;
    if (!xpLib) return;

    const maxLv = xpLib.MAX_LEVEL || 110;
    const bonus = xpLib.getLevelBonus ? xpLib.getLevelBonus(lv) : Math.max(0, lv - 1);
    const bonusEl = $("player-hero-exp-bonus");
    if (bonusEl) bonusEl.textContent = "โบนัสคะแนน +" + bonus + "%";

    if (lv >= maxLv) {
      if ($("player-hero-exp-pct")) $("player-hero-exp-pct").textContent = "MAX (100%)";
      if ($("player-hero-exp-fill")) $("player-hero-exp-fill").style.width = "100%";
      if ($("player-hero-exp-detail"))
        $("player-hero-exp-detail").textContent = "เลเวลสูงสุดแล้ว (" + maxLv + ")";
      return;
    }

    const barNeed = xpLib.xpBarForLevel ? xpLib.xpBarForLevel(lv) : 0;
    const inBar = xpLib.inLevelXp ? xpLib.inLevelXp(lv, totalExp) : 0;
    let pct = 0;
    let toNext = 0;
    if (barNeed > 0) {
      pct = Math.min(100, Math.max(0, (inBar / barNeed) * 100));
      toNext = Math.max(0, barNeed - inBar);
    }

    if ($("player-hero-exp-pct")) $("player-hero-exp-pct").textContent = pct.toFixed(1) + "%";
    if ($("player-hero-exp-fill")) $("player-hero-exp-fill").style.width = pct.toFixed(1) + "%";
    if ($("player-hero-exp-detail")) {
      $("player-hero-exp-detail").textContent =
        "ขาดอีก " + formatNumTh(toNext) + " EXP สู่ Lv." + (lv + 1);
    }
  }

  function lvfpCurrentLevel(type) {
    const want = String(type || "").toUpperCase();
    const row = (lvfpScan?.rows || []).find((r) => String(r.type || "").toUpperCase() === want);
    if (!row) return null;
    const n = Number(row.current);
    return Number.isFinite(n) ? n : null;
  }

  function paintPlayerInventoryStats() {
    // Power Levels — API types are A1/A2/A3 (HP/Jelly/Bonus)
    const pEl = $("player-stat-power");
    if (pEl) {
      const hp = lvfpCurrentLevel("A1");
      const jel = lvfpCurrentLevel("A2");
      const bon = lvfpCurrentLevel("A3");
      if (hp != null || jel != null || bon != null) {
        const fmt = (n) => (n == null ? "—" : String(n));
        pEl.textContent = fmt(hp) + "/" + fmt(jel) + "/" + fmt(bon);
      } else if (playerInvLoading) {
        pEl.textContent = "กำลังโหลด…";
      } else {
        pEl.textContent = "—";
      }
    }

    // Cookie Count
    const cEl = $("player-stat-cookies");
    if (cEl) {
      if (cookieScan && Array.isArray(cookieScan.cookies)) {
        const owned = cookieScan.cookies.filter((c) => c.owned).length;
        const total = cookieScan.cookies.length;
        cEl.textContent =
          total > 0
            ? `${formatNumTh(owned)} / ${formatNumTh(total)} ตัว`
            : `${formatNumTh(owned)} ตัว`;
      } else if (playerInvLoading) {
        cEl.textContent = "กำลังนับ…";
      } else {
        cEl.textContent = "—";
      }
    }

    // Pet Count
    const petEl = $("player-stat-pets");
    if (petEl) {
      if (petLevelScan && Array.isArray(petLevelScan.pets)) {
        const owned = petLevelScan.pets.filter((p) => p.owned).length;
        const total = petLevelScan.pets.length;
        petEl.textContent =
          total > 0
            ? `${formatNumTh(owned)} / ${formatNumTh(total)} ตัว`
            : `${formatNumTh(owned)} ตัว`;
      } else if (playerInvLoading) {
        petEl.textContent = "กำลังนับ…";
      } else {
        petEl.textContent = "—";
      }
    }

    // Treasures Count
    const tEl = $("player-stat-treasures");
    if (tEl) {
      if (Array.isArray(upgradeTreasures) && upgradeTreasures.length > 0) {
        tEl.textContent = `${formatNumTh(upgradeTreasures.length)} ชิ้น`;
      } else if (playerInvLoading) {
        tEl.textContent = "กำลังนับ…";
      } else {
        tEl.textContent = "—";
      }
    }
  }

  let playerInvLoading = false;
  async function refreshPlayerInventoryStats(force = false) {
    if (!isDevPlayConnected() || !devplaySession?.id) {
      paintPlayerInventoryStats();
      return;
    }
    if (playerInvLoading && !force) return;
    playerInvLoading = true;
    paintPlayerInventoryStats();

    const sid = devplaySession.id;
    const tasks = [];

    if (!lvfpScan || force) {
      tasks.push(
        api("/api/farm/lv-free-power/scan", {
          method: "POST",
          body: { devplay_session_id: sid, targets: lvfpTargets },
        })
          .then((res) => {
            if (res && res.rows) lvfpScan = res;
          })
          .catch(() => {})
      );
    }
    if (!cookieScan || force) {
      tasks.push(
        api("/api/farm/cookie-unlock/scan", {
          method: "POST",
          body: { devplay_session_id: sid, target_level: cookieTargetLevel },
        })
          .then((res) => {
            if (res && res.cookies) cookieScan = res;
          })
          .catch(() => {})
      );
    }
    if (!petLevelScan || force) {
      tasks.push(
        api("/api/farm/pet-unlock/scan", {
          method: "POST",
          body: { devplay_session_id: sid, target_level: petLevelTarget },
        })
          .then((res) => {
            if (res && res.pets) petLevelScan = res;
          })
          .catch(() => {})
      );
    }
    if (!upgradeTreasures.length || force) {
      tasks.push(
        api("/api/farm/upgrade/treasures?devplay_session_id=" + encodeURIComponent(sid))
          .then((res) => {
            if (res && Array.isArray(res.treasures)) upgradeTreasures = res.treasures;
          })
          .catch(() => {})
      );
    }

    if (tasks.length) {
      await Promise.allSettled(tasks);
    }
    playerInvLoading = false;
    paintPlayerInventoryStats();
  }

