  function clampPct(n) {
    const v = Number(n);
    return Number.isFinite(v) ? Math.max(0, Math.min(100, v)) : null;
  }

  function formatGbAmount(gb) {
    const n = Number(gb);
    if (!Number.isFinite(n) || n < 0) return null;
    if (Math.abs(n - Math.round(n)) < 0.005) return String(Math.round(n));
    return n.toFixed(2).replace(/\.?0+$/, "");
  }

  function formatProxyTraffic(row) {
    if (row?.traffic_label) return String(row.traffic_label);
    const planGb = Number(row?.plan_gb);
    const remainingGb = Number(
      row?.remaining_gb ??
        (Number.isFinite(Number(row?.remaining_mb)) ? Number(row.remaining_mb) / 1000 : NaN)
    );
    if (Number.isFinite(planGb) && planGb > 0 && Number.isFinite(remainingGb)) {
      const remMb = Number(row?.traffic_balance_mb ?? row?.remaining_mb);
      if (Number.isFinite(remMb) && remMb < 1000) {
        return formatProxyTrafficMb(remMb) + " / " + formatGbAmount(planGb) + " GB";
      }
      return formatGbAmount(remainingGb) + " / " + formatGbAmount(planGb) + " GB";
    }
    if (Number.isFinite(planGb) && planGb > 0 && !Number.isFinite(remainingGb)) {
      return formatGbAmount(planGb) + " GB";
    }
    const mb = Number(row?.traffic_balance_mb ?? row?.remaining_mb);
    if (!Number.isFinite(mb)) return "—";
    return formatProxyTrafficMb(mb);
  }

  function formatProxyTrafficMb(mb) {
    if (mb >= 1000) return formatGbAmount(mb / 1000) + " GB";
    if (mb >= 1) return (Math.round(mb * 10) / 10) + " MB";
    return Math.round(mb * 1000) + " KB";
  }

  function paintProxyPool(data) {
    proxyPoolStatus = data || proxyPoolStatus;
    const card = $("proxy-pool-card");
    const trafficEl = $("proxy-pool-traffic");
    const statusEl = $("proxy-pool-status");
    const detail = $("proxy-pool-detail");
    if (!card) return;
    const row = proxyPoolStatus || lastHealth?.proxy_pool;
    if (!row) {
      card.hidden = true;
      return;
    }
    card.hidden = false;
    const ready = !!(row.shop_proxy_configured ?? lastHealth?.farm_proxy_configured);
    const mb = Number(row.traffic_balance_mb ?? row.remaining_mb);
    const planGb = Number(row.plan_gb);
    const hasTraffic = Number.isFinite(mb);
    const usageAvailable = row.usage_available === true && hasTraffic;
    const depleted = usageAvailable && mb <= 0;
    const active = ready && !depleted;
    const traffic = formatProxyTraffic(row);
    if (trafficEl) trafficEl.textContent = traffic;
    if (statusEl) {
      statusEl.textContent = !ready ? "Offline" : depleted ? "หมด" : "Active";
      statusEl.classList.toggle("is-on", active);
      statusEl.classList.toggle("is-off", !active);
    }
    const bar = $("proxy-pool-bar");
    const fill = $("proxy-pool-bar-fill");
    const pct = clampPct(row.remaining_pct);
    if (bar && fill) {
      if (usageAvailable && pct != null) {
        bar.hidden = false;
        fill.style.width = pct + "%";
      } else {
        bar.hidden = true;
        fill.style.width = "0%";
      }
    }
    if (detail) {
      const poweredName = String(row.powered_by || "nettify.xyz");
      if (!ready) {
        detail.textContent = "Proxy ร้านยังไม่พร้อม";
      } else if (Number.isFinite(planGb) && planGb > 0) {
        let text = "ซื้อมา " + formatGbAmount(planGb) + " GB · Powered by " + poweredName;
        if (row.expiration_time) text += " · หมดอายุ " + row.expiration_time;
        detail.textContent = text;
      } else if (row.expiration_time) {
        detail.textContent = "หมดอายุ " + row.expiration_time;
      } else if (row.detail) {
        detail.textContent = String(row.detail).replace(/\s*[·-]\s*เหลือ\s+\d+%/g, "").trim();
      } else {
        detail.textContent = "Proxy ร้านพร้อมใช้งาน · Powered by " + poweredName;
      }
    }
    const powered = $("proxy-pool-powered");
    if (powered) {
      powered.hidden = false;
      powered.href = String(row.powered_by_url || "https://nettify.xyz");
      powered.textContent = "Powered by: " + String(row.powered_by || "nettify.xyz");
    }
    card.classList.toggle("is-ready", ready);
    card.classList.toggle("is-low", usageAvailable && mb > 0 && mb < 500);
    card.classList.toggle("is-throttled", !!row.throttled);
  }

