  function placeAccountChrome() {
    const card = $("topbar-menu-user");
    const sideSection = document.querySelector(".farm-sidebar-section--account");
    if (!card || !sideSection) return;
    if (card.parentElement !== sideSection) sideSection.prepend(card);
    let after = card;
    orderKeysForGroup("account").forEach((key) => {
      const el = $(FARM_NAV_BUTTON_IDS[key]);
      if (!el) return;
      if (el.parentElement !== sideSection || after.nextElementSibling !== el) {
        after.insertAdjacentElement("afterend", el);
      }
      after = el;
    });
  }

  // Compact user + gift-box icons next to the login button. They mirror (and click)
  // the original sidebar buttons, which stay in the DOM but are hidden by CSS.
  function syncTopbarAccountIcons() {
    const srcUser = $("topbar-menu-user");
    const srcMail = $("sidebar-mailbox-btn");
    const userBtn = $("topbar-user-btn");
    const mailBtn = $("topbar-mailbox-btn");
    if (!userBtn || !mailBtn) return;
    const show = (btn, src) => {
      const on = !!src && !src.classList.contains("hidden") && !src.hidden;
      btn.hidden = !on;
      btn.classList.toggle("hidden", !on);
    };
    show(userBtn, srcUser);
    show(mailBtn, srcMail);
    const who = $("menu-who-user");
    if (who && who.textContent && who.textContent !== "—") userBtn.title = who.textContent + " · โปรไฟล์ / จัดการบัญชี";
    const b = $("sidebar-mailbox-badge");
    const tb = $("topbar-mailbox-badge");
    if (b && tb) {
      const on = !b.classList.contains("hidden") && !b.hidden && String(b.textContent || "0").trim() !== "0";
      tb.textContent = b.textContent;
      tb.classList.toggle("hidden", !on);
    }
  }
  (function bindTopbarAccountIcons() {
    const userBtn = $("topbar-user-btn");
    const mailBtn = $("topbar-mailbox-btn");
    if (!userBtn || !mailBtn) return;
    userBtn.addEventListener("click", () => $("topbar-menu-user")?.click());
    mailBtn.addEventListener("click", () => $("sidebar-mailbox-btn")?.click());
    const obs = new MutationObserver(() => syncTopbarAccountIcons());
    ["topbar-menu-user", "sidebar-mailbox-btn", "sidebar-mailbox-badge", "menu-user-mono", "menu-user-avatar", "menu-who-user"].forEach((id) => {
      const el = $(id);
      if (el) obs.observe(el, { attributes: true, childList: true, characterData: true, subtree: true });
    });
    syncTopbarAccountIcons();
  })();

