  let sidebarCloseTimer = 0;
  const SIDEBAR_CLOSE_MS = 200;

  function setFarmSidebarOpen(open) {
    const sidebar = $("farm-sidebar");
    const scrim = $("farm-sidebar-scrim");
    const userView = $("user-view");
    const compact = isCompactNav();
    const wasOpen = document.body.classList.contains("farm-sidebar-open");
    const isOpen = compact ? !!open : true;
    if (sidebarCloseTimer) {
      clearTimeout(sidebarCloseTimer);
      sidebarCloseTimer = 0;
    }
    if (sidebar) {
      sidebar.dataset.open = isOpen ? "true" : "false";
      sidebar.setAttribute("aria-hidden", isOpen ? "false" : "true");
      if (isOpen || !compact) sidebar.removeAttribute("inert");
    }
    if (userView) {
      if (compact) userView.classList.toggle("farm-sidebar-collapsed", !isOpen);
      else userView.classList.remove("farm-sidebar-collapsed");
    }
    document.body.classList.toggle("farm-sidebar-compact", compact);
    document.body.classList.toggle("farm-sidebar-open", isOpen);
    if (scrim) {
      const useScrim = isOpen && compact;
      if (useScrim) {
        scrim.hidden = false;
        scrim.setAttribute("aria-hidden", "false");
        void scrim.offsetWidth;
        scrim.classList.add("is-on");
      } else if (compact) {
        // Drop interactivity immediately so a fading scrim cannot eat taps
        // (including a second hamburger press) while opacity/visibility animate out.
        scrim.classList.remove("is-on");
        scrim.setAttribute("aria-hidden", "true");
      } else {
        scrim.hidden = true;
        scrim.classList.remove("is-on");
        scrim.setAttribute("aria-hidden", "true");
      }
    }
    const toggle = $("topbar-menu-toggle");
    if (toggle) {
      toggle.setAttribute("aria-expanded", isOpen ? "true" : "false");
      toggle.setAttribute("aria-label", isOpen && compact ? "ปิดเมนู" : "เปิดเมนู");
    }
    if (compact && isOpen) {
      lockBodyScroll("menu-open");
      if (!wasOpen) {
        const kick = () => nudgeSidebarScroller();
        requestAnimationFrame(() => requestAnimationFrame(kick));
        sidebar?.addEventListener("transitionend", kick, { once: true });
      }
    } else if (!compact) {
      unlockBodyScroll("menu-open");
    } else {
      const closeMs = window.matchMedia("(prefers-reduced-motion: reduce)").matches
        ? 0
        : SIDEBAR_CLOSE_MS;
      sidebarCloseTimer = window.setTimeout(() => {
        sidebarCloseTimer = 0;
        if (document.body.classList.contains("farm-sidebar-open")) return;
        sidebar?.setAttribute("inert", "");
        if (scrim) {
          scrim.hidden = true;
          scrim.classList.remove("is-on");
          scrim.setAttribute("aria-hidden", "true");
        }
        unlockBodyScroll("menu-open");
      }, closeMs);
    }
  }

  function nudgeSidebarScroller() {
    const scroller = $("farm-sidebar")?.querySelector(".farm-sidebar-scroll");
    if (!scroller) return;
    const y = scroller.scrollTop;
    scroller.style.overflowY = "hidden";
    void scroller.offsetHeight;
    scroller.style.overflowY = "";
    scroller.scrollTop = y;
  }

  function initFarmSidebar() {
    const compactQuery = window.matchMedia("(max-width: 860px)");
    let wasCompact = compactQuery.matches;
    // Hoist drawer + scrim to body so their z-index competes with topbar
    // (not trapped under main.shell z-index:1). Scrim-only hoist left the
    // panel painted *under* the scrim — mobile looked like "hamburger does
    // nothing" (blur only, no menu).
    const sidebar = $("farm-sidebar");
    const scrim = $("farm-sidebar-scrim");
    if (sidebar && sidebar.parentElement !== document.body) document.body.appendChild(sidebar);
    if (scrim && scrim.parentElement !== document.body) document.body.appendChild(scrim);
    // A drawer must never be restored open on Mobile. This also prevents a
    // docked desktop sidebar from appearing without its scrim after resizing.
    setFarmSidebarOpen(!wasCompact);
    placeAccountChrome();
    placeJobInspector();
    // Creative lock: close only hamburger toggle or left scrim. No × / no panel close btn.
    scrim?.addEventListener(
      "click",
      (ev) => {
        if (ev.target !== scrim) return;
        setFarmSidebarOpen(false);
      },
      true
    );
    compactQuery.addEventListener("change", (event) => {
      const compact = event.matches;
      if (compact === wasCompact) return;
      wasCompact = compact;
      setFarmSidebarOpen(!compact);
    });
    window.addEventListener("resize", () => {
      placeAccountChrome();
      placeJobInspector();
    });

    // Swipe-to-close removed — close only hamburger / scrim (creative lock).
  }

