  function applyDevPlayConnect(data, creds) {
    const loginCreds = creds || getDevPlayCreds();
    const ttlMs = (Number(data.expires_in) || 900) * 1000;
    const ticketsKnown =
      data.party_run_tickets != null && Number.isFinite(Number(data.party_run_tickets));
    const ticketsN = ticketsKnown ? Math.max(0, Number(data.party_run_tickets)) : null;
    const nickRaw = String(data.nickname || data.nick || "").trim();
    devplaySession = {
      id: data.devplay_session_id,
      nickname: nickRaw || "player",
      email: loginCreds.email,
      password: loginCreds.password,
      mid: String(data.mid || data.member_id || "").trim().toUpperCase() || null,
      powderReady: data.powder_ready !== false,
      proxyConfigured: !!(data.proxy_configured || data.shop_proxy),
      proxyUrl: "",
      tickets: ticketsN,
      ticketsLoading: !ticketsKnown,
      coin: data.coin,
      exp: data.exp,
      level: data.level,
      powder: data.powder,
      gem: data.gem,
      life: data.life,
      giftBoxes: data.gift_boxes,
      key: data.key,
      pictureStuffSeq: data.picture_stuff_seq,
      profileImageKey: data.profile_image_key || data.profileImageKey || null,
      cookieStuffSeq: data.cookie_stuff_seq,
      cookieName: data.cookie_name || data.cookieName || null,
      expiresAt: Date.now() + ttlMs,
    };
    devplayConnectionState = "connected";
    ticketMax = ticketsKnown ? Math.max(1, ticketsN || 1) : 99;
    ticketCount = ticketsKnown
      ? Math.min(Math.max(1, ticketsN || 1), ticketMax)
      : Math.min(5, ticketMax);
    paintDevPlaySessionLine();
    paintTicketStepper();
    refreshPlayerInventoryStats();
    if (!ticketsKnown && data.devplay_session_id) {
      refreshDevPlayTickets(data.devplay_session_id);
    }
    if (farmTab === "powder") {
      refreshPowderEstimate().catch(() => {});
    }
    if (farmTab === "giftdraw") {
      refreshGiftDrawEstimate().catch(() => {});
      refreshFreeQuota("giftdraw").catch(() => {});
    }
    if (farmTab === "jelly_upgrade") {
      refreshFreeQuota("jelly_upgrade").catch(() => {});
      refreshJellyPlan().catch(() => {});
    }
    if (farmTab === "cookie_unlock") {
      refreshFreeQuota("cookie_unlock").catch(() => {});
      refreshCookieScan().catch(() => {});
    }
    if (farmTab === "pet_unlock") {
      refreshFreeQuota("pet_unlock").catch(() => {});
      if (petJobMode === "level") refreshPetLevelScan().catch(() => {});
      else refreshPetPlan().catch(() => {});
    }
    if (farmTab === "heart_free") {
      refreshFreeQuota("heart_free").catch(() => {});
      paintHeartFreeStepper();
    }
    if (farmTab === "heart" && heartMerged()) {
      paintHeartCondQuota();
      refreshFreeQuota("heart_free").then(paintHeartCondQuota, () => {});
    }
    if (farmTab === "lv_free_power") {
      refreshLvFreePowerScan().catch(() => {});
    }
    if (farmTab === "lv_free_cookie") {
      refreshLvFreeCookieScan().catch(() => {});
    }
    if (farmTab === "quest_claim") {
      refreshQuestScan().catch(() => {});
    }
    window.CKRTools?.onRefresh?.(farmTab);
    if (farmTab === "treasure_evo") {
      refreshEvoScan().catch(() => {});
    }
    if (farmTab === "upgrade") {
      loadUpgradeTreasures(true).catch(() => {});
    }
    if (farmTab === "heart") {
      // Heart's check logs into the game, so it stays an explicit button press
      // rather than firing on every tab switch.
      paintHeartStepper();
    }
    paintHeartProxyHint();
  }

  async function refreshDevPlayTickets(sessionId) {
    const sid = sessionId || devplaySession?.id;
    if (!sid || !devplaySession) return;
    try {
      const data = await api("/api/farm/devplay/tickets", {
        method: "POST",
        body: { devplay_session_id: sid },
      });
      if (!devplaySession || devplaySession.id !== sid) return;
      const ticketsKnown =
        data.party_run_tickets != null && Number.isFinite(Number(data.party_run_tickets));
      if (!ticketsKnown) {
        devplaySession.ticketsLoading = false;
        paintDevPlaySessionLine();
        paintTicketStepper();
        return;
      }
      const ticketsN = Math.max(0, Number(data.party_run_tickets));
      devplaySession.tickets = ticketsN;
      devplaySession.ticketsLoading = false;
      ticketMax = Math.max(1, ticketsN || 1);
      ticketCount = Math.min(Math.max(1, ticketCount), ticketMax);
      paintDevPlaySessionLine();
      paintTicketStepper();
      updateFarmAvailability();
    } catch (_) {
      if (devplaySession && devplaySession.id === sid) {
        devplaySession.ticketsLoading = false;
        paintDevPlaySessionLine();
        paintTicketStepper();
      }
    }
  }

  async function refreshDevPlayAccount() {
    if (!isDevPlayConnected() || devplayRefreshing || devplayConnecting || farmRunning) return;
    const sid = devplaySession?.id;
    if (!sid) {
      showToast("ไม่พบ session — สลับไอดีแล้วเชื่อมใหม่", "err");
      return;
    }
    const refreshBtn = $("devplay-refresh-btn");
    devplayRefreshing = true;
    setFarmBusy(true, "กำลังอัปเดตสถานะ DevPlay…");
    setBtnLoading(refreshBtn, true);
    paintDevPlayConnectStatus("กำลังอัปเดตสถานะ…", "muted");
    updateFarmAvailability();
    try {
      await ensureApiReady();
      const data = await api("/api/farm/devplay/refresh", {
        method: "POST",
        body: { devplay_session_id: sid },
      });
      if (!devplaySession || devplaySession.id !== sid) return;
      if (data.coin != null) devplaySession.coin = data.coin;
      if (data.exp != null) devplaySession.exp = data.exp;
      if (data.level != null) devplaySession.level = data.level;
      if (data.powder != null) devplaySession.powder = data.powder;
      if (data.gem != null) devplaySession.gem = data.gem;
      if (data.life != null) devplaySession.life = data.life;
      if (data.gift_boxes != null) devplaySession.giftBoxes = data.gift_boxes;
      if (data.key != null) devplaySession.key = data.key;
      if (data.mid || data.member_id) {
        devplaySession.mid = String(data.mid || data.member_id).trim().toUpperCase();
      }
      if (data.email) {
        devplaySession.email = String(data.email).trim();
      }
      if (data.profile_image_key || data.profileImageKey) {
        devplaySession.profileImageKey = data.profile_image_key || data.profileImageKey;
      }
      if (data.cookie_name || data.cookieName) {
        devplaySession.cookieName = data.cookie_name || data.cookieName;
      }
      if (data.picture_stuff_seq != null) {
        devplaySession.pictureStuffSeq = data.picture_stuff_seq;
      }
      devplaySession.expiresAt =
        Date.now() + (Number(data.expires_in) || 4 * 60 * 60) * 1000;
      devplayConnectionState = "connected";
      paintDevPlayHub();
      refreshPlayerInventoryStats(true);
      const creds = getDevPlayCreds();
      if (creds.email) {
        upsertDevPlayVaultEntry(creds, {
          nickname: devplaySession.nickname,
          cookieName: devplaySession.cookieName,
          profileImageKey: devplaySession.profileImageKey,
        }).catch(() => {});
      }
      if (!devplaySession.ticketsLoading) {
        devplaySession.ticketsLoading = true;
        paintDevPlayHub();
        refreshDevPlayTickets(sid);
      }
      setFarmStatus("อัปเดตสถานะไอดีแล้ว", "ok");
      showToast("อัปเดตสถานะไอดีแล้ว", "ok");
      paintDevPlayConnectStatus("", "ok");
    } catch (e) {
      const reason =
        thError(e.message) || e.userMessage || ERR_TH.refresh_failed || "รีเฟรชไม่สำเร็จ";
      paintDevPlayConnectStatus(reason, "err");
      showToast(reason, "err");
    } finally {
      devplayRefreshing = false;
      setBtnLoading(refreshBtn, false);
      setFarmBusy(false);
      updateFarmAvailability();
      paintDevPlayHub();
    }
  }

  async function connectDevPlay(opts = {}) {
    if (devplayConnecting) return false;
    if (farmStarting) {
      showErrorModal("กำลังส่งงานเข้าคิวอยู่ รอสักครู่แล้วค่อยสลับไอดี", "รอสักครู่");
      return false;
    }
    const creds = {
      email: String(opts.email ?? $("dp-acct-mail")?.value ?? "").trim(),
      password: String(opts.password ?? $("dp-acct-secret")?.value ?? ""),
    };
    if (!creds.email || !creds.password) {
      showErrorModal("กรอกอีเมลและรหัสผ่าน DevPlay ให้ครบ", "ข้อมูลไม่ครบ");
      return false;
    }
    const connectBtn = $("devplay-connect-btn");
    devplayConnecting = true;
    devplayConnectionState = opts.reconnect ? "reconnecting" : "connecting";
    setFarmBusy(true, "กำลังเชื่อมต่อ DevPlay…");
    setBtnLoading(connectBtn, true);
    paintDevPlayConnectStatus("กำลังเชื่อมต่อ…", "muted");
    paintDevPlayAccountPicker();
    updateFarmAvailability();
    try {
      await ensureApiReady();
      const data = await api("/api/farm/devplay/connect", {
        method: "POST",
        body: {
          email: creds.email,
          password: creds.password,
        },
      });
      applyDevPlayConnect(data, creds);
      await upsertDevPlayVaultEntry(creds, {
        nickname: data.nickname,
        cookieName: data.cookie_name,
        profileImageKey: data.profile_image_key,
        mid: data.mid || data.member_id || null,
      });
      paintInviteDevPlayHelpers();
      paintHeartProxyHint();
      loadProxyPool().catch(() => {});
      const okMsg = "เชื่อม DevPlay แล้ว";
      setFarmStatus(okMsg, "ok");
      if (!opts.silent) showToast(okMsg, "ok");
      return true;
    } catch (e) {
      resetDevPlaySession();
      const reason =
        e.userMessage ||
        thError(e.code || e.message) ||
        ERR_TH.connect_failed;
      const codeHint =
        e.gameCode != null
          ? "\n(รหัสระบบ: " + e.gameCode + ")"
          : e.code && e.code !== e.message
            ? "\n(" + e.code + ")"
            : "";
      paintDevPlayConnectStatus(reason, "err");
      const websiteKick = /invalid_token|missing_bearer_token|session_replaced/i.test(
        String(e.message || "")
      );
      if (!opts.silent && !websiteKick) {
        showErrorModal(
          "เชื่อมไม่สำเร็จ เนื่องจาก\n" + reason + codeHint,
          "เชื่อม DevPlay ไม่สำเร็จ"
        );
      }
      return false;
    } finally {
      devplayConnecting = false;
      setBtnLoading(connectBtn, false);
      setFarmBusy(false);
      updateFarmAvailability();
      paintDevPlayAccountPicker();
    }
  }

  async function recoverDevPlaySession() {
    if (devplayConnecting) return false;
    const creds = {
      email: String(devplaySession?.email || $("dp-acct-mail")?.value || "").trim(),
      password: String(devplaySession?.password || $("dp-acct-secret")?.value || ""),
    };
    if (!creds.email || !creds.password) {
      devplayConnectionState = "expired";
      return false;
    }
    paintDevPlayConnectStatus("กำลังเชื่อม DevPlay ใหม่อัตโนมัติ…", "muted");
    const ok = await connectDevPlay({ ...creds, reconnect: true, silent: true });
    if (ok) {
      showToast("เชื่อม DevPlay ใหม่แล้ว — กดรันซ้ำได้ทันที", "ok");
    }
    return ok;
  }

  function isAfterplaySessionGap(err) {
    const raw = String(err?.userMessage || err?.message || err?.code || "");
    if (/invalid_token|missing_bearer_token|session_replaced/i.test(raw)) return false;
    return (
      Number(err?.status) === 401 ||
      /powder_session_missing|devplay_session_expired/i.test(raw)
    );
  }

  async function recoverAfterplaySessionGap(err, statusNode) {
    if (!isAfterplaySessionGap(err)) return false;
    if (statusNode) setStatus(statusNode, "กำลังเชื่อม DevPlay ใหม่อัตโนมัติ…", "muted");
    return recoverDevPlaySession();
  }

  function syncOvenDevPlayLayout() {
    const run = $("run");
    if (!run) return;
    const compactLogin = farmTab === "devplay" && !isDevPlayConnected();
    run.classList.toggle("oven-panel--devplay-login", compactLogin);
  }

  function openInfoPage(tab, opts = {}) {
    if (tab !== "guide" && tab !== "pricing") return;
    switchFarmTab(tab, opts);
    if (window.matchMedia("(max-width: 860px)").matches) setFarmSidebarOpen(false);
    closeNavDrawer();
  }

  function infoEl(tag, cls, text) {
    const el = document.createElement(tag);
    if (cls) el.className = cls;
    if (text != null) el.textContent = text;
    return el;
  }

  function infoIcon(src, size) {
    const img = document.createElement("img");
    img.loading = "lazy";
    img.alt = "";
    img.width = size || 28;
    img.height = size || 28;
    img.decoding = "async";
    const raw = String(src || "");
    img.src = /^https?:\/\//i.test(raw) ? raw : featureIconSrc(raw);
    return img;
  }

  function setInfoAccOpen(acc, open) {
    if (!acc) return;
    acc.classList.toggle("is-open", !!open);
    const btn = acc.querySelector(".info-acc-toggle");
    if (btn) btn.setAttribute("aria-expanded", open ? "true" : "false");
  }

  function renderGuidePage() {
    const root = $("guide-page");
    const data = window.CKR_GUIDE;
    if (!root || !data || root.dataset.built === "1") return;
    root.dataset.built = "1";
    root.textContent = "";

    const head = infoEl("div", "info-page-head");
    head.appendChild(infoIcon("Angel_cookie_sm.png", 56));
    const headCopy = infoEl("div", "info-page-head-copy");
    headCopy.appendChild(infoEl("h2", "info-page-title", "Guide"));
    headCopy.appendChild(
      infoEl("p", "info-page-lead", "รหัสที่โผล่ใน Live Log แปลเป็นภาษาง่าย ๆ พร้อมคำเตือนและเวลาพัก")
    );
    head.appendChild(headCopy);
    root.appendChild(head);
    root.appendChild(infoEl("p", "info-page-intro", data.intro || ""));

    const tools = infoEl("div", "info-tools");
    const search = document.createElement("input");
    search.type = "search";
    search.className = "info-search";
    search.placeholder = "ค้นรหัส เช่น 210, 500, 20000";
    search.setAttribute("aria-label", "ค้นรหัสใน Log");
    tools.appendChild(search);
    const expand = infoEl("button", "info-tool-btn", "ขยายทั้งหมด");
    expand.type = "button";
    const collapse = infoEl("button", "info-tool-btn", "ย่อทั้งหมด");
    collapse.type = "button";
    tools.appendChild(expand);
    tools.appendChild(collapse);
    root.appendChild(tools);

    const list = infoEl("div", "info-acc-list");
    (data.groups || []).forEach((group, index) => {
      const acc = infoEl("section", "info-acc" + (index === 0 ? " is-open" : ""));
      const toggle = document.createElement("button");
      toggle.type = "button";
      toggle.className = "info-acc-toggle";
      toggle.setAttribute("aria-expanded", index === 0 ? "true" : "false");
      toggle.appendChild(infoIcon(group.icon, 32));
      const label = infoEl("span", "info-acc-label");
      label.appendChild(infoEl("strong", null, group.title || ""));
      if (group.lead) label.appendChild(infoEl("span", "info-acc-lead", group.lead));
      toggle.appendChild(label);
      toggle.appendChild(infoEl("span", "info-acc-chevron", ""));
      acc.appendChild(toggle);

      const panel = infoEl("div", "info-acc-panel");
      const inner = infoEl("div", "info-acc-panel-inner");
      const grid = infoEl("div", "guide-code-grid");
      (group.codes || []).forEach((item) => {
        const card = infoEl("article", "guide-code is-" + (item.tone || "info"));
        card.dataset.search = [item.code, item.title, item.body, item.warn, item.rest]
          .filter(Boolean)
          .join(" ");
        const top = infoEl("div", "guide-code-top");
        top.appendChild(infoEl("span", "guide-code-num", item.code || ""));
        const tone =
          item.tone === "ok" ? "สำเร็จ" : item.tone === "warn" ? "ระวัง" : item.tone === "bad" ? "ไม่ผ่าน" : "รู้ไว้";
        top.appendChild(infoEl("span", "guide-code-tone", tone));
        card.appendChild(top);
        card.appendChild(infoEl("h3", "guide-code-title", item.title || ""));
        card.appendChild(infoEl("p", "guide-code-body", item.body || ""));
        if (item.rest) card.appendChild(infoEl("p", "guide-code-rest", "เวลาพัก: " + item.rest));
        if (item.warn) card.appendChild(infoEl("p", "guide-code-warn", "คำเตือน: " + item.warn));
        grid.appendChild(card);
      });
      inner.appendChild(grid);
      panel.appendChild(inner);
      acc.appendChild(panel);
      toggle.addEventListener("click", () => setInfoAccOpen(acc, !acc.classList.contains("is-open")));
      list.appendChild(acc);
    });
    root.appendChild(list);

    const applySearch = () => {
      const query = String(search.value || "").trim().toLowerCase();
      list.querySelectorAll(".info-acc").forEach((acc) => {
        let hits = 0;
        acc.querySelectorAll(".guide-code").forEach((card) => {
          const show = !query || String(card.dataset.search || "").toLowerCase().includes(query);
          card.hidden = !show;
          if (show) hits += 1;
        });
        acc.hidden = !!query && hits === 0;
        if (query && hits) setInfoAccOpen(acc, true);
      });
    };
    search.addEventListener("input", applySearch);
    expand.addEventListener("click", () => {
      list.querySelectorAll(".info-acc").forEach((acc) => {
        if (!acc.hidden) setInfoAccOpen(acc, true);
      });
    });
    collapse.addEventListener("click", () => {
      list.querySelectorAll(".info-acc").forEach((acc) => setInfoAccOpen(acc, false));
    });
  }

