  async function refreshQuestScan() {
    paintQuestEpGrid();
    paintQuestSheet();
    if (!isDevPlayConnected() || !devplaySession?.id) {
      questScan = null;
      questSelected = new Set();
      paintQuestUi();
      return;
    }
    const refreshBtn = $("quest-refresh-btn");
    questScanning = true;
    if (refreshBtn) refreshBtn.disabled = true;
    paintQuestCostLine();
    try {
      const data = await api("/api/farm/quest-claim/scan", {
        method: "POST",
        body: { devplay_session_id: devplaySession.id, episode_seq: -1 },
      });
      questScan = data;
      pruneQuestSelected();
    } catch (e) {
      const msg = thError(e.message);
      if ($("quest-cost-line")) {
        $("quest-cost-line").textContent = msg || "ดึงเควสจากไอดีไม่สำเร็จ";
      }
    } finally {
      questScanning = false;
      if (refreshBtn) refreshBtn.disabled = false;
    }
    paintQuestUi();
  }

  function selectQuestClaimable() {
    questClaimableRows(questOpenEp).forEach((q) => questSelected.add(String(q.seq)));
    paintQuestUi();
  }

  function clearQuestSelected() {
    questSelected = new Set();
    paintQuestUi();
  }

  function toggleQuestSeq(seq) {
    const key = String(seq || "");
    if (!key) return;
    const claimable = questClaimableRows(null).some((q) => String(q.seq) === key);
    if (!claimable) return;
    if (questSelected.has(key)) questSelected.delete(key);
    else questSelected.add(key);
    paintQuestUi();
  }

  async function runQuestClaim() {
    if (!requireFeatureAccess("quest_claim")) return;
    if (!isDevPlayConnected()) {
      showErrorModal(ERR_TH.devplay_session_expired, "เชื่อม DevPlay ก่อน");
      return;
    }
    const seqs = [...questSelected].map((s) => Number(s)).filter((n) => n > 0);
    if (!seqs.length) {
      showErrorModal(ERR_TH.nothing_quest_selected, "ยังไม่ได้เลือก");
      return;
    }
    if (
      queueIfBusy("quest_claim", 1, "รับ Quest Auto · " + seqs.length + " รายการ", () =>
        runQuestClaim()
      )
    ) {
      return;
    }
    setFarmStatus("กำลังรับรางวัลเควส…", "muted");
    try {
      await submitFarmJob({
        url: "/api/farm/quest-claim/run",
        body: {
          devplay_session_id: devplaySession.id,
          seqs,
          episode_seq: questOpenEp != null ? Number(questOpenEp) : undefined,
        },
        mode: "quest_claim",
        target: seqs.length,
        handlers: {
          onSuccess: (data) => {
            refreshMe().catch(() => {});
            const result = data.result || data;
            const n = Number(result.claimed || 0);
            questSelected = new Set();
            refreshQuestScan().catch(() => {});
            setFarmStatus("รับเควสสำเร็จ " + formatNumTh(n) + " รายการ", "ok");
            loadFarmHistory().catch(() => {});
          },
          onError: (data) => {
            const result = data.result || data;
            refreshQuestScan().catch(() => {});
            setFarmStatus(farmErrorMessage(result, "รับรางวัลเควสไม่สำเร็จ"), "err");
            loadFarmHistory().catch(() => {});
          },
        },
      });
    } catch (e) {
      handleFarmRunException(e, "quest_claim");
    }
  }

  const EVO_MAX_SELECT = 8;
  const EVO_POWDER_PER_TOKEN = 1000;
  const EVO_BOX_PRICE = 5000;
  const EVO_POWDER_YIELD = 8;
  let evoScan = null;
  let evoSelected = new Set();
  let evoScanning = false;

  function evoItems() {
    return Array.isArray(evoScan?.items) ? evoScan.items : [];
  }

  function evoItemById(id) {
    const key = String(id || "");
    return evoItems().find((row) => String(row.id) === key) || null;
  }

  function pruneEvoSelected() {
    const valid = new Set(evoItems().map((row) => String(row.id)));
    evoSelected = new Set([...evoSelected].filter((id) => valid.has(id)));
  }

  function evoCeilTokens(deficit) {
    const n = Math.max(0, Math.floor(Number(deficit) || 0));
    if (n <= 0) return 0;
    return Math.ceil(n / EVO_POWDER_PER_TOKEN);
  }

  function evoSelectedItems() {
    pruneEvoSelected();
    return [...evoSelected].map(evoItemById).filter(Boolean);
  }

  function evoQuoteFromUi() {
    const items = evoSelectedItems();
    const powderHave = Math.max(0, Number(evoScan?.powder) || 0);
    const coinHave = Math.max(0, Number(evoScan?.coin) || 0);
    const matHave = {};
    let powderNeed = 0;
    let evoCoin = 0;
    items.forEach((item) => {
      evoCoin += Math.max(0, Number(item.coin) || 0);
      (item.materials || []).forEach((row) => {
        const seq = String(row.seq || "");
        const need = Math.max(1, Number(row.need) || 1);
        let have = matHave[seq];
        if (have == null) have = Math.max(0, Number(row.have) || 0);
        const take = Math.min(have, need);
        have -= take;
        matHave[seq] = have;
        powderNeed += (need - take) * Math.max(0, Number(row.craft_powder) || 0);
      });
    });
    const powderDeficit = Math.max(0, powderNeed - powderHave);
    const boxes = powderDeficit > 0 ? Math.ceil(powderDeficit / EVO_POWDER_YIELD) : 0;
    const boxCoin = boxes * EVO_BOX_PRICE;
    return {
      count: items.length,
      powder_need: powderNeed,
      powder_have: powderHave,
      powder_deficit: powderDeficit,
      token_units: evoCeilTokens(powderDeficit),
      boxes_est: boxes,
      box_coin: boxCoin,
      evo_coin: evoCoin,
      coin_need: boxCoin + evoCoin,
      coin_have: coinHave,
      can_run: items.length > 0 && coinHave >= boxCoin + evoCoin,
    };
  }

  function evoMatIconSrc(row) {
    const url = String(row?.image_url || "").trim();
    let path = "";
    if (url) path = url.startsWith("assets/") || url.startsWith("http") || url.startsWith("/api/") ? url : "assets/" + url.replace(/^\//, "");
    else {
      const tag = String(row?.image_tag || "").trim();
      path = tag ? "assets/icons/materials/" + tag + ".png" : "";
    }
    return typeof window.ckrHostedAsset === "function" ? window.ckrHostedAsset(path) : path;
  }

  function paintEvoCostLine() {
    const el = $("evo-cost-line");
    if (!el) return;
    if (!isDevPlayConnected()) {
      el.textContent = "เชื่อม DevPlay เพื่อสแกนสมบัติที่ Evo ได้";
      return;
    }
    if (evoScanning) {
      el.textContent = "กำลังอ่านคลังสมบัติ…";
      return;
    }
    const items = evoItems();
    const q = evoQuoteFromUi();
    const covered = hasFeatureAccess("treasure_evo");
    let msg =
      "Evo ได้ " +
      formatNumTh(items.length) +
      " สูตร · เลือก " +
      formatNumTh(q.count) +
      "/" +
      formatNumTh(EVO_MAX_SELECT) +
      " ชิ้น";
    if (q.count) {
      msg +=
        " · ผงขาด " +
        formatNumTh(q.powder_deficit) +
        (q.boxes_est ? " ≈" + formatNumTh(q.boxes_est) + " กล่อง" : "") +
        " · เหรียญ " +
        formatNumTh(q.coin_need);
      if (q.token_units > 0) {
        msg += covered
          ? " · มีวันเช่าแล้วไม่หัก Token"
          : " · " + formatTokenAmount(q.token_units) + " Token";
      } else {
        msg += " · ไม่หัก Token (ผงในคลังพอ)";
      }
      if (!q.can_run) msg += " · เหรียญไม่พอ";
    } else {
      msg +=
        " · ผงในไอดี " +
        formatNumTh(q.powder_have) +
        " · ผงที่ขาดทุก 1,000 = " +
        formatTokenAmount(tokenRate("treasure_evo") || 1) +
        " Token";
    }
    if (!evoScan) msg += " · กดรีเฟรชเพื่ออ่านคลัง";
    el.textContent = msg;
  }

  function paintEvoGrid() {
    const grid = $("evo-grid");
    if (!grid) return;
    const items = evoItems();
    grid.innerHTML = "";
    if (!items.length) {
      grid.innerHTML = '<p class="muted">ยังไม่มีสมบัติที่ Evo ได้ในคลังนี้</p>';
      return;
    }
    items.forEach((item) => {
      const id = String(item.id || "");
      const selected = evoSelected.has(id);
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className =
        "evo-card" +
        (selected ? " is-selected" : "") +
        (item.ready_materials ? " is-ready" : "") +
        (item.can_run ? "" : " is-blocked");
      btn.setAttribute("data-evo-id", id);
      const faces = document.createElement("div");
      faces.className = "evo-card-faces";
      const srcWrap = document.createElement("div");
      srcWrap.className = "evo-card-img-wrap";
      appendTreasureImage(srcWrap, item.source || {});
      const arrow = document.createElement("span");
      arrow.className = "evo-card-arrow";
      arrow.textContent = "→";
      const dstWrap = document.createElement("div");
      dstWrap.className = "evo-card-img-wrap is-product";
      appendTreasureImage(dstWrap, Object.assign({}, item.product || {}, { evo: true }));
      faces.append(srcWrap, arrow, dstWrap);
      const names = document.createElement("div");
      names.className = "evo-card-names";
      const srcName = document.createElement("strong");
      srcName.textContent = item.source?.name || "สมบัติ";
      const dstName = document.createElement("span");
      dstName.textContent = item.product?.name || "Evo";
      names.append(srcName, dstName);
      const mats = document.createElement("div");
      mats.className = "evo-mats";
      (item.materials || []).forEach((row) => {
        const chip = document.createElement("div");
        chip.className = "evo-mat" + (Number(row.deficit) > 0 ? " is-missing" : " is-ok");
        const imgSrc = evoMatIconSrc(row);
        if (imgSrc) {
          const img = document.createElement("img");
          img.src = imgSrc;
          img.alt = "";
          img.width = 28;
          img.height = 28;
          img.loading = "lazy";
          img.onerror = () => img.remove();
          chip.appendChild(img);
        }
        const copy = document.createElement("span");
        copy.innerHTML =
          "<b>" +
          escapeHtml(row.name || row.seq || "") +
          "</b><small>" +
          (gradeBadgeHtml(row.grade, "ckr-grade-inline") || escapeHtml(row.grade_label || row.grade || "-")) +
          " · มี " +
          formatNumTh(row.have || 0) +
          (Number(row.deficit) > 0
            ? " · Craft " + formatNumTh(row.craft_powder || 0) + " ผง"
            : " · ครบ") +
          "</small>";
        chip.appendChild(copy);
        mats.appendChild(chip);
      });
      const meta = document.createElement("div");
      meta.className = "evo-card-meta";
      meta.textContent =
        (item.grade ? "เกรด " + item.grade + " · " : "") +
        formatNumTh(item.success_percent || 0) +
        "% · เหรียญ " +
        formatNumTh(item.coin || 0) +
        (item.powder_deficit
          ? " · ผงขาด " + formatNumTh(item.powder_deficit)
          : " · วัตถุดิบครบ");
      btn.append(faces, names, mats, meta);
      grid.appendChild(btn);
    });
  }

