  function lvfcGradeOf(c) {
    return String(c?.grade || "C").toUpperCase();
  }

  function lvfcSupportsGrade(c) {
    return lvfcGradeOf(c) !== "L";
  }

  function lvfcVisibleRows() {
    return (lvfcScan?.cookies || []).filter((c) => {
      if (!lvfcSupportsGrade(c)) return false;
      if (lvfcGrade === "L") return false;
      if (lvfcGrade !== "all" && lvfcGradeOf(c) !== lvfcGrade) return false;
      return true;
    });
  }

  function lvfcQuoteFromUi() {
    const chosen = (lvfcScan?.cookies || []).filter(
      (c) => lvfcSupportsGrade(c) && lvfcSelected.has(String(c.seq))
    );
    let tokens = 0;
    const rows = chosen.map((c) => {
      const cur = Number(c.tag || c.current) || 1;
      const cap = 8;
      const want = Math.max(cur, Math.min(cap, Number(lvfcTargets[c.seq]) || cap));
      const steps = Math.max(0, want - cur);
      const grade = String(c.grade || "C").toUpperCase();
      const rate = tokenRate(LVFC_RATE_KEYS[grade] || LVFC_RATE_KEYS.C);
      const per = Math.round(steps * rate * 10000) / 10000;
      const bundle = tokenRate(LVFC_BUNDLE_KEYS[grade] || LVFC_BUNDLE_KEYS.C);
      let cost = per;
      if (steps > 0 && want >= cap && bundle > 0) cost = Math.min(per, bundle);
      tokens = Math.round((tokens + cost) * 10000) / 10000;
      return { ...c, target: want, steps, token_cost: cost };
    });
    return { rows, tokens, canRun: rows.some((r) => r.steps > 0) };
  }

  function lvfpRowIsMax(row) {
    const cur = Number(row?.current) || 1;
    const max = Number(row?.max) || cur;
    return cur >= max;
  }

  function lvfpOrderedRows() {
    const rows = lvfpScan?.rows || [];
    const byType = new Map(rows.map((r) => [r.type, r]));
    const ordered = ["A1", "A2", "A3"].map((t) => byType.get(t)).filter(Boolean);
    rows.forEach((r) => {
      if (!["A1", "A2", "A3"].includes(r.type)) ordered.push(r);
    });
    return ordered;
  }

  function paintLvFreePower() {
    const root = $("lvfp-rows");
    const banner = $("lvfp-banner");
    const cost = $("lvfp-cost-line");
    if (!root) {
      paintLvFreePowerRates();
      return;
    }
    const rows = lvfpOrderedRows();
    const maxed = rows.filter(lvfpRowIsMax);
    const open = rows.filter((r) => !lvfpRowIsMax(r) && r.upgradeable !== false);
    const nick = lvfpScan?.nickname ? String(lvfpScan.nickname) + " · " : "";
    if (banner) {
      banner.textContent = !lvfpScan
        ? "เชื่อม DevPlay เพื่ออ่านเลเวลปัจจุบัน"
        : !rows.length
          ? nick + "ยังอ่าน HP/Jelly/Bonus ไม่ได้"
          : maxed.length === rows.length
            ? nick + "ชุดพลังครบทั้ง " + formatNumTh(rows.length) + " ชนิดแล้ว อัปต่อไม่ได้"
            : nick +
              "เลือกชนิดที่ยังไม่เต็ม" +
              (maxed.length ? " · ชนิดที่เต็มจะแสดงสถานะพร้อมรูปเลเวลปัจจุบัน" : "");
    }
    root.innerHTML = rows
      .map((row) => {
        const cur = Number(row.current) || 1;
        const max = Number(row.max) || cur;
        const isMax = lvfpRowIsMax(row);
        const canUpgrade = !isMax && row.upgradeable !== false;
        const want = Math.max(cur, Math.min(max, Number(lvfpTargets[row.type]) || max));
        const selected = canUpgrade && lvfpSelected.has(row.type);
        const img = selected
          ? lvfpImageUrl(row.type, want)
          : row.image_url || lvfpImageUrl(row.type, cur);
        const kind = { A1: "hp", A2: "jelly", A3: "bonus" }[row.type] || "hp";
        const kindLabel = { A1: "HP", A2: "Jelly", A3: "Bonus" }[row.type] || row.type;
        const rateKey = LVFP_RATE_KEYS[row.type];
        const rate = rateKey ? tokenRate(rateKey) : 0;
        const tag = canUpgrade ? "label" : "div";
        let trailing;
        if (canUpgrade) {
          const opts = [];
          for (let lv = cur; lv <= max; lv += 1) {
            opts.push(
              '<option value="' + lv + '"' + (lv === want ? " selected" : "") + ">Lv." + lv + "</option>"
            );
          }
          trailing =
            '<div class="lvfp-card-action"><select data-lvfp-target="' +
            escapeHtml(row.type) +
            '"' +
            (selected ? "" : " disabled") +
            ">" +
            opts.join("") +
            "</select></div>";
        } else {
          trailing =
            '<span class="lvfp-max-badge">' +
            (isMax ? "เต็มแล้ว" : "อัปต่อไม่ได้") +
            "</span>";
        }
        const levelLine = isMax
          ? "ตอนนี้ Lv." + formatNumTh(cur) + " / สูงสุด Lv." + formatNumTh(max) + " · เต็มแล้ว อัปเกรดไม่ได้"
          : "ตอนนี้ Lv." +
            formatNumTh(cur) +
            " / สูงสุด Lv." +
            formatNumTh(max) +
            (selected && want > cur ? " → Lv." + formatNumTh(want) : "") +
            (canUpgrade ? " · " + formatTokenAmount(rate) + " Token/เลเวล" : "");
        return (
          "<" +
          tag +
          ' class="lvfp-card lvfp-card--' +
          kind +
          (selected ? " is-selected" : "") +
          (isMax ? " is-max" : "") +
          (!canUpgrade && !isMax ? " is-locked" : "") +
          '">' +
          (canUpgrade
            ? '<input type="checkbox" data-lvfp-type="' +
              escapeHtml(row.type) +
              '"' +
              (selected ? " checked" : "") +
              ">"
            : '<span class="lvfp-check-spacer" aria-hidden="true"></span>') +
          '<div class="lvfp-card-art"><img src="' +
          escapeHtml(img) +
          '" alt="' +
          escapeHtml((row.label || row.type) + " Lv." + cur) +
          '" width="60" height="60" loading="lazy" onerror="this.src=\'assets/upgrade01_30_shop.png\'"></div><div class="lvfp-card-copy"><div class="lvfp-card-kicker"><span class="lvfp-kind-chip">' +
          escapeHtml(kindLabel) +
          "</span></div><strong>" +
          escapeHtml(row.label || row.type) +
          '</strong><span class="muted">' +
          escapeHtml(levelLine) +
          "</span>" +
          rainbowBarHtml(cur, selected ? want : cur, max, 8) +
          "</div>" +
          trailing +
          "</" +
          tag +
          ">"
        );
      })
      .join("");
    const q = lvfpQuoteFromUi();
    if (cost) {
      const rental = lvFreeRentalCovered();
      cost.textContent = !lvfpScan
        ? "—"
        : !rows.length
          ? "—"
          : maxed.length === rows.length
            ? "ชุดพลังเต็มแล้วทั้ง " + formatNumTh(rows.length) + " ชนิด · อัปเกรดต่อไม่ได้"
            : !q.canRun
              ? open.length
                ? "เลือกชนิดและเลเวลที่สูงกว่าปัจจุบัน"
                : "ชุดพลังนี้ยังอัปต่อด้วยวิธีฟรีไม่ได้"
              : rental
                ? "สมาชิกรายวัน · ใช้ได้ไม่จำกัดครั้ง"
                : q.bundleApplied
                  ? "เหมา 3 ตัวเต็ม " +
                    formatTokenAmount(q.tokens) +
                    " Token (ถูกกว่าคิดรายเลเวล " +
                    formatTokenAmount(q.per) +
                    ")"
                  : "ใช้ " + formatTokenAmount(q.tokens) + " Token · คืนส่วนที่อัปไม่สำเร็จ";
    }
    paintLvFreePowerRates();
    paintPlayerInventoryStats();
  }

  async function refreshLvFreePowerScan() {
    if (!isDevPlayConnected() || !devplaySession?.id) {
      lvfpScan = null;
      lvfpSelected = new Set();
      paintLvFreePower();
      updateFarmAvailability();
      return;
    }
    try {
      const data = await api("/api/farm/lv-free-power/scan", {
        method: "POST",
        body: { devplay_session_id: devplaySession.id, targets: lvfpTargets },
      });
      lvfpScan = data;
      const valid = new Set((data.rows || []).filter((r) => r.upgradeable).map((r) => r.type));
      lvfpSelected = new Set([...lvfpSelected].filter((t) => valid.has(t)));
      (data.rows || []).forEach((r) => {
        const cur = Number(r.current) || 1;
        const max = Number(r.max) || cur;
        if (!lvfpTargets[r.type] || lvfpTargets[r.type] < cur) lvfpTargets[r.type] = max;
      });
      paintLvFreePower();
    } catch (e) {
      if ($("lvfp-banner")) $("lvfp-banner").textContent = thError(e.message) || "อ่านเลเวลไม่สำเร็จ";
    }
    updateFarmAvailability();
  }

  function paintLvFreeCookie() {
    const grid = $("lvfc-grid");
    const cost = $("lvfc-cost-line");
    if (!grid) {
      paintLvFreeCookieRates();
      return;
    }
    const rows = lvfcVisibleRows();
    if (!rows.length) {
      grid.innerHTML = "";
      if (cost) {
        cost.textContent = lvfcScan
          ? "ไม่มี Cookie ที่อัปต่อได้ในตัวกรองนี้ · ไม่รองรับเกรด L"
          : "เชื่อม DevPlay เพื่อสแกน Cookie ที่ครอบครอง";
      }
      paintLvFreeCookieRates();
      return;
    }
    grid.innerHTML = rows
      .map((c) => {
        const seq = String(c.seq || "");
        const cur = Number(c.tag || c.current) || 1;
        const want = Math.max(cur, Math.min(8, Number(lvfcTargets[seq]) || 8));
        const selected = lvfcSelected.has(seq);
        const img =
          (typeof ckrPortraitSrc === "function" && ckrPortraitSrc(c.name, c.image_url, "cookie")) ||
          c.image_url ||
          "assets/Brave-cookie.png";
        const opts = [];
        for (let lv = cur; lv <= 8; lv += 1) {
          opts.push('<option value="' + lv + '"' + (lv === want ? " selected" : "") + ">" + lv + "</option>");
        }
        const grade = String(c.grade || "C").toUpperCase();
        return (
          '<label class="lvfc-card' +
          (selected ? " is-selected" : "") +
          '" data-ckr-wiki-skip="1"><input type="checkbox" data-lvfc-seq="' +
          escapeHtml(seq) +
          '"' +
          (selected ? " checked" : "") +
          ">" +
          (gradeBadgeHtml(grade, "idshop-bento-grade-badge lvfc-grade-badge") ||
            '<span class="lvfc-grade is-' + escapeHtml(grade) + '">' + escapeHtml(grade) + "</span>") +
          '<img src="' +
          escapeHtml(img) +
          '" alt="" width="72" height="72" loading="lazy" onerror="window.ckrImgError&&ckrImgError(this);"><span class="cookie-name">' +
          escapeHtml(c.name || seq) +
          "</span>" +
          rainbowBarHtml(cur, selected ? want : cur, 8, 8) +
          '<select data-lvfc-target="' +
          escapeHtml(seq) +
          '"' +
          (selected ? "" : " disabled") +
          ">" +
          opts.join("") +
          "</select></label>"
        );
      })
      .join("");
    const q = lvfcQuoteFromUi();
    if (cost) {
      const rental = lvFreeRentalCovered();
      cost.textContent = q.canRun
        ? rental
          ? "เลือก " + formatNumTh(q.rows.length) + " ตัว · สมาชิกรายวันใช้ได้ไม่จำกัดครั้ง"
          : "เลือก " + formatNumTh(q.rows.length) + " ตัว · " + formatTokenAmount(q.tokens) + " Token · คืนส่วนที่อัปไม่สำเร็จ"
        : "เลือก Cookie ที่ยังไม่เต็ม · แสดงเฉพาะตัวที่อัปต่อได้ · ไม่รองรับเกรด L";
    }
    paintLvFreeCookieRates();
  }

  async function refreshLvFreeCookieScan() {
    if (!isDevPlayConnected() || !devplaySession?.id) {
      lvfcScan = null;
      lvfcSelected = new Set();
      paintLvFreeCookie();
      updateFarmAvailability();
      return;
    }
    try {
      const data = await api("/api/farm/lv-free-cookie/scan", {
        method: "POST",
        body: { devplay_session_id: devplaySession.id },
      });
      lvfcScan = {
        ...data,
        cookies: (data.cookies || []).filter(lvfcSupportsGrade),
      };
      const valid = new Set((lvfcScan.cookies || []).map((c) => String(c.seq)));
      lvfcSelected = new Set([...lvfcSelected].filter((seq) => valid.has(seq)));
      (lvfcScan.cookies || []).forEach((c) => {
        const seq = String(c.seq);
        const cur = Number(c.tag || c.current) || 1;
        if (!lvfcTargets[seq] || lvfcTargets[seq] < cur) lvfcTargets[seq] = 8;
      });
      paintLvFreeCookie();
    } catch (e) {
      if ($("lvfc-cost-line")) $("lvfc-cost-line").textContent = thError(e.message) || "สแกน Cookie ไม่สำเร็จ";
    }
    updateFarmAvailability();
  }

  async function runLvFreePower() {
    if (!isDevPlayConnected()) {
      showErrorModal(ERR_TH.devplay_session_expired, "เชื่อม DevPlay ก่อน");
      return;
    }
    const q = lvfpQuoteFromUi();
    if (!q.canRun) {
      showErrorModal(ERR_TH.nothing_to_upgrade, "ยังเริ่มไม่ได้");
      return;
    }
    if (!canPayForFeature("lv_free_power") && !lvFreeRentalCovered()) {
      showErrorModal("Token ไม่พอ — เติม Token ก่อนเริ่มงาน", "Token ไม่พอ");
      return;
    }
    const targets = { A1: 0, A2: 0, A3: 0 };
    q.rows.forEach((r) => {
      if (lvfpSelected.has(r.type)) targets[r.type] = r.target;
    });
    if (queueIfBusy("lv_free_power", q.tokens, "ชุดพลังฟรี", () => runLvFreePower())) return;
    setFarmStatus("กำลังอัปชุดพลังฟรี…", "muted");
    try {
      await submitFarmJob({
        url: "/api/farm/lv-free-power/run",
        body: { devplay_session_id: devplaySession.id, targets },
        mode: "lv_free_power",
        target: Math.max(1, q.rows.reduce((n, r) => n + (r.steps || 0), 0)),
        handlers: {
          onSuccess: (data) => {
            refreshMe().catch(() => {});
            refreshLvFreePowerScan().catch(() => {});
            const result = data.result || data;
            setFarmStatus("อัปชุดพลังสำเร็จ " + formatNumTh(result.bought || 0) + " ขั้น", "ok");
            loadFarmHistory().catch(() => {});
          },
          onError: (data) => {
            const result = data.result || data;
            setFarmStatus(farmErrorMessage(result, "อัปชุดพลังไม่สำเร็จ"), "err");
            loadFarmHistory().catch(() => {});
          },
        },
      });
    } catch (e) {
      handleFarmRunException(e, "lv_free_power");
    }
  }

  async function runLvFreeCookie() {
    if (!isDevPlayConnected()) {
      showErrorModal(ERR_TH.devplay_session_expired, "เชื่อม DevPlay ก่อน");
      return;
    }
    const q = lvfcQuoteFromUi();
    if (!q.canRun) {
      showErrorModal(ERR_TH.nothing_to_upgrade, "ยังไม่ได้เลือก");
      return;
    }
    if (!canPayForFeature("lv_free_cookie") && !lvFreeRentalCovered()) {
      showErrorModal("Token ไม่พอ — เติม Token ก่อนเริ่มงาน", "Token ไม่พอ");
      return;
    }
    const items = q.rows.map((c) => ({ seq: String(c.seq), target: Number(c.target) || 8 }));
    if (queueIfBusy("lv_free_cookie", items.length, "Cookie Lv ฟรี · " + items.length + " ตัว", () => runLvFreeCookie())) {
      return;
    }
    setFarmStatus("กำลังอัป Cookie Lv ฟรี…", "muted");
    try {
      await submitFarmJob({
        url: "/api/farm/lv-free-cookie/run",
        body: { devplay_session_id: devplaySession.id, items },
        mode: "lv_free_cookie",
        target: Math.max(1, items.length),
        handlers: {
          onSuccess: (data) => {
            refreshMe().catch(() => {});
            refreshLvFreeCookieScan().catch(() => {});
            const result = data.result || data;
            setFarmStatus("อัป Cookie สำเร็จ " + formatNumTh(result.bought || 0) + " ขั้น", "ok");
            loadFarmHistory().catch(() => {});
          },
          onError: (data) => {
            const result = data.result || data;
            setFarmStatus(farmErrorMessage(result, "อัป Cookie Lv ไม่สำเร็จ"), "err");
            loadFarmHistory().catch(() => {});
          },
        },
      });
    } catch (e) {
      handleFarmRunException(e, "lv_free_cookie");
    }
  }

  function setPetJobMode(mode) {
    petJobMode = mode === "level" ? "level" : "unlock";
    const unlockBtn = $("pet-mode-unlock");
    const levelBtn = $("pet-mode-level");
    const unlockPanel = $("pet-unlock-mode-panel");
    const levelPanel = $("pet-level-mode-panel");
    const hint = $("pet-panel-hint");
    const title = $("pet-unlock-btn-title");
    if (unlockBtn) {
      unlockBtn.classList.toggle("is-active", petJobMode === "unlock");
      unlockBtn.setAttribute("aria-selected", petJobMode === "unlock" ? "true" : "false");
    }
    if (levelBtn) {
      levelBtn.classList.toggle("is-active", petJobMode === "level");
      levelBtn.setAttribute("aria-selected", petJobMode === "level" ? "true" : "false");
    }
    if (unlockPanel) {
      unlockPanel.classList.toggle("hidden", petJobMode !== "unlock");
      if (petJobMode === "unlock") unlockPanel.removeAttribute("hidden");
      else unlockPanel.setAttribute("hidden", "");
    }
    if (levelPanel) {
      levelPanel.classList.toggle("hidden", petJobMode !== "level");
      if (petJobMode === "level") levelPanel.removeAttribute("hidden");
      else levelPanel.setAttribute("hidden", "");
    }
    if (hint) {
      hint.textContent =
        petJobMode === "level"
          ? "อัปเลเวล Pet ที่มีอยู่ด้วยเหรียญ — แสดงเฉพาะตัวที่ยังไม่เต็ม"
          : "สุ่ม Pet ครั้งละ 20 เพชร แล้วอัปเกรดด้วยเหรียญ — อัปเต็มจะไม่สุ่มตัวเดิมซ้ำ";
    }
    if (title) {
      title.textContent = petJobMode === "level" ? "เริ่มอัปเลเวล Pet" : "เริ่มปลดล็อก Pet";
    }
    if (petJobMode === "level") {
      if (isDevPlayConnected()) refreshPetLevelScan().catch(() => {});
      else paintPetLevelGrid();
    } else if (isDevPlayConnected()) {
      refreshPetPlan().catch(() => {});
    }
    updateFarmAvailability();
  }

  function petLevelQuoteFromUi() {
    const rows = (petLevelScan?.pets || []).filter((p) => petLevelSelected.has(String(p.seq)));
    const coin = Number(petLevelScan?.coin) || 0;
    const total = rows.reduce((sum, p) => sum + (Number(p.coin_cost) || 0), 0);
    const affordableRows = (petLevelScan?.pets || []).filter((p) => !!p.affordable);
    return {
      rows,
      total,
      coin,
      affordableCount: affordableRows.length,
      canRun: rows.length > 0 && total > 0 && total <= coin,
      unaffordable: rows.length > 0 && total > coin,
      empty: !((petLevelScan?.pets || []).length),
      allMaxed: !!(petLevelScan && petLevelScan.all_maxed),
    };
  }

  function paintPetLevelGrid() {
    const grid = $("pet-level-grid");
    const cost = $("pet-level-cost-line");
    if (!grid) return;
    const rows = petLevelScan?.pets || [];
    if (!isDevPlayConnected() || !petLevelScan) {
      grid.innerHTML = "";
      if (cost) cost.textContent = "เชื่อม DevPlay เพื่อสแกน Pet ที่อัปได้";
      return;
    }
    if (petLevelScan.all_maxed || (!rows.length && Number(petLevelScan.owned_count || 0) > 0)) {
      grid.innerHTML =
        '<div class="pet-level-empty" role="status">Pet ทั้งหมดเต็มเลเวลแล้ว — ไม่มีตัวให้อัป</div>';
      if (cost) cost.textContent = "มีเหรียญ " + formatNumTh(Number(petLevelScan.coin) || 0);
      return;
    }
    if (!rows.length) {
      grid.innerHTML =
        '<div class="pet-level-empty" role="status">ยังไม่มี Pet ในไอดีที่อัปด้วยเหรียญได้</div>';
      if (cost) cost.textContent = "มีเหรียญ " + formatNumTh(Number(petLevelScan.coin) || 0);
      return;
    }
    grid.innerHTML = rows
      .map((p) => {
        const seq = String(p.seq || "");
        const affordable = !!p.affordable;
        const selected = affordable && petLevelSelected.has(seq);
        const cls =
          "pet-level-card cookie-unlock-card" +
          (affordable ? " is-pickable" : " is-locked") +
          (selected ? " is-selected" : "") +
          (affordable ? "" : " is-unaffordable");
        const img =
          (typeof ckrPortraitSrc === "function" && ckrPortraitSrc(p.name, p.image_url, "pet")) ||
          p.image_url ||
          "assets/King_Choco_Drop.png";
        const cur = Number(p.current) || 1;
        const max = Number(p.max) || 8;
        const badge = affordable
          ? '<span class="pet-level-badge is-ok">เงินพอ</span>'
          : '<span class="pet-level-badge is-no">เงินไม่พอ</span>';
        const tag = affordable ? "button" : "div";
        const typeAttr = affordable ? ' type="button"' : "";
        const dataAttr = affordable ? ' data-pet-level-seq="' + escapeHtml(seq) + '"' : "";
        const aria = affordable
          ? ' aria-pressed="' +
            (selected ? "true" : "false") +
            '" aria-label="' +
            escapeHtml(p.name || seq) +
            (selected ? " เลือกแล้ว" : " เลือก") +
            '"'
          : ' role="group" aria-label="' + escapeHtml(p.name || seq) + '"';
        const title =
          escapeHtml(p.name || seq) +
          " · Lv." +
          cur +
          "/" +
          max +
          " · " +
          formatNumTh(Number(p.coin_cost) || 0) +
          " เหรียญ";
        return (
          "<" +
          tag +
          ' class="' +
          cls +
          '"' +
          typeAttr +
          dataAttr +
          aria +
          ' title="' +
          title +
          '" data-ckr-wiki-skip="1">' +
          (affordable
            ? '<span class="cookie-unlock-pick" aria-hidden="true">' + (selected ? "✓" : "") + "</span>"
            : '<span class="cookie-unlock-pick is-static" aria-hidden="true"></span>') +
          badge +
          '<span class="cookie-unlock-media">' +
          '<img class="cookie-unlock-img" src="' +
          escapeHtml(img) +
          '" alt="" width="56" height="56" loading="lazy" onerror="window.ckrImgError&&ckrImgError(this);">' +
          "</span>" +
          '<span class="cookie-name">' +
          escapeHtml(p.name || seq) +
          "</span>" +
          '<span class="pet-level-meta">Lv.' +
          formatNumTh(cur) +
          "/" +
          formatNumTh(max) +
          "</span>" +
          '<span class="pet-level-cost">' +
          formatNumTh(Number(p.coin_cost) || 0) +
          " เหรียญ</span></" +
          tag +
          ">"
        );
      })
      .join("");
    const q = petLevelQuoteFromUi();
    if (cost) {
      if (q.rows.length) {
        cost.textContent =
          "เลือก " +
          formatNumTh(q.rows.length) +
          " ตัว · ใช้เหรียญ " +
          formatNumTh(q.total) +
          (q.unaffordable
            ? " — เงินไม่พอ (มี " + formatNumTh(q.coin) + ")"
            : " · มี " + formatNumTh(q.coin));
      } else {
        cost.textContent =
          "เลือกเฉพาะตัวที่เงินพอ · อัปได้ " +
          formatNumTh(rows.length) +
          " ตัว · มี " +
          formatNumTh(q.coin) +
          " เหรียญ";
      }
    }
    paintPlayerInventoryStats();
  }

  async function refreshPetLevelScan() {
    if (!isDevPlayConnected() || !devplaySession?.id) {
      petLevelScan = null;
      petLevelSelected = new Set();
      paintPetLevelGrid();
      updateFarmAvailability();
      return;
    }
    try {
      const data = await api("/api/farm/pet-unlock/scan", {
        method: "POST",
        body: {
          devplay_session_id: devplaySession.id,
          target_level: petLevelTarget,
        },
      });
      petLevelScan = data;
      const valid = new Set(
        (data.pets || []).filter((p) => p.affordable).map((p) => String(p.seq))
      );
      petLevelSelected = new Set([...petLevelSelected].filter((seq) => valid.has(seq)));
      paintPetLevelGrid();
    } catch (e) {
      const msg = thError(e.message);
      if ($("pet-level-cost-line")) $("pet-level-cost-line").textContent = msg || "สแกน Pet ไม่สำเร็จ";
    }
    updateFarmAvailability();
  }

  function schedulePetLevelScan() {
    if (petLevelTimer) clearTimeout(petLevelTimer);
    petLevelTimer = setTimeout(() => refreshPetLevelScan().catch(() => {}), 180);
  }

    function paintPetPlan() {
    const setText = (id, v) => {
      if ($(id)) $(id).textContent = v;
    };
    if (!petPlan) {
      setText("pet-stat-gem", "—");
      setText("pet-stat-coin", "—");
      setText("pet-stat-gem-cost", "—");
      setText("pet-stat-coin-cost", "—");
      if ($("pet-plan-note")) $("pet-plan-note").textContent = "";
      if ($("pet-max-hint")) $("pet-max-hint").textContent = "เชื่อม DevPlay เพื่อดูเพชรคงเหลือ";
      return;
    }
    setText("pet-stat-gem", formatNumTh(petPlan.gem || 0));
    setText("pet-stat-coin", formatNumTh(petPlan.coin || 0));
    setText("pet-stat-gem-cost", formatNumTh(petPlan.gem_cost || 0));
    setText("pet-stat-coin-cost", formatNumTh(petPlan.coin_cost || 0));
    const note = $("pet-plan-note");
    if (note) {
      if (petPlan.insufficient_gem) note.textContent = "เพชรไม่พอ (ครั้งละ 20)";
      else if (petPlan.insufficient_coin) note.textContent = "เหรียญไม่พอสำหรับอัปเกรดหลังสุ่ม";
      else note.textContent = petPlan.can_run ? "พร้อมสุ่มแล้วอัปเกรด" : "";
    }
    if ($("pet-max-hint")) {
      $("pet-max-hint").textContent =
        "สุ่มได้สูงสุด " + formatNumTh(petPlan.max_draws || 0) + " ครั้งจากเพชรที่มี · ครั้งละ 20 เพชร";
    }
    const input = $("pet-count");
    const max = Math.max(1, Number(petPlan.max_draws) || 1);
    petCount = Math.min(Math.max(1, petCount), max);
    if (input && document.activeElement !== input) input.value = String(petCount);
    const minus = $("pet-minus");
    const plus = $("pet-plus");
    if (minus) minus.disabled = petCount <= 1;
    if (plus) plus.disabled = petCount >= max;
  }

  async function refreshPetPlan() {
    if (!isDevPlayConnected() || !devplaySession?.id) {
      petPlan = null;
      paintPetPlan();
      updateFarmAvailability();
      return;
    }
    try {
      const data = await api("/api/farm/pet-unlock/plan", {
        method: "POST",
        body: {
          devplay_session_id: devplaySession.id,
          count: petCount,
          target_level: petTargetLevel,
        },
      });
      petPlan = data;
      paintPetPlan();
    } catch (e) {
      const msg = thError(e.message);
      if ($("pet-plan-note")) $("pet-plan-note").textContent = msg || "อ่านแผน Pet ไม่สำเร็จ";
    }
    updateFarmAvailability();
  }

  function schedulePetPlan() {
    if (petPlanTimer) clearTimeout(petPlanTimer);
    petPlanTimer = setTimeout(() => refreshPetPlan().catch(() => {}), 180);
  }

  function clampHeartFreeTarget(value) {
    const q = freeQuotaByFeature.heart_free;
    const rem = freeQuotaRemaining("heart_free");
    const maxFree = heartMerged() ? Math.max(1, tokenMode("heart").free_limit || HEART_FREE_MAX) : HEART_FREE_MAX;
    const cap = q ? Math.max(1, Math.min(maxFree, rem > 0 ? rem : 1)) : maxFree;
    const n = Math.floor(Number(String(value ?? "").replace(/[^\d]/g, "")) || 0);
    return Math.min(Math.max(1, n || 1), cap);
  }

  function paintHeartFreeStepper() {
    const input = $("heart-free-target");
    const hint = $("heart-free-max-hint");
    const minus = $("heart-free-minus");
    const plus = $("heart-free-plus");
    heartFreeTarget = clampHeartFreeTarget(heartFreeTarget);
    if (input && document.activeElement !== input) input.value = String(heartFreeTarget);
    const rem = freeQuotaRemaining("heart_free");
    if (hint) {
      hint.textContent =
        rem <= 0
          ? "โควต้าฟรีหมดแล้ว · ใช้ฟาร์มหัวใจแบบเติมเงิน"
          : "เหลือโควต้า " + formatNumTh(rem) + " ดวง / 24 ชม. (สูงสุด 100)";
    }
    if (minus) minus.disabled = heartFreeTarget <= 1 || rem <= 0;
    if (plus) plus.disabled = rem <= 0 || heartFreeTarget >= Math.max(1, Math.min(HEART_FREE_MAX, rem));
  }

  async function runJellyUpgrade() {
    if (!requireFreeQuotaAccess("jelly_upgrade", 1)) return;
    if (!isDevPlayConnected()) {
      showErrorModal(ERR_TH.devplay_session_expired, "เชื่อม DevPlay ก่อน");
      return;
    }
    if (!jellyPlan?.can_run) {
      showErrorModal(jellyPlan?.insufficient_coin ? ERR_TH.insufficient_coin : "เลือกเลเวลที่ต้องการอัปก่อน", "ยังเริ่มไม่ได้");
      return;
    }
    if (
      queueIfBusy("jelly_upgrade", 1, "อัปเกรด Jelly", () => runJellyUpgrade())
    ) {
      return;
    }
    setFarmStatus("กำลังอัปเกรด Jelly…", "muted");
    try {
      await submitFarmJob({
        url: "/api/farm/jelly/run",
        body: { devplay_session_id: devplaySession.id, targets: jellyTargets },
        mode: "jelly_upgrade",
        target: Number(jellyPlan?.rows?.reduce((n, r) => n + (r.steps || 0), 0)) || 1,
        handlers: {
          onSuccess: (data) => {
            refreshMe().catch(() => {});
            refreshFreeQuota("jelly_upgrade").catch(() => {});
            refreshJellyPlan().catch(() => {});
            const result = data.result || data;
            const bought = Number(result.bought || 0);
            setFarmStatus("อัปเกรด Jelly สำเร็จ " + formatNumTh(bought) + " ขั้น", "ok");
            loadFarmHistory().catch(() => {});
          },
          onError: (data) => {
            const result = data.result || data;
            setFarmStatus(farmErrorMessage(result, "อัปเกรด Jelly ไม่สำเร็จ"), "err");
            loadFarmHistory().catch(() => {});
          },
        },
      });
    } catch (e) {
      handleFarmRunException(e, "jelly_upgrade");
    }
  }

