  function formatApiDetail(detail) {
    if (detail == null) return "";
    if (typeof detail === "string") return detail;
    if (typeof detail === "object" && !Array.isArray(detail)) {
      if (detail.code === "farm_busy" || detail.message === "farm_busy") {
        return "farm_busy";
      }
      if (detail.code === "peek_rate_limited" || detail.message === "peek_rate_limited") {
        return "peek_rate_limited";
      }
      if (detail.code === "refresh_rate_limited" || detail.message === "refresh_rate_limited") {
        return "refresh_rate_limited";
      }
      if (detail.code === "insufficient_tokens_for_peek") {
        return "insufficient_tokens_for_peek";
      }
      // Prefer machine code so thError can map TMN / API codes
      if (detail.code && typeof detail.code === "string") return detail.code;
      if (detail.message && typeof detail.message === "string") return detail.message;
      return detail.msg || detail.reason || "request_failed";
    }
    if (Array.isArray(detail)) {
      const parts = detail.map((item) => {
        if (!item || typeof item !== "object") return String(item);
        const locParts = Array.isArray(item.loc)
          ? item.loc.filter((x) => x !== "body" && x !== "query")
          : [];
        const loc = locParts.join(".");
        const msg = item.msg || item.type || "invalid";
        if (item.type === "missing" || /field required/i.test(String(msg))) {
          return "ข้อมูลไม่ครบ กรุณาลองใหม่";
        }
        if (loc.includes("email") || /email/i.test(msg)) {
          return "อีเมล DevPlay ไม่ถูกต้อง";
        }
        if (loc.includes("password")) return "รหัสผ่าน DevPlay ว่างหรือไม่ถูกต้อง";
        if (loc.includes("score") || loc.includes("coin") || loc.includes("exp")) {
          return "ค่าคะแนน/เหรียญ/XP ไม่ถูกต้องหรือเกินกำหนด";
        }
        return loc ? loc + ": " + msg : msg;
      });
      return parts.filter(Boolean).join(" · ") || "ข้อมูลไม่ถูกต้อง";
    }
    return String(detail);
  }

  function isTransientNetworkError(error) {
    const message = String(error?.message || "");
    return error?.name === "AbortError" || /abort|timeout|network|failed to fetch/i.test(message);
  }

  async function api(path, options = {}) {
    const inviteApiPath = /^\/api\/invite\//.test(path);
    const idshopApiPath = /^\/api\/idshop\//.test(path) || /^\/api\/admin\/idshop\//.test(path);
    const guestFeatureApi = (inviteApiPath || idshopApiPath) && !accessToken;
    if (
      !options._skipAuthSync &&
      !guestFeatureApi &&
      !/\/api\/auth\/login|\/api\/auth\/register|\/api\/auth\/signup/i.test(path)
    ) {
      await ensureFreshWebsiteSession();
    }
    const method = String(options.method || "GET").toUpperCase();
    const isFormData =
      typeof FormData !== "undefined" && options.body instanceof FormData;
    const hasBody = options.body != null && method !== "GET" && method !== "HEAD";
    const headers = Object.assign({}, options.headers || {});
    if (hasBody && !isFormData && !headers["Content-Type"] && !headers["content-type"]) {
      headers["Content-Type"] = "application/json";
    }
    if (accessToken) headers.Authorization = "Bearer " + accessToken;
    if (sessionToken) headers["X-Session-Token"] = sessionToken;
    if (inviteApiPath && !accessToken && inviteGuestToken) {
      headers["X-Invite-Guest-Token"] = inviteGuestToken;
    }
    if (idshopApiPath && idshopPreviewToken) {
      headers["X-Idshop-Preview-Token"] = idshopPreviewToken;
    }
    if (!isFormData && options.body?.client_job_key) {
      headers["X-Idempotency-Key"] = String(options.body.client_job_key).slice(0, 128);
    }
    // Read only by the enqueue paths: bill Tokens if the rental clock runs out
    // before a queued job gets its turn.
    if (queueTokenFallback && method === "POST") headers["X-Token-Fallback"] = "1";
    const timeoutMs = Number(
      options.timeoutMs != null
        ? options.timeoutMs
        : /\/api\/(?:invite\/|idshop\/)?topup\/(?:redeem|slip)/i.test(path)
          ? 90000
          : /\/api\/(?:invite\/|idshop\/)?topup\/verify/i.test(path)
            ? 90000
            : /\/api\/admin\/mailbox\/.+\/attachments/i.test(path)
              ? 180000
              : /\/api\/admin\/mailbox\/users/i.test(path)
                ? 45000
              : /\/api\/admin\/site-notices\/cover/i.test(path)
                ? 60000
                : /\/api\/auth\/login|\/api\/auth\/register|\/api\/auth\/signup/i.test(path)
                  ? 60000
                  : 35000
    );
    const ctrl =
      typeof AbortController !== "undefined" ? new AbortController() : null;
    const timer = ctrl
      ? setTimeout(() => {
          try {
            ctrl.abort();
          } catch (_) {}
        }, Math.max(3000, timeoutMs))
      : null;
    let res;
    const startedAt = Date.now();
    try {
      const fetchInit = {
        method,
        headers,
        signal: ctrl?.signal || options.signal,
      };
      if (hasBody) fetchInit.body = isFormData ? options.body : JSON.stringify(options.body);
      if (options.credentials) fetchInit.credentials = options.credentials;
      if (options.mode) fetchInit.mode = options.mode;
      if (options.cache) fetchInit.cache = options.cache;
      res = await fetch(API + path, fetchInit);
    } catch (netErr) {
      const aborted =
        netErr?.name === "AbortError" || /abort/i.test(String(netErr?.message || ""));
      const isRedeemPath = /\/(?:invite\/|idshop\/)?topup\/redeem/i.test(path);
      const retryablePost =
        method === "POST" &&
        !isRedeemPath &&
        (/\/api\/auth\/login|\/api\/auth\/register|\/api\/auth\/signup/i.test(path) ||
          /\/api\/(?:invite\/|idshop\/)?topup\/verify/i.test(path));
      if (
        (method === "GET" || retryablePost) &&
        !options._transientRetry &&
        isTransientNetworkError(netErr)
      ) {
        await new Promise((resolve) => setTimeout(resolve, 450));
        return api(path, {
          ...options,
          _transientRetry: true,
          timeoutMs: method === "GET" ? Math.max(timeoutMs, 45000) : timeoutMs,
        });
      }
      const elapsed = Date.now() - startedAt;
      const timedOut = aborted || elapsed >= Math.max(3000, timeoutMs) - 100;
      const err = new Error(timedOut ? "timeout" : "network_error");
      err.cause = netErr;
      throw err;
    } finally {
      if (timer) clearTimeout(timer);
    }
    let data = null;
    try {
      data = await res.json();
    } catch (_) {
      data = null;
    }
    if (!res.ok) {
      if (data && typeof data === "object") {
        delete data.trace;
      }
      const raw = data?.detail ?? data?.reason ?? data?.error ?? null;
      const detail = formatApiDetail(raw) || res.statusText || "request_failed";
      if (res.status === 401 && !(inviteApiPath && !accessToken)) {
        const authAction = await handleWebsiteApiUnauthorized(path, detail, options);
        if (authAction === "retry") {
          return api(path, { ...options, _authRetry: true, _skipAuthSync: true });
        }
      }
      const err = new Error(detail);
      err.status = res.status;
      err.data = data;
      if (raw && typeof raw === "object" && !Array.isArray(raw)) {
        if (raw.gate) err.gate = raw.gate;
        if (typeof raw.message === "string" && raw.message.trim()) {
          err.userMessage = raw.message.trim();
        }
        if (typeof raw.code === "string" && raw.code.trim()) {
          err.code = raw.code.trim();
        }
        if (raw.game_code != null) err.gameCode = raw.game_code;
      }
      if (/site_maintenance/i.test(String(detail)) || data?.site_maintenance) {
        if (!isAdminUser()) {
          if (lastHealth) lastHealth.site_maintenance = true;
          paintSiteMaintenance({ ...(lastHealth || {}), site_maintenance: true });
        }
      }
      throw err;
    }
    if (
      devplaySession?.id &&
      /^\/api\/farm\//.test(path) &&
      !/\/devplay\/connect$/.test(path)
    ) {
      devplaySession.expiresAt =
        Date.now() + (Number(data?.expires_in) || 4 * 60 * 60) * 1000;
      if (devplayConnectionState !== "reconnecting") {
        devplayConnectionState = "connected";
      }
    }
    return data;
  }

