  const AUTH_MODAL_MOTION_MS = 180;
  let authModalExitTimer = null;

  function hideAuthModalImmediately() {
    if (!loginView) return;
    if (authModalExitTimer) {
      clearTimeout(authModalExitTimer);
      authModalExitTimer = null;
    }
    loginView.classList.remove("is-open", "is-leaving", "is-authenticating");
    loginView.classList.add("hidden");
    loginView.setAttribute("aria-hidden", "true");
    loginView.setAttribute("inert", "");
    clearAuthVisualViewport();
  }

  let authVvBound = false;

  function syncAuthVisualViewport() {
    if (!loginView || loginView.classList.contains("hidden")) return;
    const vv = window.visualViewport;
    const h = vv && Number.isFinite(vv.height) ? Math.round(vv.height) : Math.round(window.innerHeight || 0);
    if (h > 0) {
      // Usable height inside modal padding (approx) for panel max-height
      const usable = Math.max(200, h - 16);
      loginView.style.setProperty("--auth-vvh", usable + "px");
      document.documentElement.style.setProperty("--auth-vvh", usable + "px");
      // iOS keeps layout viewport tall while keyboard is open — class, not MQ
      loginView.classList.toggle("is-kb-short", h <= 560);
    }
  }

  function clearAuthVisualViewport() {
    loginView?.classList.remove("is-kb-short");
    loginView?.style.removeProperty("--auth-vvh");
    document.documentElement.style.removeProperty("--auth-vvh");
  }

  function bindAuthVisualViewport() {
    if (authVvBound) {
      syncAuthVisualViewport();
      return;
    }
    authVvBound = true;
    const onVv = () => syncAuthVisualViewport();
    if (window.visualViewport) {
      window.visualViewport.addEventListener("resize", onVv);
      window.visualViewport.addEventListener("scroll", onVv);
    }
    window.addEventListener("resize", onVv);
    if (loginView && !loginView.dataset.authFocusScroll) {
      loginView.dataset.authFocusScroll = "1";
      loginView.addEventListener(
        "focusin",
        (ev) => {
          const t = ev.target;
          if (!(t instanceof HTMLElement)) return;
          if (!t.matches("input, textarea, select, button")) return;
          const panel = loginView.querySelector(".login-panel");
          requestAnimationFrame(() => {
            try {
              t.scrollIntoView({ block: "nearest", inline: "nearest", behavior: "smooth" });
            } catch (_) {
              t.scrollIntoView(false);
            }
            // Extra nudge so affiliate field / CTA clear the keyboard fold
            if (panel && panel.scrollHeight > panel.clientHeight) {
              const pad = 24;
              const tTop = t.getBoundingClientRect().top;
              const tBot = t.getBoundingClientRect().bottom;
              const pTop = panel.getBoundingClientRect().top;
              const pBot = panel.getBoundingClientRect().bottom;
              if (tBot > pBot - pad) panel.scrollTop += tBot - (pBot - pad);
              else if (tTop < pTop + pad) panel.scrollTop -= pTop + pad - tTop;
            }
          });
        },
        true
      );
    }
    syncAuthVisualViewport();
  }

  function revealAuthModal() {
    if (!loginView) return;
    if (authModalExitTimer) {
      clearTimeout(authModalExitTimer);
      authModalExitTimer = null;
    }
    loginView.classList.remove("hidden", "is-leaving", "is-authenticating", "is-open");
    loginView.setAttribute("aria-hidden", "false");
    loginView.removeAttribute("inert");
    bindAuthVisualViewport();
    requestAnimationFrame(() => {
      if (!loginView.classList.contains("hidden") && !loginView.classList.contains("is-leaving")) {
        loginView.classList.add("is-open");
        syncAuthVisualViewport();
        syncVisibleTurnstile();
      }
    });
  }

  function closeAuthModal({ force = false } = {}) {
    if (!loginView || loginView.classList.contains("hidden")) return;
    if (!force && (accessToken || authBusy)) return;

    setWebsiteAuthFormEnabled(false);
    loginView.classList.remove("is-open");
    loginView.classList.add("is-leaving");
    loginView.setAttribute("aria-hidden", "true");

    if (authModalExitTimer) clearTimeout(authModalExitTimer);
    authModalExitTimer = setTimeout(() => {
      authModalExitTimer = null;
      if (loginView.classList.contains("is-leaving")) hideAuthModalImmediately();
    }, AUTH_MODAL_MOTION_MS);
  }

  function applyMailboxUnread(n) {
    mailboxUnread = Math.max(0, Number(n) || 0);
    paintMailboxChrome();
  }

  function paintMailboxChrome() {
    const loggedIn = !!accessToken && !guestWorkspace;
    const btn = $("sidebar-mailbox-btn");
    const modal = $("user-mailbox-modal");
    const open = !!(modal && !modal.classList.contains("hidden"));
    if (btn) {
      btn.classList.toggle("hidden", !loggedIn || isFeatureLocked("mailbox"));
      btn.setAttribute("aria-expanded", open ? "true" : "false");
    }
    const badge = $("sidebar-mailbox-badge");
    const pill = $("mailbox-modal-pill");
    const sub = $("sidebar-mailbox-sub");
    const sum = $("mailbox-modal-sum");
    const show = mailboxUnread > 0;
    const label = formatNumTh(mailboxUnread);
    if (badge) {
      badge.textContent = label;
      badge.classList.toggle("hidden", !show);
    }
    if (pill) {
      pill.textContent = label;
      pill.classList.toggle("hidden", !show);
    }
    if (sub) sub.textContent = show ? "มีของขวัญยังไม่เปิด " + label + " ฉบับ" : "ของจากร้าน / แอดมิน";
    if (sum) sum.textContent = show ? "ยังไม่อ่าน " + label + " ฉบับ" : "ของจากแอดมิน — โหลดได้เฉพาะบัญชีนี้";
  }

  function mailboxDaysLeft(iso) {
    if (!iso) return null;
    const ms = new Date(iso).getTime() - Date.now();
    if (!Number.isFinite(ms)) return null;
    return Math.max(0, Math.ceil(ms / 86400000));
  }

  function mailboxFileSizeLabel(bytes) {
    const n = Number(bytes) || 0;
    if (n >= 1024 * 1024) return formatNumTh(Math.round(n / (1024 * 1024))) + " MB";
    if (n >= 1024) return formatNumTh(Math.round(n / 1024)) + " KB";
    return formatNumTh(n) + " B";
  }

  function mailboxDownloadFilename(header, fallback) {
    const raw = String(header || "");
    const star = /filename\*=UTF-8''([^;]+)/i.exec(raw);
    if (star) {
      try {
        return decodeURIComponent(star[1]);
      } catch (_) {}
    }
    const quoted = /filename="([^"]+)"/i.exec(raw);
    if (quoted) return quoted[1];
    const plain = /filename=([^;]+)/i.exec(raw);
    if (plain) return String(plain[1] || "").trim().replace(/^["']|["']$/g, "");
    return fallback || "download";
  }

  function mailboxUrlLooksValid(raw) {
    try {
      const u = new URL(String(raw || "").trim());
      return u.protocol === "http:" || u.protocol === "https:";
    } catch (_) {
      return false;
    }
  }

  function mailboxEmptyHtml(text) {
    return (
      '<div class="mailbox-empty">' +
      '<span class="mailbox-empty-icon" aria-hidden="true">' +
      '<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">' +
      '<path d="M20 12v8a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-8"/>' +
      '<path d="M12 22V12"/><path d="M2 7h20v5H2z"/><path d="M12 7V3"/><path d="M8 7a4 4 0 0 1 8 0"/>' +
      "</svg></span><p>" +
      escapeHtml(text || "ยังไม่มีของขวัญในช่วงนี้") +
      '</p><span class="mailbox-empty-sub">เมื่อร้านส่งของมา จะโชว์ที่นี่เฉพาะบัญชีคุณ</span></div>'
    );
  }

  function paintUserMailbox() {
    const box = $("mailbox-modal-list");
    if (!box) return;
    if (!mailboxItems.length) {
      box.innerHTML = mailboxEmptyHtml("ยังไม่มีของขวัญในช่วงนี้");
      return;
    }
    box.innerHTML = mailboxItems
      .map((item, index) => {
        const visibleDays = mailboxDaysLeft(item.visible_until);
        const downloadDays = mailboxDaysLeft(item.download_until);
        const reward = item.reward && item.reward.kind ? item.reward : null;
        const meta = reward
          ? item.claimed
            ? "รับแล้ว"
            : item.claim_ok
              ? "กดรับภายใน " + formatNumTh(visibleDays ?? 0) + " วัน"
              : "หมดเวลารับ"
          : item.download_ok
            ? "โหลดได้อีก " + formatNumTh(downloadDays ?? 0) + " วัน"
            : "หมดอายุโหลดแล้ว";
        const show = visibleDays != null && !reward ? " · แสดงอีก " + formatNumTh(visibleDays) + " วัน" : "";
        const claimBtn = !reward
          ? ""
          : item.claimed
            ? '<span class="profile-mailbox-claimed">รับแล้ว</span>'
            : item.claim_ok
              ? '<button type="button" class="btn btn-primary btn-sm" data-mailbox-claim="' +
                escapeHtml(item.id || "") +
                '">' +
                escapeHtml(reward.button || "รับของขวัญ") +
                "</button>"
              : '<span class="profile-mailbox-claimed">หมดเวลารับ</span>';
        const files = (item.attachments || [])
          .map((att) => {
            const isUrl = String(att.kind || "") === "url";
            const disabled = item.download_ok ? "" : " disabled";
            const text = item.download_ok
              ? escapeHtml(att.label || (isUrl ? "เปิดลิงก์" : "ดาวน์โหลด"))
              : "หมดอายุแล้ว";
            return (
              '<button type="button" class="btn btn-ghost btn-sm" data-mailbox-dl="' +
              escapeHtml(att.id || "") +
              '" data-mailbox-kind="' +
              (isUrl ? "url" : "file") +
              '" data-mailbox-label="' +
              escapeHtml(att.label || "download") +
              '" data-mailbox-name="' +
              escapeHtml(att.original_name || att.label || "download") +
              '"' +
              disabled +
              ">" +
              text +
              "</button>"
            );
          })
          .join("");
        return (
          '<article class="profile-mailbox-card' +
          (item.unread ? " is-unread" : "") +
          '" data-mailbox-id="' +
          escapeHtml(item.id || "") +
          '" style="animation-delay:' +
          Math.min(index, 8) * 40 +
          'ms"><h4>' +
          escapeHtml(item.title || "ของขวัญ") +
          (item.unread ? '<span class="profile-mailbox-new">ใหม่</span>' : "") +
          "</h4><p>" +
          escapeHtml(item.body || "") +
          (item.body ? " · " : "") +
          escapeHtml(meta + show) +
          '</p><div class="profile-mailbox-actions">' +
          claimBtn +
          files +
          "</div></article>"
        );
      })
      .join("");
  }

  async function loadUserMailbox() {
    if (!accessToken) return;
    const box = $("mailbox-modal-list");
    if (box && !mailboxItems.length) box.innerHTML = mailboxEmptyHtml("กำลังโหลด…");
    try {
      const data = await api("/api/mailbox");
      mailboxItems = Array.isArray(data?.items) ? data.items : [];
      applyMailboxUnread(data?.unread_count);
      paintUserMailbox();
    } catch (e) {
      if (box && !mailboxItems.length) box.innerHTML = mailboxEmptyHtml("โหลดกล่องไม่สำเร็จ");
      throw e;
    }
  }

  async function markMailboxRead(id) {
    if (!id) return;
    const current = mailboxItems.find((item) => item.id === id);
    if (current && !current.unread) return;
    try {
      await api("/api/mailbox/" + encodeURIComponent(id) + "/read", { method: "POST", body: {} });
      mailboxItems = mailboxItems.map((item) =>
        item.id === id ? { ...item, unread: false } : item
      );
      applyMailboxUnread(mailboxItems.filter((item) => item.unread).length);
      const card = document.querySelector('[data-mailbox-id="' + CSS.escape(id) + '"]');
      if (card) {
        card.classList.remove("is-unread");
        card.querySelector(".profile-mailbox-new")?.remove();
      } else {
        paintUserMailbox();
      }
    } catch (_) {}
  }

  function mailboxOpenExternal(url, popup) {
    const href = String(url || "").trim();
    if (!href) return;
    if (popup && !popup.closed) {
      try {
        popup.opener = null;
      } catch (_) {}
      popup.location.replace(href);
      return;
    }
    const a = document.createElement("a");
    a.href = href;
    a.target = "_blank";
    a.rel = "noopener noreferrer";
    document.body.appendChild(a);
    a.click();
    a.remove();
  }

  async function downloadMailboxAttachment(id, label, kind, filename) {
    if (!id) return;
    const headers = {};
    if (accessToken) headers.Authorization = "Bearer " + accessToken;
    if (sessionToken) headers["X-Session-Token"] = sessionToken;
    let popup = null;
    if (kind === "url") {
      popup = window.open("", "_blank");
      try {
        if (popup) popup.opener = null;
      } catch (_) {}
    }
    try {
      const res = await fetch(API + "/api/mailbox/attachments/" + encodeURIComponent(id) + "/download", {
        headers,
      });
      const ctype = String(res.headers.get("content-type") || "");
      if (!res.ok) {
        if (popup && !popup.closed) popup.close();
        let data = null;
        try {
          data = await res.json();
        } catch (_) {}
        const raw = data?.detail || data?.code || res.statusText || "mailbox_save_failed";
        throw new Error(typeof raw === "string" ? raw : raw.code || "mailbox_save_failed");
      }
      if (ctype.includes("application/json")) {
        const data = await res.json();
        if (data?.url) {
          mailboxOpenExternal(data.url, popup);
          return;
        }
        if (popup && !popup.closed) popup.close();
        return;
      }
      if (popup && !popup.closed) popup.close();
      const blob = await res.blob();
      const name = mailboxDownloadFilename(
        res.headers.get("content-disposition"),
        filename || label || "download"
      );
      const href = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = href;
      a.download = name;
      a.rel = "noopener";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(href), 2000);
    } catch (err) {
      if (popup && !popup.closed) popup.close();
      throw err;
    }
  }

  function mailboxModalCloseMs() {
    return prefersReducedMotion() ? 0 : 200;
  }

  function isMailboxModalOpen() {
    const modal = $("user-mailbox-modal");
    return !!(modal && !modal.classList.contains("hidden") && !modal.classList.contains("is-closing"));
  }

  function openMailboxPanel() {
    if (!requireNavMenuOpen("mailbox")) return;
    const modal = $("user-mailbox-modal");
    if (!modal) return;
    if (mailboxModalCloseTimer) {
      clearTimeout(mailboxModalCloseTimer);
      mailboxModalCloseTimer = null;
    }
    modal.classList.remove("is-closing");
    modal.classList.add("hidden");
    void modal.offsetWidth;
    modal.classList.remove("hidden");
    modal.setAttribute("aria-hidden", "false");
    paintMailboxChrome();
    loadUserMailbox().catch((e) => showToast(thError(e.message) || "โหลดกล่องไม่สำเร็จ", "err"));
  }

  function closeMailboxModal() {
    const modal = $("user-mailbox-modal");
    if (!modal || modal.classList.contains("hidden") || modal.classList.contains("is-closing")) return;
    modal.classList.add("is-closing");
    mailboxModalCloseTimer = setTimeout(() => {
      mailboxModalCloseTimer = null;
      modal.classList.add("hidden");
      modal.classList.remove("is-closing");
      modal.setAttribute("aria-hidden", "true");
      paintMailboxChrome();
    }, mailboxModalCloseMs());
  }

