  let pipelineState = null;

  function modeConfig(mode) {
    if (mode === "invite_friend") return MODE_STATUS.invite;
    return MODE_STATUS[mode] || MODE_STATUS.partyrun;
  }

  function pipelineStepsFor(mode) {
    const steps = (modeConfig(mode).steps || []).map((s) => ({ ...s }));
    if (mode === "powder" && powderJobWantsUpgrade9()) {
      const extractAt = steps.findIndex((s) => s.id === "extract");
      if (extractAt >= 0 && !steps.some((s) => s.id === "upgrade")) {
        steps.splice(extractAt, 0, { id: "upgrade", label: "ตีบวกถึง +9" });
      }
    }
    return steps;
  }

  function powderJobWantsUpgrade9() {
    const params =
      liveJob?.params ||
      statusContext?.params ||
      (typeof liveJob === "object" && liveJob?.result?.upgrade_to_9 ? { upgrade_to_9: true } : null);
    if (params && params.upgrade_to_9 === true) return true;
    if (params && params.upgrade_to_9 === false) return false;
    return !!$("powder-upgrade-9")?.checked;
  }

  const LOG_PANEL_MAX = 280;

  function truncateLogLine(text, maxLen) {
    const s = String(text || "").trim();
    if (!s) return "";
    const limit = maxLen || LOG_PANEL_MAX;
    if (s.length <= limit) return s;
    return s.slice(0, limit - 1) + "…";
  }

  function sanitizeDisplayError(raw, fallback) {
    if (!raw && fallback) return thError(fallback);
    if (typeof raw === "object" && raw !== null) {
      const code = raw.error || raw.detail || raw.message || "";
      return thError(String(code || fallback || ""));
    }
    return thError(String(raw || fallback || ""));
  }

  function parseProgressFromLogs(rawLogs, mode, targetHint) {
    const lines = (Array.isArray(rawLogs) ? rawLogs : [])
      .map((l) => String(l || "").trim())
      .filter(Boolean);
    const out = {
      current: 0,
      total: Number(targetHint) || 0,
      phase: "start",
      lines: [],
      stepIdx: 0,
    };

    for (const s of lines) {
      const friendly = formatLogLine(s, mode);
      if (friendly) {
        if (typeof friendly === "string") out.lines.push({ text: friendly, kind: "ok" });
        else out.lines.push(friendly);
      }

      if (mode === "partyrun") {
        const m = s.match(/\[round\s+(\d+)\/(\d+)\]/i);
        if (m) {
          out.current = Number(m[1]);
          out.total = Number(m[2]);
          out.phase = "run";
          out.stepIdx = 3;
        }
        if (/LOGIN OK|login ok/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 1);
        if (/clearing pending|cleared pending/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 2);
        if (/matchmaking|ingame_id/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 2);
        if (/playing \+|submitted run_end/i.test(s)) {
          out.phase = "run";
          out.stepIdx = 3;
        }
        if (/claiming reward|REWARD CLAIMED/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 4);
      } else if (mode === "giftdraw") {
        const m = s.match(/giftdraw\s+\[(\d+)\/(\d+)\]/i);
        if (m) {
          out.current = Number(m[1]);
          out.total = Number(m[2]);
          out.phase = "open";
          out.stepIdx = 1;
        }
        if (/login|initMember/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
      } else if (mode === "heart") {
        let m = s.match(/heartloop:\s*(\d+)\s*\/\s*(\d+)\s*\((\d+)\s*%\)/i);
        if (m) {
          out.current = Math.max(out.current, Number(m[1]));
          out.total = Number(m[2]) || out.total;
          out.phase = Number(m[1]) > 0 ? "send" : out.phase;
          out.stepIdx = Math.max(out.stepIdx, Number(m[1]) > 0 ? 1 : 0);
        }
        m = s.match(/session\s+\d+\s+done:\s*\+(\d+)\s+total\s+(\d+)\/(\d+)/i);
        if (m) {
          out.current = Math.max(out.current, Number(m[2]));
          out.total = Number(m[3]) || out.total;
          out.phase = "collect";
          out.stepIdx = Math.max(out.stepIdx, 2);
        }
        m = s.match(/\btotal\s+(\d+)\/(\d+)/i);
        if (m) {
          out.current = Math.max(out.current, Number(m[1]));
          out.total = Number(m[2]) || out.total;
          out.phase = "collect";
          out.stepIdx = Math.max(out.stepIdx, 2);
        }
        m = s.match(/claimed\s+(\d+)\s+mail/i);
        if (m) {
          out.phase = "collect";
          out.stepIdx = Math.max(out.stepIdx, 2);
        }
        if (/login receiver|เข้าสู่ระบบ/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
        if (/using\s+\d+|unused helpers|ส่งหัวใจ|skip login|skip send/i.test(s)) {
          out.phase = out.phase === "start" ? "send" : out.phase;
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
        if (/SendLife|AcceptLife|sending life/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 1);
      } else if (mode === "powder") {
        // Real backend: "[i/count] BUY …" then optional upgrade then "  BREAK OK powder+P".
        const up9 = powderJobWantsUpgrade9();
        let m = s.match(/\[(\d+)\/(\d+)\]\s+(?:BUY|ซื้อ)\b/i);
        if (m) {
          out.current = Number(m[1]);
          out.total = Number(m[2]);
          out.phase = "buy";
          out.stepIdx = 1;
        }
        m = s.match(/ซื้อ\s+(\d+)\s+กล่อง/i);
        if (m && Number(m[1]) > 1 && out.current) {
          out.phase = "buy";
          out.stepIdx = 1;
        }
        if (/powder:\s*upgrade/i.test(s)) {
          out.phase = "upgrade";
          out.stepIdx = Math.max(out.stepIdx, up9 ? 2 : 1);
        }
        m = s.match(/\[(\d+)\]\s+\+\d+\s+powder\s+gained=(\d+)\/(\d+)/i);
        if (m) {
          out.current = Number(m[1]);
          out.total = Number(m[3]);
          out.phase = "extract";
          out.stepIdx = up9 ? 3 : 2;
        }
        if (/ย่อย\s+\d+\s+ชิ้น|BREAK\s+OK|powder\+/i.test(s)) out.stepIdx = Math.max(out.stepIdx, up9 ? 3 : 2);
        if (/powder:\s*login|loading/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
      } else if (mode === "upgrade") {
        let line = s;
        let m = s.match(/^\[(\d+)\/(\d+)\]\s+(.+?)\s+—\s+(.+)$/);
        if (m) {
          out.total = Number(m[2]);
          out.phase = "items";
          out.stepIdx = 1;
          if (statusContext) {
            statusContext.itemIndex = Number(m[1]);
            statusContext.itemTotal = Number(m[2]);
            statusContext.itemName = m[3].trim();
          }
          line = m[4];
        }
        m = line.match(/upgrade batch:\s*item\s+(\d+)\/(\d+)\s+—\s+(.+)/i);
        if (m) {
          out.current = Math.max(0, Number(m[1]) - 1);
          out.total = Number(m[2]);
          out.phase = "items";
          out.stepIdx = 1;
          if (statusContext) {
            statusContext.itemIndex = Number(m[1]);
            statusContext.itemTotal = Number(m[2]);
            statusContext.itemName = m[3].trim();
            statusContext.itemsCompleted = Math.max(0, Number(m[1]) - 1);
          }
        }
        if (/upgrade:\s*done\s+/i.test(line)) {
          out.stepIdx = Math.max(out.stepIdx, 1);
          const doneCount = lines.filter((l) => /upgrade:\s*done\s+/i.test(String(l))).length;
          if (doneCount > 0) {
            out.current = doneCount;
            out.phase = "items";
            if (statusContext) statusContext.itemsCompleted = doneCount;
          }
        }
        if (/upgrade:\s*refresh|initMember/i.test(line)) out.stepIdx = Math.max(out.stepIdx, 0);
      } else if (mode === "cookie_unlock") {
        let m = s.match(/cookie-unlock batch:\s*item\s+(\d+)\/(\d+)\s+—\s+(.+)/i);
        if (m) {
          const name = m[3].trim();
          out.current = Math.max(0, Number(m[1]) - 1);
          out.total = Number(m[2]);
          out.phase = name.toLowerCase() === "prepare" ? "start" : "items";
          out.stepIdx = name.toLowerCase() === "prepare" ? 0 : 1;
          if (statusContext && name.toLowerCase() !== "prepare") {
            statusContext.itemIndex = Number(m[1]);
            statusContext.itemTotal = Number(m[2]);
            statusContext.itemName = name;
            statusContext.itemsCompleted = Math.max(0, Number(m[1]) - 1);
          }
        }
        m = s.match(/cookie-unlock:\s*start\s+(.+?)(?:\s+\(|$)/i);
        if (m && statusContext) {
          statusContext.itemName = m[1].trim();
          out.phase = "items";
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
        if (/cookie-unlock:\s*done\s+/i.test(s)) {
          out.stepIdx = Math.max(out.stepIdx, 1);
          const doneCount = lines.filter((l) => /cookie-unlock:\s*done\s+/i.test(String(l))).length;
          if (doneCount > 0) {
            out.current = doneCount;
            out.phase = "items";
            if (statusContext) statusContext.itemsCompleted = doneCount;
          }
          m = s.match(/cookie-unlock:\s*done\s+(.+)/i);
          if (m && statusContext) statusContext.itemName = m[1].trim();
        }
        if (/cookie-unlock:\s*refresh|initMember|prepare/i.test(s)) {
          out.stepIdx = Math.max(out.stepIdx, 0);
        }
        let cm = s.match(/cookie\s+\[(\d+)\/(\d+)\]/i);
        if (cm) {
          out.current = Number(cm[1]);
          out.total = Number(cm[2]) || out.total;
          out.phase = "items";
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
        if (/cookie:\s*initMember/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
      } else if (mode === "jelly_upgrade") {
        if (/jelly:\s*initMember/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
        const jm = s.match(/jelly\s+\[(\d+)\/(\d+)\]/i);
        if (jm) {
          out.current = Number(jm[1]);
          out.total = Number(jm[2]) || out.total;
          out.phase = "upgrade";
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
      } else if (mode === "pet_unlock") {
        if (/pet:\s*initMember/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
        const pm = s.match(/pet\s+\[(\d+)\/(\d+)\]/i);
        if (pm) {
          out.current = Number(pm[1]);
          out.total = Number(pm[2]) || out.total;
          out.phase = "draw";
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
      } else if (mode === "afterplay_fast") {
        if (/login ok|initMember|อ่านไอดี/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
        if (/play_time|รอ\s*\d+s|waiting/i.test(s)) {
          out.phase = "wait";
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
        const runM = s.match(/run\s*(\d+)\s*\/\s*(\d+)/i) || s.match(/รอบ\s*(\d+)\s*\/\s*(\d+)/);
        if (runM) {
          out.current = Number(runM[1]);
          out.total = Number(runM[2]) || out.total;
          out.phase = "run";
          out.stepIdx = Math.max(out.stepIdx, 2);
        } else if (/afterplay|ส่งรอบ|code[=:]?\s*20[01]/i.test(s)) {
          out.phase = "run";
          out.stepIdx = Math.max(out.stepIdx, 2);
        }
      } else if (mode === "unlock_l") {
        if (/login ok|initMember/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
        if (/unlock|ปลด/i.test(s)) {
          out.phase = "unlock";
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
      } else if (mode === "ice_tower") {
        if (/login ok|initMember/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
        if (/floor|ชั้น|climb/i.test(s)) {
          out.phase = "climb";
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
      } else if (mode === "friend") {
        if (/login ok|initMember/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
        if (/friend|เพื่อน/i.test(s)) {
          out.phase = "friends";
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
      } else if (mode === "invite" || mode === "invite_friend") {
        if (/queued|job /i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
        if (/invite|เชิญ|guest/i.test(s)) {
          out.phase = "invite";
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
      } else if (mode === "treasure_evo") {
        if (/evo:\s*initMember|scanning inventory/i.test(s)) out.stepIdx = Math.max(out.stepIdx, 0);
        if (/farm powder|powder farm/i.test(s)) {
          out.phase = "powder";
          out.stepIdx = Math.max(out.stepIdx, 1);
        }
        if (/evo:\s*craft/i.test(s)) {
          out.phase = "craft";
          out.stepIdx = Math.max(out.stepIdx, 2);
        }
        const itemM = s.match(/evo \[(\d+)\/(\d+)\]/i);
        if (itemM) {
          out.current = Number(itemM[1]);
          out.total = Number(itemM[2]) || out.total;
          out.phase = /FAIL/i.test(s) ? "evo" : "evo";
          out.stepIdx = Math.max(out.stepIdx, 3);
        }
        if (/evo:\s*miss|evo:\s*hit/i.test(s)) {
          out.phase = "evo";
          out.stepIdx = Math.max(out.stepIdx, 3);
        }
      }
    }

    if (!out.total && targetHint) out.total = Number(targetHint) || 0;
    return out;
  }

  const LOG_EMAIL_RE = /[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g;

  function redactLogText(raw) {
    return String(raw || "")
      .replace(LOG_EMAIL_RE, "••••")
      .replace(/\bskip login\s+\S+/gi, "ข้ามไอดีที่ใช้ไม่ได้")
      .replace(/\bskip send\s+\S+/gi, "ข้ามการส่ง")
      .replace(/\blogin receiver\s+\S+/gi, "เข้าสู่ระบบไอดีที่เชื่อมอยู่")
      .trim();
  }

  function formatLogLine(raw, mode) {
    const s = redactLogText(raw);
    if (!s) return "";
    if (/traceback|RpcError|Exception|at 0x/i.test(s)) {
      if (/ProxyError|RemoteDisconnected|Max retries|HTTPSConnectionPool|ProtocolError/i.test(s)) {
        return "ต่อเกมไม่ติด — พร็อกซีหรือเซิร์ฟเกมหลุดระหว่างสุ่มสมบัติ (ไม่ใช่ไอดีพัง) ลองเริ่มใหม่";
      }
      return "";
    }
    const translated = translateLog(s);
    if (mode === "cookie_unlock" && /cookie-unlock/i.test(s)) {
      const text = truncateLogLine(translated || s, 160);
      if (/failed|skip.+coin/i.test(s)) return { text, kind: "err" };
      if (/skip/i.test(s)) return { text, kind: "warn" };
      if (/done|OK/i.test(s)) return { text, kind: "ok" };
      return { text, kind: "ok" };
    }
    if (mode === "quest_claim" && /quest/i.test(s)) {
      const text = truncateLogLine(translated || s, 160);
      if (/ERR|failed/i.test(s)) return { text, kind: "err" };
      if (/OK/i.test(s)) return { text, kind: "ok" };
      return { text, kind: "ok" };
    }
    if (mode === "treasure_evo" && /evo/i.test(s)) {
      const text = truncateLogLine(translated || s, 160);
      if (/FAIL|failed|ERR/i.test(s)) return { text, kind: "err" };
      if (/miss/i.test(s)) return { text, kind: "warn" };
      if (/hit|OK|craft /i.test(s)) return { text, kind: "ok" };
      return { text, kind: "ok" };
    }
    if (translated && translated !== s) return truncateLogLine(translated, 160);
    if (mode === "partyrun" && /\[round\s+(\d+)\/(\d+)\]/i.test(s)) {
      const m = s.match(/\[round\s+(\d+)\/(\d+)\]/i);
      const tail = s.replace(/\[round\s+\d+\/\d+\]\s*/i, "");
      let detail = truncateLogLine(tail, 200);
      const coinM = tail.match(/coin[=:]?\s*([+\-]?\d+)/i);
      const expM = tail.match(/exp[=:]?\s*([+\-]?\d+)/i);
      if (coinM || expM) {
        detail =
          (coinM ? "เหรียญ " + coinM[1] : "") +
          (coinM && expM ? " · " : "") +
          (expM ? "EXP " + expM[1] : "");
      }
      return "รอบ " + m[1] + "/" + m[2] + (detail ? " — " + detail : "");
    }
    if (mode === "giftdraw" && /giftdraw\s+\[(\d+)\/(\d+)\]/i.test(s)) {
      const m = s.match(/giftdraw\s+\[(\d+)\/(\d+)\]:\s*(.+)/i);
      if (m) {
        const detail = formatGiftDrawRewardText(m[3]);
        return (
          "กล่อง " +
          m[1] +
          "/" +
          m[2] +
          " — " +
          truncateLogLine(detail, 220)
        );
      }
    }
    if (mode === "giftdraw" && /gift|box|reward|item/i.test(s)) {
      const labeled = formatGiftDrawRewardText(translated || s);
      return truncateLogLine(labeled, LOG_PANEL_MAX);
    }
    if (mode === "heart") {
      if (/heartloop:\s*(\d+)\s*\/\s*(\d+)\s*\((\d+)\s*%\)/i.test(s)) {
        const m = s.match(/heartloop:\s*(\d+)\s*\/\s*(\d+)\s*\((\d+)\s*%\)/i);
        return "ได้หัวใจ " + formatNumTh(m[1]) + "/" + formatNumTh(m[2]) + " · " + m[3] + "%";
      }
      if (/TOTAL\s+(\d+)\/(\d+)/i.test(s)) {
        const m = s.match(/TOTAL\s+(\d+)\/(\d+)/i);
        return "รวมได้หัวใจ " + formatNumTh(m[1]) + "/" + formatNumTh(m[2]);
      }
      if (/heart[s]?\s*\+(\d+)/i.test(s)) {
        const m = s.match(/heart[s]?\s*\+(\d+)/i);
        return "ได้หัวใจ +" + formatNumTh(m[1]);
      }
      if (/SESSION\s+\d+\s+done/i.test(s)) return truncateLogLine(s, LOG_PANEL_MAX);
    }
    if (mode === "powder") {
      if (/\[(\d+)\]\s+\+(\d+)\s+powder\s+gained=(\d+)\/(\d+)/i.test(s)) {
        const m = s.match(/\[(\d+)\]\s+\+(\d+)\s+powder\s+gained=(\d+)\/(\d+)/i);
        if (m) {
          return (
            "รอบ " +
            m[1] +
            " +" +
            formatNumTh(m[2]) +
            " ผง (รวม " +
            formatNumTh(m[3]) +
            "/" +
            formatNumTh(m[4]) +
            ")"
          );
        }
      }
      if (/BUY\s+OK|ซื้อ\s+\d+\s+กล่อง/i.test(s)) return { text: truncateLogLine(translated || s, LOG_PANEL_MAX), kind: "ok" };
      if (/ย่อย\s+\d+\s+ชิ้น|BREAK\s+OK|powder\+/i.test(s)) {
        return { text: truncateLogLine(translated || s, LOG_PANEL_MAX), kind: "ok" };
      }
      if (/BUY\s+ERR|BREAK\s+ERR/i.test(s)) {
        return { text: truncateLogLine(translated || s, LOG_PANEL_MAX), kind: "err" };
      }
      if (/powder:\s*upgrade\s+OK/i.test(s)) {
        return { text: truncateLogLine(translated || s, LOG_PANEL_MAX), kind: "ok" };
      }
      if (/powder:\s*upgrade\s+(ERR|FAIL|out_of_coins|skip)/i.test(s)) {
        return { text: truncateLogLine(translated || s, LOG_PANEL_MAX), kind: "warn" };
      }
      if (/powder:\s*upgrade/i.test(s)) {
        return { text: truncateLogLine(translated || s, LOG_PANEL_MAX), kind: "ok" };
      }
    }
    if (mode === "upgrade") {
      let line = s;
      let prefix = "";
      let pm = s.match(/^\[(\d+)\/(\d+)\]\s+(.+?)\s+—\s+(.+)$/);
      if (pm) {
        prefix = "[" + pm[1] + "/" + pm[2] + "] " + truncateLogLine(pm[3], 40) + " — ";
        line = pm[4];
      }
      let m = line.match(/upgrade batch:\s*item\s+(\d+)\/(\d+)\s+—\s+(.+)/i);
      if (m) {
        const txt = "📦 ชิ้นที่ " + m[1] + "/" + m[2] + ": " + truncateLogLine(m[3], 80);
        return { text: prefix ? prefix + txt : txt, kind: "item" };
      }
      m = line.match(/upgrade batch:\s*FAST/i);
      if (m) return { text: "⚡ โหมด Fast — ตีบวกพร้อมกัน (เสี่ยง ID ถูกระงับ)", kind: "warn" };
      m = line.match(/upgrade\s+\[(\d+)\]\s+(.+?)\s+SUCCESS\s+→\s+\+(\d+)/i);
      if (m) {
        return { text: prefix + "ครั้งที่ " + m[1] + ": ✅ ติด → +" + m[3], kind: "ok" };
      }
      m = line.match(/upgrade\s+\[(\d+)\]\s+(.+?)\s+FAIL\s+stay\s+\+(\d+)/i);
      if (m) {
        return {
          text: prefix + "ครั้งที่ " + m[1] + ": ❌ แห้ว (คงที่ +" + m[3] + ")",
          kind: "err",
        };
      }
      m = line.match(/upgrade\s+\[(\d+)\]\s+(.+?)\s+\+(\d+)→\+(\d+)/i);
      if (m) {
        return { text: prefix + "ครั้งที่ " + m[1] + ": +" + m[3] + "→+" + m[4] + " …", kind: "warn" };
      }
      m = line.match(/upgrade:\s*done\s+(.+?)\s+\+(\d+)→\+(\d+)/i);
      if (m) {
        return {
          text: prefix + "สรุป " + truncateLogLine(m[1], 50) + ": +" + m[2] + "→+" + m[3],
          kind: "ok",
        };
      }
      if (/coin ไม่พอ/i.test(line)) return { text: prefix + truncateLogLine(line, 140), kind: "err" };
      if (/upgrade batch:\s*หยุด/i.test(line)) {
        return { text: prefix + truncateLogLine(line, 140), kind: "warn" };
      }
      if (/upgrade\s+\[/i.test(line)) return { text: prefix + truncateLogLine(line, 140), kind: "warn" };
    }
    if (s.length > LOG_PANEL_MAX + 40 || /^\{/.test(s)) return "";
    return truncateLogLine(s, LOG_PANEL_MAX);
  }

  // Game-art icon (assets/gi/*.png, 64px) used in place of resource emoji in HTML.
  function gi(name, extra) {
    return '<img class="gi' + (extra ? " " + extra : "") + '" src="assets/gi/' + name + '.png" alt="" width="18" height="18" loading="lazy" decoding="async" />';
  }

  function formatNumTh(n) {
    const num = Number(n);
    if (!Number.isFinite(num)) return String(n ?? "");
    return String(Math.trunc(num)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  }

  function formatCredit(n) {
    const num = Number(n);
    if (!Number.isFinite(num)) return String(n ?? "");
    const rounded = Math.round(num * 100) / 100;
    const [intPart, frac] = rounded.toFixed(2).split(".");
    const grouped = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    if (frac === "00") return grouped;
    if (frac.endsWith("0")) return grouped + "." + frac.slice(0, 1);
    return grouped + "." + frac;
  }

  function setRunStatusSubtitle(done, ok) {
    if (done) {
      dockOk = ok !== false;
      dockPhase = ok !== false ? "done" : "error";
    }
    renderFarmDock();
  }

  function setRunStatusTitle(mode) {
    if (statusContext) statusContext.mode = mode;
    renderFarmDock({ mode });
  }

  function dockIncompletePhrase(cur, tot) {
    const afterplay = (liveJob?.mode || statusContext?.mode) === "afterplay_fast";
    const prefix = afterplay ? "สำเร็จบางส่วน" : "จบกลางคัน";
    if (afterplay && tot > 0) {
      return prefix + " " + formatNumTh(cur) + "/" + formatNumTh(tot);
    }
    return prefix;
  }

  function dockPhaseLabel(phase) {
    if (phase === "queued") {
      return queueRankChipText(lastGate, "queued") || "รอคิว";
    }
    if (phase === "running") return "กำลังดำเนินการ";
    if (phase === "done") return "สำเร็จ";
    if (phase === "error") return liveJob?.incomplete ? dockIncompletePhrase() : "ล้มเหลว";
    if (phase === "idle") return "ว่าง";
    return "—";
  }

  function progressUnit(mode) {
    if (mode === "giftdraw") return "กล่อง";
    if (mode === "heart" || mode === "heart_free") return "ดวง";
    if (mode === "upgrade") return "ชิ้น";
    if (mode === "jelly_upgrade") return "ขั้น";
    if (mode === "cookie_unlock") return "ตัว";
    if (mode === "pet_unlock") return "ครั้ง";
    if (mode === "powder") return "รอบ";
    if (mode === "afterplay_fast") return "รอบ";
    if (mode === "unlock_l") return "ตัว";
    if (mode === "ice_tower") return "ชั้น";
    if (mode === "friend") return "คน";
    if (mode === "invite" || mode === "invite_friend") return "คน";
    return "รอบ";
  }

  function jobTitleForMode(mode, extras) {
    extras = extras || {};
    const fromRow = extras.row;
    if (mode === "giftdraw") return "เปิดกล่องขวัญ";
    if (mode === "partyrun") return "Party Run";
    if (mode === "heart") {
      if (extras.free_mode || extras.row?.params?.free_mode || extras.row?.result?.free_mode) {
        return "หัวใจฟรี 100";
      }
      return "ฟาร์มหัวใจ";
    }
    if (mode === "heart_free") return "ฟาร์มหัวใจ (ฟรี)";
    if (mode === "jelly_upgrade") return "อัปเกรด Jelly";
    if (mode === "cookie_unlock") return "ปลดล็อก Cookie";
    if (mode === "pet_unlock") return "ปลดล็อก Pet";
    if (mode === "powder") {
      const p = extras.row?.params || extras.row?.result || {};
      if (p.upgrade_to_9) return "ฟาร์มผง · ตี +9 ก่อนย่อย";
      return "ฟาร์มผง";
    }
    if (mode === "upgrade") return "ตีบวกสมบัติ";
    if (mode === "afterplay_fast") {
      const fam =
        extras.family ||
        afterplayFamilyFromJob(fromRow) ||
        (fromRow ? "" : statusContext?.family || liveJob?.family || afterplayFamily);
      if (fam) return afterplayFamilyMeta(fam)?.title || "ฟาร์ม Afterplay";
      return "ฟาร์มเงิน / XP / กล่อง";
    }
    if (mode === "unlock_l") {
      const ep =
        Number(extras.ep) ||
        (fromRow ? unlockLDisplayEp(fromRow) : 0) ||
        (fromRow ? 0 : Number(statusContext?.unlockEp || liveJob?.unlockEp) || 0);
      if (ep) return "ปลดล็อค L · " + unlockLEpShortName(ep);
      return "ปลดล็อค L";
    }
    if (mode === "ice_tower") return "Ice Tower";
    if (mode === "friend") return "เพื่อน";
    if (mode === "invite" || mode === "invite_friend") return "เชิญเพื่อน";
    return "ฟาร์ม";
  }

  function formatDockElapsed(sec) {
    const n = Math.max(0, Math.floor(Number(sec) || 0));
    if (n < 60) return n + " วิ";
    const m = Math.floor(n / 60);
    const s = n % 60;
    return m + " นาที " + s + " วิ";
  }

  function parseJobClockMs(ts) {
    if (ts == null || ts === "") return null;
    if (typeof ts === "number" && Number.isFinite(ts)) return ts > 1e12 ? ts : ts * 1000;
    const ms = Date.parse(ts);
    return Number.isFinite(ms) ? ms : null;
  }

  function adoptDockClockFromJob(jobRow) {
    if (!jobRow) return;
    const status = String(jobRow.status || "").toLowerCase();
    const startIso =
      status === "queued"
        ? jobRow.created_at || jobRow.started_at
        : jobRow.started_at || jobRow.created_at;
    const startMs = parseJobClockMs(startIso);
    if (startMs) dockJobStartedAt = startMs;
    const finMs = parseJobClockMs(jobRow.finished_at);
    if (finMs) dockJobFinishedAt = finMs;
    const elapsed = Number(jobRow.elapsed_sec);
    if (Number.isFinite(elapsed) && elapsed >= 0) {
      dockServerElapsedSec = elapsed;
      if (
        (status === "succeeded" || status === "failed" || status === "cancelled") &&
        startMs &&
        !finMs
      ) {
        dockJobFinishedAt = startMs + elapsed * 1000;
      }
    }
  }

  function dockJobStartedMs() {
    if (!dockJobStartedAt) return null;
    const ms =
      typeof dockJobStartedAt === "number"
        ? dockJobStartedAt
        : Date.parse(dockJobStartedAt);
    return Number.isFinite(ms) ? ms : null;
  }

  function freezeDockJobElapsedIfTerminal(phase) {
    if ((phase === "done" || phase === "error") && dockJobStartedMs() && !dockJobFinishedAt) {
      dockJobFinishedAt = Date.now();
      stopDockElapsedTimer();
    }
  }

  function computeDockElapsedSec(phase) {
    const terminal = phase === "done" || phase === "error";
    if (
      terminal &&
      dockServerElapsedSec != null &&
      Number.isFinite(Number(dockServerElapsedSec))
    ) {
      return Math.max(0, Math.floor(Number(dockServerElapsedSec)));
    }
    const startedMs = dockJobStartedMs();
    if (!startedMs) {
      return dockServerElapsedSec != null
        ? Math.max(0, Math.floor(Number(dockServerElapsedSec) || 0))
        : 0;
    }
    if (
      phase !== "running" &&
      phase !== "done" &&
      phase !== "error" &&
      phase !== "queued"
    ) {
      return 0;
    }
    freezeDockJobElapsedIfTerminal(phase);
    const endMs = terminal && dockJobFinishedAt ? dockJobFinishedAt : Date.now();
    return Math.max(0, Math.floor((endMs - startedMs) / 1000));
  }

  function formatDockStartedAt(ts) {
    if (!ts) return "";
    try {
      const d = ts instanceof Date ? ts : new Date(ts);
      if (Number.isNaN(d.getTime())) return "";
      const parts = new Intl.DateTimeFormat("th-TH", {
        timeZone: "Asia/Bangkok",
        day: "numeric",
        month: "short",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
      }).formatToParts(d);
      const get = (type) => parts.find((p) => p.type === type)?.value || "";
      const day = get("day");
      const month = get("month");
      const year = get("year");
      const hh = String(get("hour")).padStart(2, "0");
      const mm = String(get("minute")).padStart(2, "0");
      if (!day || !hh) return "";
      return day + " " + month + " " + year + " · " + hh + ":" + mm + " น.";
    } catch (_) {
      return "";
    }
  }

  function stopDockElapsedTimer() {
    if (dockElapsedTimer) {
      clearInterval(dockElapsedTimer);
      dockElapsedTimer = null;
    }
  }

  function startDockElapsedTimer() {
    stopDockElapsedTimer();
    dockElapsedTimer = setInterval(() => {
      if (document.hidden) return;
      if (dockPhase !== "running" && dockPhase !== "queued") {
        stopDockElapsedTimer();
        return;
      }
      // Patch elapsed text only — avoid full dock rebuild every second.
      const el = document.querySelector(
        "#farm-dock-list .farm-dock-tx[data-live='1'] .farm-dock-tx-time"
      );
      if (dockJobStartedAt) {
        const startedMs = dockJobStartedMs();
        const startedFmt = formatDockStartedAt(dockJobStartedAt) || "";
        if (startedMs) {
          const sec = computeDockElapsedSec(dockPhase || "running");
          const remainWait = remainingEtaLabel();
          const line = startedFmt
            ? startedFmt + " · " + formatDockElapsed(sec) + (remainWait ? " · " + remainWait : "")
            : formatDockElapsed(sec) + (remainWait ? " · " + remainWait : "");
          if (el) el.textContent = line;
          // Keep the centered popup's live timer ticking too.
          if (liveStatusOpen) {
            const popTime = $("live-status-time");
            const popPhase = $("live-status-phase");
            if (popTime) popTime.textContent =
              "ใช้เวลา " + formatDockElapsed(sec) + (remainWait ? " · " + remainWait : "");
            if (popPhase && dockPhase === "running") {
              const cur = String(popPhase.textContent || "").replace(/\s*[·•]\s*\d+.*$/, "").trim();
              if (!cur || /กำลังดำเนินการ/.test(cur)) {
                popPhase.textContent = "กำลังดำเนินการ";
              }
            }
          }
          if (el || liveStatusOpen) return;
        }
      }
      scheduleRenderFarmDock({ reason: "elapsed" });
    }, 1000);
  }

  function dockModeIcon(mode) {
    if (mode === "afterplay_fast") {
      const fam = statusContext?.family || liveJob?.family || afterplayFamily;
      const icon = AFTERPLAY_FAMILY_NAV.find((row) => row.family === fam)?.icon;
      if (icon) return icon;
    }
    if (mode === "unlock_l") {
      const ep =
        Number(statusContext?.unlockEp || liveJob?.unlockEp) ||
        Number((statusContext?.unlockEps || liveJob?.unlockEps || [])[0]) ||
        0;
      return unlockLEpImage(ep).replace(/^assets\//, "");
    }
    const cfg = modeConfig(mode);
    const hero = cfg.heroIcon || "assets/cookie_run.gif";
    return hero.replace(/^assets\//, "") || "cookie_run.gif";
  }

  function resolveMediaSrc(urlOrFile) {
    const raw = String(urlOrFile || "").trim();
    if (!raw) return "";
    if (/^https?:\/\//i.test(raw) || raw.startsWith("data:") || raw.startsWith("blob:")) {
      return raw;
    }
    const path = raw.startsWith("assets/") ? raw : "assets/" + raw.replace(/^assets\//, "");
    return typeof window.ckrHostedAsset === "function" ? window.ckrHostedAsset(path) : path;
  }

  function currentCookieThumb(mode) {
    if (mode !== "cookie_unlock") return null;
    const thumbs = Array.isArray(statusContext?.cookieThumbs)
      ? statusContext.cookieThumbs
      : [];
    if (!thumbs.length) return null;
    const want = String(statusContext?.itemName || "").trim().toLowerCase();
    if (want) {
      const hit = thumbs.find(
        (t) => String(t.name || "").trim().toLowerCase() === want
      );
      if (hit) return hit;
    }
    const idx = Math.max(0, (Number(statusContext?.itemIndex) || 1) - 1);
    return thumbs[Math.min(idx, thumbs.length - 1)] || thumbs[0];
  }

  function buildDockSnapshot(opts = {}) {
    let phase = opts.phase || dockPhase || "idle";
    const curVal = Number(pipelineState?.progress?.current) || 0;
    if (phase === "queued" && (curVal > 0 || (pipelineState?.mode && liveJob && !liveJob.finished))) {
      phase = "running";
    }
    const activeMode =
      opts.mode ||
      (liveJob && !liveJob.finished && liveJob.mode) ||
      (phase !== "idle" && pipelineState?.mode) ||
      (phase !== "idle" && liveJob && liveJob.mode) ||
      (phase !== "idle" && statusContext?.mode) ||
      (pendingFarmJobs[0] && pendingFarmJobs[0].mode) ||
      null;
    const idleEmpty = phase === "idle" && !activeMode;
    const mode = activeMode || (idleEmpty ? null : "partyrun");

    if (idleEmpty) {
      const nick = devplaySession?.nickname
        ? " · ไอดี " + devplaySession.nickname
        : "";
      return {
        phase: "idle",
        mode: null,
        ok: null,
        panelSub: "เลือกฟีเจอร์แล้วกดรันเมื่อพร้อม",
        progress: { current: 0, total: 0, pct: 0 },
        queue: Array.isArray(lastGate?.queue_items) ? lastGate.queue_items : [],
        jobTitle: "ไม่มีงาน",
        jobDetail: "ไม่มีงานที่กำลังรัน" + nick,
        timeLine: "",
        statusBadge: "ว่าง",
        statusLineText: "ไม่มีงาน",
        fractionText: "—",
        unit: "",
        progressLabel: "",
        elapsedSec: 0,
        steps: [],
        stepKinds: {},
        logLines: [],
        iconUrl: resolveMediaSrc("devplay.png?v=20260817d"),
        cookieThumbs: [],
        currentCookieName: "",
        showLive: false,
        idleEmpty: true,
      };
    }

    const cfg = modeConfig(mode);
    const ok = opts.ok !== undefined ? opts.ok : dockOk;

    const prog = pipelineState?.progress || {};
    let cur = Number(prog.current) || 0;
    let tot =
      Number(prog.total) ||
      Number(opts.target) ||
      Number(statusContext?.target) ||
      0;

    if (phase === "done" && ok !== false && tot > 0 && cur < tot) cur = tot;

    const pct =
      tot > 0
        ? Math.min(100, Math.round((cur / tot) * 100))
        : phase === "done" && ok !== false
          ? 100
          : 0;
    const unit = progressUnit(mode);
    const elapsedSec = computeDockElapsedSec(phase);
    const clockTs =
      (phase === "done" || phase === "error") && dockJobFinishedAt
        ? dockJobFinishedAt
        : dockJobStartedAt;
    const startedAtFormatted = formatDockStartedAt(clockTs);
    const progressLabel =
      phase === "idle"
        ? ""
        : cfg.progressText(cur, tot);
    const jobTitle = jobTitleForMode(mode);
    const queue = Array.isArray(lastGate?.queue_items) ? lastGate.queue_items : [];

    const phaseKey = String(pipelineState?.progressPhase || "").toLowerCase();
    const phaseLabelTh = dockPhaseLabelTh(phaseKey, mode);
    const runningPhaseChip = phaseLabelTh
      ? /^กำลัง/.test(phaseLabelTh)
        ? phaseLabelTh
        : "กำลัง" + phaseLabelTh
      : "";
    const statusBadge =
      phase === "running" && runningPhaseChip
        ? runningPhaseChip
        : dockPhaseLabel(phase === "idle" ? "idle" : phase);

    let jobDetail = progressLabel || jobTitle;
    if (phase === "running" && phaseLabelTh) {
      jobDetail = phaseLabelTh + (tot > 0 ? " · " + progressLabel : "");
    } else if (
      phase === "running" &&
      mode === "cookie_unlock" &&
      statusContext?.itemName
    ) {
      jobDetail =
        "กำลังปลดล็อก " +
        statusContext.itemName +
        (tot > 0 ? " · " + progressLabel : "");
    } else if (phase === "idle") {
      jobDetail = "พร้อมเริ่ม · " + jobTitle;
    } else if (phase === "done" && ok !== false) {
      jobDetail = "สำเร็จ · " + jobTitle;
    } else if (phase === "error" && liveJob?.incomplete) {
      jobDetail = dockIncompletePhrase(cur, tot) + " · " + jobTitle;
    } else if (phase === "queued") {
      jobDetail = queueDetailText(lastGate, jobTitle);
    }
    const remainWaitDetail = remainingEtaLabel();
    if (remainWaitDetail && (phase === "running" || phase === "queued")) {
      jobDetail = (jobDetail || jobTitle) + " · " + remainWaitDetail;
    }
    if (devplaySession?.nickname && phase !== "error") {
      jobDetail = (jobDetail || jobTitle) + " · " + devplaySession.nickname;
    }
    if (phase === "error" && opts.errorMsg) jobDetail = opts.errorMsg;

    const cookieThumb = currentCookieThumb(mode);
    const unlockLiveThumbs =
      mode === "unlock_l"
        ? unlockLThumbsFromJob({
            progress: { ep: statusContext?.unlockEp || liveJob?.unlockEp },
            params: { target_eps: statusContext?.unlockEps || liveJob?.unlockEps || [] },
          })
        : [];
    const unlockThumb =
      unlockLiveThumbs.find((t) => Number(t.ep) === Number(statusContext?.unlockEp || liveJob?.unlockEp)) ||
      unlockLiveThumbs[0] ||
      null;
    const iconUrl = cookieThumb?.url
      ? resolveMediaSrc(cookieThumb.url)
      : unlockThumb?.url
        ? resolveMediaSrc(unlockThumb.url)
        : resolveMediaSrc(dockModeIcon(mode));

    let statusLineText = statusBadge;
    if (phase === "running") {
      statusLineText = runningPhaseChip || phaseLabelTh || "กำลังดำเนินการ";
    } else if (phase === "done" && ok !== false) {
      statusLineText = "สำเร็จแล้ว";
    } else if (phase === "error") {
      statusLineText = liveJob?.incomplete ? dockIncompletePhrase(cur, tot) : "ล้มเหลว";
    } else if (phase === "queued") {
      statusLineText = queueRankChipText(lastGate, "queued") || "รอคิว";
    }

    const clockPrefix = phase === "done" || phase === "error" ? "สำเร็จ " : "เริ่ม ";
    let timeLine = startedAtFormatted ? clockPrefix + startedAtFormatted : "";
    if (elapsedSec > 0) {
      const dur = "ใช้เวลา " + formatDockElapsed(elapsedSec);
      timeLine = timeLine ? timeLine + " · " + dur : dur;
    }
    const remainWait = remainingEtaLabel();
    if (remainWait && (phase === "running" || phase === "queued")) {
      timeLine = timeLine ? timeLine + " · " + remainWait : remainWait;
    }

    const fractionText =
      tot > 0
        ? formatNumTh(cur) + " / " + formatNumTh(tot) + " " + unit
        : phase === "running"
          ? "กำลังเริ่ม…"
          : "—";

    let panelSub = "งานที่กำลังรันและประวัติล่าสุด";
    if (phase === "running") {
      const remainWaitSub = remainingEtaLabel();
      panelSub = phaseLabelTh
        ? phaseLabelTh +
          (tot > 0
            ? " · " + formatNumTh(cur) + "/" + formatNumTh(tot) + " " + unit + " · " + pct + "%"
            : "") +
          (remainWaitSub ? " · " + remainWaitSub : "")
        : cfg.runningSub || "กำลังฟาร์ม…";
    } else if (phase === "queued") {
      panelSub = queueDetailText(lastGate, jobTitle) || "รอคิว — ถึงคิวแล้วจะเริ่มอัตโนมัติ";
    } else if (phase === "done") panelSub = ok !== false ? "สำเร็จแล้ว" : "ไม่สำเร็จ";
    else if (phase === "error") {
      panelSub = liveJob?.incomplete
        ? dockIncompletePhrase(cur, tot)
        : opts.errorMsg || "การฟาร์มล้มเหลว";
    }
    else if (farmDockFlash.text) panelSub = farmDockFlash.text;

    const steps = Array.isArray(pipelineState?.steps) ? pipelineState.steps : modeConfig(mode).steps || [];
    const stepKinds = pipelineState?.kinds || {};
    const logLines = Array.isArray(pipelineState?.logLines) ? pipelineState.logLines.slice(-120) : [];
    const cookieThumbs =
      mode === "cookie_unlock"
        ? Array.isArray(statusContext?.cookieThumbs)
          ? statusContext.cookieThumbs
          : []
        : unlockLiveThumbs;

    return {
      phase,
      mode,
      ok,
      panelSub,
      progress: { current: cur, total: tot, pct },
      queue,
      jobTitle,
      jobDetail,
      timeLine,
      statusBadge,
      statusLineText,
      fractionText,
      unit,
      progressLabel,
      elapsedSec,
      steps,
      stepKinds,
      logLines,
      iconUrl,
      cookieThumbs,
      currentCookieName:
        mode === "unlock_l"
          ? unlockThumb?.name || unlockLEpShortName(statusContext?.unlockEp || liveJob?.unlockEp)
          : statusContext?.itemName || cookieThumb?.name || "",
      currentEp: mode === "unlock_l" ? Number(statusContext?.unlockEp || liveJob?.unlockEp) || 0 : 0,
      showLive:
        phase === "running" ||
        phase === "done" ||
        phase === "error" ||
        phase === "queued",
      idleEmpty: false,
      incomplete: !!liveJob?.incomplete,
    };
  }

  function dockPhaseLabelTh(phaseKey, mode) {
    const key = String(phaseKey || "").toLowerCase();
    if (!key) return "";
    if ((key === "upgrade" || key === "items") && (mode === "lv_free_power" || mode === "lv_free_cookie")) {
      return mode === "lv_free_cookie" ? "กำลังอัปเลเวล Cookie" : "กำลังอัปชุดพลัง";
    }
    if ((key === "items" || key === "unlock") && mode === "cookie_unlock") {
      const name = String(statusContext?.itemName || "").trim();
      return name ? "กำลังปลดล็อก " + name : "กำลังปลดล็อกคุกกี้";
    }
    if (mode === "unlock_l" && (key === "unlock" || key === "unlocking" || key === "owned" || key === "hunting")) {
      const ep = Number(statusContext?.unlockEp || liveJob?.unlockEp) || 0;
      const name = ep ? unlockLEpShortName(ep) : "";
      if (key === "hunting") return name ? "ล่ากล่อง · " + name : "ล่ากล่อง";
      return name ? "ปลดด่าน · " + name : "ปลดด่าน";
    }
    if (key === "hunting") return "ล่ากล่อง";
    if (key === "playing" || key === "star_ok") return "ไต่หอ";
    const map = {
      login: "เข้าสู่ระบบเกม",
      start: "เริ่มงาน",
      clear: "เคลียร์รางวัลค้าง",
      match: "จับคู่",
      round: "วิ่งฟาร์ม",
      run: "วิ่งฟาร์ม",
      send: "ส่งหัวใจ",
      claim: mode === "heart" ? "รับหัวใจ" : "รับรางวัล",
      collect: "รับหัวใจ",
      buy: "ซื้อสมบัติ",
      extract: "ย่อยเป็นผง",
      items: "กำลังดำเนินการ",
      unlock: "ปลดล็อกคุกกี้",
      upgrade: "อัปเลเวล",
      draw: "สุ่มของ",
      open: "เปิดกล่อง",
      wait: "รอ play_time",
      waiting: "รอ play_time",
      climb: "ไต่หอ",
      friends: "จัดการเพื่อน",
      invite: "เชิญเพื่อน",
      done: "สรุปผล",
    };
    if (map[key]) return map[key];
    const steps = modeConfig(mode).steps || [];
    const hit = steps.find((s) => s.id === key);
    return hit ? hit.label : "";
  }

  function historyRowToCard(row) {
    const mode = resolveFarmJobMode(row) || "partyrun";
    const st = String(row.status || "").toLowerCase();
    const res = parseFarmJobResult(row.result);
    const cancelLike = farmJobIsCancelLike(row);
    const interruptLike = farmJobIsInterruptLike(row);
    const workerRestart = farmJobIsWorkerRestart(row);
    const heart = heartProgressFromResult(res, row.ticket_count, row);
    const heartIncomplete = mode === "heart" && heart.incomplete && !interruptLike;
    const powderRounds = Number(res.rounds ?? res.bought ?? 0) || 0;
    const powderTgt = Number(res.target ?? res.requested ?? 0) || 0;
    const powderIncomplete =
      mode === "powder" && powderTgt > 0 && powderRounds < powderTgt;
    const giftOk = Number(res.draws_ok || 0) || 0;
    const giftTgt = Number(res.requested || res.target || 0) || 0;
    const giftIncomplete = mode === "giftdraw" && giftTgt > 0 && giftOk < giftTgt;
    const inviteOk = Number(res.success ?? res.invited ?? 0) || 0;
    const inviteTgt = Number(res.target ?? res.requested ?? 29) || 29;
    const inviteIncomplete =
      (mode === "invite" || mode === "invite_friend") && inviteTgt > 0 && inviteOk < inviteTgt;
    const incompleteProgress =
      heartIncomplete || powderIncomplete || giftIncomplete || inviteIncomplete;

    let phase = "idle";
    if (st === "succeeded" && !incompleteProgress) phase = "done";
    else if (
      st === "failed" ||
      st === "error" ||
      st === "cancelled" ||
      st === "cancelled_stale" ||
      cancelLike ||
      incompleteProgress
    ) {
      phase = "error";
    } else if (st === "running" || st === "queued") {
      phase = "running";
    }

    let badge = "—";
    if (phase === "done") {
      badge = "สำเร็จ";
    } else if (workerRestart) {
      // Interrupted by deploy drain — not fake failed-0; hearts in detail.
      badge =
        heart.tgt > 0
          ? "ถูกตัด " + formatNumTh(heart.got) + "/" + formatNumTh(heart.tgt)
          : "ถูกตัด";
    } else if (cancelLike || st === "cancelled" || st === "cancelled_stale") {
      // Keep cancel badge; progress belongs in detail (หยุดกลางคัน · ได้หัวใจ X/Y).
      badge = "ยกเลิก";
    } else if (phase === "error") {
      if (mode === "heart" && heart.tgt > 0) {
        // All other heart terminals: always show real got/tgt (never force 0).
        badge = "ล้มเหลว " + formatNumTh(heart.got) + "/" + formatNumTh(heart.tgt);
      } else if (heartIncomplete) {
        badge = "ล้มเหลว " + formatNumTh(heart.got) + "/" + formatNumTh(heart.tgt);
      } else if (powderIncomplete) {
        badge = "ไม่ครบ " + formatNumTh(powderRounds) + "/" + formatNumTh(powderTgt);
      } else if (giftIncomplete) {
        badge = "ไม่ครบ " + formatNumTh(giftOk) + "/" + formatNumTh(giftTgt);
      } else if (inviteIncomplete) {
        badge = "ไม่ครบ " + formatNumTh(inviteOk) + "/" + formatNumTh(inviteTgt);
      } else {
        badge = "ล้มเหลว";
      }
    } else if (phase === "running") {
      badge = st === "queued" ? "รอคิว" : "กำลังดำเนินการ";
    }

    let detail = "";
    try {
      detail = farmHistoryRowSummary(row);
      const tmp = document.createElement("div");
      tmp.innerHTML = detail;
      detail = tmp.textContent || detail;
    } catch (_) {
      detail = JOB_KIND_TH[mode] || mode;
    }
    const when =
      formatDockStartedAt(row.finished_at || row.started_at || row.created_at) ||
      formatTopupDay(row.created_at) ||
      "";
    let elapsed = "";
    if (row.started_at && row.finished_at) {
      const ms = new Date(row.finished_at) - new Date(row.started_at);
      if (Number.isFinite(ms) && ms > 0) elapsed = "ใช้เวลา " + formatDockElapsed(ms / 1000);
    } else if (row.elapsed_sec != null && Number.isFinite(Number(row.elapsed_sec))) {
      elapsed = "ใช้เวลา " + formatDockElapsed(row.elapsed_sec);
    } else if (row.result?.elapsed_sec != null && Number.isFinite(Number(row.result.elapsed_sec))) {
      elapsed = "ใช้เวลา " + formatDockElapsed(row.result.elapsed_sec);
    }
    const whenLabel = when ? (row.finished_at ? "สำเร็จ " : "เริ่ม ") + when : "";
    return {
      mode,
      phase,
      title: jobTitleForMode(mode, { row }),
      badge,
      detail,
      timeLine: [whenLabel, elapsed].filter(Boolean).join(" · "),
      live: false,
      progress: null,
      jobId: row.id || "",
      accountKey: accountFromHistoryRow(row).key,
      accountLabel: accountFromHistoryRow(row).label,
      iconUrl: farmHistoryModeIcon(mode, row),
      cookieThumbs: mode === "unlock_l" ? unlockLThumbsFromJob(row) : [],
      currentCookieName: mode === "unlock_l" ? unlockLEpShortName(unlockLDisplayEp(row)) : "",
      currentEp: mode === "unlock_l" ? unlockLDisplayEp(row) : 0,
    };
  }

  function paintHistoryAccountFilters() {
    const box = $("job-status-history-filters");
    if (!box) return;
    const seen = new Map();
    (Array.isArray(farmHistoryItems) ? farmHistoryItems : []).forEach((row) => {
      const acc = accountFromHistoryRow(row);
      if (acc.key && acc.label && !seen.has(acc.key)) seen.set(acc.key, acc.label);
    });
    Object.values(hubJobAccounts || {}).forEach((acc) => {
      if (acc?.key && acc.label && !seen.has(acc.key)) seen.set(acc.key, acc.label);
    });
    const current = hubAccountKey();
    const currentLabel = hubAccountLabel();
    if (current && currentLabel && !seen.has(current)) seen.set(current, currentLabel);
    if (farmHistoryAccountFilter && !seen.has(farmHistoryAccountFilter)) {
      farmHistoryAccountFilter = "";
    }
    if (!seen.size) {
      box.hidden = true;
      box.replaceChildren();
      return;
    }
    box.hidden = false;
    box.replaceChildren();
    const addChip = (key, label) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "job-status-account-chip" + (farmHistoryAccountFilter === key ? " is-active" : "");
      btn.setAttribute("data-account-filter", key);
      btn.textContent = label;
      box.appendChild(btn);
    };
    addChip("", "ทุกบัญชี");
    seen.forEach((label, key) => addChip(key, label));
  }

  function buildLiveCard(snap) {
    if (!snap.showLive) return null;
    const canCancelLive =
      (snap.phase === "running" || snap.phase === "queued") &&
      !!(liveJob?.id || activeWatchJobId);
    return {
      mode: snap.mode,
      phase: snap.phase,
      title: snap.jobTitle,
      badge: snap.statusBadge,
      detail: snap.jobDetail,
      timeLine: snap.timeLine,
      live: true,
      cancelable: canCancelLive,
      jobId: liveJob?.id || activeWatchJobId || "",
      statusLineText: snap.statusLineText,
      steps: snap.steps || [],
      stepKinds: snap.stepKinds || {},
      logLines: snap.logLines || [],
      iconUrl: snap.iconUrl || "",
      cookieThumbs: snap.cookieThumbs || [],
      currentCookieName: snap.currentCookieName || "",
      currentEp: snap.currentEp || 0,
      progress: {
        pct: snap.progress.pct,
        fraction: snap.fractionText,
        show: snap.progress.total > 0 || snap.phase === "running",
      },
    };
  }

  function pendingJobsToCards() {
    return pendingFarmJobs.map((j, i) => {
      const thumbs = Array.isArray(j.extras?.cookieThumbs) ? j.extras.cookieThumbs : [];
      const first = thumbs[0];
      return {
        mode: j.mode,
        phase: "queued",
        title: typeof jobTitleForMode === "function" ? jobTitleForMode(j.mode) : j.mode,
        badge: "รอคิว",
        detail: j.label || ("คิว #" + (i + 1)),
        timeLine: "คิวส่วนตัว #" + (i + 1),
        live: false,
        pendingId: j.id,
        cancelable: true,
        iconUrl: first?.url || "",
        cookieThumbs: thumbs,
        currentCookieName: j.extras?.itemName || first?.name || "",
      };
    });
  }

  function renderTxCard(card) {
    const article = document.createElement("article");
    article.className = "farm-dock-tx";
    article.dataset.phase = card.phase || "idle";
    if (card.live) article.dataset.live = "1";
    if (card.pendingId) article.dataset.pendingId = card.pendingId;
    const iconSrc =
      resolveMediaSrc(card.iconUrl) || resolveMediaSrc(dockModeIcon(card.mode));
    const dotClass =
      card.phase === "done"
        ? "is-ok"
        : card.phase === "error"
          ? "is-err"
          : card.phase === "running" || card.phase === "queued"
            ? "is-running"
            : "";

    let progressHtml = "";
    if (card.live && card.progress?.show !== false) {
      progressHtml =
        '<div class="farm-dock-tx-progress">' +
        '<div class="farm-dock-tx-progress-head">' +
        '<span class="farm-dock-tx-status-line">' +
        '<span class="farm-dock-tx-status-dot" aria-hidden="true"></span>' +
        "<span>" +
        escapeHtml(card.statusLineText || card.badge) +
        "</span></span>" +
        '<span class="farm-dock-tx-pct">' +
        escapeHtml(String(card.progress?.pct || 0)) +
        "%</span></div>" +
        '<div class="farm-dock-tx-track" aria-hidden="true">' +
        '<span class="farm-dock-tx-fill" style="width:' +
        Math.max(card.progress?.pct > 0 ? 3 : 0, card.progress?.pct || 0) +
        '%"></span></div>' +
        '<div class="farm-dock-tx-foot">' +
        escapeHtml(card.progress?.fraction || "—") +
        "</div></div>";
    }
    let stepsHtml = "";
    if (card.live && Array.isArray(card.steps) && card.steps.length) {
      const kinds = card.stepKinds || {};
      stepsHtml =
        '<ol class="farm-dock-tx-steps" aria-label="ขั้นตอน">' +
        card.steps
          .map((s) => {
            const kind = kinds[s.id] || "idle";
            return (
              '<li class="farm-dock-tx-step is-' +
              escapeHtml(kind) +
              '"><span class="farm-dock-tx-step-dot" aria-hidden="true"></span><span>' +
              escapeHtml(s.label || s.id) +
              "</span></li>"
            );
          })
          .join("") +
        "</ol>";
    }
    let logsHtml = "";
    if (card.live) {
      const lines = Array.isArray(card.logLines) ? card.logLines : [];
      const open = !!dockLiveLogOpen;
      logsHtml =
        '<div class="farm-dock-tx-logs">' +
        '<button type="button" class="farm-dock-tx-logs-toggle" data-dock-log-toggle="1" aria-expanded="' +
        (open ? "true" : "false") +
        '">' +
        (open ? "ซ่อนรายละเอียด" : "ดูรายละเอียด") +
        (lines.length ? " (" + lines.length + ")" : "") +
        "</button>" +
        '<ul class="farm-dock-tx-log-list' +
        (open ? "" : " hidden") +
        '" aria-hidden="' +
        (open ? "false" : "true") +
        '">' +
        (lines.length
          ? lines
              .map((l) => {
                const text = typeof l === "string" ? l : l?.text || "";
                const kind = typeof l === "object" && l?.kind ? l.kind : "ok";
                return (
                  '<li class="farm-dock-tx-log-line is-' +
                  escapeHtml(kind) +
                  '">' +
                  escapeHtml(text) +
                  "</li>"
                );
              })
              .join("")
          : '<li class="farm-dock-tx-log-line is-muted">ยังไม่มีรายละเอียด</li>') +
        "</ul></div>";
    }
    const cancelHtml = card.cancelable
      ? card.pendingId
        ? '<button type="button" class="farm-dock-tx-cancel" data-cancel-pending="' +
          escapeHtml(card.pendingId || "") +
          '" aria-label="ยกเลิกคิว">×</button>'
        : card.jobId && !card.adminCancelId
          ? '<button type="button" class="farm-dock-tx-cancel" data-cancel-job="' +
            escapeHtml(card.jobId) +
            '" aria-label="ยกเลิกงาน">×</button>'
          : ""
      : "";
    // Admin cards get an explicit labeled action button in the footer.
    const adminActionHtml = card.adminJobId
      ? '<div class="farm-dock-tx-admin-actions">' +
        '<button type="button" class="farm-dock-tx-admin-log" data-admin-log="' +
        escapeHtml(card.adminJobId) +
        '">Log</button>' +
        (card.cancelable && card.adminCancelId
          ? '<button type="button" class="farm-dock-tx-forcekill' +
            (card.stuck ? " is-stuck" : "") +
            '" data-admin-cancel="' +
            escapeHtml(card.adminCancelId) +
            '">' +
            (card.stuck ? "บังคับจบงานค้าง" : "ยกเลิก / บังคับจบ") +
            "</button>"
          : "") +
        "</div>"
      : "";
    const timeFull = String(card.timeLine || "").trim();
    let durText = "";
    let dateText = "";
    if (timeFull.includes("ใช้เวลา")) {
      const durMatch = timeFull.match(/ใช้เวลา\s*([^·]+)/);
      durText = durMatch ? durMatch[1].trim() : "";
      dateText = timeFull.replace(/·?\s*ใช้เวลา.*$/, "").trim();
    } else {
      dateText = timeFull;
    }
    if (!durText && !dateText) {
      dateText = "เสร็จสิ้นล่าสุด";
    }

    const titleText = card.title || (typeof jobTitleForMode === "function" ? jobTitleForMode(card.mode) : "") || "ฟาร์ม";
    const badgeText = card.badge || (card.phase === "done" ? "สำเร็จ" : card.phase === "error" ? "ล้มเหลว" : "เสร็จสิ้น");
    const detailText = card.detail && card.detail !== "—" ? card.detail : (typeof jobTitleForMode === "function" ? jobTitleForMode(card.mode) : "สำเร็จ");
    const safeIcon = escapeHtml(iconSrc || "assets/coin.png");
    const accountPill = card.accountLabel && !card.live ? '<span class="farm-dock-acc-pill">บัญชี ' + escapeHtml(card.accountLabel) + '</span>' : '';

    let modeColHtml = "";
    if (card.mode === "unlock_l") {
      let eps = [];
      if (Array.isArray(card.cookieThumbs) && card.cookieThumbs.length > 0) {
        eps = card.cookieThumbs.map((t) => {
          const epNum = Number(t.ep) || 0;
          const epLabel = epNum === 502 ? "SP 2" : epNum === 503 ? "SP 3" : (epNum ? "EP " + epNum : (t.name || "L"));
          const imgSrc = resolveMediaSrc(t.url) || resolveMediaSrc(typeof unlockLEpImage === "function" ? unlockLEpImage(epNum) : "assets/Tiger_Lily_Cookie.png");
          return { ep: epNum, label: epLabel, name: t.name || epLabel, url: imgSrc };
        });
      } else {
        let epNum = Number(card.currentEp) || 0;
        if (!epNum) {
          const m = (card.title || "").match(/EP\s*(\d+)/i) || (card.detail || "").match(/EP\s*(\d+)/i);
          if (m) epNum = Number(m[1]);
          else if ((card.title || "").includes("Special 2") || (card.detail || "").includes("Special 2")) epNum = 502;
          else if ((card.title || "").includes("Special 3") || (card.detail || "").includes("Special 3")) epNum = 503;
        }
        const epLabel = epNum === 502 ? "SP 2" : epNum === 503 ? "SP 3" : (epNum ? "EP " + epNum : "L");
        const imgSrc = resolveMediaSrc(typeof unlockLEpImage === "function" && epNum ? unlockLEpImage(epNum) : (card.iconUrl || "assets/Tiger_Lily_Cookie.png"));
        eps = [{ ep: epNum, label: epLabel, name: epLabel, url: imgSrc }];
      }

      if (eps.length <= 1) {
        const item = eps[0] || { label: "L", name: "ปลดล็อค L", url: "assets/Tiger_Lily_Cookie.png" };
        modeColHtml =
          '<div class="farm-dock-col-mode">' +
            '<div class="farm-dock-tx-icon farm-dock-tx-icon--unlockl" title="' + escapeHtml(item.name) + '" aria-label="' + escapeHtml(item.label) + '">' +
              '<img src="' + escapeHtml(item.url) + '" alt="' + escapeHtml(item.label) + '" width="28" height="28" decoding="async" onerror="this.onerror=null;this.src=\'assets/Tiger_Lily_Cookie.png\';" />' +
              (dotClass ? '<span class="farm-dock-tx-icon-dot ' + dotClass + '"></span>' : '') +
              '<span class="farm-dock-icon-ep-badge">' + escapeHtml(item.label) + '</span>' +
            '</div>' +
            '<div class="farm-dock-mode-meta">' +
              '<div class="farm-dock-title-row">' +
                '<span class="farm-dock-tx-title">ปลดล็อค L</span>' +
                '<span class="farm-dock-ep-pill">' + escapeHtml(item.label) + '</span>' +
              '</div>' +
              accountPill +
            '</div>' +
          '</div>';
      } else {
        const iconBoxes = eps.slice(0, 3).map((item) => {
          return (
            '<div class="farm-dock-tx-icon farm-dock-tx-icon--unlockl" title="' + escapeHtml(item.name) + '">' +
              '<img src="' + escapeHtml(item.url) + '" alt="' + escapeHtml(item.label) + '" width="26" height="26" decoding="async" onerror="this.onerror=null;this.src=\'assets/Tiger_Lily_Cookie.png\';" />' +
              '<span class="farm-dock-icon-ep-badge">' + escapeHtml(item.label) + '</span>' +
            '</div>'
          );
        }).join("");
        const epSummary = eps.map((e) => e.label).join(", ");
        modeColHtml =
          '<div class="farm-dock-col-mode">' +
            '<div class="farm-dock-tx-icon-group">' +
              iconBoxes +
              (eps.length > 3 ? '<span class="farm-dock-more-tag">+' + (eps.length - 3) + '</span>' : '') +
            '</div>' +
            '<div class="farm-dock-mode-meta">' +
              '<div class="farm-dock-title-row">' +
                '<span class="farm-dock-tx-title">ปลดล็อค L</span>' +
                '<span class="farm-dock-ep-pill" title="' + escapeHtml(epSummary) + '">' + eps.length + ' ด่าน</span>' +
              '</div>' +
              accountPill +
            '</div>' +
          '</div>';
      }
    } else if (card.mode === "cookie_unlock" && Array.isArray(card.cookieThumbs) && card.cookieThumbs.length > 0) {
      const first = card.cookieThumbs[0];
      const imgSrc = resolveMediaSrc(first.url) || safeIcon;
      modeColHtml =
        '<div class="farm-dock-col-mode">' +
          '<div class="farm-dock-tx-icon" title="' + escapeHtml(first.name || 'คุกกี้') + '">' +
            '<img src="' + escapeHtml(imgSrc) + '" alt="" width="28" height="28" decoding="async" onerror="this.onerror=null;this.src=\'assets/coin.png\';" />' +
            (dotClass ? '<span class="farm-dock-tx-icon-dot ' + dotClass + '"></span>' : '') +
          '</div>' +
          '<div class="farm-dock-mode-meta">' +
            '<div class="farm-dock-title-row">' +
              '<span class="farm-dock-tx-title">' + escapeHtml(titleText) + '</span>' +
              (first.name ? '<span class="farm-dock-ep-pill">' + escapeHtml(first.name) + '</span>' : '') +
            '</div>' +
            accountPill +
          '</div>' +
        '</div>';
    } else {
      modeColHtml =
        '<div class="farm-dock-col-mode">' +
          '<div class="farm-dock-tx-icon" aria-hidden="true">' +
            '<img src="' + safeIcon + '" alt="" width="26" height="26" decoding="async" onerror="this.onerror=null;this.src=\'assets/coin.png\';" />' +
            (dotClass ? '<span class="farm-dock-tx-icon-dot ' + dotClass + '"></span>' : "") +
          '</div>' +
          '<div class="farm-dock-mode-meta">' +
            '<span class="farm-dock-tx-title">' + escapeHtml(titleText) + '</span>' +
            accountPill +
          '</div>' +
        '</div>';
    }

    article.innerHTML =
      '<div class="farm-dock-tx-row">' +
        modeColHtml +
        '<div class="farm-dock-col-status">' +
          '<span class="farm-dock-tx-badge" data-phase="' + escapeHtml(card.phase || "done") + '">' + escapeHtml(badgeText) + '</span>' +
        '</div>' +
        '<div class="farm-dock-col-detail">' +
          '<span class="farm-dock-yield-val">' + escapeHtml(detailText) + '</span>' +
        '</div>' +
        '<div class="farm-dock-col-time">' +
          (durText ? '<span class="farm-dock-dur-tag">⏱️ ' + escapeHtml(durText) + '</span>' : '') +
          (dateText ? '<span class="farm-dock-date-val">' + escapeHtml(dateText) + '</span>' : '') +
        '</div>' +
        '<div class="farm-dock-col-actions">' +
          cancelHtml +
          adminActionHtml +
          (card.jobId && !card.adminJobId
            ? '<button type="button" class="farm-dock-btn-action farm-dock-btn-log" data-owner-log="' + escapeHtml(card.jobId) + '">ดู Log</button>' +
              '<button type="button" class="farm-dock-btn-action farm-dock-btn-copy" data-copy-log="' + escapeHtml(card.jobId) + '" title="คัดลอก Log">คัดลอก</button>'
            : '<button type="button" class="farm-dock-btn-action farm-dock-btn-copy" disabled style="opacity:0.4;cursor:default;">สำเร็จ</button>') +
        '</div>' +
      '</div>' +
      progressHtml +
      stepsHtml +
      logsHtml;
    return article;
  }

  let _farmDockRenderTimer = null;
  let _farmDockRenderRaf = 0;

  function scheduleRenderFarmDock(opts = {}) {
    // Coalesce rapid callers (pollers / elapsed / activity) into one paint.
    const immediate = !!opts.immediate;
    if (immediate) {
      if (_farmDockRenderTimer) {
        clearTimeout(_farmDockRenderTimer);
        _farmDockRenderTimer = null;
      }
      if (_farmDockRenderRaf) {
        cancelAnimationFrame(_farmDockRenderRaf);
        _farmDockRenderRaf = 0;
      }
      renderFarmDock(opts);
      return;
    }
    if (_farmDockRenderTimer) return;
    _farmDockRenderTimer = setTimeout(() => {
      _farmDockRenderTimer = null;
      if (_farmDockRenderRaf) cancelAnimationFrame(_farmDockRenderRaf);
      _farmDockRenderRaf = requestAnimationFrame(() => {
        _farmDockRenderRaf = 0;
        if (document.hidden) return;
        renderFarmDock(opts);
      });
    }, 120);
  }

  function renderFarmDock(opts = {}) {
    try {
      renderFarmDockUnsafe(opts);
    } catch (err) {
      console.warn("renderFarmDock", err);
    }
  }

  function renderFarmDockUnsafe(opts = {}) {
    const snap = buildDockSnapshot(opts);
    if (jobHubShouldStayVisible() && jobStatusView === "hidden") {
      jobStatusView = "minimized";
    } else if (hasActiveJobStatus() && jobStatusView === "hidden") {
      jobStatusView = "minimized";
    }
    if (jobStatusView !== "hidden") syncJobStatusShell();
    enforceJobStatusHold();
    renderMiniStatus(snap);
    if (jobStatusView === "expanded") {
      syncJobStatusCardLayout(snap);
      // Shared header (chip/title/detail) must refresh even on History/Admin,
      // otherwise it sticks on idle "ว่าง / ไม่มีงาน" while a job is running.
      paintJobStatusHeader(snap);
      if (jobStatusTab === "live") renderLiveStatus(snap);
    }
    paintJobLogModalBody(snap.logLines);

    const panelSubEl = $("farm-dock-panel-sub");
    if (panelSubEl) panelSubEl.textContent = snap.panelSub;

    const flashSection = $("farm-dock-flash-section");
    const flashEl = $("farm-dock-flash");
    if (flashEl) {
      const flashText = farmDockFlash.text || "";
      // Don't surface inventory/status noise (e.g. ticket count) as a "live job" banner.
      const noisy =
        /^ตั๋ว\s/i.test(flashText) ||
        /Party Run\s+\d/i.test(flashText) ||
        flashText === "ยกเลิกแล้ว";
      const showFlash =
        !!flashText &&
        !noisy &&
        !snap.idleEmpty &&
        (snap.phase === "idle" || snap.phase === "done" || snap.phase === "error");
      if (showFlash) {
        flashSection?.classList.remove("hidden");
        flashEl.textContent = flashText;
        flashEl.className = "farm-dock-flash " + (farmDockFlash.kind || "muted");
      } else {
        flashSection?.classList.add("hidden");
        flashEl.textContent = "";
      }
    }

    const liveCard = buildLiveCard(snap);
    const pendingCards = pendingJobsToCards();
    const historyCards = (Array.isArray(farmHistoryItems) ? farmHistoryItems : [])
      .filter((r) => r && r.status !== "running" && r.status !== "queued")
      .slice(0, 20)
      .map(historyRowToCard)
      .filter((card) => {
        if (!farmHistoryAccountFilter) return true;
        return card.accountKey === farmHistoryAccountFilter;
      });
    paintHistoryAccountFilters();

    const liveIsActive =
      !!liveCard && (snap.phase === "running" || snap.phase === "queued");
    const activeCount = (liveIsActive ? 1 : 0) + pendingCards.length;
    const allCount = activeCount + historyCards.length;
    const allCountEl = $("farm-dock-tab-all-count");
    if (allCountEl) allCountEl.textContent = "(" + allCount + ")";
    const histCountEl = $("farm-history-count");
    if (histCountEl) {
      histCountEl.textContent = String(historyCards.length);
      histCountEl.classList.toggle("hidden", historyCards.length <= 0);
      histCountEl.hidden = historyCards.length <= 0;
    }

    paintAdminEntry();

    const isRunningOrQueued = snap.phase === "running" || snap.phase === "queued";
    if (!isRunningOrQueued && snap.phase === "idle" && jobStatusTab === "live") {
      jobStatusTab = "history";
    }

    document.querySelectorAll("[data-job-tab]").forEach((btn) => {
      const tab = btn.getAttribute("data-job-tab");
      if (tab === "live" || tab === "log") {
        btn.classList.toggle("hidden", !isRunningOrQueued && snap.phase === "idle");
      }
      let on = tab === jobStatusTab;
      if (tab === "live") on = jobStatusTab === "live" && liveSubView !== "log";
      else if (tab === "log") on = jobStatusTab === "live" && liveSubView === "log";
      btn.classList.toggle("is-active", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
    });

    const paneLive = $("job-status-pane-live");
    const paneHistory = $("job-status-pane-history");
    const paneServer = $("job-status-pane-server");
    const statusCard = $("live-status-card");
    if (statusCard) {
      statusCard.dataset.jobTab = jobStatusTab;
      statusCard.dataset.liveView = jobStatusTab === "live" ? liveSubView : "overview";
    }
    const syncStatusPane = (pane, on) => {
      if (!pane) return;
      pane.classList.toggle("is-shown", on);
      pane.classList.toggle("hidden", !on);
      pane.removeAttribute("hidden");
      pane.setAttribute("aria-hidden", on ? "false" : "true");
    };
    syncStatusPane(paneLive, jobStatusTab === "live");
    syncStatusPane(paneServer, jobStatusTab === "server");
    syncStatusPane(paneHistory, jobStatusTab === "history");
    syncJobStatusActions();

    const userActions = $("farm-dock-user-actions");
    const adminSection = $("farm-dock-admin-section");
    const list = $("farm-dock-list");

    if (userActions) {
      const showCancelAll = pendingCards.length > 0 || liveIsActive || !!queuedRun;
      userActions.classList.toggle("hidden", !showCancelAll);
    }

    if (adminSection && isAdminJobsPaneOpen()) {
      document.querySelectorAll("[data-admin-tab]").forEach((btn) => {
        const on = btn.getAttribute("data-admin-tab") === adminJobsTab;
        btn.classList.toggle("is-active", on);
        btn.setAttribute("aria-selected", on ? "true" : "false");
      });
      renderAdminJobsList();
    }

    if (list && jobStatusTab === "history") {
      list.replaceChildren();
      let painted = 0;
      if (
        liveCard &&
        (snap.phase === "done" ||
          snap.phase === "error")
      ) {
        list.appendChild(renderTxCard(liveCard));
        painted += 1;
      }
      for (const card of pendingCards) {
        list.appendChild(renderTxCard(card));
        painted += 1;
      }
      for (const card of historyCards) {
        list.appendChild(renderTxCard(card));
        painted += 1;
      }
      if (!painted) {
        if (farmHistoryLoading) {
          paintFarmDockHistorySkeleton(list, 3);
        } else {
          const empty = document.createElement("p");
          empty.className = "farm-dock-empty";
          empty.textContent = "ยังไม่มีประวัติการฟาร์ม";
          list.appendChild(empty);
        }
      }
    }

    const queueSection = $("farm-dock-queue-section");
    const queueList = $("farm-dock-queue");
    const leaveQBtn = $("farm-dock-leave-queue");
    const isMeQueued =
      !isAdminJobsPaneOpen() &&
      (snap.phase === "queued" ||
        (lastGate?.me?.status === "waiting" && snap.phase !== "running" && snap.phase !== "done" && snap.phase !== "error"));
    const showQueue = isMeQueued;
    const progBox = $("session-progress");
    if (progBox) {
      progBox.classList.toggle("hidden", isMeQueued);
    }
    if (queueList) {
      queueList.replaceChildren();
      const leaveVisible =
        snap.phase === "queued" ||
        !!queuedRun ||
        lastGate?.me?.status === "waiting" ||
        (lastGate?.me?.status === "active" && snap.phase === "queued");
      if (showQueue) {
        queueSection?.classList.remove("hidden");
        leaveQBtn?.classList.toggle("hidden", !leaveVisible);
        const myPos = lastGate?.me?.position || (queueRows.find((r) => r.is_me)?.position) || "1";
        const wait = queueWaitText(lastGate);
        const rankEl = $("job-queue-rank-text");
        const etaBadge = $("job-queue-eta-badge");
        const barFill = $("visual-queue-bar-fill");
        if (rankEl) rankEl.textContent = String(myPos || "1").replace(/^คิวที่\s*/, "");
        if (etaBadge) etaBadge.textContent = wait ? "⏱️ รอประมาณ " + wait : "⏱️ กำลังจัดสรร...";
        const workerChip = $("job-queue-worker-chip");
        if (workerChip) workerChip.textContent = queueWorkerChipText(lastGate);
        if (barFill) barFill.style.width = Math.max(20, Math.min(100, Math.round(100 / Math.max(1, Number(myPos) || 1)))) + "%";
        if (leaveQBtn) {
          leaveQBtn.textContent =
            lastGate?.me?.status === "waiting" || snap.phase === "queued"
              ? "ออกจากคิว"
              : "ออกจากคิว";
          leaveQBtn.title =
            "ยกเลิกเฉพาะงานที่ยังรอคิว — งานที่กำลังรันให้ใช้ปุ่มยกเลิกงาน";
        }
        const rows = queueRows;
        if (rows.length === 0 && (lastGate?.me?.position || leaveVisible)) {
          const li = document.createElement("li");
          li.className = "farm-dock-queue-item is-me";
          const pos = lastGate?.me?.position ?? "—";
          const ahead = lastGate?.me?.ahead;
          const wait = queueWaitText(lastGate);
          li.innerHTML =
            '<span class="farm-dock-queue-pos">#' +
            escapeHtml(pos) +
            '</span><img class="farm-dock-queue-icon" src="' +
            escapeHtml(jobKindIcon(liveJob?.mode || snap.mode, { family: liveJob?.family, unlock_ep: liveJob?.unlockEp })) +
            '" alt="" width="22" height="22" />' +
            '<span class="farm-dock-queue-kind">' +
            escapeHtml(queueDetailText(lastGate, snap.jobTitle)) +
            '</span><span class="farm-dock-queue-badge">คิวของคุณ' +
            (ahead != null ? " · ข้างหน้า " + ahead : "") +
            (wait ? " · " + escapeHtml(wait) : "") +
            "</span>";
          queueList.appendChild(li);
        }
        for (const row of rows) {
          const li = document.createElement("li");
          li.className = "farm-dock-queue-item";
          if (row.is_me) li.classList.add("is-me");
          if (row.status === "running") li.classList.add("is-running");
          const vis = {
            farm_mode: row.farm_mode,
            family: row.is_me ? liveJob?.family : "",
            unlock_ep: row.unlock_ep || (row.is_me ? liveJob?.unlockEp : 0),
            ep: row.unlock_ep,
          };
          const kind = jobKindLabel(row.job_kind, vis);
          const icon = jobKindIcon(row.job_kind, vis);
          const ahead = queueRowIsAhead(row, myPos);
          const badge = row.is_me
            ? "คิวของคุณ"
            : ahead
              ? queueProgressText(row)
              : row.status === "running"
                ? "กำลังรัน"
                : "รอคิว";
          const progressHtml = ahead
            ? '<span class="farm-dock-queue-progress" aria-hidden="true"><span class="farm-dock-queue-progress-fill" style="width:' +
              queueProgressPct(row) +
              '%"></span></span>'
            : "";
          li.innerHTML =
            '<span class="farm-dock-queue-pos">#' +
            escapeHtml(row.position ?? "—") +
            '</span><img class="farm-dock-queue-icon" src="' +
            escapeHtml(icon) +
            '" alt="" width="22" height="22" />' +
            '<span class="farm-dock-queue-kind">' +
            escapeHtml(kind) +
            "</span>" +
            progressHtml +
            '<span class="farm-dock-queue-badge">' +
            escapeHtml(badge) +
            "</span>";
          queueList.appendChild(li);
        }
      } else {
        queueSection?.classList.add("hidden");
        leaveQBtn?.classList.add("hidden");
      }
    }
    updateFarmLiveBadges();
  }

  function updateProgressBar(current, total) {
    if (!pipelineState) return;
    pipelineState.progress = {
      current: Number(current) || 0,
      total: Number(total) || pipelineState.progress?.total || 0,
    };
    renderFarmDock();
  }

  function renderLogList() {
    const list = $("farm-log");
    if (!list) return;
    list.replaceChildren();
    list.classList.add("hidden");
  }

  function clearRunStatusAutoClose() {
    if (runStatusAutoCloseTimer) {
      clearTimeout(runStatusAutoCloseTimer);
      runStatusAutoCloseTimer = null;
    }
  }

  function setRunStatusClosable() {
    runStatusClosable = true;
    const btn = $("run-status-close");
    if (btn) btn.disabled = false;
  }

  // Q6 cancel-holding: after a user-initiated cancel reaches terminal state,
  // briefly show the dock then auto-dismiss so the user is not stuck on
  // 「ล้มเหลว」/「ปิด」 or a 「ตกลง」 heart summary modal.
  function scheduleCancelTerminalHandoff(opts = {}) {
    clearRunStatusAutoClose();
    pendingAfterRunStatus = null;
    setRunStatusClosable(true);
    const delayMs = Number(opts.delayMs);
    const wait = Number.isFinite(delayMs) && delayMs >= 0 ? delayMs : 1500;
    const toastMsg = opts.toastMsg || "ยกเลิกแล้ว";
    const toastKind = opts.toastKind || "muted";
    if (toastMsg) showToast(toastMsg, toastKind);
    if (modalMode === "result") forceCloseModal();
    runStatusAutoCloseTimer = setTimeout(() => {
      runStatusAutoCloseTimer = null;
      // Terminal cancel dock must always clear even if farmRunning /
      // activeWatchJobId leftovers linger after soft-cancel settle.
      if (dockPhase === "done" || dockPhase === "error") {
        pendingAfterRunStatus = null;
        if (modalMode === "result") forceCloseModal();
        forceCloseRunStatusPopup();
        resetFarmDockIdle();
        return;
      }
      // Only bail when a *new* live job clearly owns the dock.
      if (dockPhase === "running" || dockPhase === "queued") {
        return;
      }
      pendingAfterRunStatus = null;
      if (modalMode === "result") forceCloseModal();
      forceCloseRunStatusPopup();
      resetFarmDockIdle();
    }, wait);
  }

  function isUserCancelTerminal(jobRow, status, jobId) {
    const st = String(status || jobRow?.status || "").toLowerCase();
    const id = String(jobId || jobRow?.id || liveJob?.id || "");
    const gateMe = lastGate?.me || null;
    const gateSameJob =
      !!id &&
      !!gateMe?.cancel_requested &&
      String(gateMe.job_id || gateMe.id || "") === id;
    return !!(
      (id && userCancelLatchIds.has(id)) ||
      liveJob?.cancelRequested ||
      jobRow?.cancel_requested ||
      pipelineState?.cancelling ||
      st === "cancelled" ||
      st === "cancelled_stale" ||
      farmJobIsCancelLike(jobRow) ||
      farmJobIsWorkerRestart(jobRow) ||
      gateSameJob
    );
  }

  function buildCancelTerminalToast(mode, jobRow, result, target) {
    const st = String(jobRow?.status || "").toLowerCase();
    let msg =
      st === "cancelled" ||
      liveJob?.cancelRequested ||
      userCancelLatchIds.has(String(jobRow?.id || liveJob?.id || ""))
        ? "ยกเลิกแล้ว"
        : "งานหยุดแล้ว";
    if (mode === "heart") {
      const hp = heartProgressFromResult(
        result || jobRow?.result || {},
        target,
        jobRow
      );
      if (farmJobIsWorkerRestart(jobRow)) {
        msg =
          hp.got > 0
            ? "ถูกตัดตอนอัปเดตระบบ · ได้หัวใจ " +
              formatNumTh(hp.got) +
              "/" +
              formatNumTh(hp.tgt || target || 0)
            : "ถูกตัดตอนอัปเดตระบบ";
      } else if (hp.got > 0) {
        const stale = farmJobIsStaleCancel(jobRow);
        msg =
          (stale ? "หยุดกลางคัน" : "หยุดงานแล้ว") +
          " · ได้หัวใจ " +
          formatNumTh(hp.got) +
          "/" +
          formatNumTh(hp.tgt || target || 0) +
          (stale ? " · เกมขัดข้อง" : "");
      } else if (farmJobIsStaleCancel(jobRow)) {
        msg = "หยุดกลางคัน · เกมขัดข้อง";
      }
    }
    const billed = jobRow?.billing_outcome;
    if (billed && billed.charged === false) msg += " · คืนโทเคนแล้ว";
    else if (result?.refunded || jobRow?.refunded) msg += " · มีการคืนเครดิต";
    return msg;
  }

  function hasActiveJobStatus() {
    return (
      dockPhase === "running" ||
      dockPhase === "queued" ||
      !!activeWatchJobId ||
      !!activeWatcher ||
      !!watchJobTimer ||
      !!farmRunning ||
      pendingJobsCount() > 0 ||
      hasCreditJobRunning()
    );
  }

  function syncJobStatusShell() {
    const root = $("job-status-root");
    if (!root) return;
    const showShell = jobStatusView !== "hidden";
    const showMini = showShell && jobStatusView === "minimized";
    const showExpanded = showShell && jobStatusView === "expanded";
    const viewChanged = jobStatusAppliedView !== jobStatusView;
    if (!viewChanged && jobStatusAnimTimer) return;
    if (!viewChanged) {
      if (jobStatusView === "minimized") {
        const stuckPanel = $("job-status-panel");
        const stuckBackdrop = $("job-status-backdrop");
        if (stuckPanel && !stuckPanel.classList.contains("hidden") && !stuckPanel.classList.contains("is-closing")) {
          stuckPanel.classList.add("hidden");
          stuckPanel.setAttribute("aria-hidden", "true");
          stuckBackdrop?.classList.add("hidden");
          stuckBackdrop?.setAttribute("aria-hidden", "true");
          releaseFocusTrap();
        }
      }
      return;
    }

    if (jobStatusAnimTimer) {
      clearTimeout(jobStatusAnimTimer);
      jobStatusAnimTimer = null;
    }
    jobStatusAppliedView = jobStatusView;

    const mini = $("job-status-mini");
    const panel = $("job-status-panel");
    const backdrop = $("job-status-backdrop");
    const finishShellHide = () => {
      root.classList.add("hidden");
      root.classList.remove("is-closing", "is-open", "is-minimized", "is-expanded");
      panel?.classList.add("hidden");
      panel?.classList.remove("is-closing");
      backdrop?.classList.add("hidden");
      backdrop?.classList.remove("is-closing");
      panel?.setAttribute("aria-hidden", "true");
      backdrop?.setAttribute("aria-hidden", "true");
      document.body.classList.remove("has-job-status", "has-farm-dock");
    };

    if (!showShell) {
      root.setAttribute("aria-hidden", "true");
      mini?.classList.add("hidden");
      mini?.setAttribute("aria-expanded", "false");
      releaseFocusTrap();
      if (root.classList.contains("is-open")) {
        root.classList.add("is-closing");
        root.classList.remove("is-open");
        if (panel && !panel.classList.contains("hidden")) {
          panel.classList.add("is-closing");
        }
        backdrop?.classList.add("is-closing");
        jobStatusAnimTimer = setTimeout(() => {
          jobStatusAnimTimer = null;
          if (jobStatusView !== "hidden") return;
          finishShellHide();
        }, JOB_STATUS_MOTION_MS);
      } else {
        finishShellHide();
      }
      return;
    }

    root.classList.remove("hidden", "is-closing");
    root.setAttribute("aria-hidden", "false");
    root.classList.toggle("is-minimized", showMini);
    root.classList.toggle("is-expanded", showExpanded);

    const showMiniPill =
      showShell && (!showExpanded || window.matchMedia("(min-width: 768px)").matches);
    mini?.classList.toggle("hidden", !showMiniPill);
    mini?.classList.toggle("is-panel-open", showExpanded && showMiniPill);
    mini?.setAttribute("aria-expanded", showExpanded ? "true" : "false");

    if (showExpanded) {
      panel?.classList.remove("hidden", "is-closing");
      backdrop?.classList.remove("hidden", "is-closing");
      panel?.setAttribute("aria-hidden", "false");
      backdrop?.setAttribute("aria-hidden", "false");
      if (!root.classList.contains("is-open")) {
        requestAnimationFrame(() => {
          requestAnimationFrame(() => root.classList.add("is-open"));
        });
      }
      trapFocus($("live-status-card"));
    } else {
      if (panel && !panel.classList.contains("hidden")) {
        panel.classList.add("is-closing");
        backdrop?.classList.add("is-closing");
        backdrop?.setAttribute("aria-hidden", "true");
        releaseFocusTrap();
        jobStatusAnimTimer = setTimeout(() => {
          jobStatusAnimTimer = null;
          if (jobStatusView === "expanded") return;
          panel.classList.add("hidden");
          panel.classList.remove("is-closing");
          backdrop?.classList.add("hidden");
          backdrop?.classList.remove("is-closing");
          panel.setAttribute("aria-hidden", "true");
          backdrop?.setAttribute("aria-hidden", "true");
        }, JOB_STATUS_MOTION_MS);
      } else {
        releaseFocusTrap();
        backdrop?.classList.add("hidden");
        backdrop?.classList.remove("is-closing");
        panel?.classList.add("hidden");
        panel?.classList.remove("is-closing");
        panel?.setAttribute("aria-hidden", "true");
        backdrop?.setAttribute("aria-hidden", "true");
      }
      // Keep is-open while minimized so poll/sync does not drop opacity and flicker.
      if (showMini) {
        if (!root.classList.contains("is-open")) {
          requestAnimationFrame(() => {
            requestAnimationFrame(() => root.classList.add("is-open"));
          });
        }
      } else {
        root.classList.remove("is-open");
      }
    }

    document.body.classList.toggle("has-job-status", showShell);
    document.body.classList.toggle("has-farm-dock", showShell);
    placeJobInspector();
  }

  function paintOsProgressRing(pct) {
    const n = Math.max(0, Math.min(100, Number(pct) || 0));
    const mini = $("job-status-mini-ring");
    if (mini) {
      const c = 2 * Math.PI * 9;
      mini.style.strokeDashoffset = String(c * (1 - n / 100));
    }
    const head = $("live-status-head-ring");
    if (head) {
      const c = 2 * Math.PI * 15;
      head.style.strokeDashoffset = String(c * (1 - n / 100));
    }
  }

  function syncJobStatusActions() {
    const bar = $("job-status-actions");
    if (!bar) return;
    const cancelBtn = $("live-status-cancel");
    const doneBtn = $("live-status-done");
    const shown = (el) => !!(el && !el.hidden && !el.classList.contains("hidden"));
    const open = jobStatusTab === "live" && (shown(cancelBtn) || shown(doneBtn));
    bar.classList.toggle("is-open", open);
    if (open) bar.removeAttribute("hidden");
    else bar.setAttribute("hidden", "");
    bar.setAttribute("aria-hidden", open ? "false" : "true");
  }

  function renderMiniStatus(snap) {
    const mini = $("job-status-mini");
    const capsule = $("farm-dock-capsule");
    const liveSlot = $("farm-dock-live-slot");
    snap = snap || buildDockSnapshot();
    const phase = snap.phase || "idle";
    const isBusy = phase === "running" || phase === "queued";
    if (capsule) {
      capsule.classList.toggle("is-live", isBusy);
      capsule.classList.toggle("is-idle", !isBusy);
    }
    if (liveSlot) liveSlot.setAttribute("aria-hidden", isBusy ? "false" : "true");
    if (mini) {
      if (isBusy) mini.removeAttribute("tabindex");
      else mini.setAttribute("tabindex", "-1");
    }
    if (!mini || jobStatusView === "hidden") return;
    const pct = Math.max(
      0,
      Math.min(
        100,
        phase === "done" && snap.ok !== false
          ? 100
          : phase === "error"
            ? Math.max(Number(snap.progress?.pct) || 0, 8)
            : Number(snap.progress?.pct) || 0
      )
    );

    mini.classList.toggle("is-running", isBusy);
    mini.classList.toggle("is-idle", phase === "idle");

    const iconWrap = $("job-status-mini-icon");
    const hasRing = !!iconWrap?.querySelector(".os-ring");
    const iconSrc =
      resolveMediaSrc(snap.iconUrl) ||
      resolveMediaSrc(snap.mode ? dockModeIcon(snap.mode) : "devplay.png?v=20260817d");
    if (iconWrap && iconSrc && !hasRing) {
      let img = iconWrap.querySelector("img");
      if (!img) {
        img = document.createElement("img");
        img.alt = "";
        img.width = 22;
        img.height = 22;
        img.decoding = "async";
        iconWrap.insertBefore(img, iconWrap.firstChild);
      } else {
        if (img.width !== 22) img.width = 22;
        if (img.height !== 22) img.height = 22;
      }
      if (img.getAttribute("src") !== iconSrc) {
        img.setAttribute("src", iconSrc);
      }
      let dot = $("job-status-mini-dot");
      if (!dot) {
        dot = document.createElement("span");
        dot.className = "job-status-mini-dot";
        dot.id = "job-status-mini-dot";
        dot.setAttribute("aria-hidden", "true");
        iconWrap.appendChild(dot);
      }
    }
    paintOsProgressRing(pct);

    const dot = $("job-status-mini-dot");
    if (dot) {
      const wantRunning = isBusy;
      const wantOk = phase === "done" && snap.ok !== false;
      const wantErr =
        phase === "error" || (phase === "done" && snap.ok === false);
      if (
        dot.classList.contains("is-running") !== wantRunning ||
        dot.classList.contains("is-ok") !== wantOk ||
        dot.classList.contains("is-err") !== wantErr
      ) {
        dot.classList.toggle("is-running", wantRunning);
        dot.classList.toggle("is-ok", wantOk);
        dot.classList.toggle("is-err", wantErr);
      }
    }

    const cur = Number(snap.progress?.current) || 0;
    const tot = Number(snap.progress?.total) || 0;
    let nextPct = "";
    if (phase === "queued") nextPct = "รอคิว";
    else if (isBusy && tot > 0) nextPct = formatNumTh(cur) + "/" + formatNumTh(tot);
    else if (isBusy) nextPct = Math.round(pct) + "%";
    else if (phase === "done") nextPct = "สำเร็จ";
    else if (phase === "error") {
      nextPct =
        snap.incomplete && tot > 0
          ? formatNumTh(cur) + "/" + formatNumTh(tot)
          : snap.incomplete
            ? ((snap.mode || liveJob?.mode) === "afterplay_fast" ? "สำเร็จบางส่วน" : "จบกลางคัน")
            : "ล้ม";
    }
    const pctEl = $("job-status-mini-pct");
    if (pctEl && pctEl.textContent !== nextPct) pctEl.textContent = nextPct;

    const countEl = $("job-status-mini-count");
    const busyCount = hubBusyKindCount();
    if (countEl) {
      const showCount = busyCount > 1;
      countEl.textContent = String(busyCount);
      countEl.hidden = !showCount;
      countEl.classList.toggle("hidden", !showCount);
    }

    const nextTitle = snap.jobTitle || "งานฟาร์ม";
    const nextLabel = isBusy ? `Live · ${nextTitle} ${nextPct}`.trim() : "สถานะงาน";
    if (mini.getAttribute("aria-label") !== nextLabel) {
      mini.setAttribute("aria-label", nextLabel);
    }
  }

  function setJobStatusTab(tab) {
    if (tab === "history" || tab === "server" || tab === "log") jobStatusHold = tab;
    else jobStatusHold = "";
    jobStatusTab = tab === "history" || tab === "server" ? tab : "live";
    if (tab === "log") liveSubView = "log";
    else if (tab === "live") liveSubView = "overview";
    const card = $("live-status-card");
    if (card) {
      card.dataset.liveView = jobStatusTab === "live" ? liveSubView : "overview";
      card.dataset.jobTab = jobStatusTab;
    }
    dockHistoryTab = "all";
    if (jobStatusTab === "server") refreshServerQueue().catch(() => {});
    else stopServerQueuePoll();
    if (jobStatusTab === "live") liveLogFollow = true;
    if (jobStatusTab === "history") {
      loadFarmHistory().catch(() => {});
    }
    renderFarmDock({ immediate: true });
  }

  function stopServerQueuePoll() {
    if (serverQueueTimer) {
      clearTimeout(serverQueueTimer);
      serverQueueTimer = null;
    }
  }

  function scheduleServerQueuePoll() {
    stopServerQueuePoll();
    serverQueueTimer = setTimeout(() => {
      serverQueueTimer = null;
      if (jobStatusTab !== "server" || jobStatusView !== "expanded" || document.hidden) return;
      refreshServerQueue().catch(() => {});
    }, 5000);
  }

  async function refreshServerQueue() {
    if (!accessToken) return;
    if (serverQueueInFlight) return;
    serverQueueInFlight = true;
    try {
      const data = await api("/api/farm/queue/server", { timeoutMs: 10000 });
      renderServerQueue(data);
    } catch (_) {
      const up = $("srvq-updated");
      if (up) up.textContent = "โหลดคิวเซิร์ฟเวอร์ไม่สำเร็จ — ลองรีเฟรช";
    } finally {
      serverQueueInFlight = false;
      if (jobStatusTab === "server") scheduleServerQueuePoll();
    }
  }

  function srvqDur(sec) {
    const s = Math.max(0, Math.round(Number(sec) || 0));
    if (s < 60) return s + " วินาที";
    const m = Math.round(s / 60);
    if (m < 60) return m + " นาที";
    return Math.floor(m / 60) + " ชม. " + (m % 60) + " นาที";
  }

  const SRVQ_STATE_TH = {
    running: "กำลังรัน",
    ready: "รอ Worker ว่าง",
    waiting_owner: "รองานก่อนหน้าของเจ้าของ",
    holding: "พักรอยืนยัน",
  };

  function srvqEl(tag, cls, text) {
    const el = document.createElement(tag);
    if (cls) el.className = cls;
    if (text != null) el.textContent = text;
    return el;
  }

  function renderServerQueue(data) {
    const totalsEl = $("srvq-totals");
    const mineEl = $("srvq-mine");
    const poolsEl = $("srvq-pools");
    const up = $("srvq-updated");
    if (!totalsEl || !mineEl || !poolsEl) return;
    const t = data?.totals || {};
    if (up) {
      const at = data?.generated_at ? new Date(data.generated_at) : new Date();
      up.textContent = "อัปเดต " + at.toLocaleTimeString("th-TH") + " · รีเฟรชทุก 5 วินาที";
    }

    totalsEl.textContent = "";
    [
      ["กำลังรัน", formatNumTh(t.running || 0) + " / " + formatNumTh(t.slots || 0) + " ช่อง"],
      ["รอคิวทั้งหมด", formatNumTh((t.queued || 0) + (t.holding || 0))],
      ["พร้อมเริ่มทันที", formatNumTh(t.ready || 0)],
      ["ผู้ใช้ที่มีงาน", formatNumTh(t.active_users || 0) + " คน"],
    ].forEach(([label, value]) => {
      const box = srvqEl("div", "srvq-stat");
      box.appendChild(srvqEl("span", "srvq-stat-label", label));
      box.appendChild(srvqEl("strong", "srvq-stat-value", value));
      totalsEl.appendChild(box);
    });

    mineEl.textContent = "";
    const mine = Array.isArray(data?.mine) ? data.mine : [];
    mineEl.appendChild(srvqEl("div", "srvq-section-title", "งานของคุณในคิวรวม"));
    if (!mine.length) {
      mineEl.appendChild(srvqEl("p", "srvq-empty muted", "คุณยังไม่มีงานในคิว"));
    }
    mine.forEach((job) => {
      const row = srvqEl("div", "srvq-mine-row is-" + (job.state || "ready"));
      const head = srvqEl("div", "srvq-mine-head");
      head.appendChild(srvqEl("strong", "srvq-mine-kind", jobKindLabel(job.kind)));
      head.appendChild(srvqEl("span", "srvq-mine-pool", "Worker: " + (job.pool_label || "—")));
      row.appendChild(head);
      let line;
      if (job.state === "running") {
        line = "กำลังรัน" + (job.run_sec != null ? " · " + srvqDur(job.run_sec) : "");
      } else {
        line =
          "ลำดับที่ " + formatNumTh(job.position) + " จาก " + formatNumTh(job.pool_pending) +
          " งานที่รอใน Worker นี้ · งานคนอื่นก่อนหน้า " + formatNumTh(job.others_ahead);
      }
      row.appendChild(srvqEl("div", "srvq-mine-line", line));
      const sub = [];
      if (job.state !== "running") sub.push(SRVQ_STATE_TH[job.state] || job.state);
      if (job.state === "ready") {
        sub.push("พร้อมเริ่มก่อนหน้า " + formatNumTh(job.ready_ahead) + " งาน");
        if (job.eta_sec != null) sub.push(job.eta_sec > 0 ? "คาดว่าเริ่มใน ~" + srvqDur(job.eta_sec) : "เริ่มได้ทันทีเมื่อ Worker รับ");
      }
      if (job.wait_sec != null && job.state !== "running") sub.push("รอมาแล้ว " + srvqDur(job.wait_sec));
      if (sub.length) row.appendChild(srvqEl("div", "srvq-mine-sub muted", sub.join(" · ")));
      mineEl.appendChild(row);
    });

    poolsEl.textContent = "";
    poolsEl.appendChild(srvqEl("div", "srvq-section-title", "แยกตาม Worker"));
    const pools = Array.isArray(data?.pools) ? data.pools : [];
    pools.forEach((pool) => {
      const card = srvqEl("div", "srvq-pool" + (pool.mine_running || pool.mine_pending ? " has-mine" : ""));
      const head = srvqEl("div", "srvq-pool-head");
      head.appendChild(srvqEl("strong", "srvq-pool-name", pool.label || pool.id));
      const load = srvqEl(
        "span",
        "srvq-pool-load",
        formatNumTh(pool.running || 0) + "/" + formatNumTh(pool.slots || 0) + " รัน · " +
          formatNumTh((pool.queued || 0) + (pool.holding || 0)) + " รอ"
      );
      head.appendChild(load);
      card.appendChild(head);

      const slots = Math.max(0, Number(pool.slots) || 0);
      if (slots) {
        const bar = srvqEl("div", "srvq-slot-bar");
        for (let i = 0; i < slots; i += 1) {
          bar.appendChild(srvqEl("span", "srvq-slot" + (i < (pool.running || 0) ? " is-busy" : "")));
        }
        card.appendChild(bar);
      }

      const facts = [];
      facts.push("ว่าง " + formatNumTh(pool.free_slots || 0) + " ช่อง");
      facts.push("พร้อมเริ่ม " + formatNumTh(pool.ready || 0));
      if (pool.waiting_owner) facts.push("รองานเจ้าของ " + formatNumTh(pool.waiting_owner));
      if (pool.holding) facts.push("พัก " + formatNumTh(pool.holding));
      if (pool.avg_run_sec) facts.push("งานละ ~" + srvqDur(pool.avg_run_sec));
      if (pool.oldest_wait_sec) facts.push("รอนานสุด " + srvqDur(pool.oldest_wait_sec));
      if (pool.draining) facts.push("กำลังรีสตาร์ท");
      card.appendChild(srvqEl("div", "srvq-pool-facts muted", facts.join(" · ")));

      const lineup = Array.isArray(pool.lineup) ? pool.lineup : [];
      if (lineup.length) {
        const ol = srvqEl("ol", "srvq-lineup");
        let waitNo = 0;
        lineup.forEach((it) => {
          const li = srvqEl("li", "srvq-lineup-item is-" + (it.state || "ready") + (it.mine ? " is-mine" : ""));
          const tag = it.state === "running" ? "▶" : String((waitNo += 1));
          li.appendChild(srvqEl("span", "srvq-lineup-no", tag));
          li.appendChild(
            srvqEl("span", "srvq-lineup-kind", (it.mine ? "งานของคุณ · " : "") + jobKindLabel(it.kind))
          );
          li.appendChild(
            srvqEl(
              "span",
              "srvq-lineup-state",
              (SRVQ_STATE_TH[it.state] || it.state) + (it.age_sec != null ? " · " + srvqDur(it.age_sec) : "")
            )
          );
          ol.appendChild(li);
        });
        card.appendChild(ol);
        if (pool.lineup_more) {
          card.appendChild(srvqEl("div", "srvq-more muted", "และอีก " + formatNumTh(pool.lineup_more) + " งาน"));
        }
      } else {
        card.appendChild(srvqEl("div", "srvq-empty muted", "ว่าง — ไม่มีงาน"));
      }
      poolsEl.appendChild(card);
    });
  }

  function openLivePage(pane) {
    const next = pane === "history" || pane === "server" || pane === "board" ? pane : "current";
    window.__ckrLivePane = next;
    try {
      const params = new URLSearchParams(location.search);
      if (next === "current") params.delete("pane");
      else params.set("pane", next);
      const search = params.toString();
      history.replaceState({}, "", location.pathname + (search ? "?" + search : "") + location.hash);
    } catch (_) {}
    if (jobStatusView === "expanded") {
      jobStatusView = "minimized";
      liveStatusOpen = false;
      dockExpanded = false;
      syncJobStatusShell();
    }
    switchFarmTab("live", { force: true });
    window.CKRLivePage?.setPane?.(next);
  }

  function expandJobStatus() {
    openLivePage("current");
  }

  function minimizeJobStatus() {
    jobStatusView = jobHubShouldStayVisible() ? "minimized" : "hidden";
    liveStatusOpen = false;
    dockExpanded = false;
    syncJobStatusShell();
    if (jobStatusView === "minimized") renderMiniStatus();
  }

  function hideJobStatusShell() {
    jobStatusView = "hidden";
    liveStatusOpen = false;
    dockExpanded = false;
    dockLiveLogOpen = false;
    releaseFocusTrap();
    syncJobStatusShell();
  }

  function openJobStatusHistory() {
    openLivePage("history");
  }

  function showFarmDock() {
    if (jobStatusView === "hidden") {
      jobStatusView = jobHubShouldStayVisible() || hasActiveJobStatus() ? "minimized" : "hidden";
      if (jobStatusView === "hidden") return;
    }
    syncJobStatusShell();
  }

  function hideFarmDock() {
    hideJobStatusShell();
    dockPhase = null;
    dockOk = null;
    dockJobStartedAt = null;
    dockJobFinishedAt = null;
    liveJob = null;
    statusContext = null;
    pipelineState = null;
    farmDockFlash = { text: "", kind: "muted" };
    stopDockElapsedTimer();
    clearPendingFarmJobs();
  }

  function expandFarmDock() {
    expandJobStatus();
  }

  function collapseFarmDock() {
    minimizeJobStatus();
  }

  function updateFarmDockBar(opts = {}) {
    renderFarmDock(opts);
  }

  function renderFarmDockQueue(items) {
    if (Array.isArray(items)) {
      if (lastGate) lastGate.queue_items = items;
      else lastGate = { queue_items: items };
    }
    renderFarmDock();
  }

  function showFarmDockQueue(gate, opts = {}) {
    lastGate = gate || lastGate;
    dockPhase = "queued";
    dockOk = null;
    if (!jobStatusHold && (jobStatusView !== "expanded" || jobStatusTab === "live")) {
      jobStatusTab = "live";
    }
    showFarmDock();
    renderFarmDock({
      mode: jobKindToMode(queuedJobKind || currentJobKind()),
      waking: opts.waking,
    });
  }

  function stopWatchJobPoll() {
    if (watchJobTimer) {
      clearInterval(watchJobTimer);
      watchJobTimer = null;
    }
    stopProgressPoll();
  }

  function clearActiveWatcher(jobId) {
    if (activeWatcher?.jobId === jobId) activeWatcher = null;
  }

  function persistWatchJobId(id) {
    activeWatchJobId = id || null;
    try {
      if (id) localStorage.setItem(FARM_JOB_ID_KEY, id);
      else localStorage.removeItem(FARM_JOB_ID_KEY);
    } catch (_) {}
  }

  function persistFarmIntent(intent) {
    try {
      if (!intent) {
        sessionStorage.removeItem(FARM_JOB_INTENT_KEY);
        return;
      }
      const safeBody = { ...(intent.body || {}) };
      delete safeBody.password;
      delete safeBody.email;
      delete safeBody.proxy_url;
      sessionStorage.setItem(
        FARM_JOB_INTENT_KEY,
        JSON.stringify({
          url: intent.url,
          mode: intent.mode,
          target: Number(intent.target) || 0,
          body: safeBody,
          jobId: intent.jobId || null,
          savedAt: Date.now(),
        })
      );
    } catch (_) {}
  }

  function loadFarmIntent() {
    try {
      const raw = sessionStorage.getItem(FARM_JOB_INTENT_KEY);
      const parsed = raw ? JSON.parse(raw) : null;
      if (!parsed || Date.now() - Number(parsed.savedAt || 0) > FARM_JOB_INTENT_TTL_MS) {
        return null;
      }
      return parsed;
    } catch (_) {
      return null;
    }
  }

  function newClientJobKey() {
    if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
    return (
      Date.now().toString(36) +
      "-" +
      Math.random().toString(36).slice(2) +
      "-" +
      Math.random().toString(36).slice(2)
    );
  }

  async function fetchJobStatus(jobId) {
    return api("/api/farm/job/" + encodeURIComponent(jobId));
  }

  function applyLiveJobProgress(jobRow, mode, target) {
    if (jobRow?.id && !isHubPrimaryJob(jobRow.id)) return;
    const m = mode || jobKindToMode(jobRow?.job_kind) || statusContext?.mode || "partyrun";
    const rowStatus = String(jobRow?.status || "").toLowerCase();
    adoptDockClockFromJob(jobRow);
    // Switch pipeline when the active job kind changes (prevents Party Run steps leaking onto Cookie Unlock).
    if (!pipelineState || pipelineState.mode !== m) {
      const keep = statusContext?.mode === m ? statusContext : null;
      statusContext = {
        ...(keep || {}),
        mode: m,
        target: target || keep?.target || 0,
      };
      pipelineState = freshPipeline(m);
      adoptDockClockFromJob(jobRow);
      if (!dockJobStartedAt) dockJobStartedAt = Date.now();
      if (rowStatus === "queued") {
        dockPhase = "queued";
      } else if (dockPhase !== "running" && dockPhase !== "done" && dockPhase !== "error") {
        dockPhase = "running";
      }
    } else if (rowStatus === "queued") {
      dockPhase = "queued";
    } else if (dockPhase !== "running" && dockPhase !== "done" && dockPhase !== "error") {
      dockPhase = "running";
    }
    const logs = jobRow?.logs || [];
    applyLogsToPipeline(logs, m);
    const parsed = parseProgressFromLogs(logs, m, target);
    // Prefer DB progress only when it advances past log-parsed values (or job finished).
    // Stale worker heartbeats that keep writing {current:0} must not wipe live log progress.
    const jobDone =
      jobRow?.status === "succeeded" ||
      jobRow?.status === "failed" ||
      jobRow?.status === "cancelled";
    if (jobRow?.progress) {
      const dbCur = jobRow.progress.current != null ? Number(jobRow.progress.current) : null;
      const dbTot = jobRow.progress.total != null ? Number(jobRow.progress.total) : null;
      if (dbTot != null && dbTot > 0) {
        parsed.total = Math.max(Number(parsed.total) || 0, dbTot);
      }
      if (dbCur != null && Number.isFinite(dbCur)) {
        if (jobDone || dbCur >= (Number(parsed.current) || 0)) {
          parsed.current = dbCur;
        }
      }
      if (jobRow.progress.phase) {
        parsed.phase = jobRow.progress.phase;
      }
      setDockEtaFromProgress(jobRow.progress);
    }
    if (m === "unlock_l") {
      const extra = unlockLExtrasFromJob(jobRow);
      if (extra.unlockEp) {
        if (statusContext) statusContext.unlockEp = extra.unlockEp;
        if (liveJob && liveJob.id === jobRow?.id) liveJob.unlockEp = extra.unlockEp;
      }
      if (extra.unlockEps && extra.unlockEps.length) {
        if (statusContext) statusContext.unlockEps = extra.unlockEps;
        if (liveJob && liveJob.id === jobRow?.id) liveJob.unlockEps = extra.unlockEps;
      }
    }
    if (m === "afterplay_fast") {
      const fam = afterplayFamilyFromJob(jobRow);
      if (fam) {
        if (statusContext) statusContext.family = fam;
        if (liveJob && liveJob.id === jobRow?.id) liveJob.family = fam;
      }
    }
    if (m === "upgrade" && statusContext?.itemTotal > 0) {
      parsed.total = statusContext.itemTotal;
      const done = statusContext.itemsCompleted;
      parsed.current =
        done != null ? done : Math.max(0, (statusContext.itemIndex || 1) - 1);
    }
    pipelineState.progress = {
      current: parsed.current,
      total: parsed.total || target || statusContext?.target || 0,
    };
    if (parsed.phase) {
      pipelineState.progressPhase = parsed.phase;
      const phaseStep = stepIdxFromPhase(m, parsed.phase);
      if (phaseStep >= 0) setPipelineActive(phaseStep);
    }
    renderPipeline();
  }

  function stepIdxFromPhase(mode, phase) {
    const key = String(phase || "").toLowerCase();
    if (!key) return -1;
    const alias = {
      start: "login",
      round: "run",
      collect: "claim",
      items: mode === "cookie_unlock" ? "unlock" : mode === "upgrade" ? "upgrade" : "run",
      unlock: "unlock",
      buy: "buy",
      extract: "extract",
      open: "open",
      draw: "draw",
      send: "send",
      waiting: "wait",
      wait: "wait",
      climb: "climb",
      playing: "climb",
      star_ok: "climb",
      scanned: "login",
      starting: "login",
      unlocking: "unlock",
      owned: "unlock",
      hunting: "hunting",
      friends: "friends",
      invite: "invite",
      powder: "powder",
      craft: "craft",
      evo: "evo",
      scan: "login",
    };
    const want = alias[key] || key;
    const steps = pipelineStepsFor(mode);
    return steps.findIndex((s) => s.id === want);
  }

  async function watchFarmJob(jobId, mode, target, handlers) {
    if (activeWatcher?.jobId === jobId) {
      return activeWatcher.promise;
    }
    if (activeWatcher) {
      stopWatchJobPoll();
      activeWatcher.resolve?.(null);
      activeWatcher = null;
    }
    persistWatchJobId(jobId);
    // Bind the tracked live job to this concrete job id so pollers can't hijack it.
    const keepCancel = !!(
      liveJob?.cancelRequested || userCancelLatchIds.has(String(jobId))
    );
    if (!liveJob || liveJob.finished || liveJob.id === jobId) {
      liveJob = {
        id: jobId,
        mode,
        target: Number(target) || 0,
        finished: false,
        source: "farm",
        cancelRequested: keepCancel,
      };
    } else if (liveJob.mode === mode && liveJob.source !== "credit") {
      liveJob.id = jobId;
      liveJob.finished = false;
      if (target) liveJob.target = Number(target) || liveJob.target;
      if (keepCancel) liveJob.cancelRequested = true;
    }
    rememberJobAccount(jobId);
    if (isHubPrimaryJob(jobId)) {
      dockPhase = "running";
      dockOk = null;
      if (!dockJobStartedAt) dockJobStartedAt = Date.now();
      startDockElapsedTimer();
      if (!jobStatusHold) {
        jobStatusTab = "live";
        liveSubView = "overview";
      }
      showFarmDock();
      renderFarmDock({ mode, target });
    }

    let watcherResolve = null;
    const promise = new Promise((resolve) => {
      watcherResolve = resolve;
      let settled = false;
      let pollErrors = 0;
      let tickInFlight = false;
      const finishWatch = async (jobRow) => {
        if (settled) return;
        settled = true;
        stopWatchJobPoll();
        persistWatchJobId(null);
        const result = jobRow?.result || {};
        const logs = jobRow?.logs || [];
        const st = jobRow?.status || "";
        let ok = st === "succeeded";
        const incompleteFarm =
          (mode === "powder" || mode === "afterplay_fast" || mode === "ice_tower") &&
          farmResultIncomplete(jobRow);
        if (incompleteFarm) ok = false;
        // Heart: getting some hearts but short of target is a PARTIAL success, not a
        // failure — only zero collected counts as a real failure. This stops the UI
        // from showing "รับหัวใจไม่สำเร็จ" when the pool sent whatever it could.
        if (
          mode === "heart" &&
          st !== "cancelled" &&
          st !== "cancelled_stale" &&
          !farmJobIsWorkerRestart(jobRow)
        ) {
          const hp = heartProgressFromResult(result, target, jobRow);
          if (hp.incomplete) {
            if (hp.got > 0) {
              ok = true;
              result.partial = true;
            } else {
              ok = false;
            }
          }
        }
        // Cookie unlock: treat in-game unlock / partial result as success even if
        // an older worker wrote failed after Unlock OK + upgrade fail.
        if (
          !ok &&
          st !== "cancelled" &&
          (mode === "cookie_unlock" || mode === "cookie") &&
          (Number(result.items_done || 0) > 0 || result.partial || result.ok === true)
        ) {
          ok = true;
        }
        const primary = isHubPrimaryJob(jobId);
        // Capture cancel intent BEFORE buildFinalPipeline — that call does
        // pipelineState = freshPipeline(m) and wipes pipelineState.cancelling.
        const cancelTerminal = isUserCancelTerminal(jobRow, st, jobId);
        if (primary) {
          stopDockElapsedTimer();
          dockOk = ok;
          dockPhase = ok ? "done" : "error";
        }
        lastFinishedJobId = jobId;
        if (liveJob && (liveJob.id === jobId || !liveJob.id)) {
          liveJob.id = jobId;
          liveJob.finished = true;
          liveJob.incomplete = !!incompleteFarm;
        }
        stopProgressPoll();
        if (primary) buildFinalPipeline(logs, result, ok, mode);
        const completed = Number(
          result.items_done ??
          result.rounds_completed ??
          result.hearts ??
          result.current ??
          0
        );
        if (primary && !ok && completed <= 0 && pipelineState) {
          pipelineState.extras = [
            { text: "ล้มเหลวก่อนเริ่ม · 0/" + (Number(target) || 0), kind: "err" },
            ...(pipelineState.extras || []),
          ];
        }
        if (primary && jobRow?.billing_outcome?.charged === false && pipelineState) {
          pipelineState.extras = [
            ...(pipelineState.extras || []),
            { text: "งานนี้รวมในวันเช่า · ไม่มีการหักโทเคน", kind: "ok" },
          ];
        }
        const resultError = String(
          result.error || jobRow?.error || jobRow?.detail || ""
        );
        if (/devplay_session_expired|session_expired|login_failed/i.test(resultError)) {
          devplayConnectionState = "expired";
          recoverDevPlaySession().catch(() => false);
        }
        if (primary) {
          openRunStatusPopup(false);
          setRunStatusClosable(true);
          setRunStatusSubtitle(true, ok);
          renderFarmDock({ mode, target, ok });
        }
        if (ok && typeof handlers?.onSuccess === "function") {
          handlers.onSuccess({ ...jobRow, result, ok: true, logs, ...result });
        } else if (!ok && typeof handlers?.onError === "function") {
          handlers.onError({ ...jobRow, result, ok: false, logs, ...result });
        }
        // Cancel path: handlers often park showHeartResultModal behind
        // pendingAfterRunStatus (only opens after 「ปิด」). Auto-dismiss instead.
        if (primary && cancelTerminal) {
          scheduleCancelTerminalHandoff({
            toastMsg: buildCancelTerminalToast(mode, jobRow, result, target),
          });
          userCancelLatchIds.delete(String(jobId));
        }
        clearActiveWatcher(jobId);
        persistFarmIntent(null);
        attachNextQueuedJob();
        resolve(jobRow);
      };

      let gateTick = 0;
      const tick = async () => {
        if (settled || !accessToken || tickInFlight) return;
        tickInFlight = true;
        try {
          // Gate is expensive under load — poll it every 3s, not every tick.
          gateTick += 1;
          const wantGate = gateTick === 1 || gateTick % 3 === 0 || !!queuedRun;
          const gatePromise = wantGate
            ? api("/api/farm/gate", { timeoutMs: 12000 }).catch(() => null)
            : Promise.resolve(null);
          const activePromise = api("/api/farm/active-job", {
            timeoutMs: 12000,
          }).catch(() => null);
          const [gateData, activeData] = await Promise.all([gatePromise, activePromise]);
          if (settled || activeWatcher?.jobId !== jobId) return;
          if (gateData) {
            lastGate = gateData;
            if (Array.isArray(gateData.queue_items)) {
              renderFarmDockQueue(gateData.queue_items);
            }
          }
          if (activeData?.active && activeData.job_id === jobId) {
            applyLiveJobProgress(activeData, mode || jobKindToMode(activeData.job_kind), target);
            return;
          }
          const jobRow = await fetchJobStatus(jobId);
          if (settled || activeWatcher?.jobId !== jobId) return;
          if (jobRow.status === "running" || jobRow.status === "queued") {
            applyLiveJobProgress(jobRow, mode || jobKindToMode(jobRow.job_kind), target);
            return;
          }
          const payload = { ...jobRow, ...(jobRow.result || {}), result: jobRow.result };
          pollErrors = 0;
          await finishWatch(payload);
        } catch (e) {
          pollErrors += 1;
          if (pollErrors === 3 && pipelineState) {
            pipelineState.extras = [
              {
                text: "ขาดการเชื่อมต่อชั่วคราว — กำลังลองใหม่…",
                kind: "muted",
              },
              ...(pipelineState.extras || []).filter(
                (x) => !/ขาดการเชื่อมต่อ/.test(String(x?.text || ""))
              ),
            ];
            renderFarmDock({ mode, target });
          }
          if (pollErrors >= 8 && !settled) {
            dockPhase = "error";
            dockOk = false;
            stopDockElapsedTimer();
            const msg = thError(e.message || e.data?.detail || "job_poll_failed");
            if (pipelineState) {
              pipelineState.extras = [{ text: msg, kind: "err" }];
            }
            farmDockFlash = { text: msg, kind: "err" };
            renderFarmDock({ mode, target, ok: false, errorMsg: msg });
            showToast(msg, "err");
            if (typeof handlers?.onError === "function") {
              handlers.onError({ ok: false, error: "job_poll_failed", detail: msg });
            }
            settled = true;
            stopWatchJobPoll();
            persistWatchJobId(null);
            clearActiveWatcher(jobId);
            resolve(null);
            if (!queuedRun) dequeueAndStartNext();
          }
        } finally {
          tickInFlight = false;
        }
      };

      stopWatchJobPoll();
      watchJobTimer = setInterval(tick, 2500);
      tick();
    });
    activeWatcher = { jobId, promise, resolve: watcherResolve };
    return promise;
  }

  async function withFarmStarting(fn) {
    farmStarting = true;
    updateFarmAvailability();
    try {
      return await fn();
    } finally {
      farmStarting = false;
      updateFarmAvailability();
    }
  }

  async function submitFarmJob({ url, body, mode, target, handlers, extras }) {
    body = {
      ...(body || {}),
      client_job_key: body?.client_job_key || newClientJobKey(),
    };
    const queueLabel = takePendingQueueLabel(mode);
    // หัวใจฟรี 100 is a 24h trial quota — never park it behind other jobs.
    if (body.free_mode && heartJobLive()) {
      showErrorModal(ERR_TH.no_advance_queue, "ยังเริ่มไม่ได้");
      return null;
    }
    // Something else already owns the live card: park this job in the server
    // queue rather than stealing the view from the job that is running.
    if (anyJobLive()) {
      if (!queueHasRoom()) {
        showErrorModal(queueFullMessage(), "คิวเต็ม");
        return null;
      }
      farmStarting = true;
      updateFarmAvailability();
      try {
        await ensureApiReady();
        const data = await api(url, { method: "POST", body });
        if (data?.accepted && data?.job_id) {
          rememberJobAccount(data.job_id);
          applyStartWallet(data);
          announceQueuedJob(data, queueLabel);
          // Other functions run side by side; only the same function waits its turn.
          const qItems = Array.isArray(data?.queue?.items) ? data.queue.items : [];
          const sameKindAhead = qItems.some(
            (it) => String(it.job_id || it.id || "") !== String(data.job_id) && String(it.kind || "") === String(data.kind || "")
          );
          setFarmStatus(
            sameKindAhead
              ? "เข้าคิวแล้ว" + queueSeqTag(data) + " — เริ่มต่ออัตโนมัติเมื่องานฟังก์ชันเดียวกันก่อนหน้าจบ"
              : "ส่งงานแล้ว" + queueSeqTag(data) + " — รันพร้อมกับงานฟังก์ชันอื่นได้ (ถ้าเป็นไอดีเกมเดียวกับฟาร์ม Coin/XP/กล่อง จะรอให้จบก่อนตามกฎเกม) ดูสถานะที่หน้า Live",
            "ok"
          );
        }
        return data;
      } catch (e) {
        reportQueueSubmitError(e, queueLabel);
        return null;
      } finally {
        farmStarting = false;
        updateFarmAvailability();
      }
    }
    farmRunning = true;
    persistFarmIntent({ url, body, mode, target });
    resetDockLiveForJob(mode, target, extras || {});
    showFarmDock();
    renderFarmDock({ mode, target });
    updateFarmAvailability();
    try {
      await ensureApiReady();
      const data = await api(url, { method: "POST", body });
      if (data.accepted && data.job_id) {
        persistFarmIntent({ url, body, mode, target, jobId: data.job_id });
        if (data.queue) applyQueuePayload(data.queue);
        startAdvanceQueuePoll();
        startLiveStages({ mode, target, ...(extras || {}) });
        showFarmDock();
        return await watchFarmJob(data.job_id, mode, target, handlers);
      }
      if (data.accepted && !data.job_id) {
        const err = new Error("job_tracking_unavailable");
        err.status = 503;
        throw err;
      }
      if (data.ok != null && !data.accepted) {
        const ok = !!data.ok;
        dockPhase = ok ? "done" : "error";
        dockOk = ok;
        startLiveStages({ mode, target, ...(extras || {}) });
        buildFinalPipeline(data.logs || [], data.result || data, ok, mode);
        showFarmDock();
        if (ok && handlers?.onSuccess) handlers.onSuccess(data);
        else if (!ok && handlers?.onError) handlers.onError(data);
        persistFarmIntent(null);
        return data;
      }
      return data;
    } catch (e) {
      clearStageTimer();
      const detailCode =
        e?.data?.detail?.code ||
        e?.data?.detail?.message ||
        e?.code ||
        e?.message ||
        "";
      if (/already_running/i.test(String(detailCode))) {
        showToast(ERR_TH.already_running, "muted");
        showFarmDock();
        await resumeFarmSession();
        return null;
      }
      if (e.status === 409 || /farm_busy/i.test(String(e.message))) {
        showFarmDock();
        await enterQueueFor(
          e.gate || e.data?.detail?.gate,
          () => submitFarmJob({ url, body, mode, target, handlers, extras }),
          modeToJobKind(mode)
        );
        setFarmStatus( "ระบบไม่ว่าง — จองคิวให้แล้ว รอสักครู่", "muted");
        return null;
      }
      if (/job_tracking_unavailable/i.test(String(e.message))) {
        dockPhase = "error";
        dockOk = false;
        showFarmDock();
        renderFarmDock({ mode, target, ok: false, errorMsg: "ไม่สามารถติดตามงานบนเซิร์ฟเวอร์ได้ — ลองใหม่" });
      }
      if (!/timeout|network_error/i.test(String(e.message || ""))) {
        persistFarmIntent(null);
      }
      throw e;
    } finally {
      farmRunning = false;
      updateFarmAvailability();
      if (!queuedRun && !activeWatchJobId) {
        dequeueAndStartNext(dockPhase === "done" || dockPhase === "error" ? 900 : 320);
      }
    }
  }

  async function resumeFarmSession() {
    if (!accessToken) return;
    try {
      const savedIntent = loadFarmIntent();
      const gate = await api("/api/farm/gate", { timeoutMs: 8000 }).catch(() => null);
      if (gate) lastGate = gate;
      const active = await api("/api/farm/active-job").catch(() => null);
      let jobId = active?.active ? active.job_id : null;
      if (!jobId) {
        try {
          jobId = localStorage.getItem(FARM_JOB_ID_KEY);
        } catch (_) {}
      }
      // Never resurrect a job we already finished and are showing as done/error.
      if (active?.active && jobId && jobId === lastFinishedJobId) return;
      if (active?.active && jobId) {
        const mode =
          jobKindToMode(active.job_kind || active.kind) ||
          savedIntent?.mode ||
          "partyrun";
        const target =
          Number(active.progress?.total) ||
          Number(savedIntent?.target) ||
          statusContext?.target ||
          0;
        resetDockLiveForJob(mode, target, {
          started_at: active.started_at,
          created_at: active.created_at,
          finished_at: active.finished_at,
          elapsed_sec: active.elapsed_sec,
          preserveTab: true,
        });
        statusContext = { ...(statusContext || {}), mode, target };
        if (mode === "afterplay_fast") {
          statusContext.family = afterplayFamilyFromJob(active) || afterplayFamily;
        }
        if (mode === "unlock_l") {
          const extra = unlockLExtrasFromJob(active);
          statusContext.unlockEp = extra.unlockEp;
          statusContext.unlockEps = extra.unlockEps;
        }
        liveJob = {
          id: jobId,
          mode,
          target,
          finished: false,
          source: "resume",
          family: statusContext.family,
          unlockEp: statusContext.unlockEp,
          unlockEps: statusContext.unlockEps,
        };
        startLiveStages({
          mode,
          target,
          started_at: active.started_at,
          created_at: active.created_at,
          finished_at: active.finished_at,
          elapsed_sec: active.elapsed_sec,
        });
        showFarmDock();
        farmRunning = true;
        updateFarmAvailability();
        showToast(
          "พบงาน" +
            (JOB_KIND_TH[mode] || mode) +
            "ที่รันต่อจากครั้งก่อน" +
            (gate?.me?.position
              ? " · อันดับคิว " + gate.me.position
              : gate?.me?.status === "active"
                ? " · กำลังรัน"
                : "") +
            " — ดูแถบสถานะ",
          "muted"
        );
        watchFarmJob(jobId, mode, target, {
          onSuccess: () => {
            farmRunning = false;
            updateFarmAvailability();
            refreshMe().catch(() => {});
            loadFarmHistory().catch(() => {});
          },
          onError: () => {
            farmRunning = false;
            updateFarmAvailability();
            loadFarmHistory().catch(() => {});
          },
        }).finally(() => {
          farmRunning = false;
          updateFarmAvailability();
          if (!queuedRun && !activeWatchJobId) {
            dequeueAndStartNext();
          }
        });
        return;
      }
      if (
        !active?.active &&
        !gate?.me?.status &&
        !queuedRun &&
        pendingFarmJobs.length === 0 &&
        !activeWatchJobId &&
        !activeWatcher &&
        !watchJobTimer &&
        !farmRunning
      ) {
        // Clear stale local tracking after refresh/background resume. Without
        // this, an old running phase renders as a phantom Party Run forever.
        // Never wipe while a local watcher is still attached to a live job.
        let localJobId = null;
        try {
          localJobId = localStorage.getItem(FARM_JOB_ID_KEY);
        } catch (_) {}
        if (localJobId) {
          const row = await fetchJobStatus(localJobId).catch(() => null);
          const st = String(row?.status || "");
          if (st === "queued" || st === "running") {
            // Server still has the job — re-attach instead of wiping.
            const mode =
              jobKindToMode(row.job_kind || row.kind) ||
              savedIntent?.mode ||
              "partyrun";
            const target =
              Number(row.progress?.total) ||
              Number(savedIntent?.target) ||
              0;
            resetDockLiveForJob(mode, target, { preserveTab: true });
            statusContext = { ...(statusContext || {}), mode, target };
            if (mode === "afterplay_fast") {
              statusContext.family = afterplayFamilyFromJob(row) || afterplayFamily;
            }
            if (mode === "unlock_l") {
              const extra = unlockLExtrasFromJob(row);
              statusContext.unlockEp = extra.unlockEp;
              statusContext.unlockEps = extra.unlockEps;
            }
            liveJob = {
              id: localJobId,
              mode,
              target,
              finished: false,
              source: "resume",
              family: statusContext.family,
              unlockEp: statusContext.unlockEp,
              unlockEps: statusContext.unlockEps,
            };
            farmRunning = true;
            updateFarmAvailability();
            watchFarmJob(localJobId, mode, target, {}).catch(() => {});
            return;
          }
        }
        persistWatchJobId(null);
        farmRunning = false;
        if (dockPhase === "running" || dockPhase === "queued") {
          dockPhase = null;
          liveJob = null;
          statusContext = null;
          pipelineState = null;
          stopDockElapsedTimer();
        }
        if (
          (dockPhase === "done" || dockPhase === "error") &&
          jobStatusView !== "expanded"
        ) {
          dockPhase = null;
          liveJob = null;
          statusContext = null;
          pipelineState = null;
          hideJobStatusShell();
        }
      }
      if (gate?.me?.status === "waiting" || gate?.me?.status === "active") {
        if (savedIntent?.url && savedIntent?.body) {
          queuedJobKind = modeToJobKind(savedIntent.mode);
          queuedRun = () =>
            submitFarmJob({
              url: savedIntent.url,
              body: savedIntent.body,
              mode: savedIntent.mode,
              target: savedIntent.target,
              handlers: {},
            });
        }
        showFarmDockQueue(gate);
        startQueuePoll();
      }
    } catch (_) {}
  }

  function liveStatusJobId() {
    return liveJob?.id || activeWatchJobId || "";
  }

  function syncJobStatusCardLayout(snap) {
    const card = $("live-status-card");
    if (!card) return;
    snap = snap || buildDockSnapshot();
    const phase = snap.phase || "idle";
    card.dataset.jobTab = jobStatusTab;
    card.dataset.liveView = jobStatusTab === "live" ? liveSubView : "overview";
    card.setAttribute("data-phase", phase);
    card.classList.remove("is-compact");
  }

  function paintJobStatusHeader(snap) {
    snap = snap || buildDockSnapshot();
    const phase = snap.phase || "idle";

    const iconImg = $("live-status-icon-img");
    const iconSrc =
      resolveMediaSrc(snap.iconUrl) ||
      (snap.mode ? resolveMediaSrc(dockModeIcon(snap.mode)) : resolveMediaSrc("devplay.png?v=20260817d"));
    if (iconImg && iconSrc && iconImg.getAttribute("src") !== iconSrc) {
      iconImg.src = iconSrc;
    }
    const pct = Math.max(
      0,
      Math.min(
        100,
        phase === "done" && snap.ok !== false
          ? 100
          : phase === "error"
            ? Math.max(Number(snap.progress?.pct) || 0, 8)
            : Number(snap.progress?.pct) || 0
      )
    );
    paintOsProgressRing(pct);

    const chip = $("live-status-chip");
    if (chip) {
      chip.textContent = snap.statusBadge || dockPhaseLabel(phase);
      chip.setAttribute("data-phase", phase);
    }

    const titleEl = $("live-status-title");
    if (titleEl) titleEl.textContent = snap.jobTitle || "งานฟาร์ม";
    const detailEl = $("live-status-detail");
    if (detailEl) detailEl.textContent = snap.jobDetail || snap.panelSub || "—";
  }

  function jobLogLinesAsText(logLines) {
    const lines = Array.isArray(logLines) ? logLines.slice(-200) : [];
    return lines
      .map((l) => redactLogText(typeof l === "string" ? l : l?.text || ""))
      .filter((t) => String(t).trim())
      .join("\n");
  }

  async function copyTextToClipboard(text, toastMsg) {
    const t = String(text || "").trim();
    if (!t || t === "ยังไม่มี log" || t === "กำลังโหลด…") {
      showToast("ยังไม่มี log", "err");
      return false;
    }
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(t);
      } else {
        const ta = document.createElement("textarea");
        ta.value = t;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        ta.remove();
      }
      showToast(toastMsg || "คัดลอกแล้ว", "ok");
      return true;
    } catch (_) {
      showToast("คัดลอกไม่สำเร็จ", "err");
      return false;
    }
  }

  function copyJobLogModal() {
    const body = $("job-log-body");
    return copyTextToClipboard(body?.textContent || "", "คัดลอก log แล้ว");
  }

  function copyLiveJobLogPreview() {
    const snap = buildDockSnapshot();
    return copyTextToClipboard(jobLogLinesAsText(snap.logLines), "คัดลอก log แล้ว");
  }

  function paintSessionTimelineDot(kind) {
    const dot = document.createElement("span");
    dot.className = "session-timeline-dot";
    dot.setAttribute("aria-hidden", "true");
    fillSessionTimelineDot(dot, kind);
    return dot;
  }

  function fillSessionTimelineDot(dot, kind) {
    if (!dot) return;
    if (kind === "ok") {
      dot.innerHTML =
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="20 6 9 17 4 12"/></svg>';
    } else if (kind === "pending") {
      dot.innerHTML =
        '<svg class="session-timeline-spinner" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" aria-hidden="true"><path d="M12 3a9 9 0 1 1-6.36 15.36"/></svg>';
    } else if (kind === "err") {
      dot.innerHTML =
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" aria-hidden="true"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>';
    } else {
      dot.innerHTML =
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><circle cx="12" cy="12" r="4"/></svg>';
    }
  }

  function sessionTimelineKindClass(kind) {
    if (kind === "ok") return " is-ok";
    if (kind === "pending") return " is-pending";
    if (kind === "err") return " is-err";
    return "";
  }

  function sessionTimelineSubText(kind) {
    if (kind === "ok") return "เสร็จสิ้น";
    if (kind === "pending") return "กำลังทำ";
    return "รอคิว";
  }

  function buildSessionTimelineItem(step, kind, index, snap) {
    const li = document.createElement("li");
    li.className = "session-timeline-item" + sessionTimelineKindClass(kind);
    li.dataset.stepId = String(step.id || index);
    li.dataset.kind = kind;

    const topRow = document.createElement("div");
    topRow.className = "session-timeline-card-top";

    const dot = paintSessionTimelineDot(kind);
    const stepNum = document.createElement("span");
    stepNum.className = "session-timeline-step-badge";
    stepNum.textContent = "STEP " + (index + 1);

    topRow.appendChild(dot);
    topRow.appendChild(stepNum);

    const label = document.createElement("span");
    label.className = "session-timeline-label";
    label.textContent = stepLabel(step, kind, snap.mode) || step.label || step.id;

    const sub = document.createElement("span");
    sub.className = "session-timeline-sub";
    sub.textContent = sessionTimelineSubText(kind);

    li.appendChild(topRow);
    li.appendChild(label);
    li.appendChild(sub);
    return li;
  }

  function patchLiveStatusSteps(stepsBox, snap) {
    const steps = Array.isArray(snap.steps) ? snap.steps : [];
    const kinds = snap.stepKinds || {};
    stepsBox.style.setProperty("--step-count", String(Math.max(steps.length, 1)));
    const existing = stepsBox.children;
    if (existing.length !== steps.length) {
      const frag = document.createDocumentFragment();
      for (let i = 0; i < steps.length; i++) {
        const s = steps[i];
        frag.appendChild(buildSessionTimelineItem(s, kinds[s.id] || "idle", i, snap));
      }
      stepsBox.replaceChildren(frag);
      return;
    }
    for (let i = 0; i < steps.length; i++) {
      const s = steps[i];
      const kind = kinds[s.id] || "idle";
      const li = existing[i];
      if (li.dataset.kind !== kind) {
        li.dataset.kind = kind;
        li.className = "session-timeline-item" + sessionTimelineKindClass(kind);
        fillSessionTimelineDot(li.querySelector(".session-timeline-dot"), kind);
      }
      const label = li.querySelector(".session-timeline-label");
      const labelText = stepLabel(s, kind, snap.mode) || s.label || s.id;
      if (label && label.textContent !== labelText) label.textContent = labelText;
      const sub = li.querySelector(".session-timeline-sub");
      const subText = sessionTimelineSubText(kind);
      if (sub && sub.textContent !== subText) sub.textContent = subText;
    }
  }

  function paintJobLogModalBody(logLines) {
    if (adminJobLogActive) return;
    const modal = $("job-log-modal");
    const body = $("job-log-body");
    if (!modal || !body || modal.classList.contains("hidden")) return;
    const text = jobLogLinesAsText(logLines);
    const next = text || "ยังไม่มี log";
    if (body.textContent !== next) {
      const stickBottom =
        body.scrollHeight - body.scrollTop - body.clientHeight < 48;
      body.textContent = next;
      if (stickBottom) body.scrollTop = body.scrollHeight;
    }
  }

