  $("signup-form")?.addEventListener("submit", async (ev) => {
    ev.preventDefault();
    if (lastHealth && lastHealth.signup_closed) {
      applySignupClosed(true);
      return;
    }
    const remember = !!$("signup-remember")?.checked;
    setRememberPref(remember);
    if ($("remember-me")) $("remember-me").checked = remember;

    const username = ($("signup-user")?.value || "").trim();
    const password = $("signup-pass")?.value || "";
    const confirmPassword = $("signup-pass2")?.value || "";

    if (password !== confirmPassword) {
      const pass2 = $("signup-pass2");
      if (pass2) {
        pass2.setAttribute("aria-invalid", "true");
        pass2.focus();
      }
      setStatus($("signup-status"), ERR_TH.password_mismatch, "err");
      return;
    }
    $("signup-pass2")?.removeAttribute("aria-invalid");
    if (username.includes("@")) {
      setStatus($("signup-status"), "", "muted");
      showErrorModal(ERR_TH.invalid_username, "ชื่อผู้ใช้ไม่ถูกต้อง");
      return;
    }
    if (password.length < 6) {
      setStatus($("signup-status"), "", "muted");
      showErrorModal("รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร", "รหัสผ่านสั้นเกินไป");
      return;
    }

    const token = readTurnstileToken("signup-turnstile");
    if (!token) {
      setStatus($("signup-status"), ERR_TH.turnstile_required, "err");
      ensureTurnstile("signup-turnstile");
      return;
    }

    setStatus($("signup-status"), "กำลังสมัครสมาชิก…", "muted");
    $("signup-btn").disabled = true;
    try {
      const data = await api("/api/auth/register", {
        method: "POST",
        credentials: "include",
        body: {
          username,
          password,
          confirm_password: confirmPassword,
          affiliate_code: ($("signup-affiliate")?.value || readAffiliateRef() || "").trim() || undefined,
          "cf-turnstile-response": token,
        },
      });
      if (!data.access_token || !data.refresh_token) {
        throw new Error("register_session_failed");
      }
      try {
        const { error } = await sb.auth.setSession({
          access_token: data.access_token,
          refresh_token: data.refresh_token,
        });
        if (error) console.warn("setSession", error);
      } catch (sessionErr) {
        console.warn("setSession", sessionErr);
      }
      accessToken = data.access_token;
      persistSessionToken(data.session_token || null);
      profile = data.profile;
      if (wantsRemember()) await saveAutoLoginCreds(username, password);
      else clearAutoLoginCreds();
      setStatus($("signup-status"), "", "muted");
      setupDevPlayAutofillGuards();
      await refreshMe();
      paintDevPlayAccountPicker();
      pingApiHealth(1).catch(() => {});
    } catch (e) {
      const raw = String(e.message || "");
      let title = "สมัครสมาชิกไม่สำเร็จ";
      if (raw.includes("username_taken")) title = "ชื่อผู้ใช้ซ้ำ";
      else if (raw.includes("signup_closed")) title = "ปิดรับสมัครผ่านเว็บ";
      else if (raw.includes("signup_rate_limited")) title = "สมัครถี่เกินไป";
      else if (raw.includes("affiliate_code_invalid") || raw.includes("affiliate_code_disabled")) title = "รหัสชวนสมัครไม่ถูกต้อง";
      else if (raw.includes("affiliate_self")) title = "ใช้รหัสของตัวเองไม่ได้";
      else if (raw.includes("password_mismatch")) title = "ยืนยันรหัสผ่านไม่ตรง";
      else if (raw.includes("invalid_username")) title = "ชื่อผู้ใช้ไม่ถูกต้อง";
      else if (raw.includes("turnstile_failed") || raw.includes("turnstile_required")) {
        title = "ยืนยันตัวตนไม่สำเร็จ";
      }
      else if (raw.includes("service_role_not_configured") || raw.includes("auth_not_configured")) {
        title = "ระบบยังไม่พร้อม";
      } else if (raw.includes("register_session_failed")) {
        title = "สมัครแล้ว แต่เข้าสู่ระบบไม่ได้";
      }
      const msg = thError(e.message) || "สมัครสมาชิกไม่สำเร็จ";
      setStatus($("signup-status"), "", "muted");
      resetTurnstile("signup-turnstile");
      showErrorModal(msg, title);
    } finally {
      $("signup-btn").disabled = false;
    }
  });

  async function doLogout() {
    loggingOut = true;
    accessToken = null;
    profile = null;
    mailboxItems = [];
    applyMailboxUnread(0);
    closeMailboxModal();
    earlyAccessFeatures = new Set();
    clearSessionToken();
    autoLoginAttempted = true;
    if (!wantsRemember()) clearAutoLoginCreds();
    setFarmBusy(false);
    try {
      resetDevPlaySession();
    } catch (_) {
      devplaySession = null;
    }
    devplayVaultEntries = [];
    emptyModalDismissed = false;
    showLogin({ force: true });
    prefillRememberedLogin().catch(() => {});
    try {
      await Promise.race([
        sb.auth.signOut(),
        new Promise((resolve) => setTimeout(resolve, 2500)),
      ]);
    } catch (_) {}
    try {
      const keys = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.includes("auth-token")) keys.push(k);
      }
      keys.forEach((k) => {
        localStorage.removeItem(k);
        sessionStorage.removeItem(k);
      });
    } catch (_) {}
    loggingOut = false;
  }

  $("logout-btn-menu")?.addEventListener("click", () => {
    doLogout().catch(() => {});
  });

  /* User Profile & Topup History Modal Controllers with Smooth Exit Animation */
  let userProfileCloseTimer = null;
  let userTopupCloseTimer = null;
  let affiliateInviteCloseTimer = null;

  let profileTgState = null;
  let profileTgSaving = false;

  function setProfileTgMsg(text, kind) {
    const el = $("profile-tg-msg");
    if (!el) return;
    el.textContent = text || "";
    el.classList.toggle("is-ok", kind === "ok");
    el.classList.toggle("is-warn", kind === "warn");
    el.classList.toggle("is-err", kind === "err");
  }

  function paintProfileTelegram(data) {
    profileTgState = data || null;
    const configured = !!(data && data.configured);
    const hasToken = !!(data && data.has_token);
    const savePending = !!(data && data.send_ok && data.saved === false);
    const chatLinked = !!(data && data.chat_linked);
    const badge = $("profile-tg-badge");
    const status = $("profile-tg-status");
    const tokenRow = $("profile-tg-token-row");
    const maskedRow = $("profile-tg-masked-row");
    const masked = $("profile-tg-masked");
    const card = $("profile-tg-card");
    const headChip = $("profile-head-tg-chip");
    if (card) {
      card.classList.toggle("is-ready", configured);
      card.classList.toggle("is-save-pending", savePending);
    }
    if (badge) {
      badge.classList.toggle("is-on", configured);
      badge.classList.toggle("is-warn", savePending);
      if (configured) badge.textContent = "เปิดใช้แล้ว";
      else if (savePending) badge.textContent = "บันทึกค้าง";
      else if (hasToken) badge.textContent = "รอทดสอบ";
      else badge.textContent = "ปิด";
    }
    if (status) {
      if (configured) status.textContent = "พร้อมรับข้อความ · แจ้งเฉพาะงานของคุณ";
      else if (savePending)
        status.textContent = "บอทโอเค · บันทึกค้าง — กดทดสอบเพื่อบันทึกอีกครั้ง";
      else if (hasToken) status.textContent = "ยังไม่พร้อมรับข้อความ · กดทดสอบหลัง Start บอท";
      else status.textContent = "ยังไม่พร้อมรับข้อความ";
    }
    if (headChip) {
      headChip.classList.toggle("is-on", configured);
      headChip.classList.toggle("is-wait", !configured && (hasToken || savePending));
      headChip.classList.toggle("is-warn", savePending);
      if (configured) headChip.textContent = "TG · พร้อม";
      else if (savePending) headChip.textContent = "TG · บันทึกค้าง";
      else if (hasToken) headChip.textContent = "TG · รอทดสอบ";
      else headChip.textContent = "TG · ยังไม่พร้อม";
    }
    const showMasked = !!(hasToken && data && data.token_masked) || (savePending && data && data.token_masked);
    if (showMasked) {
      if (tokenRow) tokenRow.classList.add("hidden");
      if (maskedRow) {
        maskedRow.classList.remove("hidden");
        maskedRow.hidden = false;
      }
      if (masked) masked.textContent = data.token_masked;
      const input = $("profile-tg-token");
      // Keep typed token if save pending so retry can resend without re-paste.
      if (input && !savePending) input.value = "";
    } else {
      if (tokenRow) tokenRow.classList.remove("hidden");
      if (maskedRow) {
        maskedRow.classList.add("hidden");
        maskedRow.hidden = true;
      }
    }
    const prefs = (data && data.prefs) || {};
    document.querySelectorAll("[data-tg-pref]").forEach((input) => {
      const key = input.getAttribute("data-tg-pref");
      if (!key) return;
      input.checked = prefs[key] != null ? !!prefs[key] : !!input.checked;
    });
    if ($("profile-tg-quiet-start") && prefs.quiet_hours_start) {
      $("profile-tg-quiet-start").value = prefs.quiet_hours_start;
    }
    if ($("profile-tg-quiet-end") && prefs.quiet_hours_end) {
      $("profile-tg-quiet-end").value = prefs.quiet_hours_end;
    }
  }

  function collectProfileTgPrefs() {
    const prefs = {};
    document.querySelectorAll("[data-tg-pref]").forEach((input) => {
      const key = input.getAttribute("data-tg-pref");
      if (key) prefs[key] = !!input.checked;
    });
    prefs.quiet_hours_start = $("profile-tg-quiet-start")?.value || "23:00";
    prefs.quiet_hours_end = $("profile-tg-quiet-end")?.value || "07:00";
    return prefs;
  }

  async function loadProfileTelegram() {
    if (!$("profile-tg-card") || !accessToken) return;
    try {
      const data = await api("/api/telegram/settings");
      paintProfileTelegram(data);
    } catch (_) {
      if ($("profile-tg-status")) {
        $("profile-tg-status").textContent = "โหลดตั้งค่าไม่สำเร็จ";
      }
      const headChip = $("profile-head-tg-chip");
      if (headChip) {
        headChip.classList.remove("is-on", "is-wait");
        headChip.textContent = "TG · ไม่พร้อม";
      }
    }
  }

  async function testProfileTelegram() {
    if (!accessToken) {
      setProfileTgMsg("เข้าสู่ระบบก่อน", "err");
      return;
    }
    const btn = $("profile-tg-test-btn");
    const token = String($("profile-tg-token")?.value || "").trim();
    if (!token && !(profileTgState && profileTgState.has_token)) {
      setProfileTgMsg("วาง Bot Token ก่อน", "err");
      $("profile-tg-token")?.focus();
      return;
    }
    if (btn) btn.disabled = true;
    setProfileTgMsg("กำลังทดสอบ…", "");
    try {
      const body = {};
      if (token) body.bot_token = token;
      const data = await api("/api/telegram/test", { method: "POST", body });
      // Green: bot OK · saved — ready for job alerts
      // Orange: bot OK · save failed — retry (never "เชื่อมต่อเซิร์ฟเวอร์ไม่ได้")
      if (data && data.send_ok && data.saved === false) {
        paintProfileTelegram({ ...data, send_ok: true, saved: false });
        const who = data.bot_username ? " · @" + data.bot_username : "";
        setProfileTgMsg(
          "บอทโอเค · บันทึกไม่สำเร็จ" + who + " — กดทดสอบอีกครั้ง",
          "warn"
        );
        showToast("บอทส่งได้ แต่บันทึกยังไม่ติด — ลองใหม่", "warn");
        return;
      }
      paintProfileTelegram(data);
      const who = data?.bot_username ? " · @" + data.bot_username : "";
      setProfileTgMsg("บอทโอเค · บันทึกแล้ว — พร้อมแจ้งเตือนงาน" + who, "ok");
      showToast("แจ้งเตือน Telegram พร้อมใช้", "ok");
    } catch (err) {
      // Red: send failed — check Start / token. Never confuse with network_error
      // when the API returned a Telegram domain code.
      const code = String(err?.code || err?.message || "").trim();
      const domain =
        /^(invalid_token_format|telegram_auth_failed|chat_not_found|bot_token_required|token_decrypt_failed|send_failed|telegram_send_failed)$/i.test(
          code
        );
      let msg;
      if (domain) {
        msg = thError(code) || ERR_TH.telegram_send_failed;
      } else if (/network_error|Failed to fetch|timeout/i.test(String(err?.message || ""))) {
        // Real transport failure only
        msg = thError("network_error");
      } else if (/telegram_settings_save_failed|tg_settings_/i.test(String(err?.message || ""))) {
        msg = ERR_TH.telegram_settings_save_failed;
        setProfileTgMsg(msg, "warn");
        if (btn) btn.disabled = false;
        return;
      } else {
        msg = thError(err.message) || ERR_TH.telegram_send_failed || "ส่งไม่สำเร็จ — ตรวจ Start / Token";
      }
      setProfileTgMsg(msg, "err");
      // Keep header badge honest after a failed send
      const headChip = $("profile-head-tg-chip");
      const badge = $("profile-tg-badge");
      const status = $("profile-tg-status");
      if (headChip && !(profileTgState && profileTgState.configured)) {
        headChip.classList.remove("is-on");
        headChip.classList.add("is-wait");
        headChip.textContent = "TG · ส่งไม่สำเร็จ";
      }
      if (badge && !(profileTgState && profileTgState.configured)) {
        badge.classList.remove("is-on");
        badge.textContent = "ส่งไม่สำเร็จ";
      }
      if (status && !(profileTgState && profileTgState.configured)) {
        status.textContent = "ส่งไม่สำเร็จ — เปิดบอทแล้วกด Start แล้วลองใหม่";
      }
    } finally {
      if (btn) btn.disabled = false;
    }
  }

  async function saveProfileTelegramPrefs() {
    if (!accessToken) return;
    if (profileTgSaving) return;
    profileTgSaving = true;
    const btn = $("profile-tg-save-prefs");
    if (btn) btn.disabled = true;
    setProfileTgMsg("กำลังบันทึก…", "");
    try {
      const data = await api("/api/telegram/settings", {
        method: "PUT",
        body: {
          prefs: collectProfileTgPrefs(),
          enabled: !!(profileTgState && profileTgState.chat_linked),
        },
      });
      paintProfileTelegram(data);
      setProfileTgMsg("บันทึกแล้ว", "ok");
    } catch (err) {
      const code = String(err?.code || err?.message || "");
      if (/telegram_settings_save_failed|tg_settings_/i.test(code)) {
        setProfileTgMsg(ERR_TH.telegram_settings_save_failed, "warn");
      } else {
        setProfileTgMsg(thError(err.message) || "บันทึกไม่สำเร็จ", "err");
      }
    } finally {
      profileTgSaving = false;
      if (btn) btn.disabled = false;
    }
  }

  async function revokeProfileTelegram() {
    if (!accessToken) return;
    if (!confirm("เพิกถอน Bot Token และหยุดแจ้งเตือน?")) return;
    try {
      const data = await api("/api/telegram/settings", { method: "DELETE" });
      paintProfileTelegram(data);
      setProfileTgMsg("เพิกถอนแล้ว — วางโทเคนใหม่เมื่อพร้อม", "ok");
      showToast("เพิกถอน Telegram แล้ว", "muted");
    } catch (err) {
      setProfileTgMsg(thError(err.message) || "เพิกถอนไม่สำเร็จ", "err");
    }
  }


  let profileTgGuideCloseTimer = null;

  function isProfileTgGuideOpen() {
    const modal = $("profile-tg-guide-modal");
    return !!(modal && !modal.classList.contains("hidden") && !modal.classList.contains("is-closing"));
  }

  function openProfileTgGuide() {
    const modal = $("profile-tg-guide-modal");
    if (!modal) return;
    if (profileTgGuideCloseTimer) {
      clearTimeout(profileTgGuideCloseTimer);
      profileTgGuideCloseTimer = null;
    }
    modal.classList.remove("hidden", "is-closing");
    modal.setAttribute("aria-hidden", "false");
    $("profile-tg-guide-btn")?.setAttribute("aria-expanded", "true");
  }

  function closeProfileTgGuide() {
    const modal = $("profile-tg-guide-modal");
    if (!modal || modal.classList.contains("hidden") || modal.classList.contains("is-closing")) return;
    modal.classList.add("is-closing");
    $("profile-tg-guide-btn")?.setAttribute("aria-expanded", "false");
    profileTgGuideCloseTimer = setTimeout(() => {
      profileTgGuideCloseTimer = null;
      modal.classList.add("hidden");
      modal.classList.remove("is-closing");
      modal.setAttribute("aria-hidden", "true");
    }, profileModalCloseMs());
  }


  function profileModalCloseMs() {
    return prefersReducedMotion() ? 0 : 200;
  }

  const PROFILE_ACC_LAST_KEY = "ckr-profile-acc-last";
  let profileTopupPreviewLoaded = false;

  function paintProfileDevPlay() {
    const sum = $("profile-devplay-sum");
    const current = $("profile-devplay-current");
    const list = $("profile-devplay-list");
    const logoutBtn = $("profile-devplay-logout");
    const connected = isDevPlayConnected();
    if (sum) {
      if (connected) sum.textContent = getDevPlayAccountDisplayName() || "เชื่อมแล้ว";
      else if (devplayVaultEntries.length) sum.textContent = "จำไว้ " + devplayVaultEntries.length + " ไอดี";
      else sum.textContent = "ยังไม่ได้เชื่อม";
    }
    if (logoutBtn) {
      logoutBtn.hidden = !connected;
      logoutBtn.style.display = connected ? "" : "none";
    }
    if (current) {
      current.innerHTML = "";
      if (connected) {
        const img = document.createElement("img");
        img.className = "devplay-profile-avatar";
        img.alt = "";
        img.width = 40;
        img.height = 40;
        img.loading = "lazy";
        img.decoding = "async";
        bindDevPlayAvatarImg(img, resolveDevPlayAvatarUrl(devplaySession), {
          cookieFallback: devPlayCookiePortraitUrl(devplaySession?.cookieName),
        });
        const body = document.createElement("div");
        body.className = "profile-devplay-current-body";
        const name = document.createElement("span");
        name.className = "profile-devplay-current-name";
        name.textContent = getDevPlayAccountDisplayName();
        const mail = document.createElement("span");
        mail.className = "profile-devplay-current-mail muted";
        mail.textContent = maskDevPlayEmail(devplaySession?.email || getDevPlayCreds()?.email || "");
        body.append(name, mail);
        current.append(img, body);
      } else {
        const tip = document.createElement("span");
        tip.className = "muted";
        tip.textContent = "ยังไม่ได้เชื่อม DevPlay — เลือกไอดีด้านล่างหรือไปหน้า DevPlay";
        current.appendChild(tip);
      }
    }
    if (!list) return;
    list.innerHTML = "";
    if (devplayVaultLoading && !devplayVaultEntries.length) {
      const p = document.createElement("p");
      p.className = "profile-devplay-empty";
      p.textContent = "กำลังโหลดไอดี…";
      list.appendChild(p);
      return;
    }
    if (!devplayVaultEntries.length) {
      const p = document.createElement("p");
      p.className = "profile-devplay-empty";
      p.textContent = "ยังไม่มีไอดีที่จำไว้";
      list.appendChild(p);
      return;
    }
    const activeMail = String(devplaySession?.email || getDevPlayCreds()?.email || "").trim().toLowerCase();
    devplayVaultEntries.forEach((entry) => {
      const row = document.createElement("button");
      row.type = "button";
      row.className = "devplay-vault-card";
      row.dataset.profileVaultEmail = entry.email;
      row.disabled = !!(devplayConnecting || farmRunning);
      row.setAttribute("role", "listitem");
      if (activeMail && String(entry.email || "").trim().toLowerCase() === activeMail) {
        row.classList.add("is-active");
      }
      const img = document.createElement("img");
      img.className = "devplay-vault-card-avatar";
      img.alt = "";
      img.width = 40;
      img.height = 40;
      img.loading = "lazy";
      img.decoding = "async";
      bindDevPlayAvatarImg(img, resolveVaultAvatarUrl(entry), {
        cookieFallback: devPlayCookiePortraitUrl(entry?.cookieName),
      });
      const body = document.createElement("div");
      body.className = "devplay-vault-card-body";
      const name = document.createElement("span");
      name.className = "devplay-vault-card-name";
      name.textContent = entry.nickname || "player";
      const mail = document.createElement("span");
      mail.className = "devplay-vault-card-email muted";
      mail.textContent = maskDevPlayEmail(entry.email);
      body.append(name, mail);
      const removeBtn = document.createElement("button");
      removeBtn.type = "button";
      removeBtn.className = "devplay-vault-card-remove";
      removeBtn.dataset.profileVaultRemove = entry.email;
      removeBtn.setAttribute("aria-label", "ลบบัญชี " + entry.email);
      removeBtn.textContent = "×";
      row.append(img, body, removeBtn);
      list.appendChild(row);
    });
  }

  /* Profile modal = fixed-height card with tabs (no page scroll). One pane open at a time;
     the last opened tab is remembered in localStorage. */
  const PROFILE_TABS = ["devplay", "topup", "telegram", "security"];
  let profileActiveTab = "";

  function setProfileTab(key, opts = {}) {
    const stack = $("profile-acc-stack");
    if (!stack) return;
    const next = PROFILE_TABS.includes(key) ? key : "devplay";
    profileActiveTab = next;
    document.querySelectorAll("#user-profile-modal [data-profile-tab]").forEach((btn) => {
      const on = btn.getAttribute("data-profile-tab") === next;
      btn.classList.toggle("is-active", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
      btn.tabIndex = on ? 0 : -1;
    });
    stack.querySelectorAll(".pf-pane").forEach((pane) => {
      const on = pane.getAttribute("data-profile-acc") === next;
      pane.hidden = !on;
      pane.classList.toggle("is-active", on);
    });
    try {
      localStorage.setItem(PROFILE_ACC_LAST_KEY, next);
    } catch (_) {}
    if (opts.silent) return;
    if (next === "devplay") paintProfileDevPlay();
    if (next === "topup") loadProfileTopupPreview().catch(() => {});
  }

  function restoreProfileAccordions() {
    let last = "";
    try {
      last = String(localStorage.getItem(PROFILE_ACC_LAST_KEY) || "");
    } catch (_) {}
    setProfileTab(last || "devplay", { silent: true });
  }

  function setupProfileAccordions() {
    const nav = document.querySelector("#user-profile-modal .pf-tabs");
    if (!nav || nav.dataset.bound === "1") return;
    nav.dataset.bound = "1";
    nav.addEventListener("click", (ev) => {
      const btn = ev.target.closest("[data-profile-tab]");
      if (btn) setProfileTab(btn.getAttribute("data-profile-tab"));
    });
    nav.addEventListener("keydown", (ev) => {
      if (ev.key !== "ArrowRight" && ev.key !== "ArrowLeft") return;
      const i = PROFILE_TABS.indexOf(profileActiveTab);
      const step = ev.key === "ArrowRight" ? 1 : -1;
      const next = PROFILE_TABS[(i + step + PROFILE_TABS.length) % PROFILE_TABS.length];
      setProfileTab(next);
      nav.querySelector('[data-profile-tab="' + next + '"]')?.focus();
      ev.preventDefault();
    });
  }

  async function loadProfileTopupPreview() {
    const box = $("profile-topup-preview");
    if (!box || !accessToken) return;
    box.innerHTML = '<p class="profile-topup-preview-empty muted">กำลังโหลด…</p>';
    try {
      const data = await api("/api/topup/history");
      const items = Array.isArray(data?.items) ? data.items : [];
      profileTopupPreviewLoaded = true;
      if (!items.length) {
        box.innerHTML = '<p class="profile-topup-preview-empty muted">ยังไม่มีประวัติเติมเงิน</p>';
        return;
      }
      box.innerHTML = items.slice(0, 3).map((it) => {
        const pack = it.package_label || it.credit_label || "เติมเงิน";
        const ok = it.credit_status === "credited";
        const bonus = !!(it.is_affiliate || it.hide_baht || it.package_kind === "affiliate_signup");
        const credit = it.credit_label
          || (it.tokens_credited != null ? ("+" + Number(it.tokens_credited).toLocaleString("th-TH") + " Token") : "");
        const amtLabel = bonus
          ? (credit || "โบนัส")
          : ("฿" + Number(it.amount_baht || 0).toLocaleString("th-TH", { minimumFractionDigits: 0 }));
        const status = it.status_label || (ok ? "สำเร็จ" : (it.credit_status || "—"));
        return (
          '<div class="profile-topup-preview-row">' +
            "<div><strong>" + escapeHtml(amtLabel) + "</strong> · " + escapeHtml(pack) + "</div>" +
            "<span>" + escapeHtml(status) + "</span>" +
          "</div>"
        );
      }).join("");
    } catch (err) {
      box.innerHTML =
        '<p class="profile-topup-preview-empty" style="color:#fca5a5">โหลดประวัติไม่สำเร็จ</p>';
    }
  }


  function paintUserProfileModal() {

    const whoName = profile?.username || profile?.display_name || "—";
    const ch = String(whoName || "").trim().charAt(0);
    if ($("profile-modal-name")) $("profile-modal-name").textContent = whoName;
    if ($("profile-modal-mono")) $("profile-modal-mono").textContent = ch ? ch.toUpperCase() : "—";
    if ($("profile-modal-subline")) {
      const mail = String(profile?.email || "").trim();
      $("profile-modal-subline").textContent = mail || ("@" + String(whoName || "user"));
    }
    if ($("profile-modal-role-text")) {
      $("profile-modal-role-text").textContent = profile?.role === "admin" ? "ผู้ดูแลระบบ (Admin)" : "สมาชิก CKR WWDC";
    }
    const rental = sidebarRentalMeta();
    const rentalBadge = $("profile-modal-rental-badge");
    const rentalExpiry = $("profile-modal-rental-expiry");
    const tierBadge = $("profile-modal-tier-badge");

    if (rentalBadge) {
      if (isRentalPermanent(profile)) {
        rentalBadge.textContent = "สิทธิ์ถาวร";
        rentalBadge.className = "user-profile-rental-badge is-permanent";
        if (tierBadge) tierBadge.textContent = "LIFETIME";
      } else if (profile?.rental_pending) {
        rentalBadge.textContent = "รอเริ่มใช้งาน";
        rentalBadge.className = "user-profile-rental-badge is-pending";
        if (tierBadge) tierBadge.textContent = "PENDING";
      } else if (hasFarmAccess()) {
        rentalBadge.textContent = rental.text || "กำลังใช้งาน";
        rentalBadge.className = "user-profile-rental-badge is-active";
        if (tierBadge) tierBadge.textContent = "ACTIVE";
      } else {
        rentalBadge.textContent = "หมดอายุ";
        rentalBadge.className = "user-profile-rental-badge is-expired";
        if (tierBadge) tierBadge.textContent = "FREE";
      }
    }

    if (rentalExpiry) {
      if (isRentalPermanent(profile)) {
        rentalExpiry.textContent = "ใช้งานได้ตลอดชีพ · ไม่จำกัด";
      } else {
        rentalExpiry.textContent = rental.expiry || "ไม่มีวันเช่า";
      }
    }

    if ($("profile-modal-token-value")) {
      $("profile-modal-token-value").innerHTML = topbarTokenHtml(tokenBalance());
    }
    paintProfileDevPlay();
    if (profileTgState) paintProfileTelegram(profileTgState);
  }

  function affiliateShareUrl(code) {
    const c = String(code || "").trim();
    if (!c) return "";
    return String(location.origin || "").replace(/\/$/, "") + "/?ref=" + encodeURIComponent(c);
  }

  function affiliateRewardTokens(baht, rate) {
    const n = Math.floor(Math.round(Number(baht || 0) * Number(rate || 0) * 1e6) / 1e6) / 100;
    return n > 0 ? n : 0;
  }

  function paintAffiliateExplain(min, rate, code, link) {
    const minN = Math.max(0, Number(min || 0));
    const rateN = Number(rate || 10);
    if ($("affiliate-reward-rule")) {
      $("affiliate-reward-rule").textContent =
        "ตัวอย่างโบนัส · ปัดลง(ยอดรวม 15 วัน × " + rateN + "%)";
    }
    const list = $("affiliate-examples");
    if (list) {
      const shown = [];
      [20, 50, 100, 150].forEach((baht) => {
        if (shown.includes(baht)) return;
        shown.push(baht);
      });
      list.innerHTML = shown.slice(0, 4).map((baht) => {
        return '<div class="affiliate-example-tile"><span>' +
          formatNumTh(baht) + " บาท</span><strong>+" +
          formatTokenAmount(affiliateRewardTokens(baht, rateN)) + " Token</strong></div>";
      }).join("");
    }
    if ($("affiliate-min-note")) {
      $("affiliate-min-note").textContent =
        "นับยอดเติม Token, เช่ารายวัน และซื้อโปรแกรม PC รวมภายใน 15 วันหลังสมัคร ตั้งแต่วันที่ 22 ก.ย. 2026 ไม่มีขั้นต่ำ · คนละระบบกับเมนูเชิญเพื่อน 29 คน";
    }
    if ($("affiliate-code-sample")) {
      $("affiliate-code-sample").textContent = code
        ? "ส่งรหัส " + code + " ให้กรอกตอนสมัคร"
        : "ให้กรอกตอนสมัครที่ช่องรหัสชวนสมัคร";
    }
    if ($("affiliate-link-sample")) {
      $("affiliate-link-sample").textContent = link
        ? "เปิดลิงก์นี้แล้วสมัคร ระบบจำรหัสให้บนเครื่องนั้น"
        : "ส่งให้เปิดในช่อง URL แล้วสมัคร";
    }
    if ($("profile-affiliate-min")) {
      $("profile-affiliate-min").textContent = "รวม 15 วัน · " + rateN + "%";
    }
  }

  function affiliateSignedAt(iso) {
    const d = new Date(iso || "");
    if (!iso || Number.isNaN(d.getTime())) return "";
    try {
      return d.toLocaleString("th-TH", { dateStyle: "medium", timeStyle: "short" });
    } catch (_) {
      return "";
    }
  }

  function affiliateBahtText(value) {
    const n = Number(value || 0);
    return n.toLocaleString("th-TH", { minimumFractionDigits: 0, maximumFractionDigits: 2 }) + " บาท";
  }

  function paintAffiliateRoster(data) {
    const list = $("affiliate-roster-list");
    const summary = $("affiliate-roster-summary");
    const more = $("affiliate-roster-more");
    if (!list) return;
    const rows = Array.isArray(data?.referrals) ? data.referrals : [];
    const invited = Number(data?.invited_count || 0);
    const topped = Number(data?.topped_up_count || 0);
    const baht = Number(data?.referred_topup_baht || 0);
    const tokens = Number(
      data?.received_tokens != null ? data.received_tokens : data?.tokens_earned || 0
    );
    const expected = Number(data?.expected_tokens || 0);
    const mismatches = Number(data?.token_mismatch_count || 0);
    const unpaid = rows.filter((row) => row?.bonus_status === "pending").length;
    if (summary) {
      const check =
        mismatches > 0
          ? " · Token ไม่ตรง " + formatNumTh(mismatches) + " คน"
          : unpaid > 0
            ? " · ยังไม่ได้โบนัส " + formatNumTh(unpaid) + " คน"
            : rows.length
              ? " · Token ตรงตามยอดที่ใช้คิดโบนัส"
              : "";
      summary.textContent =
        "ชวน " +
        formatNumTh(invited) +
        " คน · เติมแล้ว " +
        formatNumTh(topped) +
        " คน · รวม " +
        affiliateBahtText(baht) +
        " · ได้รับ " +
        formatTokenAmount(tokens) +
        " / ควรได้ " +
        formatTokenAmount(expected) +
        " Token" +
        check;
    }
    if (!rows.length) {
      list.innerHTML = '<p class="affiliate-roster-empty">ยังไม่มีคนสมัครด้วยรหัสนี้</p>';
    } else {
      list.innerHTML = rows
        .map((row) => {
          const name = escapeHtml(row?.username || "สมาชิก");
          const when = escapeHtml(affiliateSignedAt(row?.signed_up_at));
          const first = Number(row?.window_baht ?? row?.bonus_basis_baht ?? row?.first_topup_baht) || 0;
          const basis = Number(row?.bonus_basis_baht || 0);
          const total = Number(row?.topped_up_baht || 0);
          const label = escapeHtml(row?.bonus_label || "");
          const received = Number(row?.bonus_tokens || 0);
          const should = Number(row?.expected_tokens || 0);
          const note = escapeHtml(row?.token_note || "");
          const mismatch = row?.token_ok === false && row?.bonus_status === "paid";
          const parts = ["ยอดใน 15 วัน " + affiliateBahtText(first)];
          if (basis > 0 && Math.abs(basis - first) >= 0.01) {
            parts.push("คิดโบนัสจาก " + affiliateBahtText(basis));
          }
          if (Number(row?.topup_count || 0) > 1) {
            parts.push("รวม " + affiliateBahtText(total));
          }
          parts.push(label);
          parts.push("ควรได้ " + formatTokenAmount(should));
          parts.push("ได้รับ " + formatTokenAmount(received));
          if (note) parts.push(note);
          return (
            '<article class="affiliate-roster-row' +
            (mismatch ? " is-mismatch" : "") +
            '">' +
            '<span class="affiliate-roster-name">' +
            name +
            "</span>" +
            '<span class="affiliate-roster-baht">15 วัน ' +
            escapeHtml(affiliateBahtText(first)) +
            "</span>" +
            '<span class="affiliate-roster-when">' +
            when +
            "</span>" +
            '<span class="affiliate-roster-status">' +
            escapeHtml(parts.join(" · ")) +
            "</span></article>"
          );
        })
        .join("");
    }
    if (more) {
      const truncated = !!data?.referrals_truncated;
      more.hidden = !truncated;
      more.classList.toggle("hidden", !truncated);
      more.textContent = truncated ? "แสดง 100 คนล่าสุด" : "";
    }
  }

  async function loadProfileAffiliate() {
    const codeEl = $("profile-affiliate-code");
    const linkEl = $("profile-affiliate-link");
    const statsEl = $("profile-affiliate-stats");
    const rateEl = $("profile-affiliate-rate");
    const earnedEl = $("profile-affiliate-earned");
    const card = $("profile-affiliate-card");
    if (!card || !accessToken) return;
    try {
      const data = await api("/api/affiliate/me");
      if (data?.enabled === false) {
        card.hidden = true;
        $("sidebar-affiliate-btn")?.classList.add("hidden");
        return;
      }
      card.hidden = false;
      const code = String(data?.code || "").trim();
      const link = affiliateShareUrl(code);
      if (codeEl) codeEl.value = code;
      if (linkEl) linkEl.value = link;
      const invited = Number(data?.invited_count || 0);
      const paid = Number(data?.paid_count || 0);
      const tokens = Number(data?.tokens_earned || 0);
      if (earnedEl) earnedEl.textContent = formatTokenAmount(tokens);
      if (statsEl) {
        statsEl.textContent =
          "ชวนแล้ว " + formatNumTh(invited) + " คน · สำเร็จ " + formatNumTh(paid) + " คน";
      }
      const min = Number(data?.min_baht || 50);
      const rate = Number(data?.rate_percent || 10);
      if (rateEl) rateEl.textContent = "ได้ " + rate + "%";
      paintAffiliateExplain(min, rate, code, link);
      paintAffiliateRoster(data);
    } catch (_) {
      if (statsEl && !statsEl.textContent) statsEl.textContent = "โหลดข้อมูลไม่สำเร็จ";
    }
  }

  async function copyProfileAffiliate(kind) {
    const code = String($("profile-affiliate-code")?.value || "").trim();
    const msg = $("profile-affiliate-msg");
    if (!code) return;
    const link = affiliateShareUrl(code);
    const wantLink = kind === "link";
    const text = wantLink ? link : code;
    try {
      await navigator.clipboard.writeText(text);
      if (msg) {
        msg.textContent = wantLink ? "คัดลอกลิงก์แล้ว — วางในช่อง URL ได้เลย" : "คัดลอกรหัสแล้ว";
        msg.classList.add("is-ok");
        msg.classList.remove("is-err");
      }
      showToast(wantLink ? "คัดลอกลิงก์ชวนสมัครแล้ว" : "คัดลอกรหัสชวนสมัครแล้ว", "ok");
    } catch (_) {
      const el = wantLink ? $("profile-affiliate-link") : $("profile-affiliate-code");
      if (el) {
        el.focus();
        el.select();
      }
      if (msg) {
        msg.textContent = "คัดลอกไม่สำเร็จ — เลือกข้อความในช่องแล้วคัดลอกเอง";
        msg.classList.add("is-err");
        msg.classList.remove("is-ok");
      }
    }
  }

  function setProfileRedeemMsg(text, kind) {
    const el = $("profile-redeem-msg");
    if (!el) return;
    el.textContent = text || "";
    el.classList.toggle("is-ok", kind === "ok");
    el.classList.toggle("is-err", kind === "err");
  }

  async function submitProfileRedeem(e) {
    e?.preventDefault?.();
    const input = $("profile-redeem-code");
    const btn = $("profile-redeem-btn");
    const code = String(input?.value || "").trim();
    if (!code) {
      setProfileRedeemMsg("กรอกรหัสของขวัญก่อน", "err");
      input?.focus();
      return;
    }
    if (!accessToken) {
      setProfileRedeemMsg(ERR_TH.redeem_user_required, "err");
      return;
    }
    if (btn) btn.disabled = true;
    setProfileRedeemMsg("กำลังแลก…", "");
    try {
      const data = await api("/api/redeem", { method: "POST", body: { code } });
      applyProfileRental(data);
      paintUserProfileModal();
      if (input) input.value = "";
      setProfileRedeemMsg(data?.message || "แลกโค้ดสำเร็จ", "ok");
      showToast(data?.message || "แลกโค้ดสำเร็จ", "ok");
      refreshProfileAccess()
        .then(() => paintUserProfileModal())
        .catch(() => {});
    } catch (err) {
      setProfileRedeemMsg(thError(err.message) || err.message || "แลกไม่สำเร็จ", "err");
    } finally {
      if (btn) btn.disabled = false;
    }
  }

