  async function openUserTopupHistory() {
    const pModal = $("user-profile-modal");
    if (pModal) {
      pModal.classList.add("hidden");
      pModal.classList.remove("is-closing");
      pModal.setAttribute("aria-hidden", "true");
    }
    const modal = $("user-topup-history-modal");
    const list = $("topup-history-list");
    if (!modal || !list) return;
    if (userTopupCloseTimer) {
      clearTimeout(userTopupCloseTimer);
      userTopupCloseTimer = null;
    }
    modal.classList.remove("hidden", "is-closing");
    modal.setAttribute("aria-hidden", "false");
    paintTopupHistorySkeleton(4);

    try {
      const data = await api("/api/topup/history");
      const items = Array.isArray(data?.items) ? data.items : [];
      if (!items.length) {
        list.innerHTML = `
          <div class="topup-history-empty">
            <p>ยังไม่มีประวัติการเติมเงิน</p>
          </div>
        `;
        return;
      }

      const totalBaht = Number(data?.total_baht != null ? data.total_baht : items.reduce((sum, it) => {
        return sum + (it.credit_status === "credited" ? Number(it.amount_baht || 0) : 0);
      }, 0));
      const summaryHtml = `
        <div class="topup-history-summary">
          <div>
            <strong>${escapeHtml(formatNumTh(items.length))}</strong>
            <span>รายการ</span>
          </div>
          <div>
            <strong>฿${escapeHtml(Number(totalBaht || 0).toLocaleString("th-TH", { minimumFractionDigits: 2 }))}</strong>
            <span>เติมสำเร็จ</span>
          </div>
        </div>
      `;

      list.innerHTML = summaryHtml + items.map((it) => {
        const dateStr = it.created_at_bkk
          || (it.created_at ? new Date(it.created_at).toLocaleString("th-TH", { dateStyle: "medium", timeStyle: "short" }) : "—");
        const pack = it.package_label || it.credit_label || "เติมเงิน";
        const method = it.method_label || it.payment_method || "";
        const credit = it.credit_label
          || (it.tokens_credited != null ? ("+" + Number(it.tokens_credited).toLocaleString("th-TH") + " Token") : "");
        const bonus = !!(it.is_affiliate || it.hide_baht || it.package_kind === "affiliate_signup");
        const amtLabel = bonus
          ? (credit || "โบนัส")
          : ("฿" + Number(it.amount_baht || 0).toLocaleString("th-TH", { minimumFractionDigits: 2 }));
        const ok = it.credit_status === "credited";
        const status = it.status_label || (ok ? "สำเร็จ" : (it.credit_status || "สำเร็จ"));
        return `
          <div class="topup-history-row">
            <div class="topup-history-col">
              <strong class="topup-history-amount">${escapeHtml(amtLabel)}</strong>
              <span class="topup-history-pack">${escapeHtml(pack)}</span>
              <span class="topup-history-date">${escapeHtml(dateStr)}${method ? " · " + escapeHtml(method) : ""}</span>
            </div>
            <div class="topup-history-col topup-history-col-end">
              <strong class="topup-history-tokens">${escapeHtml(bonus ? "" : (credit || "—"))}</strong>
              <span class="topup-history-badge${ok ? " is-ok" : ""}">${escapeHtml(status)}</span>
            </div>
          </div>
        `;
      }).join("");
    } catch (err) {
      list.innerHTML = `
        <div class="topup-history-empty" style="color: #fca5a5;">
          <p>โหลดประวัติไม่สำเร็จ (${escapeHtml(err?.message || "เชื่อมต่อขัดข้อง")})</p>
        </div>
      `;
    }
  }

