  $("exchange-confirm-btn")?.addEventListener("click", async () => {
    if (topupBusy || farmRunning || peekRunning) return;
    if (!accessToken) {
      showErrorModal("กรุณาเข้าสู่ระบบก่อนแลกวันเช่า", "ต้องเข้าสู่ระบบ");
      return;
    }
    if (isRentalPermanent(profile)) {
      showErrorModal("บัญชีนี้มีสิทธิ์ถาวรอยู่แล้ว", "ไม่ต้องแลก");
      return;
    }
    const pkg = getSelectedTopupPackage();
    if (!pkg) {
      setStatus($("topup-status"), "เลือกแพ็กวันเช่าก่อน", "err");
      return;
    }
    const q = exchangeQuoteFromPack(pkg, exchangeQty);
    if (q.pick && !selectedExchangeFeature) {
      setStatus($("topup-status"), "เลือกฟังก์ชันก่อนแลกแพ็ก 1 ฟังก์ชัน", "err");
      return;
    }
    if (tokenBalance() < q.cost) {
      setStatus($("topup-status"), "Token ไม่พอสำหรับแลกแพ็กนี้", "err");
      showErrorModal("ต้องใช้ " + formatNumTh(q.cost) + " Token — ยอดตอนนี้ " + formatTokenAmount(tokenBalance()) + " Token", "Token ไม่พอ");
      return;
    }
    const btn = $("exchange-confirm-btn");
    topupBusy = true;
    if (btn) btn.disabled = true;
    setStatus($("topup-status"), "กำลังแลกวันเช่า…", "muted");
    try {
      await ensureApiReady();
      const data = await api("/api/token/exchange", {
        method: "POST",
        body: {
          package_id: pkg.id,
          qty: q.qty,
          feature: q.pick ? selectedExchangeFeature : null,
        },
      });
      applyProfileRental(data);
      flashTopupDoor();
      try {
        await refreshMe();
      } catch (_) {}
      paintExchangeConfirm();
      setStatus($("topup-status"), "แลกวันเช่าสำเร็จ · ใช้ " + formatNumTh(data.tokens_spent || q.cost) + " Token", "ok");
      showTopupSuccessModal(data);
      openVaultModal({ kind: "exchange" });
      setTimeout(() => {
        if (hasFarmAccess()) closeVaultModal();
      }, 1800);
    } catch (e) {
      if (/session_replaced/i.test(String(e.message || ""))) return;
      const msg = topupFailMessage(e, "แลกวันเช่าไม่สำเร็จ");
      setStatus($("topup-status"), msg, "err");
      showErrorModal(msg, "แลกไม่สำเร็จ");
      try {
        await refreshMe();
      } catch (_) {}
      paintExchangeConfirm();
    } finally {
      topupBusy = false;
      if (btn) btn.disabled = false;
    }
  });
