  $("feature-dock-grid")?.addEventListener("click", (ev) => {
    const btn = ev.target.closest("[data-shortcut-tab]");
    if (!btn) return;
    const family = btn.getAttribute("data-afterplay-family");
    if (family) {
      if (afterplayCalculating || afterplayBusy) return;
      if (isAfterplayFamilyLocked(family)) {
        showFeatureMaintModal(afterplayFamilyMaintKey(family));
        return;
      }
      if (hasResolvedWebsiteProfile() && !canEnterRentalFarmTab(AFTERPLAY_FAST_TAB)) {
        requireFeatureAccess("afterplay_fast");
        return;
      }
      if (!requireAfterplayModeAccess(family, afterplayPace)) return;
      afterplayFamily = family;
      setAfterplayFarmMode(afterplayFunctionId());
    }
    onFarmTabClick(btn.dataset.shortcutTab);
  });

  function onFarmTabClick(tab) {
    if (tab === "guide" || tab === "pricing") {
      openInfoPage(tab);
      return;
    }
    if (tab === "crgcode") {
      // Reference page: no DevPlay. Open at once with a loading state; CKRCode.onShow
      // checks the per-user access and shows the admin's popup text when denied.
      switchFarmTab("crgcode", { force: true });
      if (window.matchMedia("(max-width: 860px)").matches) setFarmSidebarOpen(false);
      closeNavDrawer();
      return;
    }
    if (tab === "mid_heart" || tab === "report_multi" || tab === "pc_program" || tab === "bot_ad") {
      // Works without DevPlay (MID / pasted accounts do the work).
      switchFarmTab(tab);
      if (window.matchMedia("(max-width: 860px)").matches) setFarmSidebarOpen(false);
      closeNavDrawer();
      return;
    }
    if (tab === "live") {
      switchFarmTab("live", { force: true });
      return;
    }
    if (isFarmUiBusy()) {
      if (farmRouteFromPop) syncFarmRoute({ replace: true });
      return;
    }
    if (tab !== INVITE_TAB && !isLoginFreeFarmTab(tab) && !uiPreview && !hasResolvedWebsiteProfile()) {
      openAuthModal("login");
      return;
    }
    if (tab === INVITE_TAB) {
      openInviteFriendTab();
      return;
    }
    if (isLoginFreeFarmTab(tab)) {
      openIdshopTab(tab);
      return;
    }
    if (WEB_REMOVED_TABS.has(tab)) return;
    if (tab === AFTERPLAY_FAST_TAB) {
      if (isAfterplayFamilyLocked(afterplayFamily)) {
        const openFam = AFTERPLAY_FAMILY_NAV.find((row) => !isAfterplayFamilyLocked(row.family));
        if (!openFam) {
          showFeatureMaintModal(afterplayFamilyMaintKey(afterplayFamily));
          return;
        }
        afterplayFamily = openFam.family;
        setAfterplayFarmMode(afterplayFunctionId());
      }
      if (
        hasResolvedWebsiteProfile() &&
        isAfterplayRentalOnlyMode() &&
        !isAdminUser(profile) &&
        !isRentalPermanent(profile) &&
        !hasFeatureAccess("afterplay_fast")
      ) {
        afterplayPace = "fast";
        if (afterplayFamily === "combined") afterplayFamily = "xp";
        setAfterplayFarmMode(afterplayFunctionId());
      }
    } else if (isFeatureLocked(tab)) {
      showFeatureMaintModal(tab);
      return;
    }
    if (isRentalGatedFarmTab(tab) && hasResolvedWebsiteProfile() && !canEnterRentalFarmTab(tab)) {
      requireFeatureAccess(tab);
      return;
    }
    if (tab !== "devplay" && !isDevPlayConnected()) {
      showDevPlayRequiredModal();
      return;
    }
    switchFarmTab(tab);
    if (window.matchMedia("(max-width: 860px)").matches) {
      setFarmSidebarOpen(false);
    }
  }

