          (on
            ? '<span class="admin-mailbox-rule-on">เปิดอยู่</span>'
            : '<span class="admin-mailbox-rule-off">ปิดอยู่</span>') +
          "</h4><p>" +
          escapeHtml(mailboxRuleSummary(row)) +
          " · เริ่ม " +
          escapeHtml(mailboxWhenLabel(row.since_at)) +
          " · ส่งแล้ว " +
          formatNumTh(row.match_count || 0) +
          ' คน</p><div class="admin-mailbox-actions">' +
          '<button type="button" class="btn btn-ghost btn-sm" data-mailbox-rule-edit="' +
          escapeHtml(row.id || "") +
          '">แก้ไข</button>' +
          '<button type="button" class="btn btn-ghost btn-sm" data-mailbox-rule-toggle="' +
          escapeHtml(row.id || "") +
          '" data-on="' +
          (on ? "1" : "0") +
          '">' +
          (on ? "ปิดชั่วคราว" : "เปิดอีกครั้ง") +
          "</button>" +
          '<button type="button" class="btn btn-ghost btn-sm" data-mailbox-rule-del="' +
          escapeHtml(row.id || "") +
          '">ลบกติกา</button></div></article>'
