  async function loadAdminMailboxRules() {
    const data = await api("/api/admin/mailbox/rules");
    paintAdminMailboxRules(data?.rules || []);
  }

  async function saveAdminMailboxRule() {
    const title = String($("admin-mailbox-auto-title")?.value || "").trim();
    if (!title) throw new Error("mailbox_title_required");
    if (!mailboxAutoFileCount()) throw new Error("mailbox_files_required");
    if (mailboxAutoEditId) return reviseAdminMailboxRule(title);
    const created = await api("/api/admin/mailbox", {
      method: "POST",
      body: {
        title,
        body: String($("admin-mailbox-auto-body")?.value || "").trim(),
        visible_days: Number($("admin-mailbox-auto-visible-days")?.value || 7),
        download_days: Number($("admin-mailbox-auto-download-days")?.value || 7),
        usernames: [],
      },
    });
    const dropId = created?.drop?.id;
    if (!dropId) throw new Error("mailbox_save_failed");
    await uploadMailboxAttachments(dropId, mailboxAutoPendingFiles);
    const data = await api("/api/admin/mailbox/rules", {
      method: "POST",
      body: {
        drop_id: dropId,
        ...mailboxAutoRuleFields(),
        enabled: true,
        backfill: !!$("admin-mailbox-auto-backfill")?.checked,
      },
    });
    resetAdminMailboxAutoForm();
    await loadAdminMailbox();
    const filled = Number(data?.backfill || 0);
    return filled ? "เปิดออโต้แล้ว และส่งย้อนหลัง " + formatNumTh(filled) + " คน" : "เปิดออโต้แล้ว — จะส่งเมื่อเข้าเงื่อนไข";
  }

  async function reviseAdminMailboxRule(title) {
    const id = mailboxAutoEditId;
    const wantBackfill = !!$("admin-mailbox-auto-backfill")?.checked;
    const hasNew = mailboxAutoPendingFiles.length > 0;
    const data = await api("/api/admin/mailbox/rules/" + encodeURIComponent(id) + "/revise", {
      method: "POST",
      body: {
        title,
        body: String($("admin-mailbox-auto-body")?.value || "").trim(),
        visible_days: Number($("admin-mailbox-auto-visible-days")?.value || 7),
        download_days: Number($("admin-mailbox-auto-download-days")?.value || 7),
        ...mailboxAutoRuleFields(),
        enabled: mailboxAutoEditEnabled,
        keep_attachment_ids: mailboxAutoKeptFiles.map((row) => row.id).filter(Boolean),
        backfill: wantBackfill && !hasNew,
      },
    });
    const dropId = data?.drop_id;
    if (!dropId) throw new Error("mailbox_save_failed");
    let filled = Number(data?.backfill || 0);
    if (hasNew) {
      await uploadMailboxAttachments(dropId, mailboxAutoPendingFiles);
      if (wantBackfill) {
        const extra = await api("/api/admin/mailbox/rules/" + encodeURIComponent(id), {
          method: "PATCH",
          body: { backfill: true },
        });
        filled = Number(extra?.backfill || 0);
      }
    }
    const revoked = Number(data?.revoked || 0);
    resetAdminMailboxAutoForm();
    await loadAdminMailbox();
    const bits = ["บันทึกกติกาแล้ว"];
    if (revoked) bits.push("ดึงคืน " + formatNumTh(revoked) + " คน");
    bits.push("เริ่มนับใหม่");
    if (filled) bits.push("ส่งย้อนหลัง " + formatNumTh(filled) + " คน");
    return bits.join(" · ");
  }

  function addMailboxRecipient(user) {
    const name = String(user?.username || "").trim();
    const id = String(user?.id || "").trim();
    if (!name) return;
    if (mailboxRecipients.some((row) => row.username.toLowerCase() === name.toLowerCase() || (id && row.id === id))) {
      return;
    }
    if (mailboxRecipients.length >= 200) {
      adminConsoleStatus("เลือกได้สูงสุด 200 คน", "err");
      return;
    }
    mailboxRecipients.push({ id, username: name });
    paintAdminMailboxChips();
  }

  async function addMailboxRecipientFromInput() {
    const q = String($("admin-mailbox-user-q")?.value || "").trim();
    if (q.length < 2) {
      adminConsoleStatus("พิมพ์ username อย่างน้อย 2 ตัว", "err");
      return;
    }
    const cached = adminCachedUser(q);
    if (cached?.username) {
      addMailboxRecipient(cached);
      if ($("admin-mailbox-user-q")) $("admin-mailbox-user-q").value = "";
      return;
    }
    const data = await api("/api/admin/lookup?q=" + encodeURIComponent(q));
    const user = data?.user || data?.users?.[0];
    if (!user?.username) throw new Error("ไม่พบบัญชีผู้ใช้");
    addMailboxRecipient(user);
    if ($("admin-mailbox-user-q")) $("admin-mailbox-user-q").value = "";
  }

  function addMailboxPendingFile() {
    const input = $("admin-mailbox-file");
    const file = input?.files?.[0];
    if (!file) {
      adminConsoleStatus("เลือกไฟล์ก่อนแนบ", "err");
      return false;
    }
    if (mailboxPendingFiles.length >= 10) {
      adminConsoleStatus(ERR_TH.mailbox_too_many_files, "err");
      return false;
    }
    if (file.size > MAILBOX_MAX_BYTES) {
      adminConsoleStatus(ERR_TH.mailbox_file_too_large, "err");
      if (input) input.value = "";
      return false;
    }
    mailboxPendingSeq += 1;
    mailboxPendingFiles.push({
      key: mailboxPendingSeq,
      kind: "file",
      label: String($("admin-mailbox-file-label")?.value || "").trim() || file.name,
      file,
    });
    if (input) input.value = "";
    if ($("admin-mailbox-file-label")) $("admin-mailbox-file-label").value = "";
    paintAdminMailboxFiles();
    return true;
  }

  function addMailboxPendingUrl() {
    const url = String($("admin-mailbox-url")?.value || "").trim();
    if (!url) {
      adminConsoleStatus(ERR_TH.mailbox_url_required, "err");
      return false;
    }
    if (!mailboxUrlLooksValid(url)) {
      adminConsoleStatus(ERR_TH.mailbox_url_invalid, "err");
      return false;
    }
    if (mailboxPendingFiles.length >= 10) {
      adminConsoleStatus(ERR_TH.mailbox_too_many_files, "err");
      return false;
    }
    mailboxPendingSeq += 1;
    mailboxPendingFiles.push({
      key: mailboxPendingSeq,
      kind: "url",
      label: String($("admin-mailbox-url-label")?.value || "").trim() || "เปิดลิงก์",
      url,
    });
    if ($("admin-mailbox-url")) $("admin-mailbox-url").value = "";
    if ($("admin-mailbox-url-label")) $("admin-mailbox-url-label").value = "";
    paintAdminMailboxFiles();
    return true;
  }

  function flushMailboxPendingInputs() {
    if ($("admin-mailbox-file")?.files?.[0]) {
      if (mailboxPendingFiles.length >= 10) throw new Error("mailbox_too_many_files");
      addMailboxPendingFile();
    }
    const leftover = String($("admin-mailbox-url")?.value || "").trim();
    if (!leftover) return;
    if (!mailboxUrlLooksValid(leftover)) throw new Error("mailbox_url_invalid");
    if (mailboxPendingFiles.length >= 10) throw new Error("mailbox_too_many_files");
    addMailboxPendingUrl();
  }

  function paintAdminMailboxList(drops) {
    const host = $("admin-mailbox-list");
    if (!host) return;
    const rows = Array.isArray(drops) ? drops : [];
    if (!rows.length) {
      host.innerHTML = '<p class="muted">ยังไม่ได้ส่งของขวัญ</p>';
      return;
    }
    host.innerHTML = rows
      .map((row) => {
        const st =
          row.status === "draft"
            ? "ฉบับร่าง"
            : row.status === "revoked"
              ? "ดึงคืนแล้ว"
              : "ส่งแล้ว";
        const auto =
          row.is_automation
            ? row.automation_enabled
              ? '<span class="admin-mailbox-rule-on">ออโต้เปิด</span>'
              : '<span class="admin-mailbox-rule-off">ออโต้ปิด</span>'
            : "";
        return (
          '<article class="admin-mailbox-card"><h4>' +
          escapeHtml(row.title || "") +
          auto +
          "</h4><p>" +
          escapeHtml(st) +
          " · คนรับ " +
          formatNumTh(row.recipient_count || 0) +
          " · โหลด " +
          formatNumTh(row.download_count || 0) +
          " ครั้ง · ยังไม่อ่าน " +
          formatNumTh(row.unread_count || 0) +
          " · ไฟล์ " +
          formatNumTh((row.attachments || []).length) +
          '</p><div class="admin-mailbox-actions">' +
          (row.status === "sent" || row.status === "draft"
            ? '<button type="button" class="btn btn-ghost btn-sm" data-mailbox-revoke="' +
              escapeHtml(row.id || "") +
              '">ดึงคืน</button>'
            : "") +
          "</div></article>"
        );
      })
      .join("");
  }

  async function loadAdminMailbox() {
    paintAdminMailboxChips();
    paintAdminMailboxFiles();
    paintAdminMailboxAutoFiles();
    syncMailboxAutoFields();
    if ($("admin-mailbox-auto-since") && !$("admin-mailbox-auto-since").value) {
      $("admin-mailbox-auto-since").value = mailboxLocalDatetimeValue();
    }
    const data = await api("/api/admin/mailbox");
    paintAdminMailboxList(data?.drops || []);
    await Promise.all([loadAdminMailboxRules(), loadAdminMailboxPicker({ silent: true })]);
  }

  async function sendAdminMailbox() {
    flushMailboxPendingInputs();
    const title = String($("admin-mailbox-title")?.value || "").trim();
    if (!title) throw new Error("mailbox_title_required");
    if (!mailboxRecipients.length) throw new Error("mailbox_recipients_required");
    if (!mailboxPendingFiles.length) throw new Error("mailbox_files_required");
    const created = await api("/api/admin/mailbox", {
      method: "POST",
      body: {
        title,
        body: String($("admin-mailbox-body")?.value || "").trim(),
        visible_days: Number($("admin-mailbox-visible-days")?.value || 7),
        download_days: Number($("admin-mailbox-download-days")?.value || 7),
        usernames: mailboxRecipients.map((row) => row.username),
      },
    });
    const dropId = created?.drop?.id;
    if (!dropId) throw new Error("mailbox_save_failed");
    if (dropId) await uploadMailboxAttachments(dropId, mailboxPendingFiles);
    await api("/api/admin/mailbox/" + encodeURIComponent(dropId) + "/send", {
      method: "POST",
      body: { usernames: mailboxRecipients.map((row) => row.username) },
    });
    resetAdminMailboxForm();
    await loadAdminMailbox();
  }

  async function saveAdminRedeemCampaign() {
    const payload = collectAdminRedeemPayload();
    if (!payload.name) throw new Error("redeem_name_required");
    const id = String($("admin-redeem-campaign-id")?.value || "").trim();
    const data = id
      ? await api("/api/admin/redeem/campaigns/" + encodeURIComponent(id), {
          method: "PATCH",
          body: payload,
        })
      : await api("/api/admin/redeem/campaigns", { method: "POST", body: payload });
    const camp = data?.campaign;
    if (camp?.id) adminRedeemSelectedId = camp.id;
    await loadAdminRedeem();
  }

  async function generateAdminRedeemCodes() {
    const id = adminRedeemSelectedId || String($("admin-redeem-campaign-id")?.value || "").trim();
    if (!id) throw new Error("เลือกหรือบันทึกแคมเปญก่อนสุ่มโค้ด");
    const custom = String($("admin-redeem-custom")?.value || "").trim();
    const count = Number($("admin-redeem-gen-count")?.value || 1) || 1;
    const data = await api("/api/admin/redeem/campaigns/" + encodeURIComponent(id) + "/generate", {
      method: "POST",
      body: { count, custom_code: custom || null },
    });
    const lines = (data?.codes || []).map((row) => row.code).filter(Boolean);
    const box = $("admin-redeem-generated");
    if (box && lines.length) {
      const prev = String(box.value || "").trim();
      box.value = prev ? prev + "\n" + lines.join("\n") : lines.join("\n");
    }
    if ($("admin-redeem-custom")) $("admin-redeem-custom").value = "";
    await loadAdminRedeemCodes();
    return lines.length;
  }

  function bkkYmd(d) {
    return new Intl.DateTimeFormat("en-CA", {
      timeZone: "Asia/Bangkok",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).format(d || new Date());
  }

  function shiftYmd(ymd, days) {
    const [y, m, d] = String(ymd || "").split("-").map(Number);
    if (!y || !m || !d) return bkkYmd();
    const dt = new Date(Date.UTC(y, m - 1, d + Number(days || 0)));
    return dt.toISOString().slice(0, 10);
  }

  function applyAdminTopupPreset(preset, { silent } = {}) {
    adminTopupPreset = preset || "week";
    document.querySelectorAll("[data-admin-topup-preset]").forEach((btn) => {
      btn.classList.toggle("is-on", btn.getAttribute("data-admin-topup-preset") === adminTopupPreset);
    });
    const today = bkkYmd();
    let from = today;
    let to = today;
    if (adminTopupPreset === "yesterday") {
      from = to = shiftYmd(today, -1);
    } else if (adminTopupPreset === "week") {
      from = shiftYmd(today, -6);
    } else if (adminTopupPreset === "month") {
      from = today.slice(0, 8) + "01";
    } else if (adminTopupPreset === "year") {
      from = shiftYmd(today, -365);
    } else if (adminTopupPreset === "custom") {
      from = $("admin-topup-from")?.value || from;
      to = $("admin-topup-to")?.value || to;
    }
    if ($("admin-topup-from")) $("admin-topup-from").value = from;
    if ($("admin-topup-to")) $("admin-topup-to").value = to;
    if (!silent && adminConsoleTab === "topups") {
      loadAdminTopups().catch((e) => adminConsoleStatus(thError(e.message) || "โหลดไม่สำเร็จ", "err"));
    }
  }

  function formatAdminBaht(n) {
    const num = Number(n) || 0;
    const rounded = Math.round(num * 100) / 100;
    const [intPart, frac] = rounded.toFixed(2).split(".");
    const grouped = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return frac === "00" ? grouped : grouped + "." + frac.replace(/0$/, "");
  }

  function paintAdminTopupBreakdown() {
    const box = $("admin-topup-breakdown");
    if (!box) return;
    const rows = adminTopupGroup === "week" ? adminTopupSummary?.by_week : adminTopupSummary?.by_day;
    if (!Array.isArray(rows) || !rows.length) {
      box.innerHTML = `<p class="admin-topup-empty">ยังไม่มีรายได้ในช่วงนี้</p>`;
      return;
    }
    box.innerHTML = rows
      .map(
        (row) => `<div class="admin-topup-break-row">
          <span>${escapeHtml(row.label || row.key || "")}</span>
          <span class="admin-topup-muted">${escapeHtml(formatNumTh(row.count || 0))} รายการ</span>
          <span class="admin-topup-baht">฿${escapeHtml(formatAdminBaht(row.baht))}</span>
        </div>`
      )
      .join("");
  }

  function paintAdminTopupSplit() {
    const box = $("admin-topup-split");
    if (!box) return;
    const methods = adminTopupSummary?.by_method || [];
    const packs = adminTopupSummary?.by_package || [];
    if (!methods.length && !packs.length) {
      box.innerHTML = "";
      return;
    }
    const col = (title, items) => `<div>
        <h4 class="admin-card-title">${escapeHtml(title)}</h4>
        <div class="admin-topup-breakdown">${(items || [])
          .map(
            (row) => `<div class="admin-topup-break-row">
              <span>${escapeHtml(row.label || row.key || "")}</span>
              <span class="admin-topup-muted">${escapeHtml(formatNumTh(row.count || 0))}</span>
              <span class="admin-topup-baht">฿${escapeHtml(formatAdminBaht(row.baht))}</span>
            </div>`
          )
          .join("")}</div>
      </div>`;
    box.innerHTML = `<div class="admin-topup-split-grid">${col("แยกช่องทาง", methods)}${col("แยกแพ็ก", packs)}</div>`;
  }

  function paintAdminTopupItems(append) {
    const box = $("admin-topup-list");
    if (!box) return;
    if (!append) box.innerHTML = "";
    if (!adminTopupItems.length) {
      box.innerHTML = `<p class="admin-topup-empty">ไม่พบรายการเติมเงินในช่วงที่เลือก</p>`;
      return;
    }
    const html = adminTopupItems
      .map((row) => {
        const user = row.username || row.display_name || "ไม่ทราบบัญชี";
        const ok = row.credit_status === "credited";
        return `<button type="button" class="admin-topup-row admin-topup-row--card" data-admin-topup-user="${escapeHtml(String(row.username || ""))}">
          <div class="admin-topup-main">
            <div class="admin-topup-user">${escapeHtml(user)}</div>
            <div class="admin-topup-meta">${escapeHtml(row.created_at_bkk || "")}</div>
            <div class="admin-topup-pack">${escapeHtml(row.package_label || row.package_kind || "")}</div>
            <div class="admin-topup-muted">${escapeHtml(row.method_label || row.payment_method || "")}${row.voucher_code ? " · " + escapeHtml(row.voucher_code) : ""}</div>
          </div>
          <div class="admin-topup-side">
            <span class="admin-topup-baht">฿${escapeHtml(formatAdminBaht(row.amount_baht))}</span>
            <div class="admin-topup-pills">
              <span class="admin-topup-pill ${ok ? "is-ok" : "is-wait"}">${escapeHtml(row.status_label || row.credit_status || "")}</span>
            </div>
          </div>
        </button>`;
      })
      .join("");
    if (append) box.insertAdjacentHTML("beforeend", html);
    else box.innerHTML = html;
    box.querySelectorAll("[data-admin-topup-user]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const user = btn.getAttribute("data-admin-topup-user") || "";
        if (!user) return;
        if ($("admin-rental-user")) $("admin-rental-user").value = user;
        if ($("admin-topup-q")) $("admin-topup-q").value = user;
        paintAdminWalletFields(adminCachedUser(user));
        setAdminConsoleTab("rental");
        adminConsoleStatus(`เลือกผู้ใช้: ${user}`, "muted");
      });
    });
  }

  function paintAdminTopupStats() {
    const box = $("admin-topup-stats");
    if (!box) return;
    const s = adminTopupSummary || {};
    const from = $("admin-topup-from")?.value || "";
    const to = $("admin-topup-to")?.value || "";
    box.innerHTML = `
      <div class="admin-topup-stat" data-stat="baht">
        <span class="admin-topup-stat-num">฿${escapeHtml(formatAdminBaht(s.total_baht))}</span>
        <span class="admin-topup-stat-label">รายได้รวม ${escapeHtml(from && to ? from + " – " + to : "")}</span>
      </div>
      <div class="admin-topup-stat">
        <span class="admin-topup-stat-num">${escapeHtml(formatNumTh(s.credited_count || 0))}</span>
        <span class="admin-topup-stat-label">เติมสำเร็จ</span>
      </div>
      <div class="admin-topup-stat">
        <span class="admin-topup-stat-num">${escapeHtml(formatNumTh(s.total_count || 0))}</span>
        <span class="admin-topup-stat-label">รายการทั้งหมด</span>
      </div>
      <div class="admin-topup-stat">
        <span class="admin-topup-stat-num">${escapeHtml(formatNumTh(s.pending_count || 0))}</span>
        <span class="admin-topup-stat-label">ยังไม่สำเร็จ</span>
      </div>`;
  }

  async function loadAdminTopups({ append } = {}) {
    if (!append) {
      adminTopupOffset = 0;
      adminTopupItems = [];
    }
    const from = String($("admin-topup-from")?.value || "").trim();
    const to = String($("admin-topup-to")?.value || "").trim();
    if (!from || !to) applyAdminTopupPreset(adminTopupPreset, { silent: true });
    const qs = new URLSearchParams();
    const fromV = String($("admin-topup-from")?.value || "").trim();
    const toV = String($("admin-topup-to")?.value || "").trim();
    if (fromV) qs.set("from", fromV);
    if (toV) qs.set("to", toV);
    const q = String($("admin-topup-q")?.value || "").trim();
    const method = String($("admin-topup-method")?.value || "").trim();
    const kind = String($("admin-topup-kind")?.value || "").trim();
    const status = String($("admin-topup-status")?.value || "").trim();
    if (q) qs.set("q", q);
    if (method) qs.set("method", method);
    if (kind) qs.set("package_kind", kind);
    if (status) qs.set("status", status);
    qs.set("limit", "80");
    qs.set("offset", String(adminTopupOffset));
    adminConsoleStatus("กำลังโหลดประวัติเติมเงิน…", "muted");
    if (!append) paintAdminTopupSkeleton(6);
    const data = await api("/api/admin/topup/history?" + qs.toString());
    adminTopupSummary = data?.summary || null;
    const items = Array.isArray(data?.items) ? data.items : [];
    adminTopupItems = append ? adminTopupItems.concat(items) : items;
    adminTopupHasMore = !!data?.has_more;
    adminTopupOffset = Number(data?.offset || 0) + items.length;
    const more = $("admin-topup-more");
    if (more) more.classList.toggle("hidden", !adminTopupHasMore);
    paintAdminTopupStats();
    paintAdminTopupBreakdown();
    paintAdminTopupSplit();
    paintAdminTopupItems(false);
    const total = Number(data?.total || 0);
    adminConsoleStatus(
      total ? `พบ ${formatNumTh(total)} รายการ · รายได้ ฿${formatAdminBaht(adminTopupSummary?.total_baht)}` : "ไม่พบรายการในช่วงนี้",
      "muted"
    );
  }

  function adminUserStatus(row) {
    const status = String(row?.rental_status || "").trim();
    if (status) return status;
    if (row?.banned_at) return "banned";
    if (row?.rental_is_permanent || row?.is_permanent) return "permanent";
    if (row?.rental_pending) return "pending";
    if (row?.farm_access) return "active";
    const expires = row?.rental_expires_at ? Date.parse(row.rental_expires_at) : NaN;
    if (Number.isFinite(expires) && expires > Date.now()) return "active";
    return "expired";
  }

  function adminUserIsUsing(row) {
    const status = adminUserStatus(row);
    return status === "active" || status === "pending" || status === "permanent";
  }

  function formatAdminPendingHours(seconds) {
    const n = Number(seconds) || 0;
    if (n <= 0) return "";
    const hours = Math.max(1, Math.round(n / 3600));
    return formatNumTh(hours) + " ชม.";
  }

  function adminUserTokens(row) {
    return Number(row?.token_balance ?? row?.idshop_credit_balance ?? row?.invite_credit_balance ?? 0) || 0;
  }

  function adminUserDays(row) {
    if (row?.usage_unlimited) return Number.POSITIVE_INFINITY;
    const n = Number(row?.usage_days);
    return Number.isFinite(n) ? n : 0;
  }

  function adminUserSort(a, b, key) {
    const created = (row) => Date.parse(row?.created_at || "") || 0;
    if (key === "oldest") return created(a) - created(b);
    if (key === "token_desc") return adminUserTokens(b) - adminUserTokens(a);
    if (key === "token_asc") return adminUserTokens(a) - adminUserTokens(b);
    if (key === "days_desc") return adminUserDays(b) - adminUserDays(a);
    if (key === "days_asc") return adminUserDays(a) - adminUserDays(b);
    if (key === "topup_desc") return Number(b?.topup_baht || 0) - Number(a?.topup_baht || 0);
    if (key === "topup_asc") return Number(a?.topup_baht || 0) - Number(b?.topup_baht || 0);
    return created(b) - created(a);
  }

  function adminDashMoney(n) {
    return formatNumTh(Math.round(Number(n) || 0)) + " บาท";
  }

  function adminDashDate(iso) {
    const d = new Date(String(iso || "") + "T12:00:00+07:00");
    if (Number.isNaN(d.getTime())) return String(iso || "");
    return d.toLocaleDateString("th-TH", { day: "numeric", month: "short" });
  }

  function paintAdminDashboard(data) {
    const cards = $("admin-dash-cards");
    const table = $("admin-dash-table");
    if (!cards || !table) return;
    const today = data?.today || {};
    const yesterday = data?.yesterday || {};
    const week = data?.last_7_days || {};
    const tiles = [
      ["ยอดเติมวันนี้", adminDashMoney(today.topup_baht), formatNumTh(today.topup_count || 0) + " ครั้ง"],
      ["สมัครใหม่วันนี้", formatNumTh(today.signups || 0) + " คน", "เวลาไทย"],
      ["ยอดเติมเมื่อวาน", adminDashMoney(yesterday.topup_baht), formatNumTh(yesterday.signups || 0) + " คนสมัคร"],
      ["7 วันล่าสุด", adminDashMoney(week.topup_baht), formatNumTh(week.signups || 0) + " คนสมัคร · " + formatNumTh(week.topup_count || 0) + " ครั้ง"],
      ["ผู้ใช้ทั้งหมด", formatNumTh(data?.users_total || 0), "ใช้อยู่ " + formatNumTh(data?.using_count || 0) + " · หมดอายุ " + formatNumTh(data?.expired_count || 0)],
      ["Token คงเหลือ", formatTokenAmount(data?.tokens_outstanding || 0), "ยอดเติมสะสม " + adminDashMoney(data?.topup_baht_all)],
    ];
    cards.innerHTML = tiles
      .map(
        (tile) =>
          '<article class="admin-dash-card"><span>' +
          escapeHtml(tile[0]) +
          "</span><strong>" +
          escapeHtml(tile[1]) +
          "</strong><small>" +
          escapeHtml(tile[2]) +
          "</small></article>"
      )
      .join("");
    const series = Array.isArray(data?.series) ? data.series.slice().reverse() : [];
    const payers = Array.isArray(data?.today_payers) ? data.today_payers : [];
    const rows = series
      .map(
        (row) =>
          "<tr><td>" +
          escapeHtml(adminDashDate(row.date)) +
          "</td><td>" +
          escapeHtml(adminDashMoney(row.topup_baht)) +
          "</td><td>" +
          escapeHtml(formatNumTh(row.topup_count || 0)) +
          "</td><td>" +
          escapeHtml(formatNumTh(row.signups || 0)) +
          "</td></tr>"
      )
      .join("");
    const payerLine = payers.length
      ? '<p class="admin-dash-payers">เติมวันนี้: ' +
        payers
          .map((row) => escapeHtml((row.username || "สมาชิก") + " " + adminDashMoney(row.topup_baht)))
          .join(" · ") +
        "</p>"
      : '<p class="admin-dash-payers">วันนี้ยังไม่มียอดเติมที่เครดิตสำเร็จ</p>';
    table.innerHTML =
      '<table><thead><tr><th>วันที่</th><th>ยอดเติม</th><th>ครั้ง</th><th>สมัครใหม่</th></tr></thead><tbody>' +
      (rows || '<tr><td colspan="4">ยังไม่มีข้อมูล</td></tr>') +
      "</tbody></table>" +
      payerLine;
  }

  async function loadAdminDashboard() {
    adminConsoleStatus("กำลังโหลดแดชบอร์ด…", "muted");
    try {
      const data = await api("/api/admin/dashboard?days=" + encodeURIComponent(String(adminDashDays || 14)));
      paintAdminDashboard(data);
      adminConsoleStatus("แดชบอร์ดอัปเดตแล้ว", "ok");
    } catch (e) {
      adminConsoleStatus("โหลดแดชบอร์ดไม่สำเร็จ: " + (thError(e.message) || e.message), "err");
    }
  }

  function adminUserMatchesFilter(row, filter) {
    const status = adminUserStatus(row);
    if (filter === "using") return adminUserIsUsing(row);
    if (filter === "expired") return status === "expired" || status === "banned";
    return true;
  }

  function paintAdminUserFilterChips(rows) {
    const using = rows.filter(adminUserIsUsing).length;
    const expired = rows.length - using;
    const counts = { all: rows.length, using, expired };
    document.querySelectorAll("[data-admin-user-filter]").forEach((btn) => {
      const key = btn.getAttribute("data-admin-user-filter") || "all";
      const on = key === adminUserFilter;
      btn.classList.toggle("is-on", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
      const badge = btn.querySelector("[data-filter-count]");
      if (badge) badge.textContent = String(counts[key] ?? 0);
    });
  }

  function paintAdminUsers(rows) {
    const box = $("admin-users-list");
    if (!box) return;
    paintAdminUserFilterChips(rows);
    const q = String($("admin-user-search")?.value || "").trim().toLowerCase();
    const minToken = Math.max(0, Number($("admin-user-min-token")?.value || 0) || 0);
    const minDays = Math.max(0, Number($("admin-user-min-days")?.value || 0) || 0);
    const filtered = rows.filter((row) => {
      if (!adminUserMatchesFilter(row, adminUserFilter)) return false;
      if (adminUserTokens(row) + 1e-9 < minToken) return false;
      if (minDays > 0 && !row?.usage_unlimited && adminUserDays(row) + 1e-9 < minDays) return false;
      if (!q) return true;
      const hay = [row.username, row.display_name, row.email, row.id]
        .map((v) => String(v || "").toLowerCase())
        .join(" ");
      return hay.includes(q);
    });
    const sortKey = String($("admin-user-sort")?.value || "newest");
    filtered.sort((a, b) => adminUserSort(a, b, sortKey));
    if (!filtered.length) {
      box.innerHTML = `<div class="admin-card" style="grid-column:1/-1;text-align:center;padding:2rem;"><p class="muted">${
        rows.length ? "ไม่มีผู้ใช้ในตัวกรองนี้" : "ไม่พบข้อมูลผู้ใช้"
      }</p></div>`;
      return;
    }
    box.innerHTML = filtered
      .map((row) => {
        const rawName = row.username || row.email || row.id || "—";
        const initial = (rawName.charAt(0) || "U").toUpperCase();
        const links = row.invite_credit_links != null
          ? row.invite_credit_links
          : Math.max(0, Math.floor(Number(row.invite_credit_balance || row.token_balance || 0) / (inviteLinkCost() || 14)));
        const tokens = adminUserTokens(row);
        const topupBaht = Number(row.topup_baht || 0);
        const topupCount = Number(row.topup_count || 0);
        const usage = escapeHtml(row.usage_label || (row.usage_unlimited ? "ถาวร" : "หมดอายุ"));
        const status = adminUserStatus(row);
        const expires = row.rental_expires_at || "";
        let permClass = "is-active";
        let permText = "🟢 ใช้อยู่";
        if (status === "permanent") {
          permClass = "is-perm";
          permText = "🟢 ถาวร";
        } else if (status === "pending") {
          permClass = "is-active";
          permText = "🟡 รอเริ่ม" + (formatAdminPendingHours(row.rental_pending_seconds) ? " · " + formatAdminPendingHours(row.rental_pending_seconds) : "");
        } else if (status === "banned") {
          permClass = "is-expired";
          permText = "⛔ แบน";
        } else if (status === "expired") {
          permClass = "is-expired";
          permText = "🔴 หมดอายุ";
        } else if (expires) {
          permText = "🟢 ถึง " + new Date(expires).toLocaleString("th-TH", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" });
        }
        return `<button type="button" class="admin-user-card" data-admin-user="${escapeHtml(String(row.username || row.id || ""))}">
              <div class="admin-user-info">
                <div class="admin-user-avatar">${escapeHtml(initial)}</div>
                <div class="admin-user-names">
                  <span class="admin-user-name">${escapeHtml(rawName)}</span>
                  <div class="admin-user-meta">
                    <span class="admin-user-token-pill">Token ${escapeHtml(formatTokenAmount(tokens))}</span>
                    <span class="admin-user-token-pill">Link ${escapeHtml(String(links))}</span>
                    <span class="admin-user-perm-pill ${permClass}">${escapeHtml(permText)}</span>
                  </div>
                  <div class="admin-user-detail">เติม ${escapeHtml(formatNumTh(topupBaht))} บาท · ${escapeHtml(formatNumTh(topupCount))} ครั้ง · ${usage}</div>
                </div>
              </div>
              <span class="admin-user-action-icon" aria-hidden="true">→</span>
            </button>`;
      })
      .join("");
    box.querySelectorAll("[data-admin-user]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const user = btn.getAttribute("data-admin-user") || "";
        if ($("admin-rental-user")) $("admin-rental-user").value = user;
        if ($("admin-topup-q")) $("admin-topup-q").value = user;
        paintAdminWalletFields(adminCachedUser(user));
        setAdminConsoleTab("rental");
        adminConsoleStatus(`เลือกผู้ใช้: ${user}`, "muted");
      });
    });
  }

  async function loadAdminUsers() {
    const q = String($("admin-user-search")?.value || "").trim();
    adminConsoleStatus("กำลังโหลดผู้ใช้…", "muted");
    if (!adminUsersCache.length) paintAdminUserSkeleton(6);
    try {
      const data = await api("/api/admin/users");
      let rows = Array.isArray(data?.users)
        ? data.users
        : Array.isArray(data?.profiles)
          ? data.profiles
          : [];
      if (q.length >= 2 && !rows.some((row) => String(row.username || "").toLowerCase() === q.toLowerCase())) {
        try {
          const looked = await api("/api/admin/lookup?q=" + encodeURIComponent(q));
          const extra = Array.isArray(looked?.users)
            ? looked.users
            : Array.isArray(looked?.profiles)
              ? looked.profiles
              : looked?.user
                ? [looked.user]
                : looked?.ok && (looked.username || looked.id)
                  ? [looked]
                  : [];
          extra.forEach((row) => {
            if (!rows.some((cur) => cur.id && cur.id === row.id)) rows.push(row);
          });
        } catch (_) {}
      }
      adminUsersCache = rows;
      paintAdminUsers(adminUsersCache);
      paintAdminWalletFields(adminCachedUser($("admin-rental-user")?.value));
      const using = rows.filter(adminUserIsUsing).length;
      adminConsoleStatus(
        "โหลดแล้ว " + rows.length + " บัญชี · ใช้อยู่ " + using + " · หมดอายุ " + (rows.length - using),
        "ok"
      );
    } catch (e) {
      adminConsoleStatus("โหลดรายชื่อไม่สำเร็จ: " + (thError(e.message) || e.message), "err");
    }
  }

  async function loadAdminPackages() {
    try {
      const data = await api("/api/admin/topup/packages");
      adminPackagesDraft = Array.isArray(data?.packages) ? data.packages.slice() : [];
      renderAdminPackagesList();
    } catch (e) {
      adminConsoleStatus("โหลดแพ็กเกจไม่สำเร็จ: " + (thError(e.message) || e.message), "err");
    }
  }

  // ── admin: pack pictures (16:9) + "แนะนำ" ─────────────────────────────
  function cropTo169(file) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => {
        const W = 1280, H = 720;
        const r = Math.max(W / img.width, H / img.height);
        const w = img.width * r, h = img.height * r;
        const c = document.createElement("canvas");
        c.width = W; c.height = H;
        c.getContext("2d").drawImage(img, (W - w) / 2, (H - h) / 2, w, h);
        URL.revokeObjectURL(img.src);
        resolve(c.toDataURL("image/jpeg", 0.86));
      };
      img.onerror = () => reject(new Error("อ่านรูปไม่ได้"));
      img.src = URL.createObjectURL(file);
    });
  }
  async function renderAdminPackMedia() {
    const box = $("admin-pack-media");
    if (!box) return;
    await loadTopupMedia();
    const tokenRows = (tokenPricing.pack_baht && tokenPricing.pack_baht.length ? tokenPricing.pack_baht : [20, 50, 100, 150, 200])
      .map((b) => ({ scope: "token", id: String(b), title: formatNumTh(b) + " บาท", sub: "แพ็กเติม Token" }));
    const rentalRows = adminPackagesDraft.map((p) => ({
      scope: "rental", id: p.id, title: p.label_th || p.id,
      sub: "เช่า/แลก · " + (p.duration_value || p.days || p.hours || 1) + (p.duration_unit === "hours" || p.kind === "feature" ? " ชม." : " วัน"),
    }));
    const row = (r) => {
      const m = packMedia(r.scope, r.id) || {};
      return '<div class="apm-item" data-scope="' + r.scope + '" data-id="' + escapeHtml(r.id) + '">' +
        '<div class="apm-thumb">' + (m.image ? '<img src="' + escapeHtml(m.image) + '" alt="" />' : "<span>16:9</span>") + (m.recommended ? '<span class="pk-ribbon">แนะนำ</span>' : "") + "</div>" +
        '<div class="apm-info"><b>' + escapeHtml(r.title) + '</b><small>' + escapeHtml(r.sub) + "</small></div>" +
        '<div class="apm-acts">' +
        '<label class="btn btn-ghost btn-sm">อัปโหลดรูป<input type="file" accept="image/*" hidden data-apm-upload /></label>' +
        '<button type="button" class="btn btn-sm ' + (m.recommended ? "btn-primary" : "btn-ghost") + '" data-apm-rec>' + (m.recommended ? "★ แนะนำอยู่" : "☆ ตั้งแนะนำ") + "</button>" +
        (m.image ? '<button type="button" class="admin-pkg-del-btn" data-apm-clear>ลบรูป</button>' : "") +
        "</div></div>";
    };
    box.innerHTML =
      '<h4 class="apm-h">แพ็กเติม Token</h4><div class="apm-grid">' + tokenRows.map(row).join("") + "</div>" +
      '<h4 class="apm-h">แพ็กเช่ารายวัน / แลกวันเช่า</h4><div class="apm-grid">' + (rentalRows.length ? rentalRows.map(row).join("") : '<p class="muted">ยังไม่มีแพ็กเช่า</p>') + "</div>";
  }
  document.addEventListener("change", async (ev) => {
    const inp = ev.target.closest && ev.target.closest("[data-apm-upload]");
    if (!inp || !inp.files || !inp.files[0]) return;
    const it = inp.closest(".apm-item");
    try {
      adminConsoleStatus("กำลังอัปโหลดรูป…", "muted");
      const image_b64 = await cropTo169(inp.files[0]);
      await api("/api/admin/topup/media/image", { method: "POST", body: { scope: it.dataset.scope, id: it.dataset.id, image_b64 } });
      adminConsoleStatus("อัปโหลดรูปแล้ว (ครอปเป็น 16:9 อัตโนมัติ)", "ok");
    } catch (e) {
      adminConsoleStatus("อัปโหลดไม่สำเร็จ: " + (e.message || e), "error");
    }
    inp.value = "";
    renderAdminPackMedia();
  });
  document.addEventListener("click", async (ev) => {
    const b = ev.target.closest && ev.target.closest("[data-apm-rec],[data-apm-clear]");
    if (!b) return;
    const it = b.closest(".apm-item");
    const m = packMedia(it.dataset.scope, it.dataset.id) || {};
    const body = { scope: it.dataset.scope, id: it.dataset.id };
    if (b.hasAttribute("data-apm-rec")) body.recommended = !m.recommended;
    else if (!confirm("ลบรูปของแพ็กนี้?")) return;
    else body.clear_image = true;
    try {
      await api("/api/admin/topup/media", { method: "POST", body });
      adminConsoleStatus("บันทึกแล้ว", "ok");
    } catch (e) {
      adminConsoleStatus("ไม่สำเร็จ: " + (e.message || e), "error");
    }
    renderAdminPackMedia();
  });

  function renderAdminPackagesList() {
    renderAdminPackMedia();
    const box = $("admin-packages-list");
    if (!box) return;
    if (!adminPackagesDraft.length) {
      box.innerHTML = `<div class="admin-card" style="grid-column:1/-1;text-align:center;padding:1.5rem;"><p class="muted">ยังไม่มีแพ็กเกจในระบบ</p></div>`;
      return;
    }
    const editingId = String($("admin-pkg-id")?.value || "").trim();
    box.innerHTML = adminPackagesDraft.map((pkg) => {
      const kind = pkg.kind === "feature" ? "feature" : "full";
      const kindLabel = kind === "feature" ? "Feature" : "Full Access";
      const kindClass = kind === "feature" ? "kind-feature" : "kind-full";
      const unit = pkg.duration_unit === "hours" || kind === "feature" ? "ชั่วโมง" : "วัน";
      const val = pkg.duration_value || pkg.days || pkg.hours || 1;
      const title = pkg.label_th || pkg.id;
      const on = editingId && editingId === pkg.id;
      return `<div class="admin-pkg-card${on ? " is-editing" : ""}" data-admin-pkg-edit="${pkg.id}">
        <div class="admin-pkg-head">
          <span class="admin-pkg-id-tag">${pkg.id}</span>
          <span class="admin-pkg-kind-tag ${kindClass}">${kindLabel}</span>
        </div>
        <div class="admin-pkg-body">
          <span class="admin-pkg-title">${title}</span>
          <span class="admin-pkg-duration">${val} ${unit}</span>
        </div>
        <div class="admin-pkg-price-row">
          <span class="admin-pkg-price">${pkg.price_baht} ฿ = ${pkg.price_baht} Token แลก</span>
          <div class="admin-pkg-actions">
            <button type="button" class="btn btn-ghost btn-sm" data-admin-pkg-edit="${pkg.id}">แก้ไข</button>
            <button type="button" class="admin-pkg-del-btn" data-admin-pkg-del="${pkg.id}">ลบ</button>
          </div>
        </div>
      </div>`;
    }).join("");
    box.querySelectorAll("[data-admin-pkg-edit]").forEach((btn) => {
      btn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        const editId = btn.getAttribute("data-admin-pkg-edit");
        const pkg = adminPackagesDraft.find((p) => p.id === editId);
        if (pkg) fillAdminPackageForm(pkg);
      });
    });
    box.querySelectorAll("[data-admin-pkg-del]").forEach((btn) => {
      btn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        const delId = btn.getAttribute("data-admin-pkg-del");
        adminPackagesDraft = adminPackagesDraft.filter((p) => p.id !== delId);
        renderAdminPackagesList();
        adminConsoleStatus(`ลบแพ็กเกจ ${delId} จากร่างแล้ว (กดบันทึกแคตตาล็อกเพื่อยืนยัน)`, "muted");
      });
    });
  }

  function fillAdminPackageForm(pkg) {
    if (!pkg) return;
    const kind = pkg.kind === "feature" ? "feature" : "full";
    const unit = kind === "feature" || pkg.duration_unit === "hours" ? "hours" : "days";
    if ($("admin-pkg-id")) $("admin-pkg-id").value = pkg.id || "";
    if ($("admin-pkg-label")) $("admin-pkg-label").value = pkg.label_th || "";
    if ($("admin-pkg-kind")) $("admin-pkg-kind").value = kind;
    if ($("admin-pkg-unit")) $("admin-pkg-unit").value = unit;
    if ($("admin-pkg-value")) {
      $("admin-pkg-value").value = String(pkg.duration_value || (unit === "hours" ? pkg.hours : pkg.days) || 1);
    }
    if ($("admin-pkg-price")) $("admin-pkg-price").value = String(pkg.price_baht || 1);
    syncAdminPackageUnit();
    renderAdminPackagesList();
    adminConsoleStatus(`กำลังแก้ไขแพ็ก ${pkg.id} — แก้แล้วกดบันทึกลงรายการร่าง จากนั้นบันทึกแคตตาล็อก`, "muted");
    $("admin-pkg-id")?.focus();
  }

  function resetAdminPackageForm() {
    if ($("admin-pkg-id")) $("admin-pkg-id").value = "";
    if ($("admin-pkg-label")) $("admin-pkg-label").value = "";
    if ($("admin-pkg-kind")) $("admin-pkg-kind").value = "full";
    if ($("admin-pkg-unit")) $("admin-pkg-unit").value = "days";
    if ($("admin-pkg-value")) $("admin-pkg-value").value = "1";
    if ($("admin-pkg-price")) $("admin-pkg-price").value = "150";
    renderAdminPackagesList();
  }

  function syncAdminPackageUnit() {
    const kind = $("admin-pkg-kind")?.value || "full";
    const unitEl = $("admin-pkg-unit");
    if (!unitEl) return;
    if (kind === "feature") {
      unitEl.value = "hours";
      unitEl.disabled = true;
    } else {
      unitEl.disabled = false;
    }
  }

  function collectAdminPackageRow() {
    const id = String($("admin-pkg-id")?.value || "").trim();
    if (!id) return null;
    const existing = adminPackagesDraft.find((p) => p.id === id) || {};
    const kind = $("admin-pkg-kind")?.value === "feature" ? "feature" : "full";
    const unit = kind === "feature" ? "hours" : ($("admin-pkg-unit")?.value || "days");
    const value = Number($("admin-pkg-value")?.value || 1);
    return {
      ...existing,
      id,
      kind,
      duration_unit: unit,
      duration_value: value,
      days: unit === "days" ? value : null,
      hours: unit === "hours" ? value : value * 24,
      price_baht: Number($("admin-pkg-price")?.value || 150),
      label_th: String($("admin-pkg-label")?.value || "").trim() || id,
      active: existing.active !== false,
    };
  }

  async function saveAdminPackages() {
    const data = await api("/api/admin/topup/packages", { method: "POST", body: { packages: adminPackagesDraft } });
    adminPackagesDraft = Array.isArray(data?.packages) ? data.packages.slice() : adminPackagesDraft;
    renderAdminPackagesList();
  }

