  let adminProxyState = null;

  function selectedProxyProviderId() {
    return String($("admin-proxy-provider")?.value || adminProxyState?.provider || "nettify").trim().toLowerCase();
  }

  function proxyProviderMeta(id) {
    const fromApi = (adminProxyState?.providers || []).find((p) => p.id === id);
    const fallback = PROXY_PROVIDERS[id] || PROXY_PROVIDERS.nettify || PROXY_PROVIDERS.webshare;
    if (!fromApi) return fallback;
    return {
      id: fromApi.id,
      label: fromApi.label || fallback.label,
      http: fromApi.http_placeholder || fallback.http,
      socks: fromApi.socks_placeholder || fallback.socks,
      token: fromApi.token_placeholder || fallback.token,
      hint: fromApi.token_hint || fallback.hint,
      docs: fromApi.docs_url || fallback.docs,
      powered: fromApi.powered_by || fallback.powered,
      poweredUrl: fromApi.powered_by_url || fallback.poweredUrl,
    };
  }

  function paintAdminProxyProviderFields() {
    const id = selectedProxyProviderId();
    const meta = proxyProviderMeta(id);
    const row = (adminProxyState?.providers || []).find((p) => p.id === id) || {};
    const activeId = adminProxyState?.provider || "";
    if ($("admin-proxy-url")) $("admin-proxy-url").placeholder = meta.http;
    if ($("admin-socks-url")) $("admin-socks-url").placeholder = meta.socks;
    if ($("admin-batproxies-token")) $("admin-batproxies-token").placeholder = meta.token;
    if ($("admin-proxy-token-hint")) $("admin-proxy-token-hint").textContent = meta.hint;
    if ($("admin-proxy-url-masked")) {
      $("admin-proxy-url-masked").textContent = row.http_url_masked
        ? "ค่าที่บันทึก: " + row.http_url_masked
        : "ยังไม่มี HTTP URL ในโปรไฟล์นี้";
    }
    if ($("admin-socks-url-masked")) {
      $("admin-socks-url-masked").textContent = row.socks_url_masked
        ? "ค่าที่บันทึก: " + row.socks_url_masked
        : "ยังไม่มี SOCKS5 URL ในโปรไฟล์นี้";
    }
    if ($("admin-batproxies-token-masked")) {
      $("admin-batproxies-token-masked").textContent = row.token_masked
        ? "ค่าปัจจุบัน: " + row.token_masked
        : "ยังไม่มี API token ของค่ายนี้";
    }
    const planGbEl = $("admin-batproxies-plan-gb");
    const planGb = Number(row.plan_gb);
    if (planGbEl) planGbEl.value = Number.isFinite(planGb) && planGb > 0 ? String(planGb) : "";
    const badge = $("admin-proxy-active-badge");
    if (badge) {
      badge.textContent = id === activeId ? "กำลังใช้ค่ายนี้" : "ยังไม่ใช้ — กด «ใช้ค่ายนี้» เมื่อพร้อม";
      badge.style.color = id === activeId ? "#4ade80" : "";
    }
    const docs = $("admin-proxy-docs-line");
    if (docs) {
      docs.innerHTML = `Powered by <a href="${escapeHtml(meta.poweredUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(meta.powered)}</a> · <a href="${escapeHtml(meta.docs)}" target="_blank" rel="noopener noreferrer">เอกสาร API</a>`;
    }
  }

  async function loadAdminProxy() {
    try {
      adminConsoleStatus("กำลังโหลด Proxy…", "muted");
      const data = await api("/api/admin/proxy?probe=1", { timeoutMs: 60000 });
      adminProxyState = data;
      const sel = $("admin-proxy-provider");
      if (sel && data?.providers?.length) {
        const current = sel.value;
        sel.innerHTML = data.providers.map((p) =>
          `<option value="${escapeHtml(p.id)}">${escapeHtml(p.label || p.id)}</option>`
        ).join("");
        sel.value = current && data.providers.some((p) => p.id === current)
          ? current
          : (data.provider || data.providers[0].id);
      } else if (sel && data?.provider) {
        sel.value = data.provider;
      }
      paintAdminProxyProviderFields();
      const httpMasked = data?.proxy_url_masked || "—";
      const socksMasked = data?.socks_url_masked || "—";
      const el = $("admin-proxy-status");
      if (el) {
        const ready = data?.ready ? "พร้อม" : "ยังไม่พร้อม";
        const pool = data?.pool?.detail || data?.pool?.label || "";
        const poweredBy = data?.powered_by || data?.pool?.powered_by || "nettify.xyz";
        const poweredUrl = data?.powered_by_url || data?.pool?.powered_by_url || "https://nettify.xyz";
        const activeLabel = data?.label || data?.provider || poweredBy;
        const liveLabel = (live) => {
          if (!live) return { text: "ยังไม่เช็ค", color: "#94a3b8" };
          if (live.status === "empty") return { text: "ยังไม่บันทึก", color: "#94a3b8" };
          if (live.ok) return { text: "ขึ้น", color: "#4ade80" };
          return { text: "ล่ม", color: "#f87171" };
        };
        const healthCards = (data.providers || []).map((p) => {
          const live = p.live || {};
          const st = liveLabel(live);
          const extra = live.ok
            ? (live.exit_ip || "OK")
            : (live.error || p.http_url_masked || "—");
          return `<div class="admin-invite-metric-card">
              <span class="admin-invite-metric-title">${escapeHtml(p.label || p.id)}${p.active ? " · ใช้ตอนนี้" : ""}</span>
              <span class="admin-invite-metric-value" style="color:${st.color};">${st.text}</span>
              <span class="admin-invite-metric-sub">${escapeHtml(String(extra || "—"))}</span>
            </div>`;
        }).join("");
        el.innerHTML = `
          <div class="admin-invite-metrics-grid">
            <div class="admin-invite-metric-card">
              <span class="admin-invite-metric-title">ค่ายที่ใช้งาน</span>
              <span class="admin-invite-metric-value" style="color:${data?.configured ? "#4ade80" : "#f87171"};">${escapeHtml(String(activeLabel))}</span>
              <span class="admin-invite-metric-sub">${ready}</span>
            </div>
            <div class="admin-invite-metric-card">
              <span class="admin-invite-metric-title">HTTP Proxy</span>
              <span class="admin-invite-metric-value" style="color:${data?.configured ? "#4ade80" : "#f87171"};">${ready}</span>
              <span class="admin-invite-metric-sub">${escapeHtml(httpMasked)}</span>
            </div>
            <div class="admin-invite-metric-card">
              <span class="admin-invite-metric-title">SOCKS5</span>
              <span class="admin-invite-metric-value" style="color:${data?.socks_url_masked ? "#38bdf8" : "#f87171"};">${data?.socks_url_masked ? "ตั้งแล้ว" : "ยังไม่ตั้ง"}</span>
              <span class="admin-invite-metric-sub">${escapeHtml(socksMasked)}</span>
            </div>
          </div>
          ${healthCards ? `<div class="admin-proxy-health-grid">${healthCards}</div>` : ""}
          ${pool ? `<p class="muted" style="margin-top:0.6rem;">${escapeHtml(String(pool))}</p>` : ""}
          <p class="muted" style="margin-top:0.4rem;"><a href="${escapeHtml(poweredUrl)}" target="_blank" rel="noopener noreferrer">Powered by: ${escapeHtml(poweredBy)}</a></p>
        `;
      }
      adminConsoleStatus("อัปเดต Proxy แล้ว", "ok");
    } catch (e) {
      adminConsoleStatus("โหลด Proxy ไม่สำเร็จ: " + (thError(e.message) || e.message), "err");
    }
  }

  async function saveAdminProxyProfile() {
    const provider = selectedProxyProviderId();
    const http = String($("admin-proxy-url")?.value || "").trim();
    const socks = String($("admin-socks-url")?.value || "").trim();
    const token = String($("admin-batproxies-token")?.value || "").trim();
    const gbRaw = String($("admin-batproxies-plan-gb")?.value || "").trim();
    const body = { provider, check: !!$("admin-proxy-check")?.checked };
    if (http) body.http_url = http;
    if (socks) body.socks_url = socks;
    if (token) body.api_token = token;
    if (gbRaw) {
      const gb = Number(gbRaw);
      if (!Number.isFinite(gb) || gb <= 0) {
        adminConsoleStatus("ใส่ขนาด Pool เป็น GB เช่น 3", "err");
        return;
      }
      body.plan_gb = gb;
    }
    if (!http && !socks && !token && !gbRaw) {
      adminConsoleStatus("ใส่ URL, token หรือขนาด Pool ก่อนบันทึกโปรไฟล์", "err");
      return;
    }
    await api("/api/admin/proxy/profile", { method: "POST", body });
    if ($("admin-proxy-url")) $("admin-proxy-url").value = "";
    if ($("admin-socks-url")) $("admin-socks-url").value = "";
    if ($("admin-batproxies-token")) $("admin-batproxies-token").value = "";
    await loadAdminProxy();
    loadProxyPool({ force: true }).catch(() => {});
  }

  async function useAdminProxyProvider() {
    const provider = selectedProxyProviderId();
    await api("/api/admin/proxy/provider", {
      method: "POST",
      body: { provider, check: !!$("admin-proxy-check")?.checked },
    });
    await loadAdminProxy();
    loadProxyPool({ force: true }).catch(() => {});
  }

  async function saveAdminProxy() {
    return saveAdminProxyProfile();
  }

  async function loadAdminFarmCaps() {
    try {
      const data = await api("/api/admin/settings");
      const map = {
        coin_fast: data.afterplay_max_runs_coin_fast,
        coin_safe: data.afterplay_max_runs_coin_safe,
        xp_fast: data.afterplay_max_runs_xp_fast,
        xp_safe: data.afterplay_max_runs_xp_safe,
        box: data.afterplay_max_runs_box,
        combined: data.afterplay_max_runs_combined,
      };
      Object.keys(map).forEach((key) => {
        const el = $("admin-cap-" + key);
        if (el && map[key] != null) el.value = String(map[key]);
      });
      if ($("admin-overlap-afterplay") && data.afterplay_overlap != null) {
        $("admin-overlap-afterplay").value = String(data.afterplay_overlap);
      }
      if ($("admin-overlap-unlock_l") && data.unlock_l_overlap != null) {
        $("admin-overlap-unlock_l").value = String(data.unlock_l_overlap);
      }
      if ($("admin-overlap-ice_tower") && data.ice_tower_overlap != null) {
        $("admin-overlap-ice_tower").value = String(data.ice_tower_overlap);
      }
      fillAdminTokenSettings(data);
      adminConsoleStatus("โหลดค่าเพดานรอบปัจจุบันแล้ว", "ok");
    } catch (e) {
      adminConsoleStatus("โหลดเพดานไม่สำเร็จ: " + (thError(e.message) || e.message), "err");
    }
  }

