  async function mergeAdminHearts() {
    const ta = $("admin-hearts-merge-text");
    const text = String(ta?.value || "").trim();
    if (!text) {
      adminConsoleStatus("วางรายการไอดีก่อน (email<TAB>password)", "err");
      return;
    }
    const res = await api("/api/admin/heart-helpers/merge", {
      method: "POST",
      body: { text },
    });
    if (ta) ta.value = "";
    const added = res?.added ?? 0;
    const updated = res?.updated ?? 0;
    const skipped = res?.skipped ?? 0;
    const total = res?.total ?? "—";
    adminConsoleStatus(
      `เพิ่ม ${added} · อัปเดต ${updated} · ข้าม ${skipped} · รวมคลัง ${total}`,
      "ok"
    );
    await loadAdminHearts().catch(() => {});
  }

  async function downloadAdminHearts() {
    adminConsoleStatus("กำลังเตรียมไฟล์…", "muted");
    const headers = {};
    if (accessToken) headers.Authorization = "Bearer " + accessToken;
    if (sessionToken) headers["X-Session-Token"] = sessionToken;
    const res = await fetch(API + "/api/admin/heart-helpers/download", { headers });
    if (!res.ok) {
      adminConsoleStatus("ดาวน์โหลดไม่สำเร็จ (" + res.status + ")", "err");
      return;
    }
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "heart_helpers.txt";
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
    adminConsoleStatus("ดาวน์โหลดคลังหัวใจแล้ว", "ok");
  }

