  (function bindAdminNavSheetSwipe() {
    const side = $("admin-console-sidebar");
    const toggle = $("admin-nav-sheet-toggle");
    if (!side || !toggle) return;
    let startY = 0;
    let tracking = false;
    toggle.addEventListener("touchstart", (ev) => {
      const t = ev.changedTouches && ev.changedTouches[0];
      if (!t) return;
      tracking = true;
      startY = t.clientY;
    }, { passive: true });
    toggle.addEventListener("touchend", (ev) => {
      if (!tracking) return;
      tracking = false;
      const t = ev.changedTouches && ev.changedTouches[0];
      if (!t) return;
      const dy = t.clientY - startY;
      if (dy < -28) setAdminNavSheetOpen(true);
      else if (dy > 28) setAdminNavSheetOpen(false);
    }, { passive: true });
  })();
