  function fillAdminRentalFeatureSelect() {
    const sel = $("admin-rental-feature");
    if (!sel) return;
    const current = sel.value;
    const choices =
      topupFeatureChoices.length
        ? topupFeatureChoices
        : CONSUMER_FEATURES.map((id) => ({
            id,
            label_th: FEATURE_LABEL_TH[id] || FEATURE_LABEL_TH_DEFAULT[id] || id,
          }));
    sel.innerHTML = choices
      .filter((c) => c && c.id && !WEB_REMOVED_TABS.has(c.id))
      .map((c) => {
        const id = String(c.id);
        const label = escapeHtml(c.label_th || FEATURE_LABEL_TH[id] || id);
        return `<option value="${escapeHtml(id)}">${label}</option>`;
      })
      .join("");
    if (current && [...sel.options].some((o) => o.value === current)) sel.value = current;
  }

